-- SRS review-card backfill — BATCH 3 of 4 (1053 rows).
-- Run each batch on its own in the Supabase SQL Editor; order does not matter
-- and each is idempotent. Together the 4 batches equal backfill_srs_payload.sql.
-- Repairs stored /review payloads to match the corrected banks (main-app + Top 2).
WITH d(qid, patch) AS (
  VALUES
  ('15338ca6-14','{"options": ["18 mm in diameter", "35 mm in diameter", "24 mm in diameter", "10 mm in diameter"], "correct": 2, "decode": "The adult eyeball is about 24 mm in diameter (axial length). Not 18 (too small), 35, or 10 mm.", "ow": ["18 mm is a very small (nanophthalmic) eye.", "35 mm is far too large.", "Correct. The adult eyeball is about 24 mm.", "10 mm is far too small."]}'),
  ('69292383-1g','{"options": ["Oblate spheroid", "Cylinder", "Perfect sphere", "Cone"], "correct": 0, "decode": "The normal eyeball is best described as an OBLATE spheroid (slightly wider than deep), not a perfect sphere, cylinder, or cone.", "ow": ["Correct. The eyeball is a slightly oblate spheroid.", "A cylinder is not the eyeball''s shape.", "It is close to but not a perfect sphere.", "A cone is not the eyeball''s shape."]}'),
  ('c4f7d1c4-y','{"options": ["Fibrous, vascular, and nervous coats", "Sclera, lens, and retina", "Cornea, iris, retina", "Choroid, ciliary body, and iris"], "correct": 0, "decode": "The three coats of the eye are the FIBROUS (outer), VASCULAR (middle), and NERVOUS (inner) coats. The other options mix in non-coat structures.", "ow": ["Correct. Fibrous, vascular, and nervous are the three coats.", "The lens is not a coat of the eye.", "The iris is part of a coat, not a coat itself.", "Those are all parts of the vascular coat, not the three coats."]}'),
  ('b29d4666-14','{"options": ["Uvea", "Fibrous coat", "Choroid", "Retina"], "correct": 1, "decode": "The OUTERMOST coat is the FIBROUS coat (cornea + sclera). The uvea is middle; the retina is inner.", "ow": ["The uvea is the middle (vascular) coat.", "Correct. The fibrous coat is outermost.", "The choroid is part of the middle coat.", "The retina is the inner (nervous) coat."]}'),
  ('15a165c7-13','{"options": ["Retina and choroid", "Iris and ciliary body", "Cornea and sclera", "Lens and iris"], "correct": 2, "decode": "The fibrous coat is mainly the CORNEA and SCLERA. The others belong to the vascular or nervous coats.", "ow": ["Retina and choroid are the inner and middle coats.", "Iris and ciliary body are vascular-coat parts.", "Correct. The fibrous coat is cornea and sclera.", "The lens and iris are not the fibrous coat."]}'),
  ('a0db3496-21','{"options": ["80%", "10%", "95%", "50%"], "correct": 0, "decode": "The sclera forms about 80% of the fibrous coat (the clear cornea is the front ~1/6, ~20%). Not 10, 50, or 95%.", "ow": ["Correct. The sclera is about 80% of the fibrous coat.", "10% understates the sclera''s share.", "95% overstates it; the cornea is about 1/6.", "50% understates the sclera''s share."]}'),
  ('21d89778-d','{"options": ["Vascular", "Part of the retina", "Avascular", "Highly pigmented"], "correct": 2, "decode": "The cornea is AVASCULAR (clear, nourished by tears and aqueous). Not vascular, pigmented, or part of the retina.", "ow": ["The cornea has no blood vessels normally.", "The cornea is part of the fibrous coat, not the retina.", "Correct. The cornea is avascular.", "The cornea is transparent, not pigmented."]}'),
  ('89b47019-1a','{"options": ["Retina", "Cornea", "Sclera", "Optic disc"], "correct": 1, "decode": "The MAJOR refractive surface is the CORNEA (air-tissue interface, ~43 D). Not the retina, sclera, or disc.", "ow": ["The retina detects, it does not refract.", "Correct. The cornea is the major refractive surface.", "The sclera is opaque and non-refractive.", "The optic disc is the nerve head, not a refractive surface."]}'),
  ('a61c4a3e-1b','{"options": ["Uvea", "Fibrous coat", "External coat", "Neural coat"], "correct": 0, "decode": "The VASCULAR coat is the UVEA (iris, ciliary body, choroid). Not the fibrous, external, or neural coat.", "ow": ["Correct. The uvea is the vascular (middle) coat.", "The fibrous coat is the outer coat, not vascular.", "The external coat is the fibrous coat.", "The neural coat is the retina."]}'),
  ('c625454b-o','{"options": ["Conjunctiva, cornea, and sclera", "Cornea, sclera, and retina", "Iris, ciliary body, and choroid", "Lens, iris, and retina"], "correct": 2, "decode": "The uvea is the IRIS, CILIARY BODY, and CHOROID. The other options mix in fibrous or neural structures.", "ow": ["Conjunctiva, cornea, and sclera are surface/fibrous, not uvea.", "Cornea, sclera, and retina are not the uvea.", "Correct. The uvea is iris, ciliary body, and choroid.", "Lens, iris, and retina are not the uvea."]}'),
  ('07dee8bb-y','{"options": ["Lens and retina", "Sclera and retina", "Iris and cornea", "Cornea and iris"], "correct": 1, "decode": "The choroid lies between the SCLERA (outside) and the RETINA (inside), as the middle vascular layer. Not near the lens or cornea.", "ow": ["The choroid is posterior, not between lens and retina.", "Correct. The choroid lies between the sclera and retina.", "The iris-cornea space is the anterior chamber, not the choroid.", "The cornea-iris region is anterior, not the choroid."]}'),
  ('a2adf0e8-n','{"options": ["Opaque in normal eyes", "Pigmented", "Vascular", "Avascular"], "correct": 3, "decode": "The crystalline lens is AVASCULAR and transparent (clear for the optical path). Not opaque, pigmented, or vascular in a normal eye.", "ow": ["A normal lens is clear, not opaque (opacity is cataract).", "The lens is transparent, not pigmented.", "The lens has no blood vessels.", "Correct. The normal lens is avascular."]}'),
  ('9d27cdd9-1e','{"options": ["Protect the delicate optic nerve head", "Produce the watery layer of the tears", "Supply oxygenated blood to the retina", "Fine-tune focusing of light on the retina"], "correct": 3, "decode": "The lens''s primary job is to FINE-TUNE focusing of light on the retina (accommodation). It does not protect the nerve, make tears, or supply blood.", "ow": ["The lens does not protect the optic nerve.", "Tears come from the lacrimal glands, not the lens.", "The lens is avascular and supplies no blood.", "Correct. The lens fine-tunes focus onto the retina."]}'),
  ('9147506f-y','{"options": ["Cornea", "Retina", "Choroid", "Sclera"], "correct": 1, "decode": "The NERVOUS coat of the eye is the RETINA. Not the cornea, choroid, or sclera.", "ow": ["The cornea is part of the fibrous coat.", "Correct. The retina is the nervous (inner) coat.", "The choroid is part of the vascular coat.", "The sclera is part of the fibrous coat."]}'),
  ('84304928-12','{"options": ["Muller cells only", "Amacrine and horizontal cells only", "Bipolar and ganglion cells only", "Rods and cones"], "correct": 3, "decode": "The retina''s PHOTORECEPTORS are the RODS and CONES. Muller, bipolar, ganglion, amacrine, and horizontal cells are other retinal cells.", "ow": ["Muller cells are glia, not photoreceptors.", "Amacrine and horizontal cells are interneurons, not photoreceptors.", "Bipolar and ganglion cells relay signals, not detect light.", "Correct. Rods and cones are the photoreceptors."]}'),
  ('30071967-y','{"options": ["Color vision", "Accommodation", "Vision in dim illumination", "High-acuity central vision"], "correct": 2, "decode": "RODS handle DIM (scotopic) vision (high sensitivity, no color). Cones handle color and acuity.", "ow": ["Color vision is a cone function.", "Accommodation is a lens function, not a rod one.", "Correct. Rods provide vision in dim light.", "High-acuity central vision is a cone function."]}'),
  ('d8091aeb-z','{"options": ["Color and high-acuity vision", "Peripheral vision only", "Night vision", "Scotopic vision"], "correct": 0, "decode": "Cones give COLOR and high-acuity (photopic) vision.", "ow": ["Correct. Cones handle color and high-acuity vision.", "Peripheral vision is a rod role.", "Night vision is a rod (scotopic) role.", "Scotopic vision is rod-driven, not cone."]}'),
  ('a55d0ad7-15','{"options": ["Ora serrata", "Optic disc", "Fovea centralis", "Peripheral retina"], "correct": 2, "decode": "The area of GREATEST acuity is the FOVEA CENTRALIS (cone-packed macular center). Not the disc, ora, or periphery.", "ow": ["The ora serrata is the peripheral edge, low acuity.", "The optic disc is the blind spot.", "Correct. The fovea centralis has the greatest acuity.", "The peripheral retina is rod-rich, lower acuity."]}'),
  ('df12fa47-v','{"options": ["Macula", "Optic disc", "Ciliary body", "Choroid only"], "correct": 0, "decode": "The fovea sits within the MACULA (the central retinal area). Not the disc, ciliary body, or choroid.", "ow": ["Correct. The fovea lies within the macula.", "The optic disc is the nerve head, separate from the fovea.", "The ciliary body is anterior, not retinal.", "The choroid is the vascular layer, not the site of the fovea."]}'),
  ('08ea45ee-1e','{"options": ["Contains only rods", "Contains only cones", "Has excessive pigmentation", "Contains no photoreceptors"], "correct": 3, "decode": "The optic disc is the blind spot because it contains NO PHOTORECEPTORS.", "ow": ["It is not selectively rod-only.", "It is not selectively cone-only.", "Pigmentation is not why it is blind.", "Correct. The disc has no photoreceptors."]}'),
  ('7e9fd53f-w','{"options": ["III", "V", "IV", "II"], "correct": 3, "decode": "The optic nerve is cranial nerve II. Not III, IV, or V.", "ow": ["CN III is the oculomotor nerve.", "CN V is the trigeminal nerve.", "CN IV is the trochlear nerve.", "Correct. The optic nerve is CN II."]}'),
  ('08db3981-1h','{"options": ["Iris to ciliary body", "Cornea to lens", "Lens to sclera", "Retina to brain"], "correct": 3, "decode": "The optic nerve carries visual information from the RETINA to the BRAIN. Not iris, cornea, or lens pathways.", "ow": ["The iris and ciliary body are not the visual signal path.", "The cornea-to-lens is an optical, not neural, path.", "The lens-to-sclera is not a neural pathway.", "Correct. The optic nerve carries signals from retina to brain."]}'),
  ('dcbd6aae-x','{"options": ["Subretinal space", "Vitreous cavity only", "Optic nerve", "Anterior and posterior chambers"], "correct": 3, "decode": "Aqueous humor fills the ANTERIOR and POSTERIOR chambers (in front of the vitreous). Not the vitreous cavity, subretinal space, or nerve.", "ow": ["The subretinal space is not where aqueous sits.", "The vitreous cavity holds vitreous, not aqueous.", "The optic nerve is not a fluid chamber.", "Correct. Aqueous fills the anterior and posterior chambers."]}'),
  ('98d7fa1d-1m','{"options": ["Canal of Schlemm", "Nasolacrimal duct", "Vitreous chamber", "Optic canal"], "correct": 0, "decode": "Aqueous drains mainly through the CANAL OF SCHLEMM (via the trabecular meshwork). Not the nasolacrimal duct (tears), vitreous, or optic canal.", "ow": ["Correct. Aqueous drains via the canal of Schlemm.", "The nasolacrimal duct drains tears, not aqueous.", "The vitreous chamber is not a drainage route.", "The optic canal transmits the nerve, not aqueous."]}'),
  ('e94bef21-u','{"options": ["Conjunctival sac", "Posterior segment of the eye", "Corneal stroma", "Anterior chamber"], "correct": 1, "decode": "The vitreous body occupies the POSTERIOR segment of the eye (behind the lens). Not the conjunctival sac, corneal stroma, or anterior chamber.", "ow": ["The conjunctival sac is on the surface, not the vitreous space.", "Correct. The vitreous occupies the posterior segment.", "The corneal stroma is a corneal layer, not the vitreous.", "The anterior chamber holds aqueous, not vitreous."]}'),
  ('cabbbcdd-n','{"options": ["Maintain the shape of the eyeball", "Produce tears", "Produce aqueous humor", "Control pupil size"], "correct": 0, "decode": "The vitreous helps MAINTAIN the SHAPE of the eyeball (and supports the retina). It does not make tears or aqueous, or control the pupil.", "ow": ["Correct. The vitreous maintains the eye''s shape.", "Tears come from the lacrimal glands, not the vitreous.", "Aqueous comes from the ciliary body, not the vitreous.", "Pupil size is controlled by the iris, not the vitreous."]}'),
  ('178fa2cf-1c','{"options": ["30-40 mmHg", "10-21 mmHg", "50-60 mmHg", "0-5 mmHg"], "correct": 1, "decode": "Normal IOP is about 10-21 mmHg. Higher ranges are elevated; 0-5 is hypotony.", "ow": ["30-40 mmHg is markedly elevated.", "Correct. Normal IOP is 10-21 mmHg.", "50-60 mmHg is dangerously high.", "0-5 mmHg is hypotony, too low."]}'),
  ('76f8cc77-q','{"options": ["The entire cornea and the whole pupil margin", "The retina and most of the optic nerve head", "The crystalline lens and its whole capsule", "Anterior sclera and inner surfaces of the eyelids"], "correct": 3, "decode": "The conjunctiva covers the ANTERIOR SCLERA (bulbar) and the INNER eyelids (palpebral); it stops at the limbus, so it does NOT cover the cornea. Pick the sclera-and-lid option.", "ow": ["The conjunctiva stops at the limbus; it does not cover the cornea.", "The retina and optic nerve are inside the eye, not conjunctiva.", "The lens and capsule are inside the eye.", "Correct. The conjunctiva covers the anterior sclera and inner lids."]}'),
  ('780c3485-11','{"options": ["Aqueous tears", "Aqueous humor", "Vitreous humor", "Mucus only"], "correct": 0, "decode": "The lacrimal gland makes AQUEOUS TEARS (the watery reflex layer). Aqueous HUMOR is ciliary body; vitreous is embryonic; mucus is goblet cells.", "ow": ["Correct. The lacrimal gland makes aqueous tears.", "Aqueous HUMOR comes from the ciliary body, not the lacrimal gland.", "Vitreous is embryologic, not made by the lacrimal gland.", "Mucus comes from goblet cells, not the lacrimal gland."]}'),
  ('693fca48-1b','{"options": ["Lacrimal puncta", "Pupil", "Canal of Schlemm", "Optic canal"], "correct": 0, "decode": "Tears drain through the LACRIMAL PUNCTA (into the canaliculi and sac). Not the pupil, canal of Schlemm (aqueous), or optic canal.", "ow": ["Correct. Tears drain through the lacrimal puncta.", "The pupil is an optical opening, not a tear drain.", "The canal of Schlemm drains aqueous, not tears.", "The optic canal transmits the nerve, not tears."]}'),
  ('bed194cc-1q','{"options": ["Medial rectus", "Superior rectus", "Inferior oblique", "Lateral rectus"], "correct": 3, "decode": "ABDUCTION is done by the LATERAL rectus (LR6). The medial rectus adducts; the others are elevators/depressors.", "ow": ["The medial rectus adducts, the opposite of abduction.", "The superior rectus elevates, not abducts.", "The inferior oblique elevates/extorts, not abducts.", "Correct. The lateral rectus abducts the eye."]}'),
  ('f434e40c-10','{"options": ["Depression", "Adduction", "Elevation", "Abduction"], "correct": 1, "decode": "The MEDIAL rectus primarily ADDUCTS (turns the eye nasally). Not depression, elevation, or abduction.", "ow": ["Depression is an inferior-rectus/oblique action.", "Correct. The medial rectus adducts the eye.", "Elevation is a superior-rectus/oblique action.", "Abduction is the lateral rectus''s job, the opposite."]}'),
  ('10bf26ff-1d','{"options": ["CN III", "CN II", "CN IV", "CN VI"], "correct": 3, "decode": "The LATERAL rectus is supplied by CN VI (abducens), by the LR6 rule. Not CN III, IV, or II.", "ow": ["CN III runs most other eye muscles, not the lateral rectus.", "CN II is the optic nerve (sensory), not a motor nerve.", "CN IV runs the superior oblique, not the lateral rectus.", "Correct. The lateral rectus is CN VI."]}'),
  ('352b989a-1f','{"options": ["CN III", "CN IV", "CN V", "CN VI"], "correct": 1, "decode": "The SUPERIOR OBLIQUE is supplied by CN IV (trochlear), by the SO4 rule. Not CN III, V, or VI.", "ow": ["CN III runs most eye muscles, but not the superior oblique.", "Correct. The superior oblique is CN IV.", "CN V is sensory (trigeminal), not a motor nerve here.", "CN VI runs the lateral rectus, not the superior oblique."]}'),
  ('b238540d-14','{"options": ["CN VI", "CN III", "CN II", "CN IV"], "correct": 1, "decode": "MOST extraocular muscles (SR, IR, MR, IO, and levator) are run by CN III. Only LR (CN VI) and SO (CN IV) are exceptions.", "ow": ["CN VI runs only the lateral rectus.", "Correct. CN III runs most extraocular muscles.", "CN II is the optic (sensory) nerve.", "CN IV runs only the superior oblique."]}'),
  ('d6514eff-1a','{"options": ["Extorsion only", "Adduction only", "Intorsion", "Abduction only"], "correct": 2, "decode": "The SUPERIOR OBLIQUE''s primary action is INTORSION (secondary depression and abduction). Obliques torsion first; the superior one intorts.", "ow": ["Extorsion is the INFERIOR oblique''s action.", "Adduction is a rectus action, not the SO primary.", "Correct. The superior oblique primarily intorts.", "Abduction is a secondary SO action, not primary."]}'),
  ('f6ac1e11-11','{"options": ["Protecting the ocular surface and spreading the tear film", "Producing the aqueous humor within the eyeball", "Producing new photoreceptors within the retina", "Controlling the shape and focusing of the lens"], "correct": 0, "decode": "The eyelids PROTECT the ocular surface and SPREAD the tear film with each blink. They do not make aqueous, grow photoreceptors, or shape the lens.", "ow": ["Correct. The lids protect the surface and spread tears.", "Aqueous humor comes from the ciliary body, not the lids.", "Photoreceptors are in the retina, not made by lids.", "Lens shape is controlled by the ciliary muscle, not lids."]}'),
  ('2dfe6208-17','{"options": ["Cornea", "Retina", "Tarsal plates", "Choroid"], "correct": 2, "decode": "The meibomian glands lie within the TARSAL PLATES of the lids (oil glands). Not the cornea, retina, or choroid.", "ow": ["The cornea has no meibomian glands.", "The retina is neural tissue, not lid glands.", "Correct. Meibomian glands lie within the tarsal plates.", "The choroid is vascular tissue, not lid glands."]}'),
  ('22197944-1j','{"options": ["Rhodopsin used for dim-light vision", "Lipid component of the tear film", "The vitreous humor of the eyeball", "The aqueous humor of the eyeball"], "correct": 1, "decode": "Meibomian glands make the LIPID (oil) layer of the tear film. Not rhodopsin, vitreous, or aqueous.", "ow": ["Rhodopsin is a rod pigment, not a gland product.", "Correct. Meibomian glands make the lipid tear layer.", "Vitreous is embryologic, not a meibomian product.", "Aqueous humor comes from the ciliary body."]}'),
  ('35f2ff74-13','{"options": ["Tear production", "Central detailed vision", "Pupil dilation", "Peripheral vision"], "correct": 1, "decode": "The macula provides CENTRAL, detailed (high-acuity) vision. Not tears, pupil control, or peripheral vision.", "ow": ["Tear production is the lacrimal gland''s job.", "Correct. The macula provides central detailed vision.", "Pupil size is the iris''s job.", "Peripheral vision is the peripheral retina''s job."]}'),
  ('9e702656-1b','{"options": ["Producing the watery part of the tears", "Supporting photoreceptors and absorbing light", "Controlling accommodation of the lens", "Moving the whole eyeball in its orbit"], "correct": 1, "decode": "The RPE SUPPORTS photoreceptors and ABSORBS stray light (with melanin). It does not make tears, control the lens, or move the eye.", "ow": ["Tears come from the lacrimal glands, not the RPE.", "Correct. The RPE supports photoreceptors and absorbs light.", "Accommodation is the ciliary muscle''s job.", "Eye movement is the extraocular muscles'' job."]}'),
  ('03f3944c-20','{"options": ["Lens to cornea to pupil to aqueous humor to retina", "Retina to lens to cornea to pupil and then to sclera", "Cornea to aqueous humor to pupil to lens to vitreous to retina", "Pupil to sclera to lens to vitreous body to retina"], "correct": 2, "decode": "Light passes CORNEA -> aqueous -> pupil -> lens -> vitreous -> retina (front to back). Any sequence starting at the lens or retina is out of order.", "ow": ["Light hits the cornea first, not the lens.", "Light ends at the retina; it does not start there.", "Correct. Cornea, aqueous, pupil, lens, vitreous, retina.", "Light enters through the cornea/pupil, not the sclera."]}'),
  ('de439f74-28','{"options": ["CN IV", "CN VI", "CN III", "CN II"], "correct": 2, "decode": "The remaining muscles (SR, IR, MR, IO and levator) are run by CN III. LR is CN VI and SO is CN IV.", "ow": ["CN IV runs only the superior oblique.", "CN VI runs only the lateral rectus.", "Correct. The remaining muscles are CN III.", "CN II is the optic (sensory) nerve."]}'),
  ('97f02a32-1i','{"options": ["Superior rectus", "Inferior oblique", "Inferior rectus", "Superior oblique"], "correct": 0, "decode": "When ABDUCTED, the eye ELEVATES via the SUPERIOR RECTUS (its pure vertical position). This is how you isolate the SR on motility testing.", "ow": ["Correct. In abduction, the superior rectus elevates the eye.", "The inferior oblique elevates in ADDUCTION, not abduction.", "The inferior rectus depresses, not elevates.", "The superior oblique depresses in adduction."]}'),
  ('d14a8037-1j','{"options": ["Inferior rectus", "Superior oblique", "Superior rectus", "Inferior oblique"], "correct": 0, "decode": "When ABDUCTED, the eye DEPRESSES via the INFERIOR RECTUS (its pure vertical position). This isolates the IR on testing.", "ow": ["Correct. In abduction, the inferior rectus depresses the eye.", "The superior oblique depresses in ADDUCTION, not abduction.", "The superior rectus elevates, not depresses.", "The inferior oblique elevates, not depresses."]}'),
  ('334e5223-1d','{"options": ["Inferior rectus", "Inferior oblique", "Superior oblique", "Superior rectus"], "correct": 1, "decode": "When ADDUCTED, the eye ELEVATES via the INFERIOR OBLIQUE. This isolates the IO on motility testing.", "ow": ["The inferior rectus depresses, not elevates.", "Correct. In adduction, the inferior oblique elevates the eye.", "The superior oblique depresses in adduction.", "The superior rectus elevates in ABDUCTION, not adduction."]}'),
  ('540f57d8-1e','{"options": ["Inferior rectus", "Superior rectus", "Superior oblique", "Inferior oblique"], "correct": 2, "decode": "When ADDUCTED, the eye DEPRESSES via the SUPERIOR OBLIQUE. This isolates the SO on motility testing.", "ow": ["The inferior rectus depresses in ABDUCTION, not adduction.", "The superior rectus elevates, not depresses.", "Correct. In adduction, the superior oblique depresses the eye.", "The inferior oblique elevates in adduction."]}'),
  ('fe7269a7-18','{"options": ["Elevation", "Depression", "Intorsion", "Abduction"], "correct": 0, "decode": "The SUPERIOR RECTUS''s primary action is ELEVATION (with secondary intorsion and adduction). Pick elevation.", "ow": ["Correct. The superior rectus primarily elevates.", "Depression is the inferior rectus/superior oblique.", "Intorsion is a secondary SR action, not primary.", "Abduction is the lateral rectus''s job."]}'),
  ('b7d75cd5-26','{"options": ["Convergence", "Dispersion", "Accommodation", "Refraction"], "correct": 2, "decode": "Changing the eye''s optical power to focus near is ACCOMMODATION. Convergence is eye turning; refraction is bending of light; dispersion is color spread.", "ow": ["Convergence is the eyes turning in, not focus change.", "Dispersion is splitting light into colors.", "Correct. Accommodation changes focusing power for near.", "Refraction is the bending of light, not the focus change itself."]}'),
  ('f9de5a19-1s','{"options": ["Lens", "Cornea", "Retina", "Iris"], "correct": 1, "decode": "MOST refractive power comes from the CORNEA (~43 D vs the lens ~19 D). Not the retina or iris.", "ow": ["The lens adds power but less than the cornea.", "Correct. The cornea provides most refractive power.", "The retina detects light; it does not refract.", "The iris controls light entry, not refraction."]}'),
  ('b8aef20f-1s','{"options": ["+60 D", "+10 D", "+43 D", "+20 D"], "correct": 0, "decode": "The eye''s total refractive power at distance is about +60 D (cornea ~43 + lens ~19, minus overlap). Not +10, +20, or +43 alone.", "ow": ["Correct. The eye''s total power is about +60 D.", "+10 D is far too low for the whole eye.", "+43 D is the CORNEA alone, not the whole eye.", "+20 D is roughly the lens alone, not the whole eye."]}'),
  ('3d95a0f7-19','{"options": ["Lymph", "Aqueous humor", "Vitreous humor", "Blood"], "correct": 2, "decode": "The LARGEST chamber (posterior segment) is filled with VITREOUS humor. Aqueous fills the smaller anterior chambers; not lymph or blood.", "ow": ["The eye''s chambers hold humors, not lymph.", "Aqueous fills the small anterior/posterior chambers, not the largest.", "Correct. The largest chamber holds the vitreous humor.", "Blood fills vessels, not the eye''s optical chamber."]}'),
  ('f876081c-w','{"options": ["Cylindrical cavity", "Four-sided pyramid", "Flat cavity", "Circular cavity"], "correct": 1, "decode": "The orbit is a FOUR-SIDED PYRAMID, with the apex at the optic canal and base at the orbital rim. Not a cylinder, flat, or circular cavity.", "ow": ["The orbit narrows to an apex; it is not a uniform cylinder.", "Correct. The orbit is a four-sided pyramid.", "The orbit is deep, not flat.", "The orbit is pyramidal, not simply circular."]}'),
  ('7d5b572a-1s','{"options": ["Occipital", "Temporal", "Mandible", "Ethmoid"], "correct": 3, "decode": "The ETHMOID (lamina papyracea) forms a major part of the MEDIAL orbital wall. Occipital, temporal, and mandible are not orbital bones.", "ow": ["The occipital bone is at the back of the skull, not the orbit.", "The temporal bone is not an orbital wall.", "The mandible is the jaw, not an orbital bone.", "Correct. The ethmoid forms much of the medial wall."]}'),
  ('e2e0bb84-1q','{"options": ["Orbital plate of the maxillary bone", "Perpendicular plate of the ethmoid bone", "Orbital process of the zygomatic bone", "Lesser wing of sphenoid"], "correct": 3, "decode": "The orbital ROOF is the FRONTAL bone plus the LESSER WING of the sphenoid. The maxilla is the floor; the ethmoid is medial; the zygomatic is lateral.", "ow": ["The maxilla forms the floor, not the roof.", "The ethmoid is in the medial wall, not the roof.", "The zygomatic is in the lateral wall, not the roof.", "Correct. The roof is frontal bone plus the lesser wing of the sphenoid."]}'),
  ('bd56ac4c-1k','{"options": ["Superomedial", "Superolateral", "Inferomedial", "Inferolateral"], "correct": 1, "decode": "The lacrimal gland sits SUPEROLATERAL in the orbit (upper outer, in the lacrimal fossa of the frontal bone). Not superomedial or inferior.", "ow": ["The superomedial region holds the trochlea, not the gland.", "Correct. The lacrimal gland is superolateral.", "The inferomedial region holds the lacrimal sac area, not the gland.", "The gland is superolateral, not inferolateral."]}'),
  ('750d6c5e-2y','{"options": ["Iris", "Retina", "Lens", "Orbit"], "correct": 3, "decode": "The bony ORBIT protects the eye from trauma and anchors the extraocular muscles. The iris, retina, and lens are internal soft structures.", "ow": ["The iris controls light, it does not protect or anchor muscles.", "The retina detects light; it is not protective bone.", "The lens focuses light; it is not protective bone.", "Correct. The orbit protects the eye and anchors the muscles."]}'),
  ('122837ea-20','{"options": ["4", "7", "6", "5"], "correct": 2, "decode": "SIX extraocular muscles move the eyeball (4 recti + 2 obliques). The levator raises the lid but is not counted for globe movement.", "ow": ["Four counts only the recti, missing the obliques.", "Seven overcounts (adds the levator, which moves the lid).", "Correct. Six muscles move the eyeball.", "Five undercounts the six eye-movement muscles."]}'),
  ('fc0e9c2f-s','{"options": ["Inferior rectus", "Medial rectus", "Lateral rectus", "Superior rectus"], "correct": 2, "decode": "The LATERAL rectus ABDUCTS the eye. The medial rectus adducts; the vertical recti elevate/depress.", "ow": ["The inferior rectus depresses, not abducts.", "The medial rectus adducts, the opposite.", "Correct. The lateral rectus abducts the eye.", "The superior rectus elevates, not abducts."]}'),
  ('ade4ef25-s','{"options": ["Superior oblique", "Lateral rectus", "Medial rectus", "Inferior oblique"], "correct": 2, "decode": "The MEDIAL rectus ADDUCTS the eye (turns it nasally). The lateral rectus abducts.", "ow": ["The superior oblique intorts/depresses, not simple adduction.", "The lateral rectus abducts, the opposite.", "Correct. The medial rectus adducts the eye.", "The inferior oblique elevates/extorts, not adducts."]}'),
  ('eecfaaf5-16','{"options": ["CN VI", "CN II", "CN III", "CN IV"], "correct": 0, "decode": "The lateral rectus is innervated by CN VI (LR6). Not CN II, III, or IV.", "ow": ["Correct. The lateral rectus is CN VI.", "CN II is the optic (sensory) nerve.", "CN III runs most other muscles, not the lateral rectus.", "CN IV runs the superior oblique."]}'),
  ('75ec1937-1f','{"options": ["Superior colliculus", "Edinger-Westphal nucleus", "Medial geniculate nucleus", "Lateral geniculate nucleus"], "correct": 3, "decode": "The relay nucleus for CONSCIOUS vision is the LATERAL geniculate nucleus. The MEDIAL geniculate is for hearing; the colliculus and E-W nucleus are reflex centers.", "ow": ["The superior colliculus handles reflex gaze, not conscious vision relay.", "The Edinger-Westphal nucleus is for the pupil reflex.", "The MEDIAL geniculate relays hearing, not vision.", "Correct. The lateral geniculate nucleus relays conscious vision."]}'),
  ('f489f7aa-18','{"options": ["Abduction", "Elevation", "Intorsion", "Depression"], "correct": 3, "decode": "The INFERIOR rectus''s primary action is DEPRESSION (with secondary extorsion and adduction). Pick depression.", "ow": ["Abduction is the lateral rectus''s job.", "Elevation is the superior rectus/inferior oblique.", "Intorsion is the superior oblique''s action.", "Correct. The inferior rectus primarily depresses."]}'),
  ('d9d74501-2a','{"options": ["Lacrimal gland", "Inferior oblique only", "None of the recti", "Medial rectus"], "correct": 3, "decode": "The four RECTI (including the MEDIAL rectus) arise from the annulus of Zinn. The inferior oblique arises from the orbital floor; the lacrimal gland is not a muscle.", "ow": ["The lacrimal gland is a gland, not a muscle from the ring.", "The inferior oblique arises from the floor, not the ring.", "The recti DO arise from the ring, so ''none'' is wrong.", "Correct. The medial rectus arises from the annulus of Zinn."]}'),
  ('4e900ef3-1a','{"options": ["Maxilla", "Ethmoid", "Sphenoid", "Frontal bone"], "correct": 0, "decode": "The orbital FLOOR is mainly the MAXILLA (the blowout-fracture site). Not ethmoid (medial), sphenoid (apex), or frontal (roof).", "ow": ["Correct. The maxilla forms the orbital floor.", "The ethmoid is in the medial wall.", "The sphenoid is at the apex/lateral wall.", "The frontal bone forms the roof."]}'),
  ('d018c5bc-1y','{"options": ["Orbital plate of the ethmoid bone", "Orbital surface of the palatine bone", "Greater wing of sphenoid", "Posterior lacrimal crest of the lacrimal bone"], "correct": 2, "decode": "The LATERAL wall is the ZYGOMATIC bone plus the GREATER wing of the sphenoid. Not ethmoid, palatine, or lacrimal (those are medial/floor).", "ow": ["The ethmoid is in the medial wall.", "The palatine contributes to the floor, not the lateral wall.", "Correct. The lateral wall is zygomatic plus the greater wing of the sphenoid.", "The lacrimal bone is in the medial wall."]}'),
  ('1a54a304-t','{"options": ["Optic nerve and ophthalmic artery", "Facial nerve and vein", "Maxillary nerve and artery", "Trochlear nerve and artery"], "correct": 0, "decode": "The OPTIC CANAL transmits the OPTIC NERVE and OPHTHALMIC ARTERY. Not facial, maxillary, or trochlear structures.", "ow": ["Correct. The optic canal transmits the optic nerve and ophthalmic artery.", "The facial nerve exits the stylomastoid foramen.", "The maxillary nerve uses foramen rotundum.", "The trochlear nerve uses the superior orbital fissure."]}'),
  ('31aeba6a-1z','{"options": ["CN VII and VIII", "CN III, IV, V1, and VI", "CN IX and X", "CN I and II only"], "correct": 1, "decode": "The superior orbital fissure transmits CN III, IV, V1, and VI (eye-movement and sensory branches). Not CN I/II, VII/VIII, or IX/X.", "ow": ["CN VII and VIII exit through the internal acoustic meatus.", "Correct. The fissure transmits CN III, IV, V1, and VI.", "CN IX and X exit the jugular foramen.", "CN I is olfactory and CN II uses the optic canal."]}'),
  ('15615e50-11','{"options": ["Iris, ciliary body, choroid", "Lens, vitreous, aqueous", "Retina, optic nerve, macula", "Cornea, sclera, conjunctiva"], "correct": 0, "decode": "The uveal tract is the IRIS, CILIARY BODY, and CHOROID (the vascular coat). The other options are non-uveal structures.", "ow": ["Correct. The uvea is iris, ciliary body, and choroid.", "Lens, vitreous, aqueous are not the uvea.", "Retina, optic nerve, macula are neural, not uvea.", "Cornea, sclera, conjunctiva are fibrous/surface, not uvea."]}'),
  ('723eb92b-15','{"options": ["Retina", "Sclera", "Choroid", "Cornea"], "correct": 0, "decode": "The INNERMOST layer of the eyeball is the RETINA (nervous coat). The choroid is middle; the sclera/cornea are outer.", "ow": ["Correct. The retina is the innermost layer.", "The sclera is the outer coat.", "The choroid is the middle coat.", "The cornea is the front of the outer coat."]}'),
  ('c0177901-1u','{"options": ["Pupil", "Optic disc", "Fovea", "Canal of Schlemm"], "correct": 0, "decode": "The iris controls light entering through the PUPIL (its central aperture). Not the optic disc, fovea, or canal of Schlemm.", "ow": ["Correct. The iris controls light through the pupil.", "The optic disc is the nerve head, not the light aperture.", "The fovea is the acuity center, not the aperture.", "The canal of Schlemm drains aqueous, not light."]}'),
  ('94b242d3-2k','{"options": ["Optic disc", "Ora serrata", "Peripheral retina", "Fovea centralis"], "correct": 3, "decode": "The highest cone density and sharpest vision is at the FOVEA CENTRALIS. Not the disc, ora, or periphery.", "ow": ["The optic disc has no photoreceptors (blind spot).", "The ora serrata is the peripheral edge, rod territory.", "The peripheral retina is rod-dominated, lower acuity.", "Correct. The fovea centralis has the highest cone density."]}'),
  ('9fd63627-1g','{"options": ["30 mm", "24 mm", "18 mm", "12 mm"], "correct": 1, "decode": "The adult axial length is about 24 mm. Not 30 (too long, high myope), 18, or 12 mm.", "ow": ["30 mm is a long, highly myopic eye.", "Correct. The adult axial length is about 24 mm.", "18 mm is a short, hyperopic eye.", "12 mm is far too short."]}'),
  ('68b7913d-1m','{"options": ["Iris and ciliary body", "Retina and choroid", "Retina and iris", "Sclera and cornea"], "correct": 3, "decode": "The OUTERMOST fibrous layer is the SCLERA and CORNEA. The others are the vascular or neural coats.", "ow": ["Iris and ciliary body are part of the uvea (middle coat).", "Retina and choroid are inner and middle coats.", "Retina and iris are neural and uveal, not fibrous.", "Correct. The fibrous coat is sclera and cornea."]}'),
  ('21c26063-1o','{"options": ["Sclera", "Cornea", "Choroid", "Conjunctiva"], "correct": 1, "decode": "The transparent front of the fibrous tunic is the CORNEA. The sclera is the opaque part; the conjunctiva and choroid are other structures.", "ow": ["The sclera is the opaque part of the fibrous tunic.", "Correct. The cornea is the transparent anterior fibrous tunic.", "The choroid is the vascular coat, not fibrous.", "The conjunctiva is a mucous membrane, not the fibrous tunic."]}'),
  ('effa731d-w','{"options": ["CN IV", "CN II", "CN I", "CN III"], "correct": 1, "decode": "The optic nerve is CN II. Not CN I (olfactory), III, or IV.", "ow": ["CN IV is the trochlear nerve.", "Correct. The optic nerve is CN II.", "CN I is the olfactory nerve.", "CN III is the oculomotor nerve."]}'),
  ('f67b50f9-1k','{"options": ["Optic tract", "Lateral geniculate nucleus", "Optic chiasm", "Visual cortex"], "correct": 2, "decode": "The PARTIAL crossing of optic nerve fibers (nasal fibers cross) occurs at the OPTIC CHIASM. Not the tract, LGN, or cortex.", "ow": ["The optic tract is after the crossing, not where it occurs.", "The LGN is a relay after the chiasm.", "Correct. The partial decussation occurs at the optic chiasm.", "The visual cortex is the final destination, not the crossing."]}'),
  ('b3eebdcf-2e','{"options": ["440 nm", "507 nm", "535 nm", "555 nm"], "correct": 1, "decode": "Fully dark-adapted vision is SCOTOPIC (rod-driven), and rods peak near 507 nm.", "ow": ["440 nm is the S-cone (blue) peak, a photopic value.", "Correct. Dark-adapted vision is rod-driven; rods peak near 507 nm.", "535 nm is the M-cone (green) peak, a cone value.", "555 nm is the photopic cone peak, used in bright light, not after dark adaptation."]}'),
  ('3b193e37-1d','{"options": ["30–40 minutes", "7 minutes", "15 minutes", "60 minutes"], "correct": 0, "decode": "Cones plateau at ~7 min, but rhodopsin regenerates slowly, so full ROD adaptation takes 30–40 min.", "ow": ["Correct. Slow rhodopsin regeneration makes full rod adaptation take 30–40 minutes.", "7 minutes is only the cone plateau (Kohlrausch kink), not full adaptation.", "15 minutes is partway along the rod branch, not complete.", "60 minutes overstates it; adaptation is essentially done by 40."]}'),
  ('7c1ee1f9-2t','{"options": ["Ricco point", "Stiles-Crawford effect", "Purkinje shift", "Kohlrausch kink"], "correct": 3, "decode": "The KOHLRAUSCH KINK is the ~7-minute break where cones plateau and rods take over.", "ow": ["Ricco''s law is spatial summation, not a point on the adaptation curve.", "The Stiles-Crawford effect is directional sensitivity of cones, not a curve inflection.", "The Purkinje shift is the 555→507 nm sensitivity change, not the 7-minute break.", "Correct. The Kohlrausch kink is the ~7-minute cone-to-rod handover."]}'),
  ('8644b0c5-2x','{"options": ["Positive angle kappa", "Large angle alpha", "Bilateral exotropia", "Esotropia"], "correct": 0, "decode": "POSITIVE kappa puts the pupil NASAL, so the reflex looks temporal, giving pseudo-exotropia, confirmed by a negative cover test.", "ow": ["Correct. Positive kappa shifts the pupil nasal, making the reflex look temporal with no real deviation.", "Angle alpha is measured at the nodal point and does not itself produce this reflex-plus-negative-cover picture.", "True exotropia would show outward movement on cover test; here there is none.", "Esotropia gives a nasal-looking reflex and inward cover movement, the opposite."]}'),
  ('3e9b67ec-25','{"options": ["True esotropia", "True exotropia", "Negative angle kappa", "Positive angle kappa"], "correct": 2, "decode": "NEGATIVE kappa puts the pupil TEMPORAL, so the reflex sits nasal, giving pseudo-esotropia, confirmed by a negative cover test.", "ow": ["True esotropia would show inward movement on cover test; here there is none.", "True exotropia gives a temporal-looking reflex, the opposite pattern.", "Correct. Negative kappa shifts the pupil temporal, making the reflex look nasal with no real deviation.", "Positive kappa shifts the pupil nasal and mimics exotropia, not esotropia."]}'),
  ('2cd3691c-21','{"options": ["Re-isomerization of retinal in the RPE", "Photoisomerization in the outer segment", "Cone pigment synthesis in the fovea", "Glutamate release in the dark current"], "correct": 0, "decode": "Rhodopsin regeneration needs 11-cis retinal remade from all-trans retinal in the RPE; block that and regeneration stops.", "ow": ["Correct. Re-isomerization of retinal happens in the RPE and is the regeneration step.", "Photoisomerization is the light-triggered step, not the regeneration that follows.", "Cone pigment synthesis is separate from rod rhodopsin regeneration.", "Glutamate release is dark-current synaptic activity, unrelated to regeneration."]}'),
  ('870b3275-q','{"options": ["No photoreceptors present", "Equal numbers of rods and cones", "Rod density is highest here", "Rods absent; cones densest"], "correct": 3, "decode": "The fovea excludes rods entirely and holds the highest CONE density for peak acuity.", "ow": ["The fovea is packed with cones, not devoid of photoreceptors; that describes the optic disc.", "Rods and cones are not equal here; the fovea is essentially all cones.", "Rod density peaks in the periphery, not the fovea.", "Correct. The fovea has no rods and the densest cones."]}'),
  ('6fa7afe4-1x','{"options": ["Accommodation improves periphery", "Cones are densest off-center", "The blind spot is central", "Rods peak at ~20° from the fovea"], "correct": 3, "decode": "Averted vision lands the image on peripheral retina where ROD density peaks (~20°), maximizing dim-light sensitivity.", "ow": ["Accommodation focuses the image; it does not boost peripheral sensitivity for a dim star.", "Cones are densest at the fovea, not off-center.", "The blind spot is not central; it is ~15° temporal.", "Correct. Rods peak ~20° from the fovea, so looking to the side aids scotopic detection."]}'),
  ('9b6db1c3-29','{"options": ["Torsion", "Vertical", "Horizontal", "Vergence"], "correct": 0, "decode": "The anteroposterior (Y) axis is the longest (24 mm) and rotation about it produces TORSION.", "ow": ["Correct. The AP/Y axis controls torsion.", "Vertical movements are about the X (transverse) axis.", "Horizontal movements are about the Z (vertical) axis.", "Vergence is a binocular act, not a single Fick axis."]}'),
  ('1c003396-1b','{"options": ["Vertical movements", "Horizontal movements", "Torsion", "No movement"], "correct": 1, "decode": "Rotation about the vertical (Z) axis produces HORIZONTAL movements.", "ow": ["Vertical movements are produced about the X (transverse) axis.", "Correct. The vertical Z axis produces horizontal movement.", "Torsion is produced about the anteroposterior Y axis.", "The eye does move about the Z axis, so ''no movement'' is wrong."]}'),
  ('918515be-12','{"options": ["The fovea", "The pupil center", "The nodal point", "The center of rotation"], "correct": 2, "decode": "Angle ALPHA (optical vs visual axis) is measured at the NODAL point; kappa is measured at the pupil.", "ow": ["The fovea is where the visual axis lands, not where alpha is measured.", "The pupil center is the reference for angle kappa, not alpha.", "Correct. Angle alpha is measured at the nodal point.", "The center of rotation is where the Fick axes cross, not the alpha reference."]}'),
  ('3cd77359-2h','{"options": ["Purkinje shift", "Stiles-Crawford effect", "Bezold-Brucke shift", "Troxler fading"], "correct": 0, "decode": "As light fades, peak sensitivity shifts from 555 nm to the scotopic 507 nm, so blues relatively brighten: the PURKINJE shift.", "ow": ["Correct. The Purkinje shift moves peak sensitivity toward blue-green in dim light.", "The Stiles-Crawford effect is directional cone sensitivity, not a dusk brightness change.", "The Bezold-Brucke shift is a hue change with intensity, not this scotopic brightening.", "Troxler fading is disappearance of a steady peripheral image, unrelated."]}'),
  ('9b6bfeb5-19','{"options": ["Temporal summation", "Chromatic summation", "Binocular summation", "Spatial summation"], "correct": 3, "decode": "Ricco''s law is SPATIAL summation: within the critical area, area × intensity is constant.", "ow": ["Temporal summation is governed by Bunsen-Roscoe, not Ricco.", "There is no ''chromatic summation'' law by this name.", "Binocular summation is a separate two-eye effect.", "Correct. Ricco''s law describes spatial summation."]}'),
  ('ecdf288c-2i','{"options": ["Weber''s law", "Bloch''s exception", "Bunsen-Roscoe law", "Ricco''s law"], "correct": 2, "decode": "Bunsen-Roscoe governs TEMPORAL summation: time × intensity is constant for a brief stimulus.", "ow": ["Weber''s law is about the just-noticeable difference ratio, not temporal summation.", "Bloch''s law is another name here but is offered as an ''exception'', which is wrong.", "Correct. Bunsen-Roscoe covers temporal summation.", "Ricco''s law is spatial (area × intensity), not temporal."]}'),
  ('d853b5c7-1t','{"options": ["Rhodopsin", "Chlorolabe", "Cyanolabe", "Erythrolabe"], "correct": 3, "decode": "ERYTHROLABE is the long-wavelength (red) L-cone pigment.", "ow": ["Rhodopsin is the rod pigment, not a red cone pigment.", "Chlorolabe is the green (M-cone) pigment.", "Cyanolabe is the blue (S-cone) pigment.", "Correct. Erythrolabe is the red L-cone pigment."]}'),
  ('df8a3d05-2g','{"options": ["24 mm behind the cornea", "at the nodal point", "6.5 mm behind the cornea", "13.5 mm behind the cornea"], "correct": 3, "decode": "The center of rotation, where all Fick axes cross, sits ~13.5 mm behind the cornea.", "ow": ["24 mm is the axial length of the globe, not the center of rotation.", "The nodal point is an optical reference, not the mechanical center of rotation.", "6.5 mm is far too shallow for the center of rotation.", "Correct. The center of rotation is ~13.5 mm behind the cornea."]}'),
  ('05749d26-1x','{"options": ["10× more sensitive", "100× more sensitive", "Equally sensitive", "1000× more sensitive"], "correct": 3, "decode": "Dark adaptation improves threshold by ~3 log units, making rods roughly 1000× more sensitive than cones.", "ow": ["10× understates it by two log units.", "100× is one log unit short of the ~3 log improvement.", "Rods end up far more sensitive than cones, not equal.", "Correct. ~3 log units means about 1000× greater rod sensitivity."]}'),
  ('3e0165f4-1j','{"options": ["Binocular viewing", "Smaller pupil", "Monocular viewing", "Bright background"], "correct": 0, "decode": "Binocular viewing combines both eyes'' neural signals, LOWERING threshold (higher sensitivity).", "ow": ["Correct. Two eyes summate neurally, lowering threshold.", "A smaller pupil lets in less light, raising threshold.", "Monocular viewing loses binocular summation, so it is less sensitive.", "A bright background raises threshold, the opposite of what is asked."]}'),
  ('a2a55d93-1u','{"options": ["Contrast at low spatial frequency", "Color", "Motion", "Form"], "correct": 1, "decode": "COLOR is the most vulnerable function in optic nerve disease; it fails first (basis of red desaturation).", "ow": ["Low-frequency contrast is not the earliest loss; color goes first.", "Correct. Color conduction is the most vulnerable and drops out earliest.", "Motion is the most resilient function, lost last.", "Form is more resilient than color."]}'),
  ('d55f062b-24','{"options": ["Stereopsis", "Fine acuity", "Motion", "Color"], "correct": 2, "decode": "MOTION perception is the most resilient function, lost last in optic nerve disease.", "ow": ["Stereopsis is not the most resilient single function tested here.", "Fine acuity degrades before motion.", "Correct. Motion is the most resilient, lost last.", "Color is the most vulnerable, lost first."]}'),
  ('02278be3-24','{"options": ["Only layer 1", "All six", "Layers 1, 4, 6", "Layers 2, 3, 5"], "correct": 2, "decode": "LGB layers 1, 4, 6 receive CONTRALATERAL (crossed, nasal) input.", "ow": ["Layer 1 alone is incomplete; crossed input is in 1, 4 and 6.", "Not all six; the eyes alternate across layers.", "Correct. Layers 1, 4, 6 are contralateral.", "Layers 2, 3, 5 are ipsilateral, not contralateral."]}'),
  ('873ac05d-1n','{"options": ["Color naming", "Basic feature detection", "Object recognition", "Eye movement planning"], "correct": 1, "decode": "Area 17 (primary visual cortex) detects BASIC FEATURES, not whole-object identity.", "ow": ["Color naming is a higher-order function beyond area 17.", "Correct. Area 17 performs basic feature detection.", "Object recognition needs the ventral stream beyond area 17.", "Eye-movement planning is a frontal/brainstem role, not area 17."]}'),
  ('00b9112d-18','{"options": ["''What'' object recognition", "Accommodation", "''Where / how'' spatial and motion processing", "Pupil reflexes"], "correct": 0, "decode": "The VENTRAL (''what'') stream runs to the temporal lobe for object recognition.", "ow": ["Correct. The ventral stream handles ''what'' object recognition.", "Accommodation is a reflex, not a ventral-stream perceptual task.", "''Where/how'' spatial and motion processing is the dorsal stream.", "Pupil reflexes are subcortical, not ventral-stream."]}'),
  ('c6e3d75e-y','{"options": ["Object identity", "Faces", "Spatial location and motion", "Color"], "correct": 2, "decode": "The DORSAL (''where/how'') stream runs to the parietal lobe for spatial location and motion.", "ow": ["Object identity is the ventral ''what'' stream.", "Face recognition is a ventral-stream function.", "Correct. The dorsal stream processes spatial location and motion.", "Color is processed in the ventral pathway, not the dorsal."]}'),
  ('9fa39af0-2s','{"options": ["Stays the same absolute value", "Doubles with the background", "Halves as intensity doubles", "Disappears at high intensity"], "correct": 1, "decode": "Weber''s law keeps ΔI/I constant, so when I doubles the absolute JND DOUBLES.", "ow": ["The JND does not stay a fixed absolute value; the ratio is what stays fixed.", "Correct. Constant ratio means the JND doubles when the background doubles.", "It does not halve; a bigger background needs a bigger difference.", "The JND does not disappear at high intensity."]}'),
  ('f13b3d2f-22','{"options": ["Early optic nerve disease", "Cataract", "Refractive error", "Macular hole"], "correct": 0, "decode": "Because color conduction is most vulnerable, red desaturation flags EARLY optic nerve disease.", "ow": ["Correct. Red desaturation signals early optic nerve compromise.", "Cataract dims and yellows overall, not selective red desaturation between eyes.", "Refractive error blurs; it does not desaturate red.", "A macular hole gives central metamorphopsia, not monocular red washout."]}'),
  ('88e5dac3-1d','{"options": ["Lateral geniculate", "Primary striate cortex", "Peristriate cortex", "Parastriate cortex"], "correct": 3, "decode": "Area 18 is the PARASTRIATE cortex (secondary visual area).", "ow": ["The lateral geniculate is a thalamic relay, not area 18.", "Primary striate cortex is area 17, not 18.", "Peristriate cortex is area 19.", "Correct. Area 18 is the parastriate cortex."]}'),
  ('fc2f6c6e-21','{"options": ["Object naming in both fields", "Vision in the contralateral field", "Motion perception only", "Color discrimination only"], "correct": 1, "decode": "Area 17 is primary visual cortex; a one-sided lesion drops the CONTRALATERAL field.", "ow": ["Object naming needs higher areas and both fields would not be equally hit by one-sided area 17 damage.", "Correct. A unilateral area 17 lesion causes a contralateral field defect.", "Motion loss alone points to area V5, not area 17.", "Color loss alone points to V4, not area 17."]}'),
  ('7fc8f7ee-26','{"options": ["The dorsal stream to parietal lobe", "The pretectal nuclei of midbrain", "The superior colliculus tectum", "The ventral stream to IT cortex"], "correct": 3, "decode": "Object recognition extends beyond area 17 through the VENTRAL stream to inferotemporal cortex.", "ow": ["The dorsal stream to parietal handles ''where/how'', not object recognition.", "The pretectal nuclei serve pupil reflexes, not recognition.", "The superior colliculus tectum handles orienting, not object identity.", "Correct. Recognition runs via the ventral stream to IT cortex."]}'),
  ('4a0cf1d9-1u','{"options": ["All", "2, 3, 5", "None", "1, 4, 6"], "correct": 1, "decode": "LGB layers 2, 3, 5 carry IPSILATERAL (uncrossed, temporal-retina) input.", "ow": ["Not all layers; the eyes alternate.", "Correct. Layers 2, 3, 5 are ipsilateral.", "The eyes are segregated by layer, so ''none'' is wrong.", "Layers 1, 4, 6 are contralateral, not ipsilateral."]}'),
  ('fdf72d46-1w','{"options": ["Contrast sensitivity", "Color vision", "Stereoacuity", "Visual acuity"], "correct": 0, "decode": "Because the JND scales with background, Weber''s law underlies CONTRAST sensitivity testing.", "ow": ["Correct. Weber''s law is the basis of contrast sensitivity.", "Color vision rests on cone opponency, not Weber''s law.", "Stereoacuity depends on retinal disparity, not Weber''s law.", "Visual acuity is a resolution limit, not a Weber-law contrast measure."]}'),
  ('855a45b7-1n','{"options": ["60°", "75°", "100°", "120°"], "correct": 2, "decode": "The TEMPORAL field is widest at 100° (nasal/superior 60°, inferior 75°).", "ow": ["60° is the nasal and superior extent, not temporal.", "75° is the inferior extent.", "Correct. Temporal extent is the widest at 100°.", "120° is the binocular overlap, not a monocular temporal extent."]}'),
  ('db6039ac-1v','{"options": ["45°", "60°", "75°", "100°"], "correct": 1, "decode": "Nasal and superior extents are each ~60°.", "ow": ["45° understates the nasal/superior extent.", "Correct. Nasal and superior are ~60° each.", "75° is the inferior extent.", "100° is the temporal extent."]}'),
  ('76c76dca-1r','{"options": ["45°", "60°", "75°", "100°"], "correct": 2, "decode": "The INFERIOR extent is ~75°, between the 60° nasal/superior and 100° temporal.", "ow": ["45° is too small for the inferior field.", "60° is the nasal/superior extent.", "Correct. Inferior extent is ~75°.", "100° is the temporal extent."]}'),
  ('1ed2c6c1-1c','{"options": ["60°", "90°", "120°", "180°"], "correct": 2, "decode": "The central 120° overlaps binocularly; each side adds a 30° monocular crescent.", "ow": ["60° is a single monocular extent, not the binocular overlap.", "90° understates the binocular field.", "Correct. About 120° is seen binocularly.", "180° is the full both-eyes horizontal span, not the binocular overlap."]}'),
  ('f70e477d-1p','{"options": ["90°", "30° each side", "10°", "60° each side"], "correct": 1, "decode": "Beyond the 120° binocular zone, each eye alone sees a 30° temporal crescent.", "ow": ["90° overstates the crescent.", "Correct. The monocular temporal crescent is ~30° each side.", "10° understates it.", "60° each side is too wide for the crescent."]}'),
  ('27ca04ec-1k','{"options": ["Size 0", "Size V", "Size I", "Size III"], "correct": 1, "decode": "Goldmann size V (64 mm²) is the LARGEST stimulus; size I is smallest.", "ow": ["Size 0 is smaller than I, not the largest.", "Correct. Size V is the largest Goldmann stimulus.", "Size I is the smallest.", "Size III is mid-range, not the largest."]}'),
  ('746c5eeb-x','{"options": ["III", "I", "V", "0"], "correct": 1, "decode": "Goldmann size I (0.25 mm²) is the SMALLEST stimulus; size V is largest.", "ow": ["Size III is mid-range, not the smallest.", "Correct. Size I is the smallest Goldmann stimulus.", "Size V is the largest.", "Size 0 is not the standard smallest used clinically here; I is the reference smallest."]}'),
  ('7b8473de-1j','{"options": ["31.5 apostilbs", "10 apostilbs", "100 apostilbs", "3.15 apostilbs"], "correct": 0, "decode": "Goldmann uses a 31.5 apostilb background in a 300 mm bowl.", "ow": ["Correct. The Goldmann background is 31.5 apostilbs.", "10 apostilbs is not the Goldmann standard.", "100 apostilbs is too bright for the standard.", "3.15 apostilbs is off by a factor of ten."]}'),
  ('0fc549e3-1j','{"options": ["The peripheral crescent", "The full field", "The blind spot", "The central 10°"], "correct": 3, "decode": "The Amsler grid tests only the CENTRAL 10° for macular disease.", "ow": ["The peripheral crescent is not what the Amsler grid samples.", "The grid covers only the central 10°, not the full field.", "The blind spot is not the Amsler target.", "Correct. Each square is 1° and the grid covers the central 10°."]}'),
  ('3ac41c61-1f','{"options": ["Optic nerve", "Occipital cortex", "Optic tract", "Optic chiasm"], "correct": 3, "decode": "BITEMPORAL hemianopia comes from damage to crossing nasal fibers at the CHIASM.", "ow": ["An optic nerve lesion causes a monocular defect, not bitemporal.", "An occipital lesion causes a congruous homonymous defect.", "An optic tract lesion causes a homonymous hemianopia.", "Correct. Bitemporal hemianopia localizes to the chiasm."]}'),
  ('ac41f633-1h','{"options": ["Optic nerve", "Meyer''s loop", "Optic chiasm", "Parietal radiations"], "correct": 1, "decode": "A ''pie in the sky'' superior quadrantanopia localizes to MEYER''S LOOP in the temporal lobe.", "ow": ["An optic nerve lesion gives a monocular defect, not a quadrant.", "Correct. Inferior fibers loop through the temporal lobe (Meyer''s loop).", "A chiasm lesion gives bitemporal hemianopia.", "Parietal radiations give an inferior (''pie on the floor'') defect."]}'),
  ('905246ee-2l','{"options": ["Retinitis pigmentosa", "Central serous retinopathy", "Pituitary adenoma", "Glaucoma"], "correct": 0, "decode": "Constricted fields with a central island plus night blindness point to RETINITIS PIGMENTOSA.", "ow": ["Correct. RP is a rod dystrophy: ring scotoma to central island with early nyctalopia.", "Central serous retinopathy gives a central scotoma, not peripheral constriction.", "A pituitary adenoma gives bitemporal hemianopia.", "Glaucoma gives arcuate defects and nasal steps, not this pattern with night blindness."]}'),
  ('0e4a7aa4-20','{"options": ["Light detection", "Form", "Color", "Motion"], "correct": 2, "decode": "Within the visual field, COLOR is the most vulnerable function (lost first).", "ow": ["Light detection is among the most resilient, not the first lost.", "Form is more resilient than color.", "Correct. Color is the most vulnerable, lost first.", "Motion is the most resilient, lost last."]}'),
  ('63f366ee-16','{"options": ["Tritanopia", "Protanopia", "Achromatopsia", "Deuteranomaly"], "correct": 3, "decode": "DEUTERANOMALY (weak green) is the most common color deficiency.", "ow": ["Tritan defects are rare, not the most common.", "Protanopia is less common than deuteranomaly.", "Achromatopsia is very rare.", "Correct. Deuteranomaly is the most common defect."]}'),
  ('c91ff07a-1g','{"options": ["Black", "Yellow", "White", "Gray"], "correct": 2, "decode": "ADDITIVE mixing of R+G+B light produces WHITE.", "ow": ["Black results from subtractive mixing, not additive light.", "Yellow is R+G only, not all three.", "Correct. Additive R+G+B light gives white.", "Gray is not the result of full additive mixing."]}'),
  ('c3e80333-1r','{"options": ["Green", "Red", "Black", "White"], "correct": 2, "decode": "SUBTRACTIVE mixing of C+M+Y pigments produces BLACK.", "ow": ["Green is a two-pigment mix, not all three.", "Red is not the full-pigment result.", "Correct. Subtractive C+M+Y pigment gives black.", "White comes from additive light mixing, not pigments."]}'),
  ('678986e1-1g','{"options": ["Only normals see it", "It detects tritan defects", "A control plate everyone sees", "Only protans see it"], "correct": 2, "decode": "Ishihara plate 1 is a CONTROL plate everyone reads, confirming task understanding.", "ow": ["It is not a plate only normals see.", "It does not detect tritan defects.", "Correct. Plate 1 is the control that all patients can read.", "It is not a protan-only plate."]}'),
  ('b999da75-26','{"options": ["Plate 1", "FALANT", "FM-100 Hue test", "Ishihara"], "correct": 2, "decode": "The FM-100 Hue test plots a total error score and the exact axis and severity of a color defect.", "ow": ["Plate 1 is only a control plate, not a classifier.", "FALANT is an occupational pass/fail lantern test.", "Correct. The FM-100 Hue test classifies axis and severity.", "Ishihara only screens red-green, without grading severity."]}'),
  ('0d640935-1x','{"options": ["Ladd-Franklin", "Young-Helmholtz", "Hering", "Purkinje"], "correct": 1, "decode": "YOUNG-HELMHOLTZ trichromatic theory operates at the receptor level (three cones).", "ow": ["Ladd-Franklin proposed an evolutionary color theory, not the classic trichromatic one.", "Correct. Young-Helmholtz is the trichromatic (three-cone) theory.", "Hering proposed the opponent-process (post-receptor) theory.", "Purkinje is known for the dim-light sensitivity shift, not a color theory."]}'),
  ('512638da-1z','{"options": ["Hering", "Young-Helmholtz", "Ladd-Franklin", "Newton"], "correct": 0, "decode": "HERING proposed opponent channels (red-green, blue-yellow, black-white) at the post-receptor level.", "ow": ["Correct. Hering''s opponent-process theory is post-receptor.", "Young-Helmholtz is the receptor-level trichromatic theory.", "Ladd-Franklin proposed an evolutionary theory, not opponent process.", "Newton described the spectrum, not the opponent-process theory."]}'),
  ('d5a89253-1j','{"options": ["440 nm", "507 nm", "535 nm", "750 nm"], "correct": 0, "decode": "Cyanolabe (S-cone) peaks near 440 nm (blue).", "ow": ["Correct. Cyanolabe peaks ~440 nm.", "507 nm is the rod (rhodopsin) peak.", "535 nm is the M-cone (green) peak.", "750 nm is the L-cone (red) region."]}'),
  ('1457fa04-v','{"options": ["Brighter", "Unchanged", "Green", "Dim"], "correct": 3, "decode": "Without L-cones, red light poorly stimulates remaining cones, so reds look DIM.", "ow": ["Red does not appear brighter without L-cones.", "Red is not seen unchanged in protanopia.", "Protanopes confuse reds with dark tones, but the key change is loss of luminance, not turning green.", "Correct. Missing L-cones make red appear dim."]}'),
  ('ff919694-16','{"options": ["It tests red-green and blue-yellow", "It screens red-green only", "It needs no verbal response", "It uses numeral plates only"], "correct": 0, "decode": "HRR (symbol-based) screens BOTH red-green and blue-yellow; Ishihara screens red-green only.", "ow": ["Correct. HRR tests both red-green and blue-yellow.", "Screening red-green only describes Ishihara, not HRR.", "HRR still needs a response; being response-free is not its distinction.", "HRR uses symbols, not numeral plates."]}'),
  ('db8c7cf6-1a','{"options": ["Diagnostic axis test", "Stereo test", "Occupational pass/fail test", "Macular test"], "correct": 2, "decode": "FALANT is an OCCUPATIONAL lantern pass/fail test, done at 8 feet.", "ow": ["FALANT does not map the diagnostic axis of a defect.", "It is not a stereo test.", "Correct. FALANT is an occupational pass/fail lantern test.", "It does not test the macula."]}'),
  ('793a4712-1y','{"options": ["0.5%", "2%", "8%", "20%"], "correct": 2, "decode": "Red-green deficiency affects ~8% of males (X-linked).", "ow": ["0.5% is roughly the female prevalence, not male.", "2% understates the male prevalence.", "Correct. About 8% of males have red-green deficiency.", "20% overstates it."]}'),
  ('bb7b321e-1b','{"options": ["X-linked like red-green", "Rare and autosomal", "The most common defect", "Always acquired"], "correct": 1, "decode": "Congenital TRITAN defects are RARE and AUTOSOMAL, unlike X-linked red-green.", "ow": ["Tritan defects are autosomal, not X-linked like red-green.", "Correct. Tritan defects are rare and autosomal.", "Tritan is rare, not the most common defect.", "Congenital tritan defects are inherited, not always acquired."]}'),
  ('1f01b543-t','{"options": ["12:1 to 15:1", "1:1 to 2:1", "4:1 to 6:1", "8:1 to 10:1"], "correct": 2, "decode": "Normal AC/A is 4:1 to 6:1.", "ow": ["12:1 to 15:1 is abnormally high.", "1:1 to 2:1 is abnormally low.", "Correct. Normal AC/A is 4:1 to 6:1.", "8:1 to 10:1 is high."]}'),
  ('7ea0d90b-1h','{"options": ["Convergence excess and divergence excess", "Fusional vergence dysfunction", "Basic phorias only", "Convergence and divergence insufficiency"], "correct": 0, "decode": "A HIGH AC/A means too much convergence per diopter, driving EXCESS conditions (CE, DE).", "ow": ["Correct. High AC/A is linked to convergence excess and divergence excess.", "Fusional vergence dysfunction has a normal AC/A.", "Basic phorias have a roughly normal AC/A.", "Insufficiency conditions go with a low AC/A, not high."]}'),
  ('1b2ad841-19','{"options": ["High AC/A, eso at near", "Low AC/A, exo at near, receded NPC", "Normal AC/A, equal deviation", "High eso at distance"], "correct": 1, "decode": "Convergence insufficiency has a LOW AC/A, exophoria greater at near, and a receded NPC.", "ow": ["High AC/A with eso at near describes convergence excess, not CI.", "Correct. CI shows low AC/A, near exophoria, and a receded NPC.", "Normal AC/A with equal deviation does not fit CI.", "Eso at distance is not the CI pattern."]}'),
  ('3da6e2f5-14','{"options": ["Saccade", "Vergence", "Smooth pursuit", "VOR"], "correct": 1, "decode": "VERGENCE is the slowest eye-movement system (~20°/s).", "ow": ["Saccades are the fastest movement, not the slowest.", "Correct. Vergence is the slowest system.", "Smooth pursuit is faster than vergence.", "The VOR is a very fast reflex, not the slowest."]}'),
  ('90eb4517-1f','{"options": ["Smooth pursuit", "Saccade", "Vergence", "Vestibulo-ocular reflex"], "correct": 3, "decode": "The VESTIBULO-OCULAR REFLEX has the shortest latency (~15 ms).", "ow": ["Smooth pursuit has a longer latency than the VOR.", "Saccades have ~200 ms latency, slower to start than the VOR.", "Vergence is the slowest system.", "Correct. The VOR has the shortest latency."]}'),
  ('7532c8d2-y','{"options": ["20°/s", "5°/s", "500–1000°/s", "90°/s"], "correct": 2, "decode": "Saccades are the fastest movement at 500–1000°/s.", "ow": ["20°/s is vergence velocity, not saccadic.", "5°/s is far too slow for a saccade.", "Correct. Saccadic velocity is 500–1000°/s.", "90°/s understates saccadic speed."]}'),
  ('2f6a6601-2e','{"options": ["Three times the phoria", "Twice the phoria", "Equal to the phoria", "Half the phoria"], "correct": 1, "decode": "Sheard''s criterion: the compensating fusional reserve should be at least TWICE the phoria.", "ow": ["Three times the phoria overstates Sheard''s requirement.", "Correct. Sheard''s requires reserve ≥ 2× the phoria.", "Equal to the phoria is below Sheard''s threshold.", "Half the phoria is far below the requirement."]}'),
  ('45ea0c4b-1q','{"options": ["Twice the reserve", "The blur point", "The first third of the range", "The middle third of the fusional range"], "correct": 3, "decode": "Percival''s criterion: the demand (phoria) should sit in the MIDDLE THIRD of the fusional range.", "ow": ["''Twice the reserve'' is not Percival''s rule.", "The blur point is a finding, not Percival''s criterion.", "The first third is where the demand should NOT sit.", "Correct. Percival''s places the demand in the middle third of the range."]}'),
  ('ac53febe-1o','{"options": ["Grade 1", "Grade 3", "Grade 2", "Not graded"], "correct": 0, "decode": "Worth Grade 1 is SIMULTANEOUS macular perception.", "ow": ["Correct. Grade 1 is simultaneous perception.", "Grade 3 is stereopsis.", "Grade 2 is flat fusion.", "It is graded; Grade 1 covers it."]}'),
  ('df82d21d-1z','{"options": ["Grade 4", "Grade 2", "Grade 3", "Grade 1"], "correct": 1, "decode": "Worth Grade 2 is FLAT (superimposition) fusion with amplitude.", "ow": ["There is no Grade 4 in Worth''s three-grade scheme.", "Correct. Grade 2 is flat fusion.", "Grade 3 is stereopsis.", "Grade 1 is simultaneous perception."]}'),
  ('9b347dea-18','{"options": ["The pupil", "Yoke muscles of both eyes", "A single muscle", "Agonist-antagonist of one eye"], "correct": 1, "decode": "Hering''s law of equal innervation governs binocular YOKE muscles.", "ow": ["Hering''s law is not about the pupil.", "Correct. Hering''s law applies to yoke muscles of both eyes.", "A single muscle is governed by neither of these binocular laws.", "Agonist-antagonist within one eye is Sherrington''s, not Hering''s."]}'),
  ('dbf11367-1h','{"options": ["The near accommodative response", "Equal innervation to yoke muscles", "The pupillary constriction reflex", "Agonist contracts, antagonist relaxes"], "correct": 3, "decode": "Sherrington''s law is monocular: agonist contracts while its antagonist RELAXES.", "ow": ["The near accommodative response is not Sherrington''s law.", "Equal innervation to yoke muscles is Hering''s law.", "The pupillary reflex is not this reciprocal-innervation rule.", "Correct. Sherrington''s law: agonist contracts, antagonist relaxes."]}'),
  ('9f41e0db-2b','{"options": ["Vertical", "None", "Uncrossed", "Crossed"], "correct": 2, "decode": "An object BEYOND fixation stimulates nasal retina, giving UNCROSSED (homonymous) diplopia.", "ow": ["Physiologic diplopia here is horizontal, not vertical.", "There is diplopia, not none, for a non-fixated object.", "Correct. Far objects give uncrossed diplopia.", "Crossed diplopia is for near objects, not far."]}'),
  ('90991274-1d','{"options": ["Suppression", "Crossed diplopia", "Uncrossed diplopia", "Torsional diplopia"], "correct": 1, "decode": "An object CLOSER than fixation stimulates temporal retina, giving CROSSED (heteronymous) diplopia.", "ow": ["A near object is not suppressed in normal physiologic diplopia.", "Correct. Near objects give crossed diplopia.", "Uncrossed diplopia is for far objects, not near.", "Physiologic diplopia here is horizontal, not torsional."]}'),
  ('b3a63089-1e','{"options": ["Eccentric fixation", "Constant strabismus", "Deep amblyopia", "Heterophoria"], "correct": 3, "decode": "Normal retinal correspondence is preserved in HETEROPHORIA, where fusion keeps the eyes aligned most of the time.", "ow": ["Eccentric fixation is a monocular anomaly, not where NRC is maintained.", "Constant strabismus may develop anomalous correspondence.", "Deep amblyopia disrupts normal correspondence.", "Correct. Heterophoria preserves NRC."]}'),
  ('da10d56b-1m','{"options": ["An intermittent exophoria", "Constant strabismus, fixed angle", "Uncorrected refractive error", "Long-standing orthophoria"], "correct": 1, "decode": "ARC develops in CONSTANT strabismus with a fixed angle, giving the brain time to rewire.", "ow": ["Intermittent exophoria preserves normal correspondence.", "Correct. A fixed constant deviation breeds ARC.", "Uncorrected refractive error alone does not create ARC.", "Long-standing orthophoria keeps normal correspondence."]}'),
  ('c1c9f100-19','{"options": ["Is less than the angle of deviation", "Equals the angle of deviation", "Exceeds the angle of deviation", "Does not exist"], "correct": 1, "decode": "In HARMONIOUS ARC, the anomalous angle EQUALS the objective angle of deviation.", "ow": ["Less than the deviation describes unharmonious ARC.", "Correct. Harmonious ARC: neutral point equals the deviation.", "Exceeding the deviation is not the harmonious pattern.", "The anomalous neutral point does exist in ARC."]}'),
  ('9d850375-1d','{"options": ["25 cm", "20 cm", "15 cm", "≤8 cm"], "correct": 3, "decode": "Normal NPC break is ≤8 cm; beyond ~10 cm suggests convergence insufficiency.", "ow": ["25 cm indicates a markedly receded NPC.", "20 cm is well beyond normal.", "15 cm is receded, not normal.", "Correct. Normal NPC break is ≤8 cm."]}'),
  ('47116041-17','{"options": ["30 arc minutes", "6–10 arc minutes", "60 arc minutes", "1 degree"], "correct": 1, "decode": "Panum''s fusional area at the FOVEA is small (6–10 arc min) and widens peripherally.", "ow": ["30 arc min is wider than the foveal value.", "Correct. Panum''s area at the fovea is 6–10 arc min.", "60 arc min is too wide for the fovea.", "1 degree is far too wide for the foveal area."]}'),
  ('613e98d4-27','{"options": ["Basic exophoria", "Accommodative esotropia", "Divergence excess", "Convergence insufficiency"], "correct": 1, "decode": "A hyperope straight at distance but crossing at near with high AC/A has ACCOMMODATIVE ESOTROPIA.", "ow": ["Basic exophoria diverges, opposite to crossing at near.", "Correct. Hyperopic accommodation drives excess convergence (high AC/A), crossing the eyes at near.", "Divergence excess shows exo at distance, not eso at near.", "Convergence insufficiency shows exo at near, not eso."]}'),
  ('19ee4c6d-1n','{"options": ["Add plus lenses", "Patch the dominant eye", "Reduce convergence with base-in prism", "Increase fusional convergence"], "correct": 3, "decode": "Exophoria is managed by BUILDING fusional convergence (or temporary base-out prism).", "ow": ["Plus lenses reduce convergence and suit esophoria, not exophoria.", "Patching treats amblyopia, not exophoria alignment.", "The therapeutic goal for exophoria is to increase fusional convergence, not to reduce it.", "Correct. Exophoria therapy increases fusional convergence."]}'),
  ('447dae2b-1i','{"options": ["Meridional", "Anisometropic", "Strabismic", "Deprivation"], "correct": 3, "decode": "DEPRIVATION amblyopia (cataract, ptosis, opacity) has the WORST prognosis.", "ow": ["Meridional amblyopia is milder than deprivation.", "Anisometropic amblyopia has a better prognosis than deprivation.", "Strabismic amblyopia is more treatable than deprivation.", "Correct. Deprivation amblyopia has the worst prognosis."]}'),
  ('279a6743-11','{"options": ["Equal exo at near and distance", "Exo greater at distance, high AC/A", "Eso at distance, ortho at near", "Receded NPC with exo at near"], "correct": 1, "decode": "Divergence excess shows large EXO at DISTANCE, near closer to ortho, with a high AC/A.", "ow": ["Equal exo near and distance is basic exophoria, not divergence excess.", "Correct. DE shows exo greater at distance with high AC/A.", "Eso at distance is not the DE pattern.", "A receded NPC with near exo describes convergence insufficiency."]}'),
  ('90325a7d-10','{"options": ["Ametropic", "Meridional", "Deprivation", "Strabismic"], "correct": 3, "decode": "STRABISMIC amblyopia (suppression of a constantly deviating eye) is the most common type.", "ow": ["Ametropic amblyopia is less common than strabismic.", "Meridional amblyopia is uncommon.", "Deprivation amblyopia is rare.", "Correct. Strabismic amblyopia is the most common type."]}'),
  ('e96dfebd-r','{"options": ["200–400 seconds of arc", "1–2 minutes of arc", "20–40 seconds of arc", "3000 seconds of arc"], "correct": 2, "decode": "Normal stereoacuity is 20–40 seconds of arc (smaller values = finer stereo).", "ow": ["200–400 sec arc is coarse, not normal.", "1–2 min of arc (60–120 sec) is coarser than normal.", "Correct. Normal stereoacuity is 20–40 sec arc.", "3000 sec arc is gross (the Titmus fly), not normal."]}'),
  ('3e3516cd-1r','{"options": ["20 sec arc", "400 sec arc", "100 sec arc", "40 sec arc"], "correct": 0, "decode": "The SMALLEST arc-second value represents the FINEST stereopsis, so 20 sec arc.", "ow": ["Correct. 20 sec arc is the finest depth perception listed.", "400 sec arc is coarse.", "100 sec arc is coarser than 20.", "40 sec arc is normal but coarser than 20."]}'),
  ('09d245a9-1r','{"options": ["Grade 3", "Grade 1", "Grade 2", "Grade 4"], "correct": 0, "decode": "Stereopsis corresponds to Worth GRADE 3, the highest level.", "ow": ["Correct. Stereopsis is Worth Grade 3.", "Grade 1 is simultaneous perception.", "Grade 2 is flat fusion.", "There is no Grade 4."]}'),
  ('97997f3c-2o','{"options": ["Normal stereo", "Unaffected", "No measurable stereopsis", "Reduced stereo"], "correct": 2, "decode": "Deep constant strabismic amblyopia abolishes stereopsis, so NO measurable stereo.", "ow": ["Normal stereo is not expected with deep amblyopia.", "Deep suppression does affect stereo, so ''unaffected'' is wrong.", "Correct. Deep strabismic amblyopia gives no measurable stereopsis.", "It is typically absent, not merely reduced, with 20/200 deep amblyopia."]}'),
  ('3968068e-26','{"options": ["Titmus", "Randot", "TNO", "Frisby"], "correct": 3, "decode": "The FRISBY uses transparent plates of real thickness, so no special glasses are needed.", "ow": ["The Titmus needs polarized glasses.", "The Randot needs polarized glasses.", "The TNO needs red-green glasses.", "Correct. The Frisby uses real depth and no glasses."]}'),
  ('fd144fee-1q','{"options": ["3000 sec arc", "40 sec arc", "20 sec arc", "400 sec arc"], "correct": 0, "decode": "The Titmus FLY is the coarsest target at ~3000 sec arc.", "ow": ["Correct. The Titmus fly is ~3000 sec arc (coarsest).", "40 sec arc is a fine circles target, not the fly.", "20 sec arc is finer still, not the fly.", "400 sec arc is finer than the fly."]}'),
  ('b95a5010-17','{"options": ["5 years", "2 years", "Birth", "3–6 months of age"], "correct": 3, "decode": "Stereopsis emerges around 3–6 months as binocular cortical neurons mature; it is not present at birth.", "ow": ["5 years is far too late for stereopsis onset.", "2 years is later than normal onset.", "Stereopsis is not present at birth.", "Correct. Stereopsis develops around 3–6 months."]}'),
  ('7b91b6b0-1l','{"options": ["Panum''s fusion", "Retinal disparity", "Stereopsis", "Monocular cues"], "correct": 3, "decode": "A monocular patient loses stereopsis but keeps MONOCULAR CUES for depth.", "ow": ["Panum''s fusion needs two eyes and is lost.", "Retinal disparity needs two eyes and is lost.", "Stereopsis is lost with one eye.", "Correct. Monocular cues survive the loss of one eye."]}'),
  ('294597ae-y','{"options": ["Convergence effort alone", "Binocular retinal disparity", "Pupil size differences", "Accommodative demand"], "correct": 1, "decode": "Stereopsis arises from small horizontal binocular RETINAL DISPARITY within Panum''s area.", "ow": ["Convergence effort alone does not create stereopsis.", "Correct. Stereopsis depends on binocular retinal disparity.", "Pupil-size differences do not generate stereopsis.", "Accommodative demand is not the basis of stereopsis."]}'),
  ('63d32ea2-13','{"options": ["Suppression", "Eccentric fixation", "Grade 3 only", "Worth Grades 1 and 2 first"], "correct": 3, "decode": "Stereopsis (Grade 3) is built on simultaneous perception (Grade 1) and fusion (Grade 2) FIRST.", "ow": ["Suppression prevents, not enables, stereopsis.", "Eccentric fixation is an obstacle, not a prerequisite.", "Grade 3 cannot stand without Grades 1 and 2.", "Correct. Stereopsis needs Grades 1 and 2 first."]}'),
  ('3786983d-20','{"options": ["10 meters", "50 meters", "2 meters", "Optical infinity"], "correct": 2, "decode": "Convergence is a useful depth cue only at near, within about 2 m.", "ow": ["10 m is beyond the useful convergence-cue range.", "50 m is far beyond it.", "Correct. Convergence is a useful depth cue only within ~2 m.", "At optical infinity convergence provides no depth cue."]}'),
  ('9879f8a3-3k','{"options": ["Tonometry", "Humphrey visual field", "Ishihara", "TVPS-3"], "correct": 3, "decode": "Figure-ground and sequencing complaints with normal acuity/BV call for the TVPS-3.", "ow": ["Tonometry measures IOP, unrelated to perceptual complaints.", "A visual field test does not assess visual perception.", "Ishihara tests color, not perceptual processing.", "Correct. With 20/20 and normal BV, TVPS-3 assesses the perceptual deficit."]}'),
  ('0509e17d-2d','{"options": ["20/20 acuity does NOT rule out a VIP deficit", "Acuity equals perception", "The eyes are misaligned", "20/20 rules out a perceptual deficit"], "correct": 0, "decode": "20/20 acuity does NOT rule out a visual-information-processing deficit; perception is separate from acuity.", "ow": ["Correct. 20/20 acuity does not exclude a VIP deficit.", "Acuity does not equal perception.", "This scenario is about processing, not eye alignment.", "20/20 does not rule out a perceptual deficit."]}'),
  ('2af64458-p','{"options": ["VPS includes motor output; VIP does not", "They are identical", "VIP is broad; VPS is the non-motor subset", "VPS is acuity"], "correct": 2, "decode": "VIP is the broad domain; VPS are its NON-MOTOR subset.", "ow": ["VPS is the non-motor subset; the motor split is stated backward here.", "They are not identical.", "Correct. VIP is broad; VPS is the non-motor subset.", "VPS is not acuity."]}'),
  ('788b5915-w','{"options": ["Visual-motor integration", "Non-motor perception only", "Visual fields", "Color vision"], "correct": 0, "decode": "The Beery VMI measures VISUAL-MOTOR INTEGRATION through shape copying.", "ow": ["Correct. Beery VMI measures visual-motor integration.", "It is not a non-motor perception test; copying requires motor output.", "It does not measure visual fields.", "It does not test color vision."]}'),
  ('fed4bb39-v','{"options": ["A stereo test", "A non-motor VPS test, ages 4–18", "A color test", "A motor-loaded copying test"], "correct": 1, "decode": "The TVPS-3 is a NON-MOTOR VPS test (pointing responses), ages 4–18.", "ow": ["It is not a stereo test.", "Correct. TVPS-3 is a non-motor VPS test for ages 4–18.", "It is not a color test.", "It is deliberately motor-free, not motor-loaded."]}'),
  ('e6f88e03-2q','{"options": ["TVPS-3", "Tonometry", "Visual field", "Snellen acuity"], "correct": 0, "decode": "TVPS-3 needs no motor output, so it separates a perceptual deficit from a motor one.", "ow": ["Correct. TVPS-3 isolates perception from motor output.", "Tonometry does not separate perception from motor.", "A visual field test does not address this.", "Snellen acuity does not separate perception from motor."]}'),
  ('3ac2f6b2-w','{"options": ["Requires no motor response", "Measures visual acuity only", "Splits motor-free and motor scores", "Tests color vision only"], "correct": 2, "decode": "The DTVP-2 yields BOTH motor-reduced and motor-enhanced scores, helping localize the deficit.", "ow": ["It does require some motor response; that is not its notable feature.", "It does not measure acuity only.", "Correct. DTVP-2 splits motor-free and motor scores.", "It does not test color vision only."]}'),
  ('524c7636-2b','{"options": ["Visual memory", "Visual closure", "Figure-ground", "Form constancy"], "correct": 3, "decode": "FORM CONSTANCY is recognizing an object despite changes in size or orientation.", "ow": ["Visual memory is recall of a form, not recognition across transformations.", "Visual closure is recognizing a whole from an incomplete figure.", "Figure-ground is separating an object from a busy background.", "Correct. Form constancy handles changed size or orientation."]}'),
  ('afcd180c-2b','{"options": ["Figure-ground", "Visual closure", "Spatial relations", "Form constancy"], "correct": 1, "decode": "VISUAL CLOSURE is recognizing a whole object from an incomplete or partial drawing.", "ow": ["Figure-ground is finding an object in a busy background.", "Correct. Visual closure builds the whole from a fragmentary figure.", "Spatial relations concern position and orientation between objects.", "Form constancy is recognizing a shape despite size or orientation changes."]}'),
  ('94139d54-26','{"options": ["Figure-ground", "Form constancy", "Visual closure", "Visual memory"], "correct": 0, "decode": "FIGURE-GROUND is separating a target object from a cluttered background.", "ow": ["Correct. Figure-ground separates the object from a busy background.", "Form constancy is recognizing a shape across size/orientation changes.", "Visual closure is completing an incomplete figure.", "Visual memory is recall of a form, not locating it in clutter."]}'),
  ('dc8f2fa6-2o','{"options": ["TVPS-3", "Ishihara", "Beery VMI", "Goldmann perimetry"], "correct": 2, "decode": "Handwriting and shape-copying are VISUAL-MOTOR tasks, best evaluated by the Beery VMI.", "ow": ["TVPS-3 is motor-free and does not target copying/handwriting.", "Ishihara tests color, not visual-motor integration.", "Correct. Copying and handwriting complaints point to the Beery VMI.", "Goldmann perimetry maps the field, unrelated to copying."]}'),
  ('98ea8290-1q','{"options": ["15 minutes", "7 minutes", "40 minutes", "2 minutes"], "correct": 1, "decode": "Cone-mediated dark adaptation is essentially complete by ~7 minutes (the Kohlrausch kink).", "ow": ["15 minutes is past the cone plateau, into the rod branch.", "Correct. Cones finish adapting at ~7 minutes.", "40 minutes is full rod adaptation, not cone.", "2 minutes is too early for cone completion."]}'),
  ('d839dbcb-1i','{"options": ["Peak rod sensitivity", "The handover from cones to rods", "Complete dark adaptation", "The onset of the Purkinje shift"], "correct": 1, "decode": "The Kohlrausch kink marks the HANDOVER from cones to rods (~7 min).", "ow": ["Peak rod sensitivity comes later, at full adaptation, not at the kink.", "Correct. The kink is the cone-to-rod handover.", "Complete dark adaptation is at 30–40 min, not the kink.", "The Purkinje shift is a spectral change, not the curve inflection."]}'),
  ('9b5fa3a1-1k','{"options": ["From 555 nm to 507 nm", "From 555 nm to 750 nm", "From 440 nm to 507 nm", "From 507 nm to 555 nm"], "correct": 0, "decode": "The Purkinje shift moves peak sensitivity FROM 555 nm TO 507 nm as light fades.", "ow": ["Correct. Purkinje shift: 555 nm (cones) to 507 nm (rods).", "555 to 750 nm is not the Purkinje direction.", "440 to 507 nm is not the Purkinje shift.", "507 to 555 nm is the reverse (going brighter)."]}'),
  ('238da9fe-1d','{"options": ["Neutral at 7.0", "Unchanged", "More alkaline", "More acidic"], "correct": 2, "decode": "The dark retina is more ALKALINE (~pH 7.3); in light it falls toward 7.0.", "ow": ["It is not fixed at a neutral 7.0 in the dark.", "Retinal pH does change with light state.", "Correct. The dark retina is more alkaline (~7.3).", "The dark retina is alkaline, not more acidic."]}'),
  ('bdacd395-24','{"options": ["Entrance pupil", "Corneal apex", "Nodal point", "Center of rotation"], "correct": 2, "decode": "Angle alpha (optical vs visual axis) is subtended at the NODAL point, ~5° temporal.", "ow": ["The entrance pupil is the reference for angle kappa, not alpha.", "The corneal apex is not the alpha reference.", "Correct. Angle alpha is measured at the nodal point.", "The center of rotation is where Fick axes cross, not the alpha reference."]}'),
  ('73cd386c-1d','{"options": ["Pseudo-esotropia", "Pseudo-hypertropia", "Pseudo-exotropia", "True exotropia"], "correct": 2, "decode": "A POSITIVE angle kappa (reflex nasal) produces the appearance of PSEUDO-EXOTROPIA.", "ow": ["Pseudo-esotropia comes from a negative kappa.", "Positive kappa does not mimic hypertropia.", "Correct. Positive kappa gives pseudo-exotropia.", "It is an artifact of reflex position, not a true exotropia."]}'),
  ('7526f51b-18','{"options": ["Intensity ÷ time is constant", "Area ÷ intensity is constant", "Time × intensity is constant", "Area × intensity is constant"], "correct": 3, "decode": "Ricco''s law of spatial summation: within the summation area, AREA × INTENSITY is constant.", "ow": ["Intensity ÷ time is not Ricco''s form.", "Area ÷ intensity is not the correct relationship.", "Time × intensity is the temporal (Bunsen-Roscoe) law.", "Correct. Ricco''s law: area × intensity is constant."]}'),
  ('db5a25cf-14','{"options": ["Chlorolabe", "Rhodopsin", "Cyanolabe", "Erythrolabe"], "correct": 3, "decode": "ERYTHROLABE is the long-wavelength (red) cone pigment.", "ow": ["Chlorolabe is the green (middle) pigment.", "Rhodopsin is the rod pigment.", "Cyanolabe is the blue (short) pigment.", "Correct. Erythrolabe is the red cone pigment."]}'),
  ('262efb36-1x','{"options": ["20 mm", "22 mm", "24 mm", "26 mm"], "correct": 2, "decode": "The anteroposterior (Y) axis is the longest, about 24 mm.", "ow": ["20 mm is too short for the AP axis.", "22 mm is the vertical/horizontal axis length.", "Correct. The AP axis is ~24 mm, the longest.", "26 mm overstates the AP axis."]}'),
  ('ad1d040b-19','{"options": ["1, 2 and 3", "1, 4 and 6", "2, 3 and 5", "4, 5 and 6"], "correct": 1, "decode": "LGB layers 1, 4, 6 receive CROSSED (nasal, contralateral) fibers.", "ow": ["Layers 1, 2, 3 mix sides incorrectly here.", "Correct. Layers 1, 4, 6 take crossed nasal fibers.", "Layers 2, 3, 5 take uncrossed temporal fibers.", "Layers 4, 5, 6 mix sides incorrectly."]}'),
  ('db9f127c-w','{"options": ["Peristriate cortex", "Striate cortex", "Parastriate cortex", "Prestriate motor area"], "correct": 2, "decode": "Brodmann area 18 is the PARASTRIATE cortex.", "ow": ["Peristriate cortex is area 19, not 18.", "Striate cortex is area 17.", "Correct. Area 18 is the parastriate cortex.", "There is no ''prestriate motor area'' by this label; 18 is parastriate."]}'),
  ('ff997bc8-1n','{"options": ["Visual acuity", "Light projection", "Color vision", "Motion perception"], "correct": 2, "decode": "COLOR VISION fails earliest in optic nerve disease (basis of red desaturation).", "ow": ["Visual acuity is more resilient than color early on.", "Light projection is a very late, gross function.", "Correct. Color vision fails earliest.", "Motion perception is the most resilient, lost last."]}'),
  ('61af3c32-1c','{"options": ["Color constancy", "Face recognition", "Object identity", "Spatial location and motion"], "correct": 3, "decode": "The DORSAL stream to the parietal lobe processes SPATIAL LOCATION and MOTION.", "ow": ["Color constancy is a ventral-stream function.", "Face recognition is ventral-stream.", "Object identity is the ventral ''what'' stream.", "Correct. The dorsal stream handles spatial location and motion."]}'),
  ('3f3c890e-1t','{"options": ["60°", "75°", "90°", "100°"], "correct": 3, "decode": "The TEMPORAL field is widest at 100° (S60, I75, N60).", "ow": ["60° is the nasal/superior extent.", "75° is the inferior extent.", "90° is not the temporal maximum.", "Correct. The temporal extent is 100°."]}'),
  ('d8264e02-1c','{"options": ["10°", "30°", "60°", "100°"], "correct": 1, "decode": "The monocular temporal crescent is the outer ~30°, beyond the 120° binocular overlap.", "ow": ["10° understates the crescent.", "Correct. The temporal crescent is ~30° each side.", "60° is too wide for the crescent.", "100° is the whole temporal extent, not the crescent."]}'),
  ('dba2fdbf-2c','{"options": ["I", "V", "III", "II"], "correct": 1, "decode": "Goldmann size V (64 mm²) maps the far periphery in advanced field loss.", "ow": ["Size I (0.25 mm²) is the smallest, used for fine central testing.", "Correct. Size V is the largest, used for far-peripheral mapping.", "Size III is the standard mid-range, not the largest.", "Size II is smaller than V."]}'),
  ('dc4fbdfb-18','{"options": ["1 arc minute", "1°", "5°", "5 arc minutes"], "correct": 1, "decode": "Each Amsler square subtends 1°, and the grid covers the central 10°.", "ow": ["1 arc minute is far too small for one square.", "Correct. One Amsler square subtends 1°.", "5° is too large for a single square.", "5 arc minutes is far too small."]}'),
  ('4c10ad49-1h','{"options": ["Meyer''s loop", "The occipital pole", "The optic chiasm", "The parietal radiation"], "correct": 0, "decode": "A ''pie in the sky'' superior quadrantanopia localizes to MEYER''S LOOP in the temporal lobe.", "ow": ["Correct. Meyer''s loop carries inferior fibers through the temporal lobe.", "The occipital pole lesion gives a congruous macular-splitting defect, not a temporal-lobe quadrantanopia.", "The chiasm gives bitemporal hemianopia.", "Parietal radiation lesions give an inferior (''pie on the floor'') defect."]}'),
  ('59bf8733-2c','{"options": ["Lateral geniculate body", "Striate cortex", "Photoreceptors", "Ganglion cells"], "correct": 2, "decode": "Young-Helmholtz trichromacy operates at the PHOTORECEPTOR level (three cone types).", "ow": ["The lateral geniculate is post-receptor, not the trichromatic site.", "The striate cortex is post-receptor.", "Correct. Trichromacy operates at the photoreceptors.", "Ganglion cells are post-receptor (opponent) processing."]}'),
  ('b5e25bb9-1n','{"options": ["Ladd-Franklin", "Hering", "Young and Helmholtz", "Purkinje"], "correct": 1, "decode": "HERING proposed the OPPONENT-PROCESS theory (red-green, blue-yellow, black-white).", "ow": ["Ladd-Franklin proposed an evolutionary theory.", "Correct. Hering proposed the opponent-process theory.", "Young and Helmholtz proposed trichromacy.", "Purkinje is known for the dim-light sensitivity shift."]}'),
  ('6d65222c-1c','{"options": ["Deuteranomaly", "Protanopia", "Tritanomaly", "Deuteranopia"], "correct": 0, "decode": "DEUTERANOMALY (green weakness) is the most common inherited color defect.", "ow": ["Correct. Deuteranomaly is the commonest defect.", "Protanopia is less common than deuteranomaly.", "Tritanomaly is rare.", "Deuteranopia (total green loss) is less common than deuteranomaly."]}'),
  ('94ea4bcb-1n','{"options": ["A tritan plate", "A control plate everyone can read", "The hardest plate", "A red-green screening plate"], "correct": 1, "decode": "Ishihara plate 1 (''12'') is a CONTROL plate everyone, including color-defectives, can read.", "ow": ["It is not a tritan plate.", "Correct. Plate 1 is the control everyone reads.", "It is the easiest, demonstration plate, not the hardest.", "It is not a red-green screening plate; it screens nothing."]}'),
  ('0b7baa5e-1v','{"options": ["Ishihara plates", "HRR plates", "D-15 panel", "FM-100 Hue test"], "correct": 3, "decode": "The FM-100 Hue test is the most comprehensive, grading axis and severity of a color defect.", "ow": ["Ishihara only screens red-green.", "HRR screens red-green and blue-yellow but does not grade severity as finely.", "The D-15 sorts a short cap set; it is a screener, less detailed than FM-100.", "Correct. FM-100 Hue is the most comprehensive test."]}'),
  ('47c24bda-1e','{"options": ["20 feet", "40 cm", "1 meter", "8 feet"], "correct": 3, "decode": "The FALANT occupational lantern test is performed at 8 feet.", "ow": ["20 feet is not the FALANT working distance.", "40 cm is a near distance, not the FALANT setup.", "1 meter is not the standard FALANT distance.", "Correct. FALANT is performed at 8 feet."]}'),
  ('e4d6f44a-u','{"options": ["1:1 to 2:1", "8:1 to 10:1", "12:1", "4:1 to 6:1"], "correct": 3, "decode": "Normal AC/A is 4:1 to 6:1.", "ow": ["1:1 to 2:1 is abnormally low.", "8:1 to 10:1 is high.", "12:1 is very high.", "Correct. Normal AC/A is 4:1 to 6:1."]}'),
  ('40fe71ac-z','{"options": ["The smooth pursuit", "The saccade", "Vergence", "The vestibulo-ocular reflex"], "correct": 2, "decode": "VERGENCE is the slowest eye movement (~20°/s); the VOR is fastest.", "ow": ["Smooth pursuit is faster than vergence.", "The saccade is fast, not the slowest.", "Correct. Vergence is the slowest movement.", "The VOR is the fastest reflex, not the slowest."]}'),
  ('4e1f857e-1r','{"options": ["Half the phoria", "Equal to the phoria", "Twice the phoria", "Three times the phoria"], "correct": 2, "decode": "Sheard''s criterion requires the fusional reserve to be at least TWICE the phoria.", "ow": ["Half the phoria is far below Sheard''s requirement.", "Equal to the phoria is below the threshold.", "Correct. Sheard''s requires reserve ≥ 2× the phoria.", "Three times the phoria overstates the rule."]}'),
  ('a0615add-10','{"options": ["Flat fusion with amplitude", "Stereopsis", "Simultaneous macular perception", "Suppression"], "correct": 2, "decode": "Worth Grade 1 is SIMULTANEOUS macular perception.", "ow": ["Flat fusion with amplitude is Grade 2.", "Stereopsis is Grade 3.", "Correct. Grade 1 is simultaneous perception.", "Suppression is not a Worth fusion grade."]}'),
  ('9cb3b292-1r','{"options": ["Crossed diplopia", "Uncrossed diplopia", "Absent entirely", "Vertical diplopia"], "correct": 1, "decode": "An object BEYOND fixation gives UNCROSSED physiologic diplopia.", "ow": ["Crossed diplopia is for objects nearer than fixation.", "Correct. Far objects give uncrossed diplopia.", "Physiologic diplopia is present, not absent, off the fixation point.", "It is horizontal, not vertical."]}'),
  ('9ec5a2cd-13','{"options": ["≤15 cm", "≤2 cm", "≤8 cm", "≤20 cm"], "correct": 2, "decode": "Normal NPC breaks at ≤8 cm; beyond ~10 cm suggests convergence insufficiency.", "ow": ["≤15 cm is receded, not normal.", "≤2 cm is closer than the typical normal break.", "Correct. Normal NPC break is ≤8 cm.", "≤20 cm is markedly receded."]}'),
  ('8a0c2450-s','{"options": ["20–40 seconds of arc", "100–200 seconds of arc", "1–2 minutes of arc", "5–10 seconds of arc"], "correct": 0, "decode": "Normal stereoacuity is 20–40 arc seconds.", "ow": ["Correct. Normal stereoacuity is 20–40 arc sec.", "100–200 arc sec is coarse.", "1–2 min of arc (60–120 sec) is coarser than normal.", "5–10 arc sec is finer than typical normal."]}'),
  ('23b80f2c-1a','{"options": ["6–10 arc minutes", "30–60 arc minutes", "1–2 arc minutes", "2–3 degrees"], "correct": 0, "decode": "Panum''s fusional area at the fovea spans about 6–10 arc minutes and widens peripherally.", "ow": ["Correct. Panum''s area at the fovea is 6–10 arc min.", "30–60 arc min is a peripheral, not foveal, width.", "1–2 arc min understates the foveal area.", "2–3 degrees is far too wide for the fovea."]}'),
  ('dd7e62de-1f','{"options": ["Fly", "Animals", "Circles", "Randot forms"], "correct": 0, "decode": "The Titmus FLY is the coarsest target (~3000 arc sec).", "ow": ["Correct. The Titmus fly is the coarsest target.", "The animals are finer than the fly.", "The circles are the fine graded target.", "Randot forms are not part of the Titmus fly."]}'),
  ('e69867ce-18','{"options": ["VPS is the non-motor subset of VIP", "VIP is a subset of VPS", "They are interchangeable terms", "Neither involves motor output"], "correct": 0, "decode": "VPS are the NON-MOTOR subset within the broader VIP domain.", "ow": ["Correct. VPS is the non-motor subset of VIP.", "VIP is the broader term, not a subset of VPS.", "They are not interchangeable.", "VIP as a whole includes motor output, so ''neither involves motor'' is wrong."]}'),
  ('33db3dce-1m','{"options": ["Copy geometric shapes", "Sort cards by color", "Point to a matching form", "Name the shapes aloud"], "correct": 0, "decode": "The Beery VMI asks the child to COPY geometric shapes (visual-motor integration).", "ow": ["Correct. The Beery VMI uses shape copying.", "Sorting by color is not the Beery task.", "Pointing to a match is the TVPS-3 method.", "Naming shapes aloud is not the Beery task."]}'),
  ('7e194d73-1n','{"options": ["Trace the figure", "Point to the answer", "Draw the target", "Assemble blocks"], "correct": 1, "decode": "The TVPS-3 is motor-free: the child POINTS to the answer.", "ow": ["Tracing adds motor demand, unlike the TVPS-3.", "Correct. TVPS-3 uses pointing only.", "Drawing the target adds motor demand.", "Assembling blocks is a motor task, not TVPS-3."]}'),
  ('ed53e5b0-20','{"options": ["The visual axis", "The Y-axis", "The Z-axis", "The X-axis"], "correct": 2, "decode": "Horizontal movements occur about the Z (vertical) axis; the axis is named for the line the eye rotates around.", "ow": ["The visual axis is a line of sight, not a rotation axis for horizontal movement.", "The Y (AP) axis governs torsion.", "Correct. The Z (vertical) axis governs horizontal movement.", "The X axis governs vertical movement."]}'),
  ('1355f5f8-1d','{"options": ["Pupil", "Nodal point", "Center of rotation", "Fovea"], "correct": 0, "decode": "Angle KAPPA is measured at the PUPIL; alpha at the nodal point.", "ow": ["Correct. Angle kappa is measured at the pupil.", "The nodal point is the reference for angle alpha.", "The center of rotation is where Fick axes cross.", "The fovea is where the visual axis lands, not the kappa reference."]}'),
  ('99b27b23-2c','{"options": ["A larger reflex displacement", "A negative cover test", "The absence of diplopia", "Testing with a red filter"], "correct": 1, "decode": "Positive kappa mimics exotropia but shows a NEGATIVE cover test (no true deviation).", "ow": ["Reflex displacement size does not distinguish it; the cover test does.", "Correct. A negative cover test distinguishes pseudo- from true exotropia.", "Diplopia is not the distinguishing feature here.", "A red filter is not needed to make this distinction."]}'),
  ('b82a7ba4-1u','{"options": ["Superior retina", "Nasal retina", "Temporal retina", "Fovea"], "correct": 2, "decode": "The 30° monocular crescent is seen by the TEMPORAL retina alone.", "ow": ["The superior retina does not define the temporal crescent.", "The nasal retina sees the temporal field but the crescent input is from temporal retina of that eye.", "Correct. The temporal retina alone sees the 30° crescent.", "The fovea sees central, not peripheral crescent, field."]}'),
  ('4a150e87-w','{"options": ["Brighter than normal", "Unchanged in brightness", "Abnormally dim", "Bright blue"], "correct": 2, "decode": "Protanopes lack L-cones, so red loses luminance and appears ABNORMALLY DIM.", "ow": ["Red does not appear brighter to a protanope.", "Red brightness is not unchanged; it is reduced.", "Correct. Red appears abnormally dim in protanopia.", "Red does not turn bright blue."]}'),
  ('ece72b7d-1n','{"options": ["The most common defect", "Confined to females", "X-linked recessive", "Autosomal and rare"], "correct": 3, "decode": "Tritan defects are AUTOSOMAL and RARE, affecting the sexes equally.", "ow": ["Tritan defects are rare, not the most common.", "They are not confined to females.", "They are autosomal, not X-linked recessive like red-green.", "Correct. Tritanopia is autosomal and rare."]}'),
  ('169d0dde-1a','{"options": ["Naming the color", "Tracing a path", "Reading a number", "Arranging caps in hue order"], "correct": 3, "decode": "On the FM-100 Hue test the patient ARRANGES caps in hue order.", "ow": ["Naming the color is not the FM-100 task.", "Tracing a path is not the FM-100 method.", "Reading a number is the Ishihara task.", "Correct. FM-100 requires arranging caps in hue order."]}'),
  ('be8f6b7f-15','{"options": ["Smooth pursuit", "Saccade", "Vergence movement", "Vestibulo-ocular reflex"], "correct": 1, "decode": "The SACCADE is the fastest VOLUNTARY eye movement.", "ow": ["Smooth pursuit is slower than a saccade.", "Correct. The saccade is the fastest voluntary movement.", "Vergence is the slowest movement.", "The VOR is faster but is a reflex, not voluntary."]}'),
  ('5aebbd37-1v','{"options": ["Low", "High", "Variable", "Normal"], "correct": 0, "decode": "Convergence insufficiency carries a LOW AC/A (too little convergence per diopter).", "ow": ["Correct. CI has a low AC/A.", "High AC/A drives the excess conditions, not CI.", "The AC/A in CI is characteristically low, not simply variable.", "A normal AC/A does not define CI."]}'),
  ('ee1d2e41-1q','{"options": ["The eyes stay aligned", "Phorias are always intermittent", "Fusion is permanently absent", "The angle is too small to adapt"], "correct": 0, "decode": "A heterophoria keeps the EYES ALIGNED by fusion most of the time, preserving normal correspondence.", "ow": ["Correct. Because the eyes stay aligned, NRC persists.", "Phorias are not always intermittent; the point is fusion keeps alignment.", "Fusion is present in a phoria, not permanently absent.", "A phoria''s angle is not too small to adapt; the reason is maintained alignment."]}'),
  ('e47820b8-1j','{"options": ["Reversible", "Permanent regardless of therapy", "Untreatable after age 3", "Only correctable by surgery"], "correct": 0, "decode": "Suppression treated early within the critical period is REVERSIBLE.", "ow": ["Correct. Early treatment makes suppression reversible.", "It is not permanent regardless of therapy when treated early.", "It is treatable during the critical period, not untreatable after age 3.", "It does not require surgery to correct."]}'),
  ('1235ad8b-55','{"options": ["Bilateral exotropia", "Large angle alpha", "Positive angle kappa", "Negative angle kappa"], "correct": 2, "decode": "A reflex ~1 mm TEMPORAL in both eyes with a negative cover test is POSITIVE angle kappa (pseudo-exotropia).", "ow": ["Bilateral exotropia would move on cover test; here there is none.", "Angle alpha is measured at the nodal point and does not produce this reflex-plus-negative-cover picture.", "Correct. Positive kappa puts the pupil nasal, so the reflex looks temporal with no true deviation.", "Negative kappa gives a nasal reflex (pseudo-esotropia), the opposite."]}'),
  ('f337fa19-42','{"options": ["440 nm", "507 nm", "535 nm", "555 nm"], "correct": 1, "decode": "After 40 min of dark adaptation vision is SCOTOPIC (rod-driven); threshold is lowest near 507 nm.", "ow": ["440 nm is the S-cone (photopic) peak.", "Correct. Rod-driven scotopic vision peaks near 507 nm.", "535 nm is the M-cone (green) peak.", "555 nm is the photopic cone peak, not scotopic."]}'),
  ('4a9727a1-37','{"options": ["Re-isomerization of all-trans retinal to 11-cis retinal in the RPE", "Release of glutamate at the synaptic terminal in the dark", "Transport of all-trans retinal from photoreceptors to RPE", "Photoisomerization of 11-cis retinal in the outer segment"], "correct": 0, "decode": "Rhodopsin regeneration is the RPE RE-ISOMERIZATION of all-trans back to 11-cis retinal; block it and rhodopsin cannot regenerate.", "ow": ["Correct. Re-isomerization in the RPE is the regeneration step.", "Dark-current glutamate release is unrelated to regeneration.", "Transport is a prerequisite but not the regeneration step itself.", "Photoisomerization is the light trigger, not the regeneration."]}'),
  ('e3dc5d23-3h','{"options": ["Color perception", "Form perception", "Motion perception", "Spatial contrast sensitivity"], "correct": 0, "decode": "COLOR perception is the most vulnerable function and fails earliest in optic neuritis.", "ow": ["Correct. Color is selectively affected earliest in optic nerve disease.", "Form perception is more resilient than color.", "Motion is the most resilient function, lost last.", "Contrast sensitivity is affected later than color."]}'),
  ('a6f38c71-4g','{"options": ["The JND stays a fixed fraction of the new background intensity", "The JND doubles because the background intensity doubled", "The JND stays constant regardless of the background intensity", "The JND decreases because more light is available"], "correct": 0, "decode": "Weber''s law keeps ΔI/I constant, so the JND stays a fixed FRACTION of the background.", "ow": ["Correct. The JND is a fixed fraction of the new background intensity.", "The JND does double in absolute terms, but the defining rule is the constant ratio; this option omits the ratio basis.", "The JND does not stay constant in absolute value.", "The JND does not decrease with more light; the ratio holds."]}'),
  ('07f3048e-4i','{"options": ["High-acuity pattern vision at the fovea", "Circadian rhythm entrainment via the suprachiasmatic nucleus", "Motion detection in the peripheral visual field", "ON-pathway activation feeding into the LGB parvocellular layers"], "correct": 1, "decode": "ipRGCs express melanopsin and drive CIRCADIAN entrainment via the suprachiasmatic nucleus.", "ow": ["ipRGCs are non-image-forming and do not serve foveal pattern vision.", "Correct. ipRGCs entrain circadian rhythm through the SCN.", "They do not detect peripheral motion.", "They do not feed the LGB parvocellular pattern pathway."]}'),
  ('9ee6b619-6x','{"options": ["Pituitary adenoma", "Central serous retinopathy", "Retinitis pigmentosa", "Glaucoma"], "correct": 2, "decode": "Constricted isopters with a central island plus years of night blindness point to RETINITIS PIGMENTOSA.", "ow": ["A pituitary adenoma gives bitemporal hemianopia, not concentric constriction.", "Central serous retinopathy gives a central scotoma.", "Correct. RP is a rod dystrophy giving a ring scotoma to a central island with nyctalopia.", "Glaucoma gives arcuate defects and nasal steps, not this pattern with night blindness."]}'),
  ('e5daff48-4x','{"options": ["FALANT", "D-15", "HRR", "FM-100 Hue test"], "correct": 3, "decode": "The FM-100 Hue test defines the exact AXIS and SEVERITY of a color defect.", "ow": ["FALANT is an occupational pass/fail test, not diagnostic.", "The D-15 is a screener, less detailed than FM-100.", "HRR screens red-green and blue-yellow but does not quantify as precisely.", "Correct. FM-100 gives a total error score and the axis of confusion."]}'),
  ('ee0d8d3e-ai','{"options": ["Convergence insufficiency; passes Sheard''s", "Divergence excess; passes Sheard''s", "Basic exophoria; passes Sheard''s", "Convergence insufficiency; fails Sheard''s"], "correct": 3, "decode": "Ortho at distance, near exophoria, receded NPC, near symptoms = CONVERGENCE INSUFFICIENCY, and PFC below 2× the phoria FAILS Sheard''s.", "ow": ["It is CI, but the PFC (10 PD) is below 2×12 = 24 PD, so it fails Sheard''s, not passes.", "This is not divergence excess; the deviation is exo at near with ortho at distance.", "It is not basic exophoria; distance is ortho.", "Correct. CI that fails Sheard''s (PFC 10 PD < 24 PD needed)."]}'),
  ('c04c3f9e-72','{"options": ["Normal retinal correspondence with strabismus", "Unharmonious anomalous retinal correspondence", "Suppression of the right eye", "Harmonious anomalous retinal correspondence"], "correct": 3, "decode": "An after-image displacement that MATCHES the angle of deviation indicates HARMONIOUS ARC.", "ow": ["NRC would give a symmetric cross, not a deviation-matched displacement.", "Unharmonious ARC would show a displacement not matching the deviation.", "Suppression would prevent the after-image from being seen.", "Correct. Displacement matching the angle of deviation is harmonious ARC."]}'),
  ('b2f7a4ef-72','{"options": ["Gaze-evoked nystagmus", "Infantile nystagmus syndrome with null point", "Acquired pendular nystagmus", "Jerk nystagmus from a vestibular lesion"], "correct": 1, "decode": "Congenital pendular nystagmus that DAMPENS with convergence and has a null point is INFANTILE NYSTAGMUS SYNDROME.", "ow": ["Gaze-evoked nystagmus appears only at eccentric gaze, not in primary position.", "Correct. Congenital onset, pendular, convergence-dampening, with a null point = INS.", "Acquired pendular nystagmus has adult onset and does not dampen with convergence.", "Vestibular jerk nystagmus has fast and slow phases, unlike this pendular pattern."]}'),
  ('74494c69-40','{"options": ["A plaid pattern", "A diagonal grating", "Alternating suppression of each grating", "Permanent suppression of the non-dominant eye''s grating"], "correct": 2, "decode": "Incompatible images to each eye produce BINOCULAR RIVALRY: alternating suppression of each grating.", "ow": ["A plaid requires fusible, compatible components; rivalry does not blend them.", "A diagonal grating would be a fusion result, not rivalry.", "Correct. Rivalry alternates suppression between the two gratings.", "Suppression alternates rather than being permanent for one eye."]}'),
  ('dc0b5ee7-3h','{"options": ["Reduced stereo", "Stereo unaffected because the left eye is normal", "No measurable stereopsis", "Normal stereo"], "correct": 2, "decode": "Deep constant strabismic amblyopia disrupts binocular neurons, so there is NO measurable stereopsis.", "ow": ["Reduced stereo understates it; deep amblyopia typically abolishes stereopsis.", "A normal fellow eye does not preserve stereopsis without binocular input.", "Correct. Deep strabismic amblyopia gives no measurable stereopsis.", "Normal stereo is not expected with deep amblyopia."]}'),
  ('ef7891f8-6r','{"options": ["Ishihara color vision testing", "Humphrey visual field testing", "Beery VMI", "TVPS-3"], "correct": 3, "decode": "Figure-ground and place-keeping problems with normal acuity/BV are VPS deficits, best assessed by the TVPS-3.", "ow": ["Ishihara tests color, not visual perception.", "A Humphrey field test does not assess VPS.", "Beery VMI tests visual-motor copying, not the described non-motor deficit.", "Correct. TVPS-3 assesses non-motor VPS in children."]}'),
  ('9e3b0468-4w','{"options": ["Snellen acuity testing", "Humphrey visual field test", "DTVP-2 motor-enhanced subtest", "TVPS-3"], "correct": 3, "decode": "A poor Beery VMI could be perceptual OR motor, so do the motor-free TVPS-3 to separate them.", "ow": ["Snellen acuity does not separate perception from motor.", "A visual field test does not address this.", "The DTVP-2 also separates them but is less specific for the perceptual subtype than TVPS-3.", "Correct. TVPS-3 is motor-free and isolates perception from motor output."]}'),
  ('a60dff7e-q','{"options": ["13.5 mm behind cornea", "22 mm each", "24 mm", "~150,000/mm²"], "correct": 3, "decode": "Foveal cone density is about 150,000/mm², the highest-acuity zone.", "ow": ["13.5 mm behind the cornea is the center of rotation, not a cone density.", "22 mm is an axis length, not a density.", "24 mm is the AP axis length, not a density.", "Correct. Foveal cone density is ~150,000/mm²."]}'),
  ('07b1d47d-n','{"options": ["22 mm each", "24 mm", "13.5 mm behind cornea", "~150,000/mm²"], "correct": 1, "decode": "The Y (AP) axis is about 24 mm, the full eyeball depth.", "ow": ["22 mm is the X and Z axis length.", "Correct. The Y (AP) axis is 24 mm.", "13.5 mm behind the cornea is the center of rotation.", "150,000/mm² is foveal cone density, not an axis length."]}'),
  ('01a93390-j','{"options": ["13.5 mm behind cornea", "~150,000/mm²", "24 mm", "22 mm each"], "correct": 3, "decode": "The X and Z axes are each about 22 mm, shorter than the AP axis.", "ow": ["13.5 mm behind the cornea is the center of rotation.", "150,000/mm² is a cone density, not an axis length.", "24 mm is the AP (Y) axis.", "Correct. The X and Z axes are 22 mm each."]}'),
  ('91dff314-p','{"options": ["13.5 mm behind cornea", "~150,000/mm²", "22 mm each", "24 mm"], "correct": 0, "decode": "The center of rotation is about 13.5 mm behind the cornea; all axes pass through it.", "ow": ["Correct. The center of rotation is 13.5 mm behind the cornea.", "150,000/mm² is foveal cone density.", "22 mm is an axis length.", "24 mm is the AP axis length."]}'),
  ('59962d74-o','{"options": ["62.5 mm", "~150,000/mm²", "22 mm each", "24 mm"], "correct": 0, "decode": "The adult IPD averages about 62.5 mm, used in spectacle dispensing.", "ow": ["Correct. Adult IPD averages ~62.5 mm.", "150,000/mm² is a cone density.", "22 mm is an axis length.", "24 mm is the AP axis length."]}'),
  ('65dc9772-p','{"options": ["2–5 mm", "24 mm", "~150,000/mm²", "22 mm each"], "correct": 0, "decode": "The normal pupil ranges about 2–5 mm (physiologic 3–4 mm).", "ow": ["Correct. Normal pupil range is 2–5 mm.", "24 mm is the AP axis length.", "150,000/mm² is a cone density.", "22 mm is an axis length."]}'),
  ('5a1ba6f5-u','{"options": ["~24 mm behind the cornea", "~13.5 mm behind the cornea", "~17 mm in front of the cornea", "~7 mm behind the cornea"], "correct": 0, "decode": "The secondary focal point F₂ sits about 24 mm behind the cornea, on the retina in emmetropia.", "ow": ["Correct. F₂ is ~24 mm behind the cornea.", "13.5 mm behind the cornea is the center of rotation.", "17 mm in front of the cornea is the primary focal point region, not F₂ behind.", "7 mm behind the cornea is far too shallow for F₂."]}'),
  ('8fb061ba-25','{"options": ["Photopic", "Rhodopsin", "Kohlrausch kink", "Purkinje shift"], "correct": 0, "decode": "PHOTOPIC vision is bright-light, cone-mediated, peaking at 555 nm.", "ow": ["Correct. Photopic = bright-light cone vision, peak 555 nm.", "Rhodopsin is the rod pigment, not the term for bright-light vision.", "The Kohlrausch kink is a point on the adaptation curve.", "The Purkinje shift is a spectral sensitivity change."]}'),
  ('31bdf9e5-38','{"options": ["Photopic", "Purkinje shift", "Rhodopsin", "Kohlrausch kink"], "correct": 1, "decode": "The PURKINJE SHIFT is the move of peak sensitivity from 555 nm to 507 nm as light decreases.", "ow": ["Photopic is the bright-light state, not the shift itself.", "Correct. The Purkinje shift is 555→507 nm as light falls.", "Rhodopsin is a pigment, not the sensitivity shift.", "The Kohlrausch kink is the adaptation-curve inflection."]}'),
  ('e906e022-3m','{"options": ["Purkinje shift", "Rhodopsin", "Photopic", "Kohlrausch kink"], "correct": 3, "decode": "The KOHLRAUSCH KINK is the ~7-minute inflection where rod sensitivity takes over from cones.", "ow": ["The Purkinje shift is a spectral change, not the curve inflection.", "Rhodopsin is a pigment, not a curve point.", "Photopic is the bright-light state.", "Correct. The Kohlrausch kink is the ~7-minute cone-to-rod inflection."]}'),
  ('590e88d1-2v','{"options": ["Purkinje shift", "Photopic", "Rhodopsin", "Kohlrausch kink"], "correct": 2, "decode": "RHODOPSIN is the rod photopigment that bleaches in light and regenerates in the dark (needs vitamin A).", "ow": ["The Purkinje shift is a sensitivity change, not a pigment.", "Photopic is the bright-light state.", "Correct. Rhodopsin is the rod pigment that bleaches and regenerates.", "The Kohlrausch kink is a curve inflection."]}'),
  ('acf81d16-1u','{"options": ["Photopic", "Purkinje shift", "Erythrolabe", "Kohlrausch kink"], "correct": 2, "decode": "ERYTHROLABE is the red-sensitive cone pigment, peak ~750 nm (L-cones).", "ow": ["Photopic is the bright-light state, not a pigment.", "The Purkinje shift is a sensitivity change.", "Correct. Erythrolabe is the red L-cone pigment.", "The Kohlrausch kink is a curve inflection."]}'),
  ('fa5cf3a2-1w','{"options": ["Chlorolabe", "Photopic", "Kohlrausch kink", "Purkinje shift"], "correct": 0, "decode": "CHLOROLABE is the green-sensitive cone pigment, peak ~535 nm (M-cones).", "ow": ["Correct. Chlorolabe is the green M-cone pigment.", "Photopic is the bright-light state.", "The Kohlrausch kink is a curve inflection.", "The Purkinje shift is a sensitivity change."]}'),
  ('669c317c-1v','{"options": ["Purkinje shift", "Cyanolabe", "Kohlrausch kink", "Photopic"], "correct": 1, "decode": "CYANOLABE is the blue-sensitive cone pigment, peak ~440 nm (S-cones).", "ow": ["The Purkinje shift is a sensitivity change, not a pigment.", "Correct. Cyanolabe is the blue S-cone pigment.", "The Kohlrausch kink is a curve inflection.", "Photopic is the bright-light state."]}'),
  ('7c2c9e8e-2f','{"options": ["Purkinje shift", "Kohlrausch kink", "Photopic", "Nodal point"], "correct": 3, "decode": "The NODAL POINT is where rays pass undeviated; angle alpha is measured here.", "ow": ["The Purkinje shift is a sensitivity change, not a point.", "The Kohlrausch kink is a curve inflection.", "Photopic is the bright-light state.", "Correct. The nodal point passes rays undeviated and defines angle alpha."]}'),
  ('2e53a61c-27','{"options": ["Photopic", "Purkinje shift", "Cardinal points", "Kohlrausch kink"], "correct": 2, "decode": "CARDINAL POINTS are the six key points that define the eye''s optical system.", "ow": ["Photopic is the bright-light state.", "The Purkinje shift is a sensitivity change.", "Correct. Cardinal points are the six optical reference points.", "The Kohlrausch kink is a curve inflection."]}'),
  ('0af24f54-1t','{"options": ["Parastriate cortex", "Dorsal stream", "Ventral stream", "Peristriate cortex"], "correct": 0, "decode": "The PARASTRIATE cortex is Brodmann area 18 (secondary visual processing).", "ow": ["Correct. Parastriate cortex = area 18.", "The dorsal stream is a pathway, not a Brodmann area label here.", "The ventral stream is a pathway, not area 18.", "Peristriate cortex is area 19."]}'),
  ('66db7bb0-2e','{"options": ["Peristriate cortex", "Parastriate cortex", "Ventral stream", "Dorsal stream"], "correct": 0, "decode": "The PERISTRIATE cortex is Brodmann area 19 (higher processing: motion, form, object recognition).", "ow": ["Correct. Peristriate cortex = area 19.", "Parastriate cortex is area 18.", "The ventral stream is a pathway, not area 19.", "The dorsal stream is a pathway, not area 19."]}'),
  ('b82876d0-1u','{"options": ["Ventral stream", "Parastriate cortex", "Dorsal stream", "Peristriate cortex"], "correct": 0, "decode": "The VENTRAL stream is the ''what'' pathway to the temporal lobe for object recognition.", "ow": ["Correct. Ventral stream = ''what'' pathway, object recognition.", "Parastriate cortex is area 18, not the ventral stream.", "The dorsal stream is the ''where'' pathway.", "Peristriate cortex is area 19, not the ventral stream."]}'),
  ('e51d6512-20','{"options": ["Ventral stream", "Parastriate cortex", "Peristriate cortex", "Dorsal stream"], "correct": 3, "decode": "The DORSAL stream is the ''where'' pathway to the parietal lobe for spatial location and motion.", "ow": ["The ventral stream is the ''what'' pathway.", "Parastriate cortex is area 18, not the dorsal stream.", "Peristriate cortex is area 19, not the dorsal stream.", "Correct. Dorsal stream = ''where'' pathway, spatial location and motion."]}'),
  ('6313d1b0-24','{"options": ["Peristriate cortex", "Parastriate cortex", "Ventral stream", "Duplicity theory"], "correct": 3, "decode": "DUPLICITY THEORY: the retina has two systems, scotopic (rods) and photopic (cones).", "ow": ["Peristriate cortex is area 19, not a retinal duplex theory.", "Parastriate cortex is area 18.", "The ventral stream is a cortical pathway.", "Correct. Duplicity theory describes the rod/cone dual system."]}'),
  ('551a9dc2-p','{"options": ["120° central", "60°", "75°", "100°"], "correct": 2, "decode": "The inferior visual field extent is about 75°.", "ow": ["120° is the binocular overlap, not the inferior extent.", "60° is the nasal/superior extent.", "Correct. The inferior extent is 75°.", "100° is the temporal extent."]}'),
  ('99417fce-p','{"options": ["120° central", "100°", "60°", "75°"], "correct": 1, "decode": "The temporal visual field extent is about 100°, the widest.", "ow": ["120° is the binocular overlap, not a monocular temporal extent.", "Correct. The temporal extent is 100°.", "60° is the nasal/superior extent.", "75° is the inferior extent."]}'),
  ('8973e73b-m','{"options": ["75°", "100°", "60°", "120° central"], "correct": 2, "decode": "The nasal visual field extent is about 60°, limited by the nose.", "ow": ["75° is the inferior extent.", "100° is the temporal extent.", "Correct. The nasal extent is 60°.", "120° is the binocular overlap."]}'),
  ('9def3932-o','{"options": ["100°", "120° central", "75°", "60°"], "correct": 1, "decode": "The binocular overlap is the central 120° seen by both eyes at once.", "ow": ["100° is the temporal monocular extent.", "Correct. The binocular overlap is the central 120°.", "75° is the inferior extent.", "60° is the nasal/superior extent."]}'),
  ('8664a783-p','{"options": ["30° each side", "100°", "60°", "75°"], "correct": 0, "decode": "The monocular crescent is about 30° on each side, seen by temporal retina alone.", "ow": ["Correct. The monocular crescent is 30° each side.", "100° is the temporal extent.", "60° is the nasal/superior extent.", "75° is the inferior extent."]}'),
  ('b4329470-r','{"options": ["75°", "100°", "Central 10°", "60°"], "correct": 2, "decode": "The Amsler grid covers the central 10° at 28–30 cm.", "ow": ["75° is the inferior field extent, not the Amsler coverage.", "100° is the temporal extent.", "Correct. The Amsler grid covers the central 10°.", "60° is the nasal/superior extent."]}'),
  ('52a8d81c-r','{"options": ["1°", "2°", "5°", "10°"], "correct": 0, "decode": "Each Amsler square subtends 1° of visual field.", "ow": ["Correct. One Amsler square = 1°.", "2° is too large for a single square.", "5° is far too large.", "10° is the whole grid, not one square."]}'),
  ('53ec669a-2h','{"options": ["Hemianopia", "Scotoma", "Quadrantanopia", "Perimetry"], "correct": 1, "decode": "A SCOTOMA is a localized area of reduced or absent vision within the field.", "ow": ["Hemianopia is loss of half the field, not a localized spot.", "Correct. A scotoma is a localized field defect.", "Quadrantanopia is loss of a quarter of the field.", "Perimetry is the mapping method, not a defect."]}'),
  ('30814cff-1m','{"options": ["Perimetry", "Scotoma", "Quadrantanopia", "Hemianopia"], "correct": 2, "decode": "QUADRANTANOPIA is loss of a quarter of the visual field.", "ow": ["Perimetry is the mapping method, not a defect.", "A scotoma is a localized spot, not a quadrant.", "Correct. Quadrantanopia is loss of a quarter of the field.", "Hemianopia is loss of half the field."]}'),
  ('5ecc8402-1n','{"options": ["Hemianopia", "Perimetry", "Scotoma", "Quadrantanopia"], "correct": 1, "decode": "PERIMETRY is the systematic mapping of the visual field.", "ow": ["Hemianopia is a half-field defect, not the mapping method.", "Correct. Perimetry is systematic field mapping.", "A scotoma is a localized defect.", "Quadrantanopia is a quarter-field defect."]}'),
  ('c022b29f-26','{"options": ["Quadrantanopia", "Apostilb", "Hemianopia", "Scotoma"], "correct": 1, "decode": "The APOSTILB is the luminance unit for the Goldmann bowl background and stimuli.", "ow": ["Quadrantanopia is a field defect, not a luminance unit.", "Correct. The apostilb is the Goldmann luminance unit.", "Hemianopia is a field defect.", "A scotoma is a field defect."]}'),
  ('728834ad-29','{"options": ["Anomalous trichromacy", "Protan-", "Monochromacy", "Dichromacy"], "correct": 0, "decode": "ANOMALOUS TRICHROMACY: all three cone types are present but one has a shifted peak.", "ow": ["Correct. Anomalous trichromacy has a shifted cone peak.", "''Protan-'' names a defect axis, not this three-cone-shifted category.", "Monochromacy has only one cone type.", "Dichromacy has only two cone types."]}'),
  ('8ec7ba71-1w','{"options": ["Monochromacy", "Dichromacy", "Protan-", "Anomalous trichromacy"], "correct": 1, "decode": "DICHROMACY: only two functioning cone types; one is absent.", "ow": ["Monochromacy has only one cone type.", "Correct. Dichromacy has two functioning cone types.", "''Protan-'' names an axis, not the two-cone category.", "Anomalous trichromacy keeps all three cones with a shifted peak."]}'),
  ('d86a843a-25','{"options": ["Monochromacy", "Dichromacy", "Protan-", "Anomalous trichromacy"], "correct": 0, "decode": "MONOCHROMACY: only one cone type (or rods only); complete color blindness.", "ow": ["Correct. Monochromacy has one cone type; complete color blindness.", "Dichromacy has two cone types.", "''Protan-'' names an axis, not the single-cone category.", "Anomalous trichromacy keeps all three cones with a shifted peak."]}'),
  ('c47f0345-1v','{"options": ["Tropia", "Heterophoria", "Fusion", "Phoria"], "correct": 2, "decode": "FUSION is the blending of the two ocular images into one percept.", "ow": ["A tropia is a manifest deviation, not image blending.", "Heterophoria is a latent deviation, not fusion itself.", "Correct. Fusion blends the two images into one.", "A phoria is a latent deviation tendency, not fusion."]}'),
  ('4c2c9113-2j','{"options": ["Fusion", "Phoria", "NRC", "Tropia"], "correct": 1, "decode": "A PHORIA is a latent tendency to deviate, revealed only under dissociation.", "ow": ["Fusion is image blending, not a latent deviation.", "Correct. A phoria is a latent, dissociation-revealed deviation.", "NRC is a correspondence state, not a deviation.", "A tropia is a manifest, not latent, deviation."]}'),
  ('4e27dd1c-1r','{"options": ["Fusion", "Phoria", "Tropia", "Heterophoria"], "correct": 2, "decode": "A TROPIA is a manifest (constant) deviation, always present.", "ow": ["Fusion is image blending, not a deviation.", "A phoria is latent, not manifest.", "Correct. A tropia is a manifest, always-present deviation.", "Heterophoria is a latent deviation, not a tropia."]}'),
  ('130cee64-1r','{"options": ["Tropia", "Orthophoria", "Fusion", "Heterophoria"], "correct": 1, "decode": "ORTHOPHORIA is ideal alignment with no deviation tendency.", "ow": ["A tropia is a manifest deviation, the opposite of orthophoria.", "Correct. Orthophoria is ideal alignment with no deviation.", "Fusion is image blending, not the alignment state.", "Heterophoria is a latent deviation, not zero tendency."]}'),
  ('05bac6a5-1r','{"options": ["Tropia", "NRC", "Fusion", "Phoria"], "correct": 1, "decode": "NRC (normal retinal correspondence): both foveas share the same visual direction.", "ow": ["A tropia is a deviation, not a correspondence state.", "Correct. NRC means both foveas share one visual direction.", "Fusion is image blending, not correspondence.", "A phoria is a latent deviation, not correspondence."]}'),
  ('d16a54df-2r','{"options": ["Fusion", "Phoria", "ARC", "Tropia"], "correct": 2, "decode": "ARC: the fovea of one eye and an extrafoveal area of the other share a visual direction.", "ow": ["Fusion is image blending, not anomalous correspondence.", "A phoria is a latent deviation.", "Correct. ARC pairs one fovea with the other eye''s extrafoveal point.", "A tropia is a deviation, not a correspondence state."]}'),
  ('b54f584f-38','{"options": ["Phoria", "Fusion", "Panum''s area", "Tropia"], "correct": 2, "decode": "PANUM''S AREA is the zone around the horopter where non-corresponding points still fuse.", "ow": ["A phoria is a latent deviation, not a fusional zone.", "Fusion is the outcome; Panum''s area is where it can occur.", "Correct. Panum''s area allows fusion despite small disparity.", "A tropia is a manifest deviation, not a fusional zone."]}'),
  ('4f1cb51e-26','{"options": ["Tropia", "Fusion", "Phoria", "Suppression"], "correct": 3, "decode": "SUPPRESSION is the brain''s active inhibition of one eye''s signal.", "ow": ["A tropia is a manifest deviation, not inhibition.", "Fusion is image blending, the opposite of suppression.", "A phoria is a latent deviation, not inhibition.", "Correct. Suppression is active inhibition of one eye''s signal."]}'),
  ('ebd416f7-2v','{"options": ["Tropia", "Phoria", "Fusion", "Amblyopia"], "correct": 3, "decode": "AMBLYOPIA is reduced acuity in one eye without structural pathology (''lazy eye'').", "ow": ["A tropia is a deviation, not reduced acuity per se.", "A phoria is a latent deviation.", "Fusion is image blending.", "Correct. Amblyopia is reduced acuity with no structural cause."]}'),
  ('c14b3597-25','{"options": ["Phoria", "Fusion", "Tropia", "Diplopia"], "correct": 3, "decode": "DIPLOPIA is double vision from non-corresponding retinal stimulation.", "ow": ["A phoria is a latent deviation, not double vision itself.", "Fusion is single-image blending, the opposite of diplopia.", "A tropia is a deviation that may cause diplopia but is not the doubling.", "Correct. Diplopia is double vision from non-corresponding stimulation."]}'),
  ('15217d09-2g','{"options": ["Retinal blood vessels lit obliquely", "Traction on the vitreous base", "White blood cells moving in retinal capillaries", "Vitreous opacities casting shadows"], "correct": 2, "decode": "Scheerer''s blue-field phenomenon comes from WHITE BLOOD CELLS moving in perifoveal capillaries.", "ow": ["Retinal vessels lit obliquely give Purkinje figures, not moving bright dots.", "Vitreous-base traction is not the blue-field mechanism.", "Correct. Leukocytes in perifoveal capillaries create the moving bright dots.", "Vitreous opacities cast floaters, not the blue-field dots."]}'),
  ('52d22f8a-17','{"options": ["Retinal blood vessels", "Vitreous opacities", "Lens fiber sutures", "White blood cells in capillaries"], "correct": 0, "decode": "Purkinje figures are entoptic shadows of one''s own RETINAL BLOOD VESSELS.", "ow": ["Correct. Purkinje figures are shadows of the retinal vessels.", "Vitreous opacities give floaters, not the vascular tree image.", "Lens sutures give the physiologic halo, not Purkinje figures.", "White blood cells give the blue-field phenomenon, not Purkinje figures."]}'),
  ('3933d1d3-19','{"options": ["Raised intraocular pressure", "Lens fiber diffraction", "Retinal capillary blood flow", "Vitreous traction"], "correct": 3, "decode": "Moore''s lightning streaks come from VITREOUS TRACTION on the retina.", "ow": ["Raised IOP is not the cause of Moore''s streaks.", "Lens diffraction gives the physiologic halo, not streaks.", "Retinal capillary flow gives the blue-field phenomenon.", "Correct. Moore''s lightning streaks are from vitreous traction."]}'),
  ('33958ce2-1e','{"options": ["Ganglion cells stimulated directly", "Light entering the pupil normally", "Diffraction at the cornea", "Vitreous floaters drifting"], "correct": 0, "decode": "A PHOSPHENE is light perceived from direct mechanical or electrical stimulation of GANGLION cells, with no light entering.", "ow": ["Correct. A phosphene comes from directly stimulated ganglion cells.", "Normal light entering the pupil is ordinary vision, not a phosphene.", "Corneal diffraction is not the phosphene mechanism.", "Drifting floaters are vitreous shadows, not phosphenes."]}'),
  ('0c30860c-1z','{"options": ["Corneal epithelial edema", "Raised intraocular pressure", "Lens fibers diffracting light", "Vitreous syneresis with age"], "correct": 2, "decode": "The PHYSIOLOGIC colored halo comes from LENS FIBERS diffracting light; a pathologic halo comes from corneal edema.", "ow": ["Corneal epithelial edema gives a PATHOLOGIC halo, not the physiologic one.", "Raised IOP causes the pathologic (edema) halo.", "Correct. The physiologic halo is lens-fiber diffraction.", "Vitreous syneresis gives floaters, not a colored halo."]}'),
  ('3e376fd5-1c','{"options": ["Provide most of the eye''s refractive power", "Produce the aqueous humor of the eye", "Absorb stray light within the eyeball", "Control the size of the eye''s pupil"], "correct": 0, "decode": "The cornea''s main optical job is to provide MOST of the eye''s refractive power (the air-cornea interface).", "ow": ["Correct. The cornea provides most of the eye''s focusing power.", "Aqueous is produced by the ciliary body, not the cornea.", "Absorbing stray light is the RPE''s role.", "Pupil size is controlled by the iris."]}'),
  ('a59dbe4e-1d','{"options": ["+10.00 D", "+60.00 D", "+20.00 D", "+43.00 D"], "correct": 3, "decode": "The cornea contributes about +43 D of the eye''s ~+60 D total.", "ow": ["+10 D is far too low for the cornea.", "+60 D is the whole eye, not the cornea alone.", "+20 D is closer to the lens contribution.", "Correct. The cornea is about +43 D."]}'),
  ('e548bc96-19','{"options": ["Tear production", "Accommodation", "Color perception", "Phototransduction"], "correct": 1, "decode": "The crystalline lens primarily provides ACCOMMODATION (adjustable focus).", "ow": ["Tear production is the lacrimal gland''s role.", "Correct. The lens provides accommodation.", "Color perception is a cone function.", "Phototransduction happens in photoreceptors."]}'),
  ('cb77335f-19','{"options": ["Changes the axial length of the eye", "Changes the thickness of the retina", "Changes the curvature of the cornea", "Changes the refractive power of the lens"], "correct": 3, "decode": "Accommodation changes the REFRACTIVE POWER of the lens by altering its curvature.", "ow": ["Axial length is fixed in adults, not changed by accommodation.", "Retinal thickness is unrelated to accommodation.", "Corneal curvature does not change to accommodate.", "Correct. Accommodation changes the lens''s refractive power."]}'),
  ('918baee7-1d','{"options": ["Flatter", "More convex", "Less powerful", "Thinner"], "correct": 1, "decode": "During accommodation the lens becomes MORE CONVEX (more power) for near focus.", "ow": ["Flatter describes the unaccommodated distance state.", "Correct. The lens rounds up (more convex) for near.", "Less powerful is the distance state, not accommodation.", "Thinner describes the relaxed distance lens."]}'),
  ('bc82008b-1b','{"options": ["Ciliary muscle", "Medial rectus", "Superior rectus", "Orbicularis oculi"], "correct": 0, "decode": "The CILIARY muscle controls lens shape via the zonules for accommodation.", "ow": ["Correct. The ciliary muscle drives accommodation.", "The medial rectus moves the eye, not the lens.", "The superior rectus moves the eye.", "The orbicularis oculi closes the lids."]}'),
  ('b4d5eed6-1f','{"options": ["1.00", "1.70", "1.376", "1.33"], "correct": 2, "decode": "The refractive index of the cornea is about 1.376.", "ow": ["1.00 is air, not the cornea.", "1.70 is far too high for ocular tissue.", "Correct. The corneal index is ~1.376.", "1.33 is water/aqueous, just below the cornea."]}'),
  ('ce991615-18','{"options": ["1.80", "1.33", "1.50", "1.00"], "correct": 3, "decode": "The refractive index of air is 1.00, the reference value.", "ow": ["1.80 is high-index glass.", "1.33 is water.", "1.50 is crown glass/plastic.", "Correct. Air is n = 1.00."]}'),
  ('b3304d36-1e','{"options": ["Ora serrata", "Peripheral retina", "Fovea centralis", "Optic disc"], "correct": 2, "decode": "Cone density peaks at the FOVEA CENTRALIS.", "ow": ["The ora serrata is the peripheral retinal edge, rod territory.", "The peripheral retina is rod-rich, not cone-dense.", "Correct. Cones are densest at the fovea centralis.", "The optic disc has no photoreceptors."]}'),
  ('4af81bd8-1n','{"options": ["Many large blood vessels feeding the region", "High cone density and minimal overlying retinal tissue", "No functioning photoreceptors at that point", "An especially high density of rod photoreceptors"], "correct": 1, "decode": "The fovea gives peak acuity through HIGH CONE DENSITY plus minimal overlying tissue.", "ow": ["Large blood vessels would reduce, not improve, acuity.", "Correct. Dense cones and displaced inner layers give the sharpest image.", "''No photoreceptors'' describes the blind spot, not the fovea.", "The fovea is rod-free, not rod-dense."]}'),
  ('a9be4a0d-1b','{"options": ["Ocular surfaces", "Extraocular muscles", "Optic nerve fibers", "The retina only"], "correct": 0, "decode": "Purkinje images are reflections from the eye''s four refracting OCULAR SURFACES.", "ow": ["Correct. Purkinje images reflect off ocular surfaces.", "Extraocular muscles do not produce these reflections.", "Optic nerve fibers do not reflect light this way.", "They are surface reflections, not retinal-only."]}'),
  ('a4403477-1p','{"options": ["Increase accommodation", "Become more sensitive in low illumination", "Increase pupil size permanently", "Adjust to bright light"], "correct": 1, "decode": "Dark adaptation is the rod-driven rise in SENSITIVITY in low illumination.", "ow": ["Accommodation is focusing, not dark adaptation.", "Correct. Dark adaptation increases sensitivity in low light.", "Pupil dilation is transient, not the defining process.", "Adjusting to bright light is light adaptation, the opposite."]}'),
  ('2ea7c842-19','{"options": ["Rhodopsin", "Hemoglobin", "Iodopsin", "Melanin"], "correct": 0, "decode": "The rod pigment is RHODOPSIN (visual purple).", "ow": ["Correct. Rods contain rhodopsin.", "Hemoglobin is a blood protein, not a visual pigment.", "Iodopsin is a cone pigment.", "Melanin is RPE/skin pigment, not a rod pigment."]}'),
  ('f734f7f7-15','{"options": ["Lens capsule", "Extraocular muscles", "Photoreceptors", "Cornea"], "correct": 2, "decode": "Phototransduction happens in the PHOTORECEPTOR outer segments.", "ow": ["The lens capsule does not transduce light.", "Extraocular muscles do not transduce light.", "Correct. Phototransduction occurs in the photoreceptors.", "The cornea focuses light but does not transduce it."]}'),
  ('93993fa6-16','{"options": ["Vitreous cavity only", "Optic nerve", "Subretinal space", "Anterior and posterior chambers"], "correct": 3, "decode": "Aqueous humor fills the ANTERIOR and POSTERIOR chambers of the front segment.", "ow": ["The vitreous cavity holds vitreous, not aqueous.", "The optic nerve is not a fluid chamber.", "The subretinal space is not where aqueous sits.", "Correct. Aqueous fills the anterior and posterior chambers."]}'),
  ('a077c9a2-11','{"options": ["Control pupil size", "Maintain the shape of the eyeball", "Produce visual pigments", "Produce tears"], "correct": 1, "decode": "The vitreous humor helps MAINTAIN THE SHAPE of the eyeball and supports the retina.", "ow": ["Pupil size is controlled by the iris, not the vitreous.", "Correct. The vitreous maintains globe shape.", "It does not produce visual pigments.", "It does not produce tears."]}'),
  ('9b502311-1a','{"options": ["Lens", "Optic disc", "Fovea", "Macula"], "correct": 1, "decode": "The blind spot corresponds to the OPTIC DISC, which has no photoreceptors.", "ow": ["The lens is not part of the retina and is not the blind spot.", "Correct. The optic disc is the blind spot.", "The fovea is a peak-vision area, the opposite of blind.", "The macula is a high-acuity area, not the blind spot."]}'),
  ('9b6e3a2c-1z','{"options": ["Frontal cortex", "Cerebellum", "Occipital cortex", "Temporal pole"], "correct": 2, "decode": "The optic radiations run from the lateral geniculate nucleus to the OCCIPITAL cortex.", "ow": ["The frontal cortex handles planning, not primary vision.", "The cerebellum handles coordination, not vision.", "Correct. The optic radiations end in the occipital cortex.", "The temporal pole handles memory and hearing, not primary vision."]}'),
  ('2114980d-17','{"options": ["Occipital lobe", "Temporal lobe", "Parietal lobe", "Frontal lobe"], "correct": 0, "decode": "The primary visual cortex is in the OCCIPITAL lobe.", "ow": ["Correct. The primary visual cortex is in the occipital lobe.", "The temporal lobe handles hearing and memory.", "The parietal lobe handles touch and spatial sense.", "The frontal lobe handles planning."]}'),
  ('cd9f4a69-14','{"options": ["Brodmann area 44", "Brodmann area 17", "Brodmann area 41", "Brodmann area 4"], "correct": 1, "decode": "The primary visual cortex is Brodmann area 17 (striate cortex).", "ow": ["Area 44 is Broca''s speech area.", "Correct. The primary visual cortex is area 17.", "Area 41 is primary auditory cortex.", "Area 4 is primary motor cortex."]}'),
  ('8f6accd5-13','{"options": ["Peripheral vision", "Central detailed vision", "Tear production", "Aqueous production"], "correct": 1, "decode": "The macula provides central detailed (cone) vision.", "ow": ["Peripheral vision is a rod-rich role, not the macula.", "Correct. The macula gives central detailed vision.", "Tear production is the lacrimal gland''s role.", "Aqueous production is the ciliary body''s role."]}'),
  ('8a42e185-z','{"options": ["Macula", "Fovea", "Ora serrata", "Blind spot"], "correct": 3, "decode": "The optic disc is also known as the BLIND SPOT (fiber exit, no receptors).", "ow": ["The macula is a peak-vision area, not the disc.", "The fovea is a peak-vision area, not the disc.", "The ora serrata is the peripheral retinal edge.", "Correct. The optic disc is the blind spot."]}'),
  ('beed44d1-1o','{"options": ["Cornea", "Choroid", "Retina", "Lens"], "correct": 2, "decode": "Photoreceptors that begin the visual pathway are in the RETINA.", "ow": ["The cornea focuses light but has no photoreceptors.", "The choroid is the blood supply behind the retina.", "Correct. Photoreceptors are in the retina.", "The lens focuses light but has no photoreceptors."]}'),
  ('14f275dd-2i','{"options": ["Ishihara", "Schirmer", "Amsler grid", "Worth 4 Dot"], "correct": 3, "decode": "The WORTH 4 DOT test detects suppression and assesses binocular fusion.", "ow": ["Ishihara tests color, not suppression.", "The Schirmer test measures tear volume.", "The Amsler grid tests the macula.", "Correct. The Worth 4 Dot detects suppression and tests fusion."]}'),
  ('a018304a-28','{"options": ["Maddox rod", "Amsler grid", "Cover test", "Ishihara"], "correct": 1, "decode": "The AMSLER GRID evaluates central retinal/macular function.", "ow": ["The Maddox rod checks alignment, not the macula.", "Correct. The Amsler grid tests macular function.", "The cover test checks eye deviation.", "Ishihara tests color."]}'),
  ('b8d216e3-1i','{"options": ["Lens-retina interface", "Aqueous-lens interface", "Air-cornea interface", "Vitreous-retina interface"], "correct": 2, "decode": "The largest refractive change occurs at the AIR-CORNEA interface (biggest index jump).", "ow": ["The lens-retina interface is not where the big bend occurs.", "The aqueous-lens interface has a small index difference.", "Correct. The air-cornea interface bends light the most.", "The vitreous-retina interface has a negligible index jump."]}'),
  ('b3ab0c97-1v','{"options": ["5 minutes of arc", "1 minute of arc", "20 minutes of arc", "10 minutes of arc"], "correct": 1, "decode": "20/20 vision resolves detail subtending about 1 minute of arc.", "ow": ["5 minutes of arc is much coarser than 20/20.", "Correct. 20/20 corresponds to 1 minute of arc.", "20 minutes of arc is far coarser.", "10 minutes of arc maps to much poorer acuity."]}'),
  ('3e7c5390-1f','{"options": ["Stereopsis and depth perception", "Only peripheral vision", "Only color vision", "Better dark adaptation only"], "correct": 0, "decode": "Binocular vision yields STEREOPSIS and depth perception from two viewpoints.", "ow": ["Correct. Binocular vision provides stereopsis and depth.", "Peripheral vision does not require two eyes.", "Color vision does not require two eyes.", "Dark adaptation does not require two eyes."]}'),
  ('59cf0f07-z','{"options": ["Bipolar and ganglion cells", "Muller and bipolar cells", "Rods and cones", "Amacrine and horizontal cells"], "correct": 2, "decode": "The two photoreceptors are RODS and CONES.", "ow": ["Bipolar and ganglion cells process the signal, not photoreceptors.", "Muller and bipolar cells are support/processing cells.", "Correct. The photoreceptors are rods and cones.", "Amacrine and horizontal cells are processing interneurons."]}'),
  ('5410b9e7-14','{"options": ["Lateral geniculate body", "Optic tract", "Optic radiation", "Optic nerve"], "correct": 3, "decode": "Retinal ganglion cell axons form the OPTIC NERVE first.", "ow": ["The lateral geniculate body is a downstream relay, not formed by the axons directly.", "The optic tract comes after the chiasm.", "The optic radiation comes after the geniculate.", "Correct. Ganglion cell axons form the optic nerve."]}'),
  ('7ca897e0-1c','{"options": ["Nasal", "Superior only", "Inferior only", "Temporal"], "correct": 0, "decode": "At the chiasm, NASAL retinal fibers cross while temporal fibers stay uncrossed.", "ow": ["Correct. Nasal fibers cross at the chiasm.", "The split is nasal/temporal, not superior-only.", "The split is nasal/temporal, not inferior-only.", "Temporal fibers do not cross."]}'),
  ('9599fdc2-1d','{"options": ["Optic radiation", "Ciliary nerve", "Optic tract", "Optic nerve"], "correct": 2, "decode": "After the chiasm, fibers continue as the OPTIC TRACT.", "ow": ["The optic radiation comes only after the geniculate relay.", "The ciliary nerve is unrelated to the visual pathway here.", "Correct. After the chiasm the fibers are the optic tract.", "The optic nerve is before the chiasm, not after."]}'),
  ('969e9866-1l','{"options": ["AMD and glaucoma", "Glaucoma and diabetic retinopathy", "Trachoma and corneal opacity", "Uncorrected refractive error and cataract"], "correct": 3, "decode": "The two biggest global vision-impairment causes are the CHEAP, fixable ones: uncorrected refractive error (number one) and cataract. Glaucoma and AMD blind fewer people worldwide than these two.", "ow": ["Important, but not the top two globally.", "Major causes, but below refractive error and cataract.", "Regional infectious causes, not the global top two.", "Correct. Uncorrected refractive error and cataract lead worldwide."]}'),
  ('a5c1e387-25','{"options": ["Over 80%", "About 20%", "About half", "Under 10%"], "correct": 0, "decode": "Because the leading causes (refractive error, cataract) are correctable, over 80% of global vision impairment is avoidable. The low percentages contradict that.", "ow": ["Correct. More than 80% of vision impairment is preventable or curable.", "Far too low given correctable causes dominate.", "Understates the avoidable fraction.", "Understates it badly."]}'),
  ('5857d045-1w','{"options": ["Pandemic", "Endemic", "Epidemic", "Sporadic"], "correct": 1, "decode": "''Constantly present at a low steady level'' is endemic. Epidemic is a sudden rise, pandemic is worldwide, sporadic is scattered cases.", "ow": ["Worldwide spread, not a steady local level.", "Correct. Endemic means constantly present at a low steady level.", "A sudden rise above baseline, not steady.", "Occasional scattered cases, not constant presence."]}'),
  ('6898812b-1m','{"options": ["Prevalence", "Incidence", "Endemicity", "Mortality"], "correct": 1, "decode": "Counting only NEW cases over time is incidence. Prevalence counts all existing cases at a point; mortality is deaths.", "ow": ["Prevalence counts all cases, new and old.", "Correct. Incidence counts only new cases over a period.", "A pattern of presence, not a case count.", "Deaths, not new cases."]}'),
  ('d413ea96-30','{"options": ["Primary", "Secondary", "Quaternary", "Tertiary"], "correct": 0, "decode": "Preventing disease BEFORE it starts (screening, education) is PRIMARY prevention. Secondary catches early disease, tertiary limits disability.", "ow": ["Correct. Primary prevention acts before disease onset.", "Secondary is early detection of existing disease.", "Not a standard prevention level used here.", "Tertiary limits disability in established disease."]}'),
  ('d1f4c9cb-1q','{"options": ["Refractive error", "Glaucoma", "Diabetic retinopathy", "Cataract"], "correct": 3, "decode": "In the Philippines the leading cause of bilateral BLINDNESS is cataract (a curable cause). Refractive error causes impairment more than outright blindness.", "ow": ["A leading impairment cause, but cataract leads blindness here.", "A cause of blindness, but not the leading one.", "Less common as a leading blindness cause locally.", "Correct. Cataract is the leading cause of bilateral blindness in the Philippines."]}'),
  ('1450d6fb-1c','{"options": ["October 10, 1950", "May 1, 1960", "January 1, 1945", "April 7, 1948"], "correct": 3, "decode": "The WHO was established on 7 April 1948, marked yearly as World Health Day. The other dates are distractors.", "ow": ["Not the WHO founding date.", "Not the WHO founding date.", "That is around the UN era, not WHO''s founding.", "Correct. WHO was established on 7 April 1948."]}'),
  ('91e718bf-1o','{"options": ["Prevent, prolong, promote", "Diagnose, treat, cure", "Educate, vaccinate, isolate", "Screen, refer, follow"], "correct": 0, "decode": "Winslow''s public health definition uses three P verbs: prevent disease, prolong life, promote health. The clinical verbs (diagnose, treat, cure) are individual medicine, not public health.", "ow": ["Correct. Prevent, prolong, promote are Winslow''s three verbs.", "These are clinical medicine verbs, not public health.", "Specific interventions, not the defining verbs.", "Program steps, not Winslow''s definition."]}'),
  ('acb1e1ac-2y','{"options": ["Primary", "Tertiary", "Secondary", "Quaternary"], "correct": 1, "decode": "Rehabilitation that limits disability in ESTABLISHED disease is TERTIARY prevention. Primary is before onset; secondary is early detection.", "ow": ["Primary acts before disease starts.", "Correct. Tertiary prevention limits disability in established disease.", "Secondary is early detection, not rehabilitation.", "Not a standard level here."]}'),
  ('e0cf9e36-27','{"options": ["PhilHealth Z-benefit", "RA 8050 program", "Community Eye Health Program", "Expanded Program on Immunization"], "correct": 2, "decode": "The DOH program integrating eye care into local public health is the Community Eye Health Program. The others are a financing benefit, a law, or an immunization program.", "ow": ["A PhilHealth financing package, not the eye-health program.", "A law, not a DOH community program.", "Correct. The Community Eye Health Program integrates eye care locally.", "The immunization program, unrelated to eye care."]}'),
  ('aea8134a-z','{"options": ["Minus", "Plus", "Prism", "Cylinder only"], "correct": 0, "decode": "Myopia focuses light in FRONT of the retina, so a diverging MINUS lens pushes it back. Plus is for hyperopia; prism and cylinder correct alignment and astigmatism.", "ow": ["Correct. Minus (diverging) lenses correct myopia.", "Plus corrects hyperopia, the opposite.", "Prism corrects alignment, not focus.", "Cylinder corrects astigmatism, not simple myopia."]}'),
  ('d908cde2-y','{"options": ["33 cm in front of the eye", "At the near point", "At infinity", "Behind the eye"], "correct": 0, "decode": "Far point distance (in meters) = 1/|power|, so a -3.00 D myope''s far point is 1/3 m = 33 cm, and the minus sign puts it in FRONT of the eye. Not infinity (that is emmetropia) or behind (hyperopia).", "ow": ["Correct. 1/3 m = 33 cm in front for a -3 D myope.", "The near point is a different landmark.", "Infinity is the emmetrope''s far point.", "A far point behind the eye is hyperopia, not myopia."]}'),
  ('333bc772-1m','{"options": ["18.5 − 0.30", "15 + 0.25", "15 − 0.25", "25 − 0.40"], "correct": 2, "decode": "Hofstetter''s MINIMUM amplitude = 15 - 0.25 x age. The average is 18.5 - 0.30 x age and the maximum is 25 - 0.40 x age; match minimum to the 15/0.25 pair.", "ow": ["That is the AVERAGE formula (18.5 - 0.30).", "Wrong sign; amplitude falls with age, so it is minus.", "Correct. Minimum amplitude = 15 - 0.25 x age.", "That is the MAXIMUM formula (25 - 0.40)."]}'),
  ('4b146e23-m','{"options": ["Facultative only", "Latent plus manifest", "Manifest minus latent", "Absolute only"], "correct": 1, "decode": "Total hyperopia = latent (hidden by ciliary tone) + manifest (what you measure). Facultative and absolute are subdivisions of manifest, not the total.", "ow": ["Facultative is only part of manifest hyperopia.", "Correct. Total hyperopia = latent + manifest.", "Subtraction is wrong; the parts add up.", "Absolute is only part of manifest, not the total."]}'),
  ('2b8a4b50-f','{"options": ["Permanent axial elongation myopia", "A patient feigning myopia", "Flattening of the central cornea", "Accommodative spasm, clears on cycloplegia"], "correct": 3, "decode": "Pseudomyopia is an accommodative SPASM that mimics myopia and disappears with cycloplegia. It is not true axial myopia, malingering, or a corneal change.", "ow": ["That is true axial myopia, which cycloplegia does not clear.", "Not a spasm; this describes faking.", "A corneal change, not accommodative spasm.", "Correct. Pseudomyopia is accommodative spasm that clears on cycloplegia."]}'),
  ('ec1ff522-14','{"options": ["Corrected with prism", "Steep at 90°, more common in youth", "Steep at 180°, more common with age", "Always pathological"], "correct": 1, "decode": "With-the-rule astigmatism is steep at 90 degrees (vertical) and is common in the young. Against-the-rule (steep at 180) rises with age. WTR is not pathological.", "ow": ["Astigmatism is corrected with cylinder, not prism.", "Correct. WTR is steep at 90 degrees, common in youth.", "That describes against-the-rule, common with age.", "WTR is a normal refractive pattern, not pathology."]}'),
  ('d9fb0541-2c','{"options": ["0.50 D", "1.00 D", "1.50 D", "2.00 D"], "correct": 2, "decode": "Subtract the working-distance dioptric value: 1/0.67 m is about 1.50 D. At 67 cm you take away 1.50 D from the gross retinoscopy finding.", "ow": ["1/0.67 is not 0.50; that would be a 2 m distance.", "1.00 D corresponds to a 1 m working distance.", "Correct. 1/0.67 m is about 1.50 D to subtract.", "2.00 D corresponds to a 50 cm distance."]}'),
  ('53d47f9e-1o','{"options": ["Minus", "Plus", "Prism", "Cylinder only"], "correct": 0, "decode": "''Against'' motion in retinoscopy means the eye is over-minused/myopic at that setting, so you neutralize it by adding MINUS. ''With'' motion takes plus.", "ow": ["Correct. Against motion is neutralized with minus lenses.", "Plus neutralizes WITH motion, the opposite.", "Prism does not neutralize retinoscopy motion.", "Cylinder refines axis, not the neutralizing sphere."]}'),
  ('5e5e7220-27','{"options": ["Divergence excess", "Pseudomyopia", "Accommodative esotropia", "Convergence insufficiency"], "correct": 2, "decode": "A hyperopic child whose esotropia disappears with FULL PLUS is accommodative esotropia: uncorrected hyperopia drives extra accommodation and convergence. Plus glasses remove the drive.", "ow": ["Divergence excess is exo at distance, not this.", "Pseudomyopia is a spasm, not a strabismus.", "Correct. Accommodative esotropia resolves with full plus correction.", "Convergence insufficiency is exo at near, the opposite."]}'),
  ('c0eeda2b-u','{"options": ["At infinity", "Virtual, behind the eye", "33 cm in front", "At the near point"], "correct": 1, "decode": "A hyperope''s far point is VIRTUAL, behind the eye, because the eye is underpowered and needs converging light. Infinity is the emmetrope; 33 cm in front is a myope.", "ow": ["Infinity is the emmetrope''s far point.", "Correct. The hyperope''s far point is virtual, behind the eye.", "A far point in front belongs to a myope.", "The near point is a different landmark."]}'),
  ('b52ebe4c-13','{"options": ["Fully compensated by accommodation", "Not overcome by accommodation", "It affects near vision only", "Hidden by resting ciliary tone"], "correct": 1, "decode": "ABSOLUTE hyperopia is the part that accommodation CANNOT overcome, so vision is blurred even with maximal effort. Facultative hyperopia can be compensated by accommodation.", "ow": ["That is facultative hyperopia, not absolute.", "Correct. Absolute hyperopia cannot be overcome by accommodation.", "Hyperopia affects distance too, not near only.", "That describes latent hyperopia, hidden by tone."]}'),
  ('daaa902d-17','{"options": ["35", "40", "45", "55"], "correct": 2, "decode": "Presbyopia typically becomes symptomatic around age 45, as accommodative amplitude drops below near demand. 35 is early; 55 is late.", "ow": ["Earlier than the typical onset.", "A bit early for symptomatic presbyopia.", "Correct. Presbyopia usually begins around age 45.", "Later than the average onset."]}'),
  ('3a9b1f94-26','{"options": ["1.00 D", "2.00 D", "3.00 D", "6.00 D"], "correct": 2, "decode": "Anisometropia carries the highest amblyopia risk when the difference exceeds about 3.00 D (especially hyperopic). Smaller differences carry lower risk.", "ow": ["Lower risk at only 1 D difference.", "Moderate risk, but not the highest-risk cutoff.", "Correct. A difference over about 3.00 D carries the highest amblyopia risk.", "Very high, but 3 D is the quoted threshold."]}'),
  ('04bc74aa-1s','{"options": ["Plano sphere with plus cyl", "Minus sphere with minus cyl", "Plus sphere with plus cyl", "Minus sphere with plus cyl"], "correct": 1, "decode": "Compound myopic astigmatism means both meridians are myopic, so in minus-cylinder form it is a MINUS sphere with a MINUS cylinder. Any plus sphere or plus cyl would not keep both meridians myopic.", "ow": ["A plano sphere leaves one meridian emmetropic, not compound myopic.", "Correct. Minus sphere with minus cylinder keeps both meridians myopic.", "Plus sphere makes it hyperopic, not myopic.", "Minus sphere with plus cyl is mixed, not compound myopic."]}'),
  ('2a8e43c5-y','{"options": ["Plus add", "Sphere only", "Cylinder", "Prism"], "correct": 2, "decode": "Astigmatism has different power in different meridians, so it needs a CYLINDER (or toric). A sphere, add, or prism cannot correct meridional differences.", "ow": ["An add is for presbyopia, not astigmatism.", "A sphere cannot fix meridional differences.", "Correct. Cylinder corrects astigmatism.", "Prism corrects alignment, not astigmatism."]}'),
  ('11549680-2f','{"options": ["0.50 D", "1.50 D", "3.00 D", "6.00 D"], "correct": 1, "decode": "At 67 cm the neutral point is 1.50 D, so ''against'' motion in all meridians (needing more minus) means the eye is myopic by MORE than that 1.50 D working-distance value.", "ow": ["Below the 1.50 D neutral for this distance.", "Correct. Against motion at 67 cm means myopia beyond 1.50 D.", "More than needed; the threshold is the 1.50 D working distance.", "Far more than the working-distance threshold."]}'),
  ('56d2c3b3-1q','{"options": ["Amblyopia", "Cataract that won''t improve", "Uncorrected refractive error", "Organic"], "correct": 2, "decode": "If a pinhole IMPROVES vision, the blur was optical, so the cause is uncorrected refractive error (the pinhole cuts blur circles). Amblyopia, dense cataract, and organic disease do not improve with a pinhole.", "ow": ["Amblyopia does not improve with a pinhole.", "A dense cataract may not improve, unlike this.", "Correct. Pinhole improvement means an uncorrected refractive cause.", "Organic disease does not improve with a pinhole."]}'),
  ('9b8117e3-3v','{"options": ["Left esophoria", "Left exophoria", "Right exotropia", "Left esotropia"], "correct": 1, "decode": "Recovery (''drifts back out when uncovered'') means a PHORIA, and the uncovered eye moving INWARD to refixate means it had drifted OUT, so left exophoria. Inward refixation = exo; recovery = latent.", "ow": ["Esophoria would refixate outward, not inward.", "Correct. Inward refixation with recovery is a left exophoria.", "Recovery indicates a phoria, not a manifest tropia.", "A tropia would not recover; this is a phoria."]}'),
  ('f1d4b904-1x','{"options": ["No deviation", "Hyperdeviation", "Exo deviation", "Eso deviation"], "correct": 3, "decode": "A corneal reflex displaced TEMPORALLY means the eye is rotated NASALLY (inward), so it is an eso deviation. Reflex position is opposite the direction of eye turn.", "ow": ["A displaced reflex means there is a deviation.", "Temporal displacement is horizontal, not a hyper.", "Temporal reflex means the eye turned in, which is eso not exo.", "Correct. A temporally displaced reflex indicates an eso deviation."]}'),
  ('e173b2e5-1v','{"options": ["Optic chiasm", "Lateral geniculate nucleus", "Occipital cortex", "Pretectal nucleus"], "correct": 3, "decode": "The pupillary light reflex leaves the visual pathway before the cortex, at the PRETECTAL nucleus (midbrain). The chiasm, LGN, and cortex are for conscious vision, not the reflex.", "ow": ["The chiasm handles fiber crossing, not the light reflex relay.", "The LGN relays conscious vision, not the reflex.", "The cortex is conscious vision, past the reflex branch point.", "Correct. The light reflex synapses at the pretectal nucleus."]}'),
  ('49a85058-1m','{"options": ["2 cm", "7 cm", "15 cm", "20 cm"], "correct": 1, "decode": "A normal near point of convergence break is about 7 cm (roughly 5 to 10). 2 cm is too close; 15 to 20 cm is receded (abnormal).", "ow": ["Closer than normal.", "Correct. A normal NPC break is about 7 cm.", "A receded (abnormal) near point.", "A markedly receded near point."]}'),
  ('77609cc2-q','{"options": ["Measures stereoacuity directly", "Tests one eye at a time only", "Shows total deviation, not its type", "Differentiates phoria from tropia"], "correct": 2, "decode": "The ALTERNATING cover test dissociates the eyes and shows the TOTAL deviation (phoria plus tropia) but not its type. Cover-uncover, not alternate cover, separates phoria from tropia.", "ow": ["It does not directly measure stereoacuity.", "It alternates between eyes, not one eye only.", "Correct. The alternate cover test shows total deviation, not its type.", "Cover-uncover, not alternate cover, distinguishes phoria from tropia."]}'),
  ('f8348e50-23','{"options": ["Hirschberg test", "Swinging flashlight test", "Cover test", "Maddox rod"], "correct": 1, "decode": "An RAPD (Marcus Gunn pupil) is found with the swinging flashlight test, comparing the two eyes'' light responses. Hirschberg, cover, and Maddox tests assess alignment, not the afferent pupil.", "ow": ["Hirschberg checks alignment, not the pupil.", "Correct. The swinging flashlight test detects an RAPD.", "The cover test checks alignment, not the pupil.", "Maddox rod checks phoria, not the pupil."]}'),
  ('431df0f1-1a','{"options": ["3 m", "6 m", "10 m", "40 cm"], "correct": 1, "decode": "Standard far acuity is tested at 6 meters (20 feet), where light is effectively parallel. 3 and 10 m are non-standard; 40 cm is near.", "ow": ["Not the standard far distance.", "Correct. Far acuity is tested at 6 meters.", "Not the standard testing lane.", "That is the near testing distance."]}'),
  ('4832e3d5-x','{"options": ["Dilation, divergence, relaxation", "Saccade, pursuit, vergence", "Blink, tearing, closure", "Constriction, accommodation, convergence"], "correct": 3, "decode": "The near reflex triad is constriction (miosis), accommodation, and convergence, all firing to focus on a near target. The other triads mix in unrelated actions.", "ow": ["Those are the opposite responses (for distance).", "Eye-movement types, not the near triad.", "Protective lid actions, not the near triad.", "Correct. Constriction, accommodation, and convergence are the near triad."]}'),
  ('70fb7a4b-1w','{"options": ["Hyperopia with convergence excess", "Uncorrected astigmatism", "An early nuclear cataract", "Uncorrected simple myopia"], "correct": 0, "decode": "Frontal headache and eyestrain classically come from uncorrected hyperopia with convergence excess, since sustained accommodation and convergence fatigue the near effort. Simple myopia blurs distance without this asthenopia.", "ow": ["Correct. Hyperopia with convergence excess causes classic asthenopia.", "Astigmatism can cause strain but is not the classic pairing.", "A cataract blurs vision, not this eyestrain pattern.", "Simple myopia blurs distance without near eyestrain."]}'),
  ('f04f0b35-1e','{"options": ["48 mm", "54 mm", "64 mm", "74 mm"], "correct": 2, "decode": "Average adult interpupillary distance is about 64 mm. 48 to 54 is small; 74 is large.", "ow": ["Smaller than average.", "Smaller than average.", "Correct. Average adult IPD is about 64 mm.", "Larger than average."]}'),
  ('9f980edc-20','{"options": ["Half", "Always exactly the same", "Equal to or better", "Worse"], "correct": 2, "decode": "With both eyes working (binocular summation), binocular acuity should be EQUAL TO OR BETTER than the best single eye, never worse. Half or worse would signal a problem.", "ow": ["Summation does not halve acuity.", "It can be better, not always identical.", "Correct. Binocular acuity is equal to or better than the best eye.", "Worse binocular acuity is abnormal."]}'),
  ('db4666cc-23','{"options": ["5°", "15°", "30°", "45°"], "correct": 1, "decode": "On Hirschberg, each millimeter of reflex displacement is roughly 7 degrees, so a reflex at the PUPILLARY MARGIN is about 15 degrees. The limbus is about 45 degrees.", "ow": ["Too small for a pupil-margin reflex.", "Correct. A reflex at the pupillary margin is about 15 degrees.", "That is beyond the pupil margin.", "That is a reflex at the limbus, not the pupil margin."]}'),
  ('d04a9618-1j','{"options": ["Uncorrected astigmatism", "An organic cause", "Presbyopia", "Uncorrected myopia"], "correct": 1, "decode": "If a pinhole does NOT improve reduced acuity, the blur is not optical, so the cause is organic (retinal, optic nerve, dense media). Refractive errors would have improved with the pinhole.", "ow": ["Astigmatism would improve with a pinhole.", "Correct. No pinhole improvement points to an organic cause.", "Presbyopia is a near-focus refractive issue that a pinhole helps.", "Myopia would improve with a pinhole."]}'),
  ('405a7c79-13','{"options": ["In the dark", "Through a pinhole", "Binocularly, both eyes open", "With one eye occluded"], "correct": 2, "decode": "The near point of convergence is a BINOCULAR test: both eyes open, target moved in until one eye breaks. Occlusion, darkness, or a pinhole would defeat the binocular measurement.", "ow": ["Convergence needs light and both eyes, not darkness.", "A pinhole is for acuity, not convergence.", "Correct. NPC is tested binocularly with both eyes open.", "Occluding an eye prevents measuring convergence."]}'),
  ('985f779d-v','{"options": ["Constriction of the opposite pupil", "Convergence", "Accommodation", "Constriction of the illuminated pupil"], "correct": 3, "decode": "The DIRECT light reflex is constriction of the SAME (illuminated) pupil. Constriction of the other eye is the consensual reflex.", "ow": ["That is the consensual reflex, the opposite eye.", "Convergence is part of the near triad, not the light reflex.", "Accommodation is part of the near triad, not the light reflex.", "Correct. The direct reflex is constriction of the lit pupil."]}'),
  ('b25eeb6b-1d','{"options": ["Virtual, inverted", "Real, erect, 40x", "Virtual, erect, ~15x", "Real, inverted, 2–5x"], "correct": 2, "decode": "Direct ophthalmoscopy gives a VIRTUAL, ERECT image at about 15x. Indirect ophthalmoscopy gives a real, inverted, lower-power image.", "ow": ["The direct image is erect, not inverted.", "Not the direct ophthalmoscope''s image or power.", "Correct. Direct ophthalmoscopy: virtual, erect, about 15x.", "That real, inverted, low-power image is indirect ophthalmoscopy."]}'),
  ('b2df0d76-23','{"options": ["More magnification, narrower field", "More magnification, wider field", "No change", "Less magnification, wider field"], "correct": 3, "decode": "A stronger condensing lens (+20 vs +14) gives LESS magnification but a WIDER field in indirect ophthalmoscopy. Power and magnification trade off inversely.", "ow": ["Stronger lens gives less, not more, magnification.", "Higher power lowers magnification, not raises it.", "There is a change; power alters magnification and field.", "Correct. A stronger lens gives less magnification and a wider field."]}'),
  ('ba84587b-1d','{"options": ["Keratometry", "Direct ophthalmoscopy", "Indirect ophthalmoscopy", "Van Herick"], "correct": 2, "decode": "Indirect ophthalmoscopy, with its wide field and scleral depression, is best for the PERIPHERAL retina. Direct gives a narrow central view; keratometry and Van Herick are anterior tests.", "ow": ["Keratometry measures the cornea, not the retina.", "Direct gives a narrow central field, poor for periphery.", "Correct. Indirect ophthalmoscopy best views the peripheral retina.", "Van Herick estimates the angle, not the retina."]}'),
  ('d3ff8093-1k','{"options": ["Grade 2", "Grade 0–1", "Grade 3–4", "Any grade"], "correct": 1, "decode": "On Van Herick, a shallow angle (grade 0 to 1) is unsafe to dilate (angle-closure risk). Grades 3 to 4 are open and safe.", "ow": ["Grade 2 is borderline but not the unsafe range asked.", "Correct. Grades 0 to 1 are shallow and unsafe to dilate.", "Grades 3 to 4 are open and safe to dilate.", "Not any grade; wide angles are safe."]}'),
  ('adf7d183-y','{"options": ["Total astigmatism from keratometry", "Pupil diameter in dim light", "Axial length of the globe", "Amplitude of accommodation"], "correct": 0, "decode": "Javal''s rule estimates TOTAL astigmatism from the keratometric (corneal) astigmatism. It does not give pupil size, axial length, or accommodation.", "ow": ["Correct. Javal''s rule estimates total astigmatism from keratometry.", "Pupil size is unrelated to Javal''s rule.", "Axial length needs biometry, not Javal''s rule.", "Amplitude of accommodation is a separate measurement."]}'),
  ('a623ec01-17','{"options": ["Show fluorescein staining", "Examine retinal blood vessels", "Measure intraocular pressure", "Assess the anterior chamber angle"], "correct": 0, "decode": "The cobalt-blue filter makes fluorescein glow, so it shows corneal staining and tear film. It does not measure pressure, view vessels, or grade the angle.", "ow": ["Correct. Cobalt blue shows fluorescein staining.", "Retinal vessels are viewed with red-free, not cobalt blue.", "Pressure needs a tonometer, not a filter.", "The angle is assessed with gonioscopy, not this filter."]}'),
  ('9756cef0-2e','{"options": ["Same direction", "Does not move", "Rotates", "Opposite direction"], "correct": 3, "decode": "In parallax, an ANTERIOR opacity moves OPPOSITE to the observer''s movement (against motion), while a posterior one moves with. Anterior equals opposite.", "ow": ["Same-direction (with) motion means a posterior opacity.", "A moving opacity does show parallax.", "Parallax is linear displacement, not rotation.", "Correct. An anterior opacity moves opposite (against) the observer."]}'),
  ('882672fa-o','{"options": ["Total corneal power including the back surface", "Axial length", "Anterior corneal surface power only", "Lens power"], "correct": 2, "decode": "A keratometer measures only the ANTERIOR corneal surface power (from its curvature). It does not include the back surface, axial length, or lens power.", "ow": ["It measures only the front surface, not total corneal power.", "Axial length needs biometry, not keratometry.", "Correct. The keratometer measures anterior corneal surface power only.", "Lens power needs a lensometer, not a keratometer."]}'),
  ('58f3b384-2b','{"options": ["+0.50 cyl × 90°", "−0.50 cyl × 90°", "−1.00 cyl × 180°", "Zero"], "correct": 1, "decode": "Javal''s rule assumes a fixed internal (lenticular) astigmatism of about -0.50 cyl x 90 (against-the-rule), which it adds to the corneal value. The plus, larger, and zero options are wrong.", "ow": ["Wrong sign; the internal component is minus at 90.", "Correct. Javal uses about -0.50 cyl x 90 for internal astigmatism.", "Wrong power and axis.", "Javal assumes a nonzero internal component."]}'),
  ('97f127bf-1b','{"options": ["Viewing vessels and nerve fiber layer", "Viewing fluorescein staining", "Measuring the chamber angle", "Producing cycloplegia"], "correct": 0, "decode": "The red-free (green) filter makes blood and the nerve fiber layer stand out dark against the fundus. Fluorescein needs cobalt blue; the angle needs gonioscopy.", "ow": ["Correct. Red-free (green) best shows vessels and the nerve fiber layer.", "Fluorescein is viewed with cobalt blue, not green.", "The angle needs gonioscopy, not a filter.", "Cycloplegia is a drug effect, not a filter."]}'),
  ('7fac8b00-1i','{"options": ["3:2", "2:1", "2:3", "1:1"], "correct": 0, "decode": "The normal retinal vein-to-artery caliber ratio is 3:2 (veins slightly wider). 2:1 is too wide; 1:1 or 2:3 would be abnormal.", "ow": ["Correct. The normal V:A ratio is 3:2.", "Too wide a vein-to-artery ratio.", "Arteries are not wider than veins normally.", "Equal calibers would be abnormal."]}'),
  ('74939961-17','{"options": ["Specular reflection, Van Herick", "Gonioscopic angle viewing", "Fundus examination", "Applanation tonometry"], "correct": 0, "decode": "A ~60 degree illumination angle is used for specular reflection and the Van Herick estimate. Gonioscopy needs a lens; fundus and applanation use different setups.", "ow": ["Correct. About 60 degrees is used for specular reflection and Van Herick.", "Gonioscopy uses a contact lens, not just a slit angle.", "Fundus exam needs a fundus lens, not this angle.", "Applanation uses a tonometer tip, not this angle."]}'),
  ('d4448d33-1b','{"options": ["33–37 D", "60 D", "50–55 D", "40–47 D"], "correct": 3, "decode": "Average keratometry readings are about 40 to 47 D (mean corneal power ~43 D). 33 to 37 is too flat; 50 to 60 is too steep.", "ow": ["Far too flat for a normal cornea.", "Steeper than a normal cornea.", "Steeper than normal average keratometry.", "Correct. Normal keratometry is about 40 to 47 D."]}'),
  ('78d0795b-1d','{"options": ["Real and inverted", "Virtual and inverted", "Real and erect", "Virtual and erect"], "correct": 0, "decode": "Indirect ophthalmoscopy forms a REAL, INVERTED aerial image through the condensing lens. Direct ophthalmoscopy is the virtual, erect one.", "ow": ["Correct. The indirect image is real and inverted.", "The image is real, not virtual.", "The indirect image is inverted, not erect.", "That describes the direct ophthalmoscope image."]}'),
  ('069bd563-1q','{"options": ["45°", "90°", "135°", "180°"], "correct": 3, "decode": "For with-the-rule astigmatism (steep vertical), the correcting minus-cylinder axis is near 180 (horizontal). WTR minus-cyl axis = 180.", "ow": ["Not the WTR minus-cyl axis.", "90 is the steep (power) meridian, not the minus-cyl axis.", "That would be an oblique axis.", "Correct. WTR minus-cyl axis is near 180."]}'),
  ('d07e4bc0-2k','{"options": ["Dilate with caution and monitor", "Van Herick does not guide dilation", "Dilate freely, no risk", "Do not dilate under any setting"], "correct": 0, "decode": "A Van Herick shadow about one-quarter of the section (grade 2) means a narrowish angle: dilate with caution and monitor. It is neither wide-open-safe nor absolutely contraindicated.", "ow": ["Correct. A quarter-width (grade 2) angle means dilate with caution.", "Van Herick does guide dilation safety.", "A quarter-width angle is not risk-free.", "Grade 2 is not an absolute contraindication."]}'),
  ('262d0c89-1w','{"options": ["Power meridian", "Add power", "Axis of the minus cylinder", "Sphere power"], "correct": 0, "decode": "On the astigmatic dial the darkest, clearest black line marks the more ametropic POWER meridian (its focal line is on the retina). It is not the add, sphere, or a cylinder axis directly.", "ow": ["Correct. The blackest line indicates the power meridian.", "The dial does not indicate an add.", "The line marks a meridian, not the cylinder axis directly.", "It is not the sphere setting."]}'),
  ('9413fee1-2f','{"options": ["−0.25 D", "+0.50 D", "None", "+0.25 D"], "correct": 3, "decode": "To keep the circle of least confusion on the retina, add +0.25 D sphere for every -0.50 D cylinder added on the astigmatic dial (move the spherical equivalent). This is the ''+0.25 per -0.50'' rule.", "ow": ["Wrong sign; you add plus, not minus, sphere.", "Too much; add half the cylinder, not equal.", "You must adjust sphere to hold the endpoint.", "Correct. Add +0.25 D sphere per -0.50 D cylinder."]}'),
  ('e40e6175-1t','{"options": ["Under-minused; add minus", "Over-minused; add plus", "Correctly corrected already", "Hyperopic and uncorrected"], "correct": 1, "decode": "On duochrome, GREEN clearer means the focus is too far forward, so the eye is OVER-minused: add plus (reduce minus). Mnemonic RAM-GAP: on Green Add Plus.", "ow": ["Green clearer means over-minused, so you reduce, not add, minus.", "Correct. Green clearer means over-minused: add plus.", "A clear preference for green means adjustment is needed.", "Green clearer is an over-minus sign, not simple hyperopia."]}'),
  ('ec47bc60-2k','{"options": ["Cylinder over-powered → reduce minus", "Sphere too plus", "Cylinder under-powered → add minus", "Axis is wrong"], "correct": 2, "decode": "On the JCC power check, preferring position 1 (red dots parallel to the axis) means the cylinder is UNDER-powered: add minus cylinder. Do not touch axis or sphere here.", "ow": ["Preference for more cylinder means add, not reduce, minus.", "This is a cylinder-power check, not sphere.", "Correct. Position 1 preference means add minus cylinder.", "Axis is checked in a separate JCC step."]}'),
  ('36d8e1ec-1h','{"options": ["+0.50 to +0.75 D of fog", "A minus over-correction", "+3.00 D of fog", "Just enough to reach 20/20"], "correct": 0, "decode": "Fog the eye about +0.50 to +0.75 D before the astigmatic dial, enough to blur but still see the lines. A large fog or a minus over-correction defeats the test.", "ow": ["Correct. About +0.50 to +0.75 D of fog is ideal.", "A minus over-correction is the opposite of fogging.", "Too much fog blurs the whole dial.", "Fogging deliberately keeps you below 20/20."]}'),
  ('88cc6f8e-1v','{"options": ["Perpendicular to the axis", "At 90° from the sphere", "45° to the axis", "Parallel to the tentative axis"], "correct": 3, "decode": "On the JCC AXIS check, the handle (flip axis) is held PARALLEL to the tentative cylinder axis. On the power check it straddles the axis at 45.", "ow": ["That would be the power-check orientation, not the axis check.", "The handle relates to the cylinder axis, not the sphere.", "45 degrees is the power-check straddle, not the axis check.", "Correct. For the axis check the handle is parallel to the tentative axis."]}'),
  ('571acd0d-2f','{"options": ["Exactly 1.00 D", "Any amount", "> 0.75 D", "≤ 0.50 D"], "correct": 2, "decode": "The rotating clock-dial (fan) method suits larger cylinders, over about 0.75 D; small cylinders are refined with the JCC. Use the dial when cyl is greater than 0.75 D.", "ow": ["Not a specific single value.", "Not for any amount; small cyl uses JCC.", "Correct. Use the clock-dial method when cylinder exceeds 0.75 D.", "Small cylinders are better refined with the JCC."]}'),
  ('ef83d680-1m','{"options": ["Neither eye", "The weaker eye only", "Both eyes simultaneously", "The dominant eye only"], "correct": 2, "decode": "In binocular balancing the re-fog (added plus) goes on BOTH eyes at once, keeping accommodation relaxed and equal while you compare. One eye alone would not balance them.", "ow": ["You must fog to compare, so ''neither'' is wrong.", "Fog both, not just the weaker eye.", "Correct. Re-fog both eyes simultaneously for balancing.", "Fog both, not only the dominant eye."]}'),
  ('4084aa05-1h','{"options": ["3Δ BD OD and 3Δ BU OS", "10Δ BI OD", "6Δ BO each eye", "No prism"], "correct": 0, "decode": "Prism dissociation for balancing uses about 3 prism diopters base-down over one eye and base-up over the other (3 BD OD, 3 BU OS), separating the two blurred images vertically. The horizontal or no-prism options do not dissociate for balance.", "ow": ["Correct. 3 BD OD and 3 BU OS vertically dissociates for balancing.", "Base-in dissociates horizontally, not the balancing setup.", "Base-out each eye is not the vertical dissociation used.", "No prism leaves the images fused, defeating the test."]}'),
  ('384afbd1-36','{"options": ["Add plus to the other eye", "Restart the monocular refraction", "Leave the dominant eye clearer", "Keep adding plus until equal"], "correct": 2, "decode": "If +0.25 to the clearer eye just REVERSES the preference rather than equalizing, a perfect balance is not achievable, so leave the DOMINANT eye slightly clearer. Do not keep piling on plus.", "ow": ["Adding plus to the other eye over-fogs it.", "No need to restart the whole refraction.", "Correct. When balance flips, leave the dominant eye clearer.", "Endless plus over-fogs both eyes."]}'),
  ('b25e43ed-1s','{"options": ["Plus lenses until blur", "Prism until diplopia", "Cylinder until clear", "Minus lenses until blur"], "correct": 3, "decode": "PRA (positive relative accommodation) is measured by adding MINUS lenses until first sustained blur, stimulating accommodation. Plus lenses measure NRA instead.", "ow": ["Plus-to-blur measures NRA, not PRA.", "Prism measures vergence ranges, not PRA.", "Cylinder is not used for relative accommodation.", "Correct. PRA is minus lenses added until blur."]}'),
  ('ab0f5cee-1a','{"options": ["Uncorrected astigmatism", "Red-green deficiency", "Advanced presbyopia", "High axial myopia"], "correct": 1, "decode": "The duochrome relies on comparing red vs green, so it is INVALID in red-green color deficiency. Astigmatism, presbyopia, and myopia do not invalidate it.", "ow": ["Astigmatism affects clarity but not the color comparison validity.", "Correct. Red-green deficiency invalidates the duochrome test.", "Presbyopia does not invalidate the red-green comparison.", "Myopia does not invalidate the duochrome."]}'),
  ('76d928df-1e','{"options": ["Binocular balance", "The astigmatic dial", "MPMVA", "First blur"], "correct": 2, "decode": "The endpoint of the OEP #7 subjective is MPMVA (maximum plus to maximum visual acuity), the most plus that still gives best acuity. Balance and the dial are earlier steps.", "ow": ["Binocular balance is a separate later step.", "The astigmatic dial refines cylinder, not the sphere endpoint.", "Correct. MPMVA is the #7 subjective endpoint.", "First blur is a landmark, not the final endpoint."]}'),
  ('60777ffd-1n','{"options": ["Add minus / reduce plus", "Add cylinder", "Reduce minus / add plus", "Do nothing"], "correct": 0, "decode": "On duochrome, RED clearer means the focus is too far back (under-minused), so add minus (reduce plus). Mnemonic RAM: on Red Add Minus.", "ow": ["Correct. Red clearer means add minus (reduce plus).", "Cylinder is not adjusted from the duochrome.", "That would over-plus an already under-minused eye.", "A clear red preference calls for adjustment."]}'),
  ('f010f70f-1d','{"options": ["Both use habitual", "#3 = Test #7 Rx; #8 = habitual", "Both use #7", "#3 = habitual Rx; #8 = Test #7 Rx"], "correct": 3, "decode": "In OEP analysis, test #3 uses the HABITUAL Rx and test #8 uses the Test #7 (subjective) Rx. Match #3 to habitual and #8 to the #7 result.", "ow": ["#3 uses habitual, but #8 uses the #7 Rx, not habitual.", "Reversed; #3 is habitual and #8 is #7.", "Only #8 uses #7; #3 uses habitual.", "Correct. #3 = habitual Rx, #8 = Test #7 Rx."]}'),
  ('9c558a1b-1v','{"options": ["Cylinder under-powered → add minus", "Cylinder over-powered → reduce minus", "Wrong axis", "Sphere error only"], "correct": 1, "decode": "On the JCC power check, preferring position 2 (white dots parallel to the axis) means the cylinder is OVER-powered: reduce minus cylinder. It is not an axis or sphere issue.", "ow": ["Position 2 means too much cylinder, so reduce, not add.", "Correct. Position 2 preference means reduce minus cylinder.", "Axis is checked separately, not here.", "This step evaluates cylinder power, not sphere."]}'),
  ('420da385-1o','{"options": ["Glasses → prism → VT → surgery", "VT → surgery → glasses → prism", "Surgery → VT → prism → glasses", "Prism → glasses → surgery → VT"], "correct": 0, "decode": "Manage binocular vision least-invasive first: glasses, then prism, then vision therapy, then surgery as a last resort. Any order starting with surgery or VT before optics is wrong.", "ow": ["Correct. Glasses, then prism, then VT, then surgery.", "Surgery and VT should not precede simple optics.", "Surgery is a last resort, not first.", "Optics come before surgery; the order here is scrambled."]}'),
  ('8cb2a795-1s','{"options": ["Base in", "Base up", "Base down", "Base out"], "correct": 0, "decode": "Exophoria is an outward drift, so you correct it with BASE-IN prism (base toward the nose shifts the image out, relaxing the over-convergence needed). Base-out is for esophoria; vertical bases are for hypers.", "ow": ["Correct. Base-in prism corrects exophoria.", "Vertical prism is for hyperphoria, not exo.", "Vertical prism is for hyperphoria, not exo.", "Base-out corrects esophoria, the opposite."]}'),
  ('214d8698-1g','{"options": ["÷ 3", "phoria ÷ 2", "recovery − phoria", "2 × phoria"], "correct": 0, "decode": "Sheard''s prism = (2 x phoria - reserve) all divided by 3. The defining step is the divide-by-3 at the end; the other formulas are not Sheard''s.", "ow": ["Correct. Sheard''s prism uses the divide-by-3 formula.", "Phoria over 2 is not Sheard''s criterion.", "Recovery minus phoria is not Sheard''s.", "Twice the phoria alone is not the formula."]}'),
  ('28b43570-1k','{"options": ["Full hyperopic correction", "Early strabismus surgery", "Base-in prism at near", "Patching the sound eye"], "correct": 0, "decode": "Accommodative esotropia is driven by uncorrected hyperopia, so the FIRST step is full hyperopic (plus) correction to remove the accommodative drive. Surgery, prism, and patching come only if needed later.", "ow": ["Correct. Full hyperopic correction is the first step.", "Surgery is not first-line for accommodative esotropia.", "Prism is a later adjunct, not the first step.", "Patching treats amblyopia, not the eso drive itself."]}'),
  ('bef36eaf-1p','{"options": ["Neither", "Good eye", "Amblyopic eye", "Both alternately from the start"], "correct": 1, "decode": "Conventional occlusion patches the GOOD (sound) eye, forcing the amblyopic eye to work. Patching the amblyopic eye would worsen it.", "ow": ["You must patch to force the weak eye to work.", "Correct. Patch the good eye to force the amblyopic eye.", "Patching the amblyopic eye worsens amblyopia.", "Alternating from the start does not push the weak eye enough."]}'),
  ('6b9a608e-1b','{"options": ["Aligns eyes without restoring acuity", "Replaces the need for patching", "Is the first-line treatment", "Cures the underlying amblyopia"], "correct": 0, "decode": "Strabismus surgery straightens the eyes but does NOT restore acuity; amblyopia still needs patching. It is cosmetic/functional alignment, not a cure for the amblyopia.", "ow": ["Correct. Surgery aligns the eyes but does not restore acuity.", "Patching is still needed after surgery.", "Refractive correction and patching come before surgery.", "Surgery does not cure the underlying amblyopia."]}'),
  ('8d2c4a44-1i','{"options": ["Central fixation", "Alternating fixation", "Eccentric fixation", "No fixation"], "correct": 2, "decode": "Pleoptics is specifically for amblyopia with ECCENTRIC fixation, retraining the fovea to fixate. Central fixation does not need it.", "ow": ["Central fixation does not require pleoptics.", "Alternating fixation implies no amblyopia to treat this way.", "Correct. Pleoptics targets eccentric fixation.", "''No fixation'' is not the pleoptics indication."]}'),
  ('d26c2c8f-1w','{"options": ["12–18 years", "0–2 years", "5–7 years", "8–10 years"], "correct": 1, "decode": "The most sensitive (critical) period for amblyopia is the first years of life, about 0 to 2 years, when the visual system is most plastic. Older ages respond less.", "ow": ["Far past the critical period.", "Correct. The 0 to 2 year window is most sensitive.", "Later and less plastic than the critical period.", "Older still, with lower plasticity."]}'),
  ('e31814de-1l','{"options": ["out; dominant", "down; higher", "up; lower", "in; non-dominant"], "correct": 1, "decode": "For a hyper deviation, place prism BASE-DOWN before the HIGHER eye (pushing its image down toward fusion). Base-up before the higher eye would worsen it.", "ow": ["Base-out is for horizontal, not vertical, deviation.", "Correct. Base-down before the higher eye corrects a hyper.", "Base-up before the higher eye worsens the hyper.", "Base-in is horizontal, not vertical."]}'),
  ('cd7943be-x','{"options": ["Amblyopia in the good eye", "No risk at all", "Permanent strabismus", "Cataract in the patched eye"], "correct": 0, "decode": "Over-patching the sound eye can induce occlusion (reverse) AMBLYOPIA in that good eye. It is a real risk, so patching is monitored.", "ow": ["Correct. Over-patching risks amblyopia in the good eye.", "There is a real occlusion-amblyopia risk.", "Over-patching does not cause strabismus.", "Patching does not cause cataract."]}'),
  ('1d1f6466-2l','{"options": ["Cataract", "Sixth nerve palsy", "Convergence insufficiency", "Presbyopia"], "correct": 1, "decode": "A new distance esophoria (divergence insufficiency) must be distinguished from a SIXTH nerve palsy, which also gives distance esodeviation and can signal serious pathology. Cataract and presbyopia are unrelated.", "ow": ["A cataract does not cause an eso deviation.", "Correct. Rule out a sixth nerve palsy in new distance esodeviation.", "Convergence insufficiency is exo at near, the opposite.", "Presbyopia is a near-focus problem, not a deviation."]}'),
  ('b94349d7-1u','{"options": ["No prism needed", "2Δ base out", "2Δ base in", "4Δ base in"], "correct": 2, "decode": "Sheard''s = (2 x phoria - reserve)/3 = (2 x 8 - 10)/3 = 6/3 = 2, and exophoria takes base-in, so 2 base-in. Base-out or ''no prism'' are wrong.", "ow": ["The formula gives a nonzero prism here.", "Exophoria takes base-in, not base-out.", "Correct. (16 - 10)/3 = 2 base-in.", "The calculation gives 2, not 4."]}'),
  ('3ff16af9-1k','{"options": ["Full refractive correction", "Patching immediately", "Surgery", "Prism"], "correct": 0, "decode": "Anisometropic amblyopia is first treated by FULL refractive correction (equalize the retinal images); patching follows only if needed. Surgery and prism are not first steps.", "ow": ["Correct. Full refractive correction comes first.", "Correct the refraction before patching.", "Surgery is not first-line for refractive amblyopia.", "Prism does not treat anisometropic amblyopia."]}'),
  ('1ff69aac-1y','{"options": ["Refer for strabismus surgery", "Begin convergence exercises", "Prescribe relieving prism", "Correct the refractive error"], "correct": 3, "decode": "Before any vision therapy for a binocular disorder, you must first CORRECT the refractive error, since clear equal images are the foundation. Exercises, prism, or surgery come after.", "ow": ["Surgery is a last resort, not the first step.", "Exercises come after the refraction is corrected.", "Prism is considered after refraction, not before.", "Correct. Correct the refractive error before starting VT."]}'),
  ('703a1f40-x','{"options": ["Color vision", "Horizontal phorias", "Accommodation", "Vertical deviations"], "correct": 3, "decode": "The Parks 3-step test isolates the paretic muscle in a VERTICAL (cyclovertical) deviation. It is not for color, horizontal phorias, or accommodation.", "ow": ["Not a color-vision test.", "It localizes vertical, not horizontal, deviations.", "Not an accommodation test.", "Correct. Parks 3-step localizes a vertical (cyclovertical) palsy."]}'),
  ('82f88800-14','{"options": ["Two parallel strings seen", "No strings visible at all", "An X at the fixated bead", "A single string seen"], "correct": 2, "decode": "On the Brock string a normal response is an X crossing exactly at the fixated bead (physiological diplopia with fusion). Two parallel strings, one string, or no strings signal suppression or misalignment.", "ow": ["Two parallel strings suggest a vergence error.", "Seeing no strings is abnormal.", "Correct. A normal Brock string shows an X at the fixated bead.", "A single string means one eye is suppressed."]}'),
  ('8dcb1d31-1c','{"options": ["With prism", "Under cycloplegia", "With both eyes open", "Monocularly"], "correct": 3, "decode": "CAM visual stimulator treatment is done MONOCULARLY, occluding the good eye so the amblyopic eye is stimulated. Prism, cycloplegia, and both-eyes-open are not the setup.", "ow": ["No prism is used in CAM stimulation.", "Cycloplegia is not part of CAM.", "It is monocular, not both eyes open.", "Correct. CAM stimulation is performed monocularly."]}'),
  ('6986e2e7-1k','{"options": ["±0.50 D, target 5 cpm", "+4.00 D only", "±2.00 D, target 12 cpm", "Prism flippers only"], "correct": 2, "decode": "Accommodative infacility is trained with plus/minus 2.00 D lens flippers, targeting about 12 cycles per minute. The weak or plus-only or prism options are wrong.", "ow": ["Too weak a flipper and too low a target.", "A single plus lens is not a flipper drill.", "Correct. Plus/minus 2.00 D flippers, target about 12 cpm.", "Prism flippers train vergence, not accommodation."]}'),
  ('af3c84d0-1k','{"options": ["Much less effective than full-time", "Contraindicated", "About as effective as full-time", "Only for adults"], "correct": 2, "decode": "For moderate amblyopia, part-time patching (2 to 6 hours) is about AS effective as full-time, with better compliance. It is neither much weaker nor contraindicated.", "ow": ["It is roughly equal, not much less effective.", "Part-time patching is a standard, not contraindicated, option.", "Correct. Part-time patching is about as effective as full-time for moderate amblyopia.", "It is used in children, not only adults."]}'),
  ('9ff83508-1x','{"options": ["Prism", "Patching", "Vision therapy", "Surgery"], "correct": 0, "decode": "Sheard''s and Percival''s criteria are decision rules for prescribing PRISM in heterophoria. They do not decide patching, VT, or surgery.", "ow": ["Correct. Sheard''s and Percival''s criteria guide prism prescribing.", "Patching decisions are separate.", "VT decisions are not these criteria.", "Surgery is decided on other grounds."]}'),
  ('dd3eae6e-26','{"options": ["Push-ups → Brock string → vectogram", "Hart chart → pleoptics → CAM", "Surgery → prism → glasses", "Patching → atropine → CAM"], "correct": 0, "decode": "A typical convergence-insufficiency VT sequence builds from simple to complex: push-ups, then Brock string, then vectograms. The other sequences mix in unrelated or out-of-order steps.", "ow": ["Correct. Push-ups, then Brock string, then vectograms.", "Pleoptics and CAM are amblyopia tools, not this CI sequence.", "Surgery does not lead a VT sequence.", "Patching and atropine treat amblyopia, not convergence insufficiency."]}'),
  ('81d3beb1-22','{"options": ["Blur 9 / Break 12 / Recovery 5", "Blur 17 / Break 21 / Recovery 11", "Blur 30 / Break 35 / Recovery 20", "No norm exists"], "correct": 1, "decode": "Normal near positive fusional convergence is about blur 17, break 21, recovery 11 (Sheard''s norms). The much smaller or larger sets are abnormal.", "ow": ["Reduced values, below the norm.", "Correct. Near PFC is about blur 17 / break 21 / recovery 11.", "Higher than the typical norm.", "A norm does exist for near PFC."]}'),
  ('7bf67eb9-v','{"options": ["Suppression only", "Stereopsis", "Accommodation and saccades", "Color vision"], "correct": 2, "decode": "The Hart chart trains ACCOMMODATION (near-far clarity) and SACCADES (jumping between letters). It is not a suppression, stereopsis, or color drill.", "ow": ["It is a clarity and eye-movement drill, not suppression.", "Stereopsis is trained with other tools.", "Correct. The Hart chart trains accommodation and saccades.", "Not a color-vision drill."]}'),
  ('49d65be2-10','{"options": ["After exactly two weeks of wear", "As soon as any improvement is seen", "When VA equalizes or stops improving", "Patching is never discontinued"], "correct": 2, "decode": "Stop patching when acuity EQUALIZES or plateaus (stops improving). A fixed two-week rule, stopping at first improvement, or never stopping are all wrong.", "ow": ["Duration is guided by acuity, not a fixed two weeks.", "Stopping at first improvement is premature.", "Correct. Discontinue when VA equalizes or stops improving.", "Patching does end once the endpoint is reached."]}'),
  ('d67e7168-1v','{"options": ["Excellent stereopsis", "Normal fusion", "Suppression of that eye", "Accommodative spasm"], "correct": 2, "decode": "On the Brock string, a MISSING X limb on one side means that eye is SUPPRESSED (its string is not perceived). It is not a sign of good stereopsis or normal fusion.", "ow": ["A missing limb is abnormal, not excellent stereopsis.", "A missing limb is not normal fusion.", "Correct. An absent X limb indicates suppression of that eye.", "It signals suppression, not accommodative spasm."]}'),
  ('f9e1da33-1o','{"options": ["Incidence", "Prevalence", "Attack ratio", "Endemic rate"], "correct": 0, "decode": "NEW cases over a period is incidence. Prevalence is all existing cases; attack rate and endemic rate are different measures.", "ow": ["Correct. Incidence counts new cases over time.", "Prevalence counts all cases, new and old.", "An attack rate is a specific outbreak measure, not general new-case count.", "Endemicity describes steady presence, not a new-case count."]}'),
  ('dcf40dc3-25','{"options": ["Endemic", "Sporadic", "Pandemic", "Epidemic"], "correct": 0, "decode": "Constant low-frequency presence in a population is endemic. Sporadic is scattered, epidemic is a surge, pandemic is worldwide.", "ow": ["Correct. Endemic means constantly present at low frequency.", "Sporadic means scattered, occasional cases.", "Pandemic is worldwide spread.", "Epidemic is a surge above baseline."]}'),
  ('53f3a6a6-1i','{"options": ["Glaucoma and diabetic retinopathy", "Trachoma and onchocerciasis", "Refractive error and cataract", "AMD and glaucoma"], "correct": 2, "decode": "The two biggest global causes of visual impairment are the correctable ones: refractive error and cataract. Glaucoma, AMD, and tropical infections rank lower globally.", "ow": ["Major causes, but below refractive error and cataract.", "Regional infections, not the global top two.", "Correct. Refractive error and cataract lead globally.", "Important, but not the top two."]}'),
  ('0ddf8497-1g','{"options": ["Cataract", "Diabetic retinopathy", "Uncorrected refractive error", "Glaucoma"], "correct": 0, "decode": "The leading cause of blindness in the Philippines is cataract (curable). Refractive error causes more impairment than outright blindness.", "ow": ["Correct. Cataract leads blindness in the Philippines.", "A cause, but not the leading one locally.", "Causes impairment more than blindness.", "A cause of blindness, but not the leading one."]}'),
  ('5ec9cb40-1u','{"options": ["Prevent, prolong, promote", "Screen, refer, monitor", "Educate, legislate, fund", "Diagnose, treat, cure"], "correct": 0, "decode": "Winslow''s public health definition uses the three P verbs: prevent, prolong, promote. The clinical verbs are individual medicine, not public health.", "ow": ["Correct. Prevent, prolong, promote are Winslow''s verbs.", "Program steps, not the defining verbs.", "Policy actions, not Winslow''s definition.", "Clinical medicine verbs, not public health."]}'),
  ('2c8681c2-18','{"options": ["May 8, 1950", "October 24, 1945", "June 12, 1946", "April 7, 1948"], "correct": 3, "decode": "The WHO was founded on 7 April 1948, celebrated as World Health Day. The other dates are distractors.", "ow": ["Not the WHO founding date.", "That is the UN Charter era, not WHO.", "Not the WHO founding date.", "Correct. WHO was founded on 7 April 1948."]}'),
  ('a90bd282-1u','{"options": ["25 − 0.40 × age", "15 − 0.40 × age", "15 − 0.25 × age", "18.5 − 0.30 × age"], "correct": 2, "decode": "Hofstetter MINIMUM amplitude = 15 - 0.25 x age. Average is 18.5 - 0.30; maximum is 25 - 0.40. Match minimum to 15/0.25.", "ow": ["That is the maximum formula.", "Wrong coefficient; minimum uses 0.25, not 0.40.", "Correct. Minimum = 15 - 0.25 x age.", "That is the average formula."]}'),
  ('04566e8d-1u','{"options": ["15 − 0.25 × age", "18.5 − 0.30 × age", "25 − 0.40 × age", "20 − 0.30 × age"], "correct": 1, "decode": "Hofstetter AVERAGE amplitude = 18.5 - 0.30 x age. Minimum is 15 - 0.25; maximum is 25 - 0.40. Match average to 18.5/0.30.", "ow": ["That is the minimum formula.", "Correct. Average = 18.5 - 0.30 x age.", "That is the maximum formula.", "Not a Hofstetter formula."]}'),
  ('10c41d61-10','{"options": ["1 meter in front", "At optical infinity", "Behind the eye", "33 cm in front of the eye"], "correct": 3, "decode": "A -3.00 D myope''s far point is 1/3 m = 33 cm in FRONT of the eye. Not 1 m, infinity, or behind.", "ow": ["1 m corresponds to a -1 D myope.", "Infinity is the emmetrope''s far point.", "Behind the eye is the hyperope''s far point.", "Correct. 1/3 m = 33 cm in front for a -3 D myope."]}'),
  ('ef2c33f1-z','{"options": ["At optical infinity", "Real, in front of the eye", "Virtual, behind the eye", "At the corneal plane"], "correct": 2, "decode": "A hyperope''s far point is VIRTUAL, behind the eye, since the underpowered eye needs converging light. Infinity is the emmetrope; in front is a myope.", "ow": ["Infinity is the emmetrope''s far point.", "A real front far point belongs to a myope.", "Correct. The hyperope''s far point is virtual, behind the eye.", "The corneal plane is a reference, not the far point."]}'),
  ('9580460f-23','{"options": ["1.00 D", "4.50 D", "7.00 D", "10.00 D"], "correct": 1, "decode": "By Donders'' table, amplitude at age 40 is about 4.50 D. Higher values fit younger ages; near 1 D fits the sixties.", "ow": ["About 1 D fits the sixties, not 40.", "Correct. Donders gives about 4.50 D at age 40.", "About 7 D fits a younger patient.", "10 D fits the teens, not 40."]}'),
  ('33ed81df-25','{"options": ["Adding 1.50 D", "Subtracting 1.50 D", "Adding 2.50 D", "Subtracting 2.00 D"], "correct": 1, "decode": "At 67 cm the working-distance value is 1.50 D, which you SUBTRACT from the gross retinoscopy finding. Adding it, or using the wrong value, is incorrect.", "ow": ["You subtract the working distance, not add it.", "Correct. Subtract 1.50 D for a 67 cm working distance.", "2.50 D is not the 67 cm value, and you subtract.", "2.00 D corresponds to a 50 cm distance."]}'),
  ('9901bdbf-17','{"options": ["Rotate the axis", "Add plus", "Change the working distance", "Add minus"], "correct": 1, "decode": "''With'' motion in retinoscopy means you need more plus, so ADD PLUS to reach neutral. Against motion takes minus.", "ow": ["Motion type sets the sphere, not the axis.", "Correct. With motion is neutralized by adding plus.", "The working distance stays fixed; adjust the lens.", "Minus neutralizes against motion, not with."]}'),
  ('a4ed1eb9-1l','{"options": ["60–120°", "150–180°", "0–30°", "Exactly 45°"], "correct": 0, "decode": "With-the-rule astigmatism has its STEEP power meridian near vertical, about 60 to 120 degrees. The horizontal band (150 to 180) is against-the-rule.", "ow": ["Correct. WTR steep meridian is about 60 to 120 degrees.", "That horizontal band is against-the-rule.", "That horizontal band is against-the-rule.", "45 degrees is oblique, not WTR."]}'),
  ('7a94e39e-1i','{"options": ["10 foot-candles", "100 foot-candles", "20 foot-candles", "50 foot-candles"], "correct": 2, "decode": "Standard acuity-chart illumination is about 20 foot-candles. Much dimmer or brighter values are non-standard.", "ow": ["Dimmer than the standard.", "Brighter than the standard.", "Correct. About 20 foot-candles is standard chart illumination.", "Brighter than the standard."]}'),
  ('689bdd39-1g','{"options": ["0.02", "0.1", "0.2", "1.0"], "correct": 1, "decode": "Decimal acuity = test distance over the bottom number, so 20/200 = 0.1. The other decimals correspond to different acuities.", "ow": ["0.02 would be about 20/1000.", "Correct. 20/200 equals 0.1 in decimal.", "0.2 is 20/100, not 20/200.", "1.0 is 20/20."]}'),
  ('6df8b3e0-1n','{"options": ["Uncorrected astigmatism", "An organic cause", "Simple myopia", "Latent hyperopia"], "correct": 1, "decode": "If a pinhole does NOT improve acuity, the blur is not optical, so the cause is organic. Refractive errors would have improved with the pinhole.", "ow": ["Astigmatism improves with a pinhole.", "Correct. No pinhole improvement means an organic cause.", "Simple myopia improves with a pinhole.", "Latent hyperopia is refractive and would improve."]}'),
  ('58d9338f-1b','{"options": ["54 mm", "60 mm", "64 mm", "72 mm"], "correct": 2, "decode": "Mean adult interpupillary distance is about 64 mm. 54 to 60 is small; 72 is large.", "ow": ["Smaller than average.", "Slightly small.", "Correct. Mean adult IPD is about 64 mm.", "Larger than average."]}'),
  ('e0d4b667-1t','{"options": ["Pretectal nucleus", "Superior colliculus", "Lateral geniculate body", "Optic chiasm"], "correct": 0, "decode": "The pupillary light reflex fibers leave the pathway at the PRETECTAL nucleus (midbrain). The colliculus, LGN, and chiasm are not the reflex relay.", "ow": ["Correct. Light reflex fibers synapse at the pretectal nucleus.", "The superior colliculus handles reflex gaze, not the light reflex relay.", "The LGN relays conscious vision, not the reflex.", "The chiasm is a crossing point, not the reflex relay."]}'),
  ('2f6d97cf-1j','{"options": ["Argyll-Robertson pupil", "Marcus Gunn pupil", "Horner''s pupil", "Adie''s pupil"], "correct": 1, "decode": "An RAPD is the Marcus Gunn pupil, found on the swinging flashlight test. Argyll-Robertson, Horner, and Adie are different pupil syndromes.", "ow": ["Argyll-Robertson shows light-near dissociation, not an RAPD.", "Correct. The RAPD is the Marcus Gunn pupil.", "Horner is a small sympathetic-loss pupil.", "Adie is a tonic dilated pupil."]}'),
  ('ac1a0215-1r','{"options": ["Pupil constriction", "Lid retraction", "Depression of gaze", "Pupil dilation"], "correct": 0, "decode": "The near reflex triad is convergence, accommodation, and pupil CONSTRICTION (all for near focus). Dilation, lid retraction, and gaze depression are not part of it.", "ow": ["Correct. Pupil constriction completes the near triad.", "Lid retraction is not part of the near triad.", "Gaze depression is not part of the near triad.", "Dilation is the opposite of the near response."]}'),
  ('62129ba2-1x','{"options": ["An exo deviation", "Orthophoria", "An eso deviation", "A hyper deviation"], "correct": 2, "decode": "A temporally displaced corneal reflex means the eye is rotated nasally (in), so an ESO deviation. Reflex position is opposite the eye''s turn.", "ow": ["Temporal reflex means the eye turned in, which is eso not exo.", "A displaced reflex means a deviation exists.", "Correct. A temporally displaced reflex indicates an eso deviation.", "Temporal displacement is horizontal, not a hyper."]}'),
  ('f5f671c2-18','{"options": ["Virtual and inverted", "Virtual and erect", "Real and erect", "Real and inverted"], "correct": 1, "decode": "Direct ophthalmoscopy gives a VIRTUAL, ERECT image (about 15x). The real, inverted image is indirect ophthalmoscopy.", "ow": ["The direct image is erect, not inverted.", "Correct. Direct ophthalmoscopy gives a virtual, erect image.", "The direct image is virtual, not real.", "Real and inverted describes indirect ophthalmoscopy."]}'),
  ('440c7c3d-24','{"options": ["No change in field or magnification", "A narrower field and more magnification", "A wider field and less magnification", "A wider field and more magnification"], "correct": 2, "decode": "A stronger condensing lens gives a WIDER field but LESS magnification in indirect ophthalmoscopy; power and magnification trade off inversely.", "ow": ["Power does change field and magnification.", "Stronger lens widens the field, not narrows it, and lowers magnification.", "Correct. A stronger lens gives a wider field and less magnification.", "Magnification falls, not rises, with a stronger lens."]}'),
  ('8de6cee3-18','{"options": ["Grade 1 or 2", "Grade 0 or 1", "Grade 2 only", "Grade 3 or 4"], "correct": 3, "decode": "Wide-open angles (Van Herick grade 3 or 4) are safe to dilate; shallow grades 0 to 1 are not. Higher grade means safer.", "ow": ["Grade 1 is shallow and unsafe.", "Grades 0 to 1 are shallow, the unsafe range.", "Grade 2 is borderline, not clearly safe.", "Correct. Grades 3 to 4 are open and safe to dilate."]}'),
  ('3fdb6342-1b','{"options": ["43–44 D", "48–50 D", "35–37 D", "38–40 D"], "correct": 0, "decode": "Average keratometry is about 43 to 44 D (mean corneal power). Steeper (48 to 50) or flatter (35 to 40) values are outside the norm.", "ow": ["Correct. Average keratometry is about 43 to 44 D.", "Steeper than the normal average.", "Too flat for a normal cornea.", "Flatter than the normal average."]}'),
  ('23a6899e-20','{"options": ["−0.50 cyl × 180°", "−0.50 cyl × 90°", "−1.25 cyl × 90°", "+0.50 cyl × 90°"], "correct": 1, "decode": "Javal''s rule takes internal (lenticular) astigmatism as about -0.50 cyl x 90 (against-the-rule). The 180 axis, larger power, and plus sign are wrong.", "ow": ["Wrong axis; the internal component is at 90.", "Correct. Javal uses -0.50 cyl x 90 internally.", "Wrong magnitude for the internal constant.", "Wrong sign; it is minus at 90."]}'),
  ('80460cb7-29','{"options": ["On the corneal surface", "At the pupil plane", "Anterior to the pupil plane", "Posterior to the pupil plane"], "correct": 3, "decode": "An opacity moving in the SAME direction as the scope (with motion) lies POSTERIOR to the pupil plane; against (opposite) motion is anterior. Same = behind.", "ow": ["A corneal opacity moves opposite (anterior pattern).", "At the pupil plane an opacity shows no parallax.", "Anterior opacities move opposite, not with.", "Correct. Same-direction (with) motion means posterior to the pupil."]}'),
  ('cefc015b-2e','{"options": ["45°", "90°", "135°", "180°"], "correct": 1, "decode": "Against-the-rule astigmatism (steep horizontal) has its correcting minus-cylinder axis near 90 (vertical). ATR minus-cyl axis = 90.", "ow": ["Oblique, not the ATR axis.", "Correct. ATR minus-cyl axis is near 90.", "Oblique, not the ATR axis.", "180 is the WTR minus-cyl axis, not ATR."]}'),
  ('a2805499-1s','{"options": ["20/100", "20/200", "20/20", "20/30–20/40"], "correct": 3, "decode": "When properly fogged before refinement, the target sees only about 20/30 to 20/40 (deliberately blurred, accommodation relaxed). Reaching 20/20 means under-fogged.", "ow": ["Too blurred; over-fogged.", "Far too blurred.", "20/20 means the fog was removed.", "Correct. Proper fog leaves the patient at about 20/30 to 20/40."]}'),
  ('dc3cf586-1m','{"options": ["Circle of least confusion", "Axis of the plus cylinder", "Axis of the minus cylinder", "Power meridian"], "correct": 3, "decode": "On the astigmatic dial the darkest line marks the more ametropic POWER meridian. It is not the circle of least confusion or a cylinder axis directly.", "ow": ["The circle of least confusion is a focus point, not a dial line.", "The line marks a meridian, not the plus-cyl axis directly.", "It marks a meridian, not the minus-cyl axis directly.", "Correct. The darkest line is the power meridian."]}'),
  ('e06479c3-1d','{"options": ["−0.25 D sphere per −0.50 D cyl", "+0.25 D sphere per −0.50 D cyl", "+0.50 D sphere per −0.50 D cyl", "+0.25 D sphere per −0.25 D cyl"], "correct": 1, "decode": "To hold the spherical equivalent, add +0.25 D sphere for every -0.50 D cylinder. The minus, equal, and mismatched-step options break the balance.", "ow": ["Wrong sign; you add plus sphere.", "Correct. Add +0.25 D sphere per -0.50 D cylinder.", "Too much sphere for the cylinder change.", "Wrong pairing of sphere step to cylinder step."]}'),
  ('3080803d-1x','{"options": ["Add minus cylinder", "Add plus sphere", "Reduce the minus cylinder", "Leave the axis unchanged"], "correct": 0, "decode": "On JCC, preferring Position 1 means the cylinder is under-corrected, so add minus cylinder (this bank treats Position 1 preference as a cylinder-power call). Do not touch sphere or reduce cylinder.", "ow": ["Correct. Position 1 preference means add minus cylinder.", "This step adjusts cylinder, not sphere.", "Reducing cylinder is the Position 2 response.", "A clear preference calls for a cylinder change."]}'),
  ('e780189c-1v','{"options": ["Presbyopic", "Over-minused", "Correctly corrected", "Under-minused"], "correct": 3, "decode": "On duochrome, RED clearer means the focus is too far back, so the eye is UNDER-minused (add minus). Mnemonic RAM: on Red Add Minus.", "ow": ["Presbyopia is a near-focus issue, not a duochrome endpoint.", "Over-minused would prefer green, not red.", "A clear red preference means adjustment is needed.", "Correct. Red clearer means under-minused."]}'),
  ('f430faeb-1p','{"options": ["12Δ BI OD / 6Δ BU OS", "3Δ BD OD / 3Δ BU OS", "3Δ BO OD / 3Δ BI OS", "6Δ BI OD / 6Δ BO OS"], "correct": 1, "decode": "Vertical balance uses about 3 base-down over one eye and 3 base-up over the other (3 BD OD / 3 BU OS), separating the images vertically. The horizontal setups do not dissociate for vertical balance.", "ow": ["Base-in dissociates horizontally, not the vertical balance setup.", "Correct. 3 BD OD / 3 BU OS gives vertical dissociation.", "Base-out/base-in is horizontal, not this setup.", "Base-in/base-out is horizontal, not vertical."]}'),
  ('cfd084ce-1j','{"options": ["+1.50 D", "+0.50 to +0.75 D", "+0.25 D", "+3.00 D"], "correct": 1, "decode": "The re-fog in binocular balance is a small +0.50 to +0.75 D on both eyes, enough to blur equally. Larger fogs over-blur; +0.25 is too little.", "ow": ["Too much fog for balancing.", "Correct. Re-fog both eyes with about +0.50 to +0.75 D.", "Too little to reliably blur.", "Far too much fog."]}'),
  ('d1ecbaac-q','{"options": ["Cylinder until clear", "Plus lenses until blur", "Prism until break", "Minus lenses until blur"], "correct": 3, "decode": "PRA is measured by adding MINUS lenses until first blur (stimulating accommodation). Plus-to-blur is NRA; prism and cylinder are unrelated.", "ow": ["Cylinder is not used for relative accommodation.", "Plus-to-blur measures NRA, not PRA.", "Prism measures vergence, not accommodation.", "Correct. PRA is minus lenses added until blur."]}'),
  ('58924fe9-1a','{"options": ["Base-up", "Base-down", "Base-in", "Base-out"], "correct": 2, "decode": "Relieving prism for EXOphoria is base-IN (shifts the image out, easing over-convergence). Base-out is for eso; vertical bases are for hypers.", "ow": ["Vertical prism is for hyperphoria, not exo.", "Vertical prism is for hyperphoria, not exo.", "Correct. Base-in relieves exophoria.", "Base-out relieves esophoria, the opposite."]}'),
  ('223801b6-1m','{"options": ["Lower eye", "Dominant eye", "Higher eye", "Amblyopic eye"], "correct": 2, "decode": "For a hyperphoria, place the base-DOWN prism before the HIGHER eye (pushing its image down toward fusion). Not the lower, dominant, or amblyopic eye.", "ow": ["Base-down before the lower eye worsens the hyper.", "Prism placement follows the deviation, not dominance.", "Correct. Base-down before the higher eye corrects a hyper.", "Placement follows the higher eye, not the amblyopic one."]}'),
  ('26bdda96-1a','{"options": ["(phoria − recovery) ÷ 2", "(2 × phoria − recovery) ÷ 3", "(2 × recovery − phoria) ÷ 3", "(2 × phoria + recovery) ÷ 3"], "correct": 1, "decode": "Sheard''s prism = (2 x phoria - recovery) / 3. The other formulas are not Sheard''s.", "ow": ["Not Sheard''s formula.", "Correct. Sheard''s = (2 x phoria - recovery) / 3.", "The terms are reversed.", "Wrong sign inside the formula."]}'),
  ('5e497f68-1h','{"options": ["Twice the fusional reserve", "The middle third of the vergence range", "The outer third of the range", "One prism dioptre of ortho"], "correct": 1, "decode": "Percival''s criterion asks the phoria to sit within the MIDDLE THIRD of the total vergence range (ignoring the phoria itself). The other statements are not Percival''s rule.", "ow": ["Twice-the-reserve is not Percival''s statement.", "Correct. Percival wants the demand in the middle third of the range.", "The outer third is where you would prescribe, not the target.", "One prism dioptre of ortho is not Percival''s criterion."]}'),
  ('297345f9-1q','{"options": ["≥4.00 D", "≥1.00 D", "≥0.50 D", "≥2.00 D"], "correct": 3, "decode": "Borish''s threshold for clinically significant anisometropia is about 2.00 D or more. Smaller differences are less significant; 4 D is beyond the threshold.", "ow": ["Higher than the stated threshold.", "Below the significance threshold.", "Well below the threshold.", "Correct. Borish uses about 2.00 D or more."]}'),
  ('005b9f80-1k','{"options": ["Patch the good eye", "Give full cycloplegic correction", "Remove the opacity", "Begin atropine penalization"], "correct": 2, "decode": "Deprivation (stimulus-deprivation) amblyopia from an opacity is first treated by REMOVING the opacity (e.g., congenital cataract surgery); patching and penalization come after. Clear the visual axis first.", "ow": ["Patch only after clearing the opacity.", "Correction alone cannot bypass a dense opacity.", "Correct. Remove the opacity first in deprivation amblyopia.", "Penalization comes after removing the opacity."]}'),
  ('8777b5d4-13','{"options": ["Anisometropia", "Convergence insufficiency", "Accommodative infacility", "Eccentric fixation"], "correct": 3, "decode": "Pleoptics is specifically for ECCENTRIC fixation amblyopia. Anisometropia, convergence insufficiency, and accommodative infacility are treated differently.", "ow": ["Anisometropic amblyopia is treated with correction and patching.", "Convergence insufficiency is a vergence problem, not pleoptics.", "Accommodative infacility uses flippers, not pleoptics.", "Correct. Pleoptics targets eccentric fixation."]}'),
  ('51ce16bb-w','{"options": ["5 min twice daily", "7 minutes weekly for several weeks", "30 min daily for a year", "2 hours daily for a month"], "correct": 1, "decode": "The CAM stimulator protocol is short and infrequent: about 7 minutes per session, weekly for several weeks. The daily long-duration options are wrong.", "ow": ["Not the CAM schedule.", "Correct. About 7 minutes weekly for several weeks.", "Far longer than the CAM protocol.", "Far longer than the CAM protocol."]}'),
  ('b6a2f8d7-1d','{"options": ["Expands the fusional vergence range", "Compensates the deviation optically", "Works only in strabismus", "Eliminates the refractive error"], "correct": 0, "decode": "Vision therapy EXPANDS the fusional vergence range (a lasting functional change), whereas prism only optically compensates the deviation. Therapy is not limited to strabismus and does not remove refractive error.", "ow": ["Correct. VT expands the fusional vergence range.", "That describes prism, not therapy.", "VT is used in heterophorias, not only strabismus.", "VT does not eliminate refractive error."]}'),
  ('f6729061-15','{"options": ["Normal fusion", "Eccentric fixation", "Convergence excess", "Suppression"], "correct": 3, "decode": "An absent X limb on the Brock string means that eye is SUPPRESSED. It is not normal fusion, eccentric fixation, or convergence excess.", "ow": ["A missing limb is abnormal, not normal fusion.", "Eccentric fixation is a foveal issue, not a missing string.", "Convergence excess is a vergence posture, not string suppression.", "Correct. An absent X limb indicates suppression."]}'),
  ('688577b3-p','{"options": ["−2.50 D", "+4.00 D", "+0.50 D", "+2.00 D"], "correct": 3, "decode": "Normal NRA (plus-to-blur) is about +2.00 D. The minus value, +4.00, and +0.50 are not the standard finding.", "ow": ["NRA is plus, not minus.", "Higher than the standard NRA.", "Lower than the standard NRA.", "Correct. Normal NRA is about +2.00 D."]}'),
  ('3ee2abc8-21','{"options": ["±4.00 D, 20 cpm", "±0.50 D, 30 cpm", "±1.00 D, 6 cpm", "±2.00 D, 12 cpm"], "correct": 3, "decode": "Standard accommodative flipper training uses plus/minus 2.00 D lenses aiming at about 12 cycles per minute in adults. The weaker/stronger powers and off rates are wrong.", "ow": ["Too strong a flipper and too high a target.", "Too weak and too fast a target.", "Too weak and too slow a target.", "Correct. Plus/minus 2.00 D flippers, about 12 cpm."]}'),
  ('cefabe9e-1d','{"options": ["Stereopsis", "Saccades", "Fusional vergence", "Color discrimination"], "correct": 1, "decode": "The Hart chart trains accommodation together with SACCADES (jumping the eyes between letters). It is not a stereopsis, vergence, or color drill.", "ow": ["Stereopsis is trained with other tools.", "Correct. The Hart chart pairs accommodation with saccades.", "Fusional vergence uses vectograms, not the Hart chart.", "Not a color-discrimination drill."]}'),
  ('9620f312-17','{"options": ["Central to peripheral targets", "Stereopsis before fusion", "Peripheral to central targets", "Grade III to Grade I"], "correct": 2, "decode": "Antisuppression therapy works from PERIPHERAL toward CENTRAL targets, since peripheral fusion is easier to regain first. Central-first or grade-reversed sequences are wrong.", "ow": ["The sequence runs peripheral to central, not the reverse.", "Fusion is built before stereopsis, and this asks target order.", "Correct. Antisuppression progresses peripheral to central.", "Fusion grades build I to III, not the reverse."]}'),
  ('71e5b96a-1u','{"options": ["Patching adds nothing to glasses", "Full-time is clearly superior", "Only atropine works", "Part-time equals full-time"], "correct": 3, "decode": "PEDIG trials showed part-time patching equals full-time for MODERATE amblyopia, with better compliance. Patching does help, and atropine is not the only option.", "ow": ["Patching adds real benefit beyond glasses.", "Full-time is not superior for moderate amblyopia.", "Atropine is an alternative, not the only effective option.", "Correct. Part-time equals full-time for moderate amblyopia."]}'),
  ('a3ccb4c1-2g','{"options": ["Epidemic", "Pandemic", "Endemic", "Sporadic"], "correct": 2, "decode": "Constant low steady frequency in a community is endemic. Epidemic is a surge, pandemic is worldwide, sporadic is scattered.", "ow": ["An epidemic is a surge above baseline.", "A pandemic is worldwide.", "Correct. Endemic means constant low steady presence.", "Sporadic means scattered cases."]}'),
  ('6ab07635-3c','{"options": ["Quaternary", "Secondary", "Tertiary", "Primary"], "correct": 3, "decode": "Stopping disease BEFORE it starts (screening, education) is PRIMARY prevention. Secondary is early detection; tertiary limits disability.", "ow": ["Not a standard prevention level here.", "Secondary is early detection of existing disease.", "Tertiary limits disability in established disease.", "Correct. Primary prevention acts before onset."]}'),
  ('4f6d5fc3-1q','{"options": ["Diabetic retinopathy", "Glaucoma", "Cataract", "Refractive error"], "correct": 2, "decode": "The leading cause of bilateral BLINDNESS in the Philippines is cataract (curable). Refractive error causes more impairment than blindness.", "ow": ["A cause, but not the leading one.", "A cause of blindness, but not the leading one.", "Correct. Cataract leads bilateral blindness in the Philippines.", "Causes impairment more than outright blindness."]}'),
  ('c3334b59-2t','{"options": ["Mortality", "Prevalence", "Incidence", "Endemicity"], "correct": 2, "decode": "Counting only NEW cases in one year is incidence. Prevalence counts all cases; mortality is deaths.", "ow": ["Mortality counts deaths, not new cases.", "Prevalence counts all existing cases.", "Correct. New cases per year is incidence.", "Endemicity describes steady presence, not a case count."]}'),
  ('ea2b39c6-2f','{"options": ["Glaucoma", "Diabetic retinopathy", "Cataract", "Errors of refraction"], "correct": 3, "decode": "The leading cause of bilateral LOW VISION (not blindness) in the Philippines is uncorrected refractive error. Cataract leads blindness, but refractive error leads low vision.", "ow": ["Not the leading low-vision cause.", "Not the leading low-vision cause.", "Cataract leads blindness, not low vision.", "Correct. Errors of refraction lead bilateral low vision."]}'),
  ('e6740983-2r','{"options": ["Diabetic retinopathy", "Pterygium", "Trachoma", "Corneal opacity"], "correct": 1, "decode": "WHO''s blinding conditions include diabetic retinopathy, trachoma, and corneal opacity, but a pterygium usually does NOT cause vision impairment (unless it reaches the visual axis). Pick the benign surface growth.", "ow": ["Diabetic retinopathy is a listed blinding cause.", "Correct. A pterygium typically does not impair vision.", "Trachoma is a listed blinding cause.", "Corneal opacity is a listed blinding cause."]}'),
  ('637810a9-7i','{"options": ["+3.00 DS", "−3.00 DS", "+1.50 DS", "−1.50 DS"], "correct": 1, "decode": "Squints at distance but reads well at near equals myopia, and against motion in all meridians is neutralized by MINUS. The gross neutralizing lens here is -3.00 DS (net -1.50 after the working distance).", "ow": ["Plus is for hyperopia; against motion needs minus.", "Correct. Against motion in a distance-squinting child neutralizes with -3.00 DS gross.", "1.50 D is the working-distance value, not the gross neutral.", "Under-minused for an all-meridian against motion."]}'),
  ('e3c63174-50','{"options": ["3.75 D", "4.50 D", "5.00 D", "7.00 D"], "correct": 2, "decode": "Hofstetter average = 18.5 - 0.30 x age = 18.5 - 0.30 x 45 = 18.5 - 13.5 = 5.00 D. The other values do not match the calculation.", "ow": ["Too low for the average at 45.", "That is the minimum, not the average, at this age.", "Correct. 18.5 - 13.5 = 5.00 D.", "Too high for age 45."]}'),
  ('9e965bbb-7c','{"options": ["Left esotropia", "Left esophoria", "Left exophoria", "Right exotropia"], "correct": 2, "decode": "Recovery (''moves back outward when uncovered'') means a PHORIA, and the uncovered eye moving INWARD to refixate means it had drifted OUT, so left exophoria. Inward refixation = exo; recovery = latent.", "ow": ["A tropia would not recover; this recovers.", "Esophoria refixates outward, not inward.", "Correct. Inward refixation with recovery is a left exophoria.", "The moving eye is the left, and it recovers, so not a right tropia."]}'),
  ('31b8d264-3u','{"options": ["The pinhole result is invalid — a 20/60 eye should always reach 20/20 through pinhole", "The right eye has a purely organic pathology", "The right eye has both an uncorrected refractive error AND an organic component", "The right eye has an uncorrected refractive error only"], "correct": 2, "decode": "Pinhole improving only PARTLY (to 20/30, not 20/20) means part of the blur was refractive (the part that cleared) and part is organic (the residual). So both components are present.", "ow": ["A partial pinhole gain is a real, valid finding.", "Purely organic would show no pinhole improvement.", "Correct. Partial improvement means both refractive and organic components.", "A refractive-only cause would clear fully to 20/20."]}'),
  ('4ac5288e-63','{"options": ["Do not dilate — the angle is closed", "Proceed with dilation — the angle is wide open", "Dilate with caution and monitor for angle closure", "Measure IOP before deciding, then dilate freely if normal"], "correct": 2, "decode": "A Van Herick shadow about one-quarter of the section (grade 2) is a narrowish angle: dilate with CAUTION and monitor. It is neither closed nor wide-open, and IOP alone does not clear it for free dilation.", "ow": ["A quarter-width angle is narrow, not closed.", "A quarter-width angle is not wide open.", "Correct. Dilate with caution and monitor for angle closure.", "Normal IOP does not make a narrow angle safe to dilate freely."]}'),
  ('1b956af2-4s','{"options": ["16x → 16x → 16x", "25x → 6x → 40x", "40x → 16x → 6x", "6x → 16x → 25–40x"], "correct": 3, "decode": "Match magnification to task: survey adnexa at LOW power, examine cornea at MEDIUM, hunt cells and flare at HIGH. So 6x, then 16x, then 25 to 40x, going low to high.", "ow": ["A single magnification cannot serve all three tasks well.", "Starts too high and jumps around.", "Reverse order; you build from low to high.", "Correct. 6x survey, 16x cornea, 25 to 40x for cells and flare."]}'),
  ('7a8c4fcc-4c','{"options": ["Pigment on the corneal endothelium", "Inflammatory white blood cells", "A closed anterior chamber angle", "Protein leaked into the aqueous"], "correct": 3, "decode": "A hazy ''headlight-in-fog'' glow with NO discrete particles is FLARE, protein leaked into the aqueous. Discrete particles would be cells; this is the protein haze.", "ow": ["Endothelial pigment is a deposit, not a beam haze.", "Discrete white cells would be seen as particles, not a haze.", "A closed angle is a structural finding, not a beam glow.", "Correct. Protein leak (flare) gives the particle-free hazy glow."]}'),
  ('c5383456-3v','{"options": ["Increase the minus cylinder by 0.25D", "Add +0.25D to the sphere only", "Reduce the minus cylinder by 0.25D", "Rotate the axis clockwise toward the red dot"], "correct": 0, "decode": "On the JCC power check with preference for Position 1, the cylinder is under-corrected, so increase the minus cylinder by 0.25 D. Sphere and axis are handled in other steps.", "ow": ["Correct. Position 1 preference means add 0.25 D minus cylinder.", "This is a cylinder-power check, not a sphere step.", "Reducing cylinder is the Position 2 response.", "Axis rotation is a separate JCC step."]}'),
  ('28453037-5w','{"options": ["Repeat the monocular subjective refraction for OD before continuing", "Allow OD to retain the better vision and begin binocular reduction", "Add another +0.25D to OD to see if equality appears", "Add +0.25D to OS to bring it back"], "correct": 1, "decode": "When +0.25 to the clearer (dominant) eye just FLIPS the preference instead of equalizing, a perfect balance is impossible, so let the dominant eye stay clearer and move on to binocular reduction. Do not keep piling on plus or restart.", "ow": ["No need to redo the whole monocular refraction.", "Correct. Let the dominant eye keep the edge and proceed with binocular reduction.", "More plus over-fogs the dominant eye.", "Adding plus to OS over-fogs it without balancing."]}'),
  ('33a8e1a3-5e','{"options": ["Prescribe full cycloplegic correction and reassess", "Refer immediately for strabismus surgery", "Patch the right eye for 6 hours/day", "Prescribe BO prism to compensate for the esotropia"], "correct": 0, "decode": "Hyperopic child + esotropia that matches the +3.50 D on cycloplegic refraction is accommodative esotropia: FIRST give full cycloplegic (plus) correction and reassess. Surgery, patching, and base-out prism are not the first step.", "ow": ["Correct. Full cycloplegic correction first, then reassess.", "Surgery is not first-line for accommodative esotropia.", "Patching treats amblyopia, not the eso drive itself.", "Base-out prism does not address the accommodative drive."]}'),
  ('f5fe082c-5e','{"options": ["No prism needed; criterion is met", "2 Δ BO", "2 Δ BI", "4 Δ BI"], "correct": 2, "decode": "Sheard''s = (2 x phoria - reserve)/3 = (2 x 8 - 10)/3 = 6/3 = 2, and exophoria takes base-IN, so 2 base-in. Base-out or ''no prism'' are wrong.", "ow": ["The formula yields a nonzero prism.", "Exophoria takes base-in, not base-out.", "Correct. (16 - 10)/3 = 2 base-in.", "The calculation gives 2, not 4."]}'),
  ('b806fa22-m','{"options": ["cataract", "refractive error", "over 80%", "~25%"], "correct": 2, "decode": "The avoidable share of global vision impairment is OVER 80%, because the leading causes (refractive error, cataract) are correctable. The named diseases are causes, not the share.", "ow": ["Cataract is a cause, not the avoidable share.", "Refractive error is a cause, not the share.", "Correct. Over 80% of vision impairment is avoidable.", "Understates the avoidable share."]}'),
  ('8f5bf112-10','{"options": ["cataract", "~25%", "refractive error", "over 80%"], "correct": 0, "decode": "The Philippine leading cause of BLINDNESS is cataract. The percentages and refractive error are distractors here.", "ow": ["Correct. Cataract leads blindness in the Philippines.", "A percentage, not a disease cause.", "Refractive error leads low vision, not blindness.", "A percentage, not a disease cause."]}'),
  ('d1c6e810-11','{"options": ["over 80%", "~25%", "cataract", "refractive error"], "correct": 3, "decode": "The Philippine leading cause of LOW VISION is refractive error (cataract leads blindness). The percentages are distractors.", "ow": ["A percentage, not the low-vision cause.", "A percentage, not the low-vision cause.", "Cataract leads blindness, not low vision.", "Correct. Refractive error leads low vision in the Philippines."]}'),
  ('c7f5d6e9-s','{"options": ["~25%", "cataract", "over 80%", "refractive error"], "correct": 0, "decode": "Amblyopia prevalence among the affected group is quoted here as about 25%. The disease names and the 80% figure are distractors.", "ow": ["Correct. About 25% is the quoted amblyopia share.", "A disease cause, not the share.", "That is the avoidable-share figure, not amblyopia.", "A disease cause, not the share."]}'),
  ('437b2da2-12','{"options": ["0.25 to 3.00 D", "AOA < 5.00 D", "67 cm → −1.50D correction", "~0.25D or less"], "correct": 1, "decode": "Functional presbyopia is defined by amplitude of accommodation dropping below about 5.00 D, the point where sustained near work fails. The distance-correction and near-zero values describe other categories.", "ow": ["A near add range, not the presbyopia threshold.", "Correct. Functional presbyopia is AOA under about 5.00 D.", "That is the retinoscopy working distance, not presbyopia.", "Near-zero amplitude is absolute presbyopia, not functional."]}'),
  ('b0c5edf2-u','{"options": ["~0.25D or less", "AOA < 5.00 D", "0.25 to 3.00 D", "67 cm → −1.50D correction"], "correct": 0, "decode": "Absolute presbyopia is when amplitude falls to about 0.25 D or less, essentially no accommodation left. The under-5 D value is functional presbyopia.", "ow": ["Correct. Absolute presbyopia is about 0.25 D or less amplitude.", "Under 5 D is functional presbyopia, not absolute.", "A near add range, not absolute presbyopia.", "That is the working distance, not presbyopia."]}'),
  ('f5389d52-18','{"options": ["67 cm → −1.50D correction", "AOA < 5.00 D", "0.25 to 3.00 D", "~0.25D or less"], "correct": 0, "decode": "The standard retinoscopy working distance is 67 cm, which corresponds to a -1.50 D correction. The accommodation values belong to presbyopia definitions.", "ow": ["Correct. 67 cm equals a -1.50 D working-distance correction.", "That is a presbyopia amplitude value.", "A near add range, not the working distance.", "An accommodation value, not the working distance."]}'),
  ('8af11fb8-z','{"options": ["~0.25D or less", "3.00 to 6.00 D", "AOA < 5.00 D", "67 cm → −1.50D correction"], "correct": 1, "decode": "Medium (moderate) myopia is about 3.00 to 6.00 D. Below 3 is low; above 6 is high.", "ow": ["Near-zero is not a myopia class.", "Correct. Medium myopia is 3.00 to 6.00 D.", "An accommodation value, not a myopia class.", "That is the working distance, not a myopia class."]}'),
  ('90a54a89-x','{"options": ["AOA < 5.00 D", "~0.25D or less", "6.00 D and above", "67 cm → −1.50D correction"], "correct": 2, "decode": "High myopia is 6.00 D and above. Lower ranges are low or medium myopia.", "ow": ["An accommodation value, not a myopia class.", "Near-zero is not a myopia class.", "Correct. High myopia is 6.00 D and above.", "That is the working distance, not a myopia class."]}'),
  ('f7363112-n','{"options": ["AOA < 5.00 D", "3.00 to 5.00 D", "~0.25D or less", "67 cm → −1.50D correction"], "correct": 1, "decode": "Medium hyperopia is about 3.00 to 5.00 D. Below 3 is low; above 5 is high.", "ow": ["An accommodation value, not a hyperopia class.", "Correct. Medium hyperopia is 3.00 to 5.00 D.", "Near-zero is not a hyperopia class.", "That is the working distance, not a hyperopia class."]}'),
  ('a9a33617-l','{"options": ["67 cm → −1.50D correction", "5.00 D and above", "~0.25D or less", "AOA < 5.00 D"], "correct": 1, "decode": "High hyperopia is 5.00 D and above. Lower ranges are low or medium.", "ow": ["That is the working distance, not a hyperopia class.", "Correct. High hyperopia is 5.00 D and above.", "Near-zero is not a hyperopia class.", "An accommodation value, not a hyperopia class."]}'),
  ('a541abbc-r','{"options": ["67 cm → −1.50D correction", "AOA < 5.00 D", "~0.25D or less", "10.00 D"], "correct": 3, "decode": "On Donders'' table, amplitude at age 20 is about 10.00 D (youthful accommodation). The presbyopia and working-distance values are distractors.", "ow": ["That is the working distance, not the age-20 amplitude.", "An accommodation category, not the age-20 value.", "Near-zero fits the elderly, not age 20.", "Correct. Donders gives about 10.00 D at age 20."]}'),
  ('dc9694b2-r','{"options": ["4.50 D", "~0.25D or less", "AOA < 5.00 D", "67 cm → −1.50D correction"], "correct": 0, "decode": "On Donders'' table, amplitude at age 40 is about 4.50 D. The near-zero and working-distance values are distractors.", "ow": ["Correct. Donders gives about 4.50 D at age 40.", "Near-zero fits the elderly, not age 40.", "An accommodation category, not the age-40 value.", "That is the working distance, not the age-40 value."]}'),
  ('bed38517-r','{"options": ["~0.25D or less", "67 cm → −1.50D correction", "AOA < 5.00 D", "3.50 D"], "correct": 3, "decode": "On Donders'' table, amplitude at age 45 is about 3.50 D. The other values are categories or the working distance.", "ow": ["Near-zero fits the elderly, not age 45.", "That is the working distance, not the age-45 value.", "An accommodation category, not the age-45 value.", "Correct. Donders gives about 3.50 D at age 45."]}'),
  ('7fdb514c-2j','{"options": ["Hyperopia", "Emmetropia", "Myopia", "Hypermetropia"], "correct": 1, "decode": "Parallel rays focusing exactly on the retina at rest, needing no correction, is emmetropia. Any refractive error would need correction.", "ow": ["Hyperopia focuses behind the retina.", "Correct. Emmetropia focuses on the retina at rest.", "Myopia focuses in front of the retina.", "Hypermetropia is hyperopia, which needs correction."]}'),
  ('e08cc168-29','{"options": ["Myopia", "Hyperopia", "Emmetropia", "Hypermetropia"], "correct": 0, "decode": "Near-sightedness with the image in FRONT of the retina is myopia. Hyperopia focuses behind; emmetropia focuses on the retina.", "ow": ["Correct. Myopia focuses the image in front of the retina.", "Hyperopia focuses behind the retina.", "Emmetropia focuses on the retina.", "Hypermetropia is hyperopia, focusing behind."]}'),
  ('80f4d1d9-1w','{"options": ["Emmetropia", "Myopia", "Hyperopia", "Hypermetropia"], "correct": 2, "decode": "Far-sightedness with the image BEHIND the retina is hyperopia. Myopia focuses in front; emmetropia on the retina.", "ow": ["Emmetropia focuses on the retina.", "Myopia focuses in front of the retina.", "Correct. Hyperopia focuses the image behind the retina.", "Hypermetropia is the same as hyperopia, but the primary term asked is hyperopia."]}'),
  ('ec805697-2g','{"options": ["Hypermetropia", "Hyperopia", "Emmetropia", "Myopia"], "correct": 0, "decode": "Hypermetropia is the older/British term for the same condition as hyperopia; both are valid. The distractors are different refractive states.", "ow": ["Correct. Hypermetropia is the older term for hyperopia.", "Hyperopia is the condition, but the question asks its synonym.", "Emmetropia is normal, not hyperopia.", "Myopia is the opposite error."]}'),
  ('cf5d57c1-2h','{"options": ["Emmetropia", "Hyperopia", "Astigmatism", "Myopia"], "correct": 2, "decode": "Different powers in different meridians giving multiple foci (no single point focus) is astigmatism. The others are single-power states.", "ow": ["Emmetropia has a single on-retina focus.", "Hyperopia has a single focus behind the retina.", "Correct. Astigmatism gives multiple foci from unequal meridians.", "Myopia has a single focus in front."]}'),
  ('d3047534-28','{"options": ["Presbyopia", "Myopia", "Emmetropia", "Hyperopia"], "correct": 0, "decode": "Age-related loss of accommodative amplitude from lens stiffening is presbyopia. The others are refractive errors, not an aging accommodation loss.", "ow": ["Correct. Presbyopia is the age-related loss of accommodation.", "Myopia is a refractive error, not accommodation loss.", "Emmetropia is normal refraction.", "Hyperopia is a refractive error, not aging accommodation loss."]}'),
  ('e1b73ecb-1u','{"options": ["Emmetropia", "Hyperopia", "Myopia", "Anisometropia"], "correct": 3, "decode": "A refractive-error DIFFERENCE between the two eyes is anisometropia (aniso = unequal, metropia = refraction). The single-eye states do not describe a between-eye difference.", "ow": ["Emmetropia is normal, not a between-eye difference.", "Hyperopia is one error type, not a difference.", "Myopia is one error type, not a difference.", "Correct. Anisometropia is unequal refraction between the eyes."]}'),
  ('0b50b178-1o','{"options": ["Myopia", "Emmetropia", "Hyperopia", "Aniseikonia"], "correct": 3, "decode": "Unequal IMAGE SIZE between the two eyes is aniseikonia (eikon = image). Anisometropia is unequal refraction; aniseikonia is unequal image size.", "ow": ["Myopia is a refractive error, not an image-size difference.", "Emmetropia is normal.", "Hyperopia is a refractive error, not an image-size difference.", "Correct. Aniseikonia is unequal retinal image size."]}'),
  ('4a7502b3-22','{"options": ["Emmetropia", "Aphakia", "Myopia", "Hyperopia"], "correct": 1, "decode": "Absence of the crystalline lens, leaving extreme hyperopia, is aphakia (a = without, phakos = lens). Hyperopia is a result, but the term for no lens is aphakia.", "ow": ["Emmetropia is normal, not a missing lens.", "Correct. Aphakia is absence of the crystalline lens.", "Myopia is the opposite of the resulting error.", "Hyperopia is the result, but the missing-lens term is aphakia."]}'),
  ('0306004f-26','{"options": ["Emmetropia", "Myopia", "Hypermetropia", "Facultative hyperopia"], "correct": 3, "decode": "The hyperopia that accommodation CAN overcome is facultative hyperopia. Absolute cannot be overcome; latent is hidden by tone.", "ow": ["Emmetropia is normal, not overcome-able hyperopia.", "Myopia is the opposite error.", "Hypermetropia is the general term, not this subtype.", "Correct. Facultative hyperopia can be overcome by accommodation."]}'),
  ('b74f15d2-2h','{"options": ["Latent hyperopia", "Hypermetropia", "Emmetropia", "Myopia"], "correct": 0, "decode": "The hyperopia masked by tonic ciliary tone and revealed only under cycloplegia is latent hyperopia. Manifest is what routine refraction shows.", "ow": ["Correct. Latent hyperopia is revealed only under cycloplegia.", "Hypermetropia is the general term, not this subtype.", "Emmetropia is normal refraction.", "Myopia is the opposite error."]}'),
  ('b8270c35-28','{"options": ["Hypermetropia", "Myopia", "Manifest hyperopia", "Emmetropia"], "correct": 2, "decode": "The hyperopia measurable by routine refraction WITHOUT cycloplegia is manifest hyperopia. Latent needs cycloplegia to reveal.", "ow": ["Hypermetropia is the general term, not this subtype.", "Myopia is the opposite error.", "Correct. Manifest hyperopia is measurable without cycloplegia.", "Emmetropia is normal refraction."]}'),
  ('119bae5f-2h','{"options": ["Emmetropia", "Hyperopia", "Myopia", "AC/A ratio"], "correct": 3, "decode": "Prism diopters of convergence generated per diopter of accommodation is the AC/A ratio. The single-eye refractive terms do not describe this ratio.", "ow": ["Emmetropia is a refractive state, not a ratio.", "Hyperopia is a refractive error, not a ratio.", "Myopia is a refractive error, not a ratio.", "Correct. AC/A is convergence per unit accommodation."]}'),
  ('7278d8ec-2f','{"options": ["Emmetropia", "Pseudomyopia", "Hypermetropia", "Hyperopia"], "correct": 1, "decode": "Apparent myopia from tonic accommodative spasm in a non-myopic eye is pseudomyopia, which clears with cycloplegia. True myopia would not clear.", "ow": ["Emmetropia is normal; this is a spasm-induced pseudo-error.", "Correct. Pseudomyopia is spasm-induced apparent myopia.", "Hypermetropia is hyperopia, the opposite.", "Hyperopia is the opposite error."]}'),
  ('1bc5be9c-p','{"options": ["6.5mm", "3.0mm", "41–55mm", "4.0mm"], "correct": 2, "decode": "A child''s interpupillary distance runs about 41 to 55 mm (smaller than the ~64 mm adult). The single-millimeter values are far too small.", "ow": ["Far too small for an interpupillary distance.", "Far too small for an interpupillary distance.", "Correct. Children''s PD is about 41 to 55 mm.", "Far too small for an interpupillary distance."]}'),
  ('6adc5eb2-u','{"options": ["4.0mm", "41–55mm", "3.0mm", "6.5mm"], "correct": 0, "decode": "A normal pupil in room light is about 4.0 mm (mid-range). 3.0 mm fits bright direct light, 6.5 mm fits darkness; the 41 to 55 value is a child''s PD, not a pupil.", "ow": ["Correct. About 4.0 mm in room light.", "That is a child''s PD, not a pupil size.", "3.0 mm fits bright direct light.", "6.5 mm fits darkness."]}'),
  ('a054296a-s','{"options": ["6.5mm", "3.0mm", "41–55mm", "4.0mm"], "correct": 0, "decode": "In DARKNESS the pupil dilates to about 6.5 mm. Room light gives ~4.0, direct light ~3.0; 41 to 55 is a PD.", "ow": ["Correct. About 6.5 mm in darkness.", "3.0 mm fits direct light.", "That is a child''s PD, not a pupil size.", "4.0 mm fits room light."]}'),
  ('ad4c3258-w','{"options": ["6.5mm", "3.0mm", "4.0mm", "41–55mm"], "correct": 1, "decode": "Under bright DIRECT light the pupil constricts to about 3.0 mm. Room light gives ~4.0, darkness ~6.5.", "ow": ["6.5 mm fits darkness, not direct light.", "Correct. About 3.0 mm in direct light.", "4.0 mm fits room light.", "That is a child''s PD, not a pupil size."]}'),
  ('dac02c4b-r','{"options": [">0.5 mm", ">3.0 mm", ">1.0 mm", ">2.0 mm"], "correct": 2, "decode": "Anisocoria becomes clinically notable when the pupils differ by more than 1.0 mm. Smaller differences are physiologic; larger thresholds miss true anisocoria.", "ow": ["Below the notable threshold.", "Too large a threshold; you would miss real anisocoria.", "Correct. A difference over 1.0 mm defines notable anisocoria.", "Larger than the standard threshold."]}'),
  ('68228d59-p','{"options": ["30° = 60Δ", "Up to +5° nasally", "5° = 10Δ", "15° = 30Δ"], "correct": 1, "decode": "Normal angle kappa is a small positive value, up to about +5 degrees nasally (reflex slightly nasal to center). The large degree-to-prism conversions are distractors.", "ow": ["Far too large for a normal kappa.", "Correct. Normal angle kappa is up to about +5 degrees nasally.", "Larger than a normal kappa.", "Far too large for a normal kappa."]}'),
  ('ac9f43b4-2q','{"options": ["Version", "Vergence", "Duction", "NPC"], "correct": 0, "decode": "Both eyes moving the SAME direction together is a version (conjugate). Vergence is opposite directions; duction is one eye; NPC is a near point.", "ow": ["Correct. Version is conjugate movement of both eyes the same way.", "Vergence is opposite-direction movement.", "Duction is a single-eye movement.", "NPC is a near point, not a movement type."]}'),
  ('4c0ff082-1o','{"options": ["NPC", "Version", "Duction", "Vergence"], "correct": 2, "decode": "A single-eye movement in any direction is a duction. Version and vergence are binocular; NPC is a near point.", "ow": ["NPC is a near point, not a movement type.", "Version is binocular, both eyes together.", "Correct. Duction is a monocular eye movement.", "Vergence is binocular, opposite directions."]}'),
  ('6cfc85eb-2i','{"options": ["NPC", "Vergence", "Duction", "Version"], "correct": 1, "decode": "Both eyes moving in OPPOSITE directions (convergence/divergence) is vergence. Version is same-direction; duction is one eye.", "ow": ["NPC is a near point, not a movement type.", "Correct. Vergence is opposite-direction binocular movement.", "Duction is a single-eye movement.", "Version is same-direction movement."]}'),
  ('a9830fe4-2q','{"options": ["Version", "Vergence", "Duction", "NPC"], "correct": 3, "decode": "The closest point the eyes can hold convergence without diplopia is the near point of convergence (NPC). Version, vergence, and duction are movement types, not a near point.", "ow": ["Version is a movement type, not a near point.", "Vergence is a movement type, not the near point value.", "Duction is a single-eye movement.", "Correct. NPC is the closest point of maintained convergence."]}'),
  ('b82b149e-2l','{"options": ["Duction", "Version", "Vergence", "NPA"], "correct": 3, "decode": "The closest point the eye can still focus clearly (maximum accommodation) is the near point of accommodation (NPA). The movement terms do not describe focusing.", "ow": ["Duction is an eye movement, not focusing.", "Version is an eye movement, not focusing.", "Vergence is an eye movement, not focusing.", "Correct. NPA is the closest point of clear focus."]}'),
  ('8fa5f82d-2l','{"options": ["Duction", "Version", "Vergence", "Phoria"], "correct": 3, "decode": "A LATENT deviation controlled by fusion, appearing only when fusion is broken, is a phoria. The movement terms are not deviations.", "ow": ["Duction is a movement, not a latent deviation.", "Version is a movement, not a deviation.", "Vergence is a movement, not a deviation.", "Correct. A phoria is a latent, fusion-controlled deviation."]}'),
  ('d5ce657d-2e','{"options": ["Version", "Vergence", "Tropia", "Duction"], "correct": 2, "decode": "A MANIFEST, constant misalignment present with both eyes open is a tropia. Phoria is latent; the movement terms are not deviations.", "ow": ["Version is a movement, not a deviation.", "Vergence is a movement, not a deviation.", "Correct. A tropia is a manifest, constant deviation.", "Duction is a single-eye movement."]}'),
  ('f527ec7a-2p','{"options": ["Version", "RAPD", "Vergence", "Duction"], "correct": 1, "decode": "Paradoxical dilation of a pupil as light swings to it is an RAPD (afferent defect on that side). The movement terms are unrelated.", "ow": ["Version is an eye movement, not a pupil sign.", "Correct. Paradoxical dilation on swinging light is an RAPD.", "Vergence is an eye movement, not a pupil sign.", "Duction is an eye movement, not a pupil sign."]}'),
  ('0af40e1b-2e','{"options": ["Version", "Duction", "Marcus Gunn pupil", "Vergence"], "correct": 2, "decode": "An RAPD from impaired optic nerve or retinal input compared to the fellow eye is the Marcus Gunn pupil. The movement terms are unrelated.", "ow": ["Version is an eye movement, not a pupil sign.", "Duction is an eye movement, not a pupil sign.", "Correct. The RAPD is the Marcus Gunn pupil.", "Vergence is an eye movement, not a pupil sign."]}'),
  ('5370f2e7-2h','{"options": ["Version", "Duction", "Hirschberg test", "Vergence"], "correct": 2, "decode": "The corneal-reflex method estimating tropia size in prism diopters is the Hirschberg test. The movement terms are not alignment tests.", "ow": ["Version is a movement, not the reflex test.", "Duction is a movement, not the reflex test.", "Correct. Hirschberg estimates tropia size from the corneal reflex.", "Vergence is a movement, not the reflex test."]}'),
  ('6230d911-1w','{"options": ["Vergence", "Duction", "Version", "PERRL"], "correct": 3, "decode": "The standard abbreviation for normal pupil findings is PERRL (pupils equal, round, reactive to light). The movement terms are not pupil notation.", "ow": ["Vergence is an eye movement, not pupil notation.", "Duction is an eye movement, not pupil notation.", "Version is an eye movement, not pupil notation.", "Correct. PERRL is the normal-pupil abbreviation."]}'),
  ('f96919c5-2v','{"options": ["Version", "Anisocoria", "Duction", "Vergence"], "correct": 1, "decode": "Unequal pupil sizes, physiologic if the difference is 1 mm or less and equal in light and dark, is anisocoria. The movement terms are unrelated.", "ow": ["Version is an eye movement, not a pupil finding.", "Correct. Anisocoria is unequal pupil size.", "Duction is an eye movement, not a pupil finding.", "Vergence is an eye movement, not a pupil finding."]}'),
  ('92bd6111-18','{"options": ["16x", "6x–10x", "2–5x; 1.5–4.5x", "6x"], "correct": 2, "decode": "Indirect ophthalmoscopy magnifies only about 2 to 5x (varies with lens). The higher single values fit other instruments.", "ow": ["Too high for indirect ophthalmoscopy.", "Too high for indirect ophthalmoscopy.", "Correct. Indirect ophthalmoscopy magnifies about 2 to 5x.", "Too high for indirect ophthalmoscopy."]}'),
  ('bb603441-t','{"options": ["40–47D", "+22 D", "+10 D", "≤1.00D"], "correct": 0, "decode": "Normal keratometry (K) readings run about 40 to 47 D. The lens-power and astigmatism values are distractors.", "ow": ["Correct. Normal K readings are about 40 to 47 D.", "That is a slit-lamp objective power.", "That is a slit-lamp ocular power.", "That is a normal corneal astigmatism value."]}'),
  ('070a4fea-x','{"options": ["+10 D", "≤1.00D", "40–47D", "+22 D"], "correct": 1, "decode": "Normal corneal astigmatism is about 1.00 D or less. The K-range and lens powers are distractors.", "ow": ["A slit-lamp ocular power, not astigmatism.", "Correct. Normal corneal astigmatism is 1.00 D or less.", "That is the K-reading range, not astigmatism.", "A slit-lamp objective power, not astigmatism."]}'),
  ('f98de8c8-17','{"options": ["40–47D", "+22 D", "≤1.00D", "+10 D"], "correct": 3, "decode": "The slit lamp''s eyepiece (ocular) is about +10 D. The objective is +22 D; the K-range and astigmatism values are distractors.", "ow": ["That is the K-reading range, not the ocular.", "That is the objective power, not the ocular.", "That is a corneal astigmatism value.", "Correct. The slit-lamp ocular is about +10 D."]}'),
  ('4fa32340-11','{"options": ["≤1.00D", "+10 D", "40–47D", "+22 D"], "correct": 3, "decode": "The slit lamp''s objective lens is about +22 D (the ocular is +10 D). The K-range and astigmatism values are distractors.", "ow": ["A corneal astigmatism value, not the objective.", "That is the ocular power, not the objective.", "That is the K-reading range, not the objective.", "Correct. The slit-lamp objective is about +22 D."]}'),
  ('777896e9-2a','{"options": ["Mire", "Van Herick technique", "Parallelepiped", "Ophthalmoscopy"], "correct": 3, "decode": "Examining the interior of the eye with an ophthalmoscope is ophthalmoscopy. Mire, Van Herick, and parallelepiped are slit-lamp terms.", "ow": ["A mire is a keratometry target, not the exam.", "Van Herick estimates the angle, not interior exam.", "A parallelepiped is a slit-beam form, not the exam.", "Correct. Ophthalmoscopy examines the eye''s interior."]}'),
  ('b64a6381-26','{"options": ["Ophthalmoscopy", "Mire", "Van Herick technique", "Parallelepiped"], "correct": 3, "decode": "A slit beam about 3 mm wide giving a 3D block view of corneal volume is the parallelepiped. Ophthalmoscopy, mire, and Van Herick are different.", "ow": ["Ophthalmoscopy is a fundus exam, not a beam form.", "A mire is a keratometry target, not a beam form.", "Van Herick estimates the angle, not a beam block.", "Correct. The parallelepiped is the 3 mm block-view slit beam."]}'),
  ('4b860b7a-26','{"options": ["Ophthalmoscopy", "Mire", "Parallelepiped", "Van Herick technique"], "correct": 3, "decode": "The slit-lamp method estimating anterior chamber angle depth is the Van Herick technique. Ophthalmoscopy, mire, and parallelepiped are different.", "ow": ["Ophthalmoscopy is a fundus exam, not an angle estimate.", "A mire is a keratometry target, not an angle estimate.", "A parallelepiped is a beam form, not the angle method.", "Correct. The Van Herick technique estimates angle depth."]}'),
  ('85355686-2i','{"options": ["Van Herick technique", "Mire", "Ophthalmoscopy", "Parallelepiped"], "correct": 1, "decode": "The target circles or crosses reflected off the cornea in keratometry are the mires. Van Herick, ophthalmoscopy, and parallelepiped are other techniques.", "ow": ["Van Herick estimates the angle, not a keratometry target.", "Correct. Mires are the keratometry targets reflected off the cornea.", "Ophthalmoscopy is a fundus exam, not a target.", "A parallelepiped is a slit-beam form, not a keratometry target."]}'),
  ('d0068690-2a','{"options": ["Parallelepiped", "Ophthalmoscopy", "Van Herick technique", "Javal''s rule"], "correct": 3, "decode": "The formula predicting TOTAL astigmatism from corneal astigmatism is Javal''s rule. The other terms are slit-lamp or fundus techniques.", "ow": ["A parallelepiped is a slit-beam form, not a formula.", "Ophthalmoscopy is a fundus exam, not a formula.", "Van Herick estimates the angle, not astigmatism.", "Correct. Javal''s rule predicts total from corneal astigmatism."]}'),
  ('a7bb847d-l','{"options": ["+0.50 to +0.75D to both eyes", "+0.25D sphere per −0.50D cyl", "+0.50 to +0.75D above best sphere", "±0.12, ±0.25, ±0.50D"], "correct": 2, "decode": "The ideal fog is about +0.50 to +0.75 D ABOVE the best sphere, blurring just enough. The ''both eyes'' phrasing is the balance re-fog, and the other values are different constants.", "ow": ["That phrasing is the binocular-balance re-fog, not the astigmatic-dial fog.", "That is the sphere-per-cylinder rule, not the fog amount.", "Correct. Fog about +0.50 to +0.75 D above best sphere.", "Those are JCC strengths, not the fog amount."]}'),
  ('503d13ae-k','{"options": ["+0.25D sphere per −0.50D cyl", "+0.50 to +0.75D above best sphere", "+0.50 to +0.75D to both eyes", "±0.12, ±0.25, ±0.50D"], "correct": 3, "decode": "Standard JCC cross-cylinder strengths are plus/minus 0.12, 0.25, and 0.50 D. The fog and sphere-per-cylinder values are different.", "ow": ["That is the sphere-per-cylinder rule, not JCC strengths.", "That is the astigmatic-dial fog, not JCC strengths.", "That is the binocular-balance re-fog, not JCC strengths.", "Correct. JCC strengths are plus/minus 0.12, 0.25, 0.50 D."]}'),
  ('7db33937-u','{"options": ["+0.25D sphere per −0.50D cyl", "±0.12, ±0.25, ±0.50D", "+0.50 to +0.75D above best sphere", "+0.50 to +0.75D to both eyes"], "correct": 0, "decode": "The sphere compensation is +0.25 D sphere per -0.50 D cylinder (to hold the spherical equivalent). The other values are fog amounts or JCC strengths.", "ow": ["Correct. Add +0.25 D sphere per -0.50 D cylinder.", "Those are JCC strengths, not the sphere rule.", "That is the astigmatic-dial fog amount.", "That is the binocular-balance re-fog."]}'),
  ('9531bfea-v','{"options": ["+0.25D sphere per −0.50D cyl", "±0.12, ±0.25, ±0.50D", "+0.50 to +0.75D to both eyes", "+0.50 to +0.75D above best sphere"], "correct": 2, "decode": "The binocular-balance re-fog is +0.50 to +0.75 D applied to BOTH eyes. The ''above best sphere'' phrase is the astigmatic-dial fog; the others are different constants.", "ow": ["That is the sphere-per-cylinder rule.", "Those are JCC strengths.", "Correct. The balance re-fog is +0.50 to +0.75 D to both eyes.", "That phrasing is the astigmatic-dial fog, not the balance re-fog."]}'),
  ('700cfb52-h','{"options": ["+2.00D", "+0.25D sphere per −0.50D cyl", "+0.50 to +0.75D above best sphere", "±0.12, ±0.25, ±0.50D"], "correct": 0, "decode": "Normal NRA (plus-to-blur) is about +2.00 D. The other options are fog or sphere-rule constants.", "ow": ["Correct. Normal NRA is about +2.00 D.", "That is the sphere-per-cylinder rule, not NRA.", "That is the astigmatic-dial fog, not NRA.", "Those are JCC strengths, not NRA."]}'),
  ('f12f657c-h','{"options": ["±0.12, ±0.25, ±0.50D", "+0.25D sphere per −0.50D cyl", "+0.50 to +0.75D above best sphere", "−2.37D"], "correct": 3, "decode": "Normal PRA (minus-to-blur) is about -2.37 D. The plus and fog values are not PRA.", "ow": ["Those are JCC strengths, not PRA.", "That is the sphere-per-cylinder rule, not PRA.", "That is the astigmatic-dial fog, not PRA.", "Correct. Normal PRA is about -2.37 D."]}'),
  ('c9fe5a9f-2f','{"options": ["MPMVA", "Duochrome / Bichrome", "TIB", "Fogging"], "correct": 3, "decode": "Deliberate over-plussing to blur the image and relax accommodation is fogging. MPMVA is an endpoint; duochrome and TIB are other tests.", "ow": ["MPMVA is the endpoint, not the blurring step.", "Duochrome is a red-green check, not fogging.", "TIB is a balance technique, not fogging.", "Correct. Fogging over-plusses to relax accommodation."]}'),
  ('00cf5f2d-2d','{"options": ["Defogging", "Duochrome / Bichrome", "MPMVA", "TIB"], "correct": 0, "decode": "Reducing plus (or adding minus) after the astigmatic correction is set is defogging (clearing the fog). MPMVA is the endpoint; the others are separate tests.", "ow": ["Correct. Defogging reduces plus after the cylinder is set.", "Duochrome is a color check, not defogging.", "MPMVA is the endpoint, not the clearing step.", "TIB is a balance technique, not defogging."]}'),
  ('18431a5a-2c','{"options": ["Defogging", "Duochrome / Bichrome", "Fogging", "MPMVA"], "correct": 3, "decode": "The endpoint of highest plus (lowest minus) that still gives best acuity is MPMVA (maximum plus to maximum VA). Fogging and defogging are steps toward it.", "ow": ["Defogging is a step, not the endpoint.", "Duochrome is a check, not the endpoint.", "Fogging is a step, not the endpoint.", "Correct. MPMVA is the maximum-plus best-acuity endpoint."]}'),
  ('5576c68e-2k','{"options": ["MPMVA", "Defogging", "Fogging", "Duochrome / Bichrome"], "correct": 3, "decode": "The two-color test based on chromatic aberration is the duochrome (bichrome is its binocular version). MPMVA, fogging, and defogging are different steps.", "ow": ["MPMVA is an endpoint, not the color test.", "Defogging is a clearing step, not the color test.", "Fogging is a blurring step, not the color test.", "Correct. Duochrome/bichrome is the two-color chromatic-aberration test."]}'),
  ('2dd9d513-2k','{"options": ["Defogging", "Fogging", "MPMVA", "TIB"], "correct": 3, "decode": "The balance technique using a SEPTUM to separate each eye''s field is Turville Infinity Balance (TIB). Fogging, defogging, and MPMVA are not septum methods.", "ow": ["Defogging is a clearing step, not a septum method.", "Fogging is a blurring step, not a septum method.", "MPMVA is an endpoint, not a septum method.", "Correct. TIB uses a septum to separate the eyes'' fields."]}'),
  ('41be9db2-2l','{"options": ["Fogging", "OEP", "MPMVA", "Defogging"], "correct": 1, "decode": "The 21-step phorometric protocol mapping accommodation and convergence is the OEP (Optometric Extension Program) analysis. The other terms are single steps.", "ow": ["Fogging is one step, not the whole protocol.", "Correct. OEP is the 21-step phorometric protocol.", "MPMVA is an endpoint, not the protocol.", "Defogging is one step, not the protocol."]}'),
  ('ad953387-24','{"options": ["MPMVA", "PRA", "Defogging", "Fogging"], "correct": 1, "decode": "The maximum accommodation that can be STIMULATED at 40 cm (test #20) is the PRA. NRA is the inhibited one (#21).", "ow": ["MPMVA is an endpoint, not a relative-accommodation measure.", "Correct. PRA (#20) is the accommodation that can be stimulated.", "Defogging is a step, not a measure.", "Fogging is a step, not a measure."]}'),
  ('cffb1426-23','{"options": ["MPMVA", "NRA", "Fogging", "Defogging"], "correct": 1, "decode": "The maximum accommodation that can be INHIBITED at 40 cm (test #21) is the NRA. PRA is the stimulated one (#20).", "ow": ["MPMVA is an endpoint, not a relative-accommodation measure.", "Correct. NRA (#21) is the accommodation that can be relaxed/inhibited.", "Fogging is a step, not a measure.", "Defogging is a step, not a measure."]}'),
  ('ff941193-2q','{"options": ["Strabismus", "Tropia", "Phoria", "Eccentric fixation"], "correct": 0, "decode": "Manifest misalignment where one eye deviates from fixation is strabismus. Phoria is latent; eccentric fixation is a foveal issue.", "ow": ["Correct. Strabismus is manifest ocular misalignment.", "A tropia is the manifest deviation, but the umbrella condition asked is strabismus.", "A phoria is a latent, not manifest, deviation.", "Eccentric fixation is a foveal fixation problem, not misalignment."]}'),
  ('a9579388-2b','{"options": ["Strabismus", "Eccentric fixation", "Phoria", "Tropia"], "correct": 2, "decode": "A latent tendency to deviate, held by fusion, is a phoria. Strabismus/tropia are manifest; eccentric fixation is a foveal issue.", "ow": ["Strabismus is a manifest deviation.", "Eccentric fixation is a foveal fixation problem.", "Correct. A phoria is a latent, fusion-controlled deviation.", "A tropia is a manifest deviation."]}'),
  ('8495a71f-28','{"options": ["Eccentric fixation", "Tropia", "Phoria", "Strabismus"], "correct": 1, "decode": "A manifest deviation where the eye actually turns is a tropia. Phoria is only a tendency; strabismus is the general condition; eccentric fixation is foveal.", "ow": ["Eccentric fixation is a foveal problem, not a turn.", "Correct. A tropia is a manifest, actual eye turn.", "A phoria only tends to deviate.", "Strabismus is the umbrella term; the specific manifest turn is a tropia."]}'),
  ('2aa6e20c-2p','{"options": ["Eccentric fixation", "Tropia", "Phoria", "Strabismus"], "correct": 0, "decode": "Fixation at a non-foveal retinal point in the amblyopic eye is eccentric fixation. The deviation terms describe alignment, not the fixation point.", "ow": ["Correct. Eccentric fixation uses a non-foveal retinal point.", "A tropia is an alignment deviation, not a fixation point.", "A phoria is a latent deviation, not a fixation point.", "Strabismus is misalignment, not the fixation point."]}'),
  ('789ecc74-2x','{"options": ["Penalization", "Strabismus", "Tropia", "Phoria"], "correct": 0, "decode": "Deliberately blurring or occluding the BETTER eye to force the amblyopic eye is penalization. The deviation terms are unrelated.", "ow": ["Correct. Penalization blurs/occludes the good eye to force the amblyopic one.", "Strabismus is a deviation, not a treatment.", "A tropia is a deviation, not a treatment.", "A phoria is a deviation, not a treatment."]}'),
  ('a72edc73-4a','{"options": ["Phoria", "Pleoptics", "Strabismus", "Tropia"], "correct": 1, "decode": "Intense light stimulation of the non-foveal area to retrain foveal fixation in eccentric-fixation amblyopia is pleoptics. The deviation terms are unrelated.", "ow": ["A phoria is a deviation, not a treatment.", "Correct. Pleoptics rehabilitates foveal fixation in eccentric fixation.", "Strabismus is a deviation, not a treatment.", "A tropia is a deviation, not a treatment."]}'),
  ('45b185a4-2q','{"options": ["Aniseikonia", "Tropia", "Strabismus", "Phoria"], "correct": 0, "decode": "Unequal image size between the eyes causing fusion difficulty is aniseikonia. The deviation terms describe alignment, not image size.", "ow": ["Correct. Aniseikonia is unequal retinal image size.", "A tropia is a deviation, not an image-size difference.", "Strabismus is misalignment, not image size.", "A phoria is a deviation, not an image-size difference."]}'),
  ('61802207-2m','{"options": ["Prism segment", "Bifocal segment", "Iseikonic lens", "Aspheric lens"], "correct": 2, "decode": "A lens that equalizes retinal image size WITHOUT changing power is an iseikonic (size) lens. Prism, bifocal, and aspheric segments do other jobs.", "ow": ["A prism shifts images, it does not equalize size.", "A bifocal adds near power, not size correction.", "Correct. An iseikonic lens equalizes image size without altering power.", "An aspheric lens reduces aberration, not image size."]}'),
  ('8f80cacc-3f','{"options": ["Eccentric fixation", "Physiological diplopia", "Vision therapy", "Pleoptics"], "correct": 2, "decode": "The broad term including accommodation, sensory fusion, and higher perceptual training (not just convergence) is vision therapy. Pleoptics is narrower; the other terms are findings.", "ow": ["Eccentric fixation is a finding, not a therapy program.", "Physiological diplopia is a phenomenon, not a therapy.", "Correct. Vision therapy is the broad training program.", "Pleoptics is a narrow amblyopia technique, not the broad term."]}'),
  ('1cd1833f-3z','{"options": ["Eccentric fixation", "Vision therapy", "Pleoptics", "Physiological diplopia"], "correct": 2, "decode": "The monocular technique that dazzles the peripheral retina with intense light to rehabilitate foveal fixation is pleoptics. Eccentric fixation is the problem, not the treatment.", "ow": ["Eccentric fixation is the condition, not the technique.", "Vision therapy is the broad program, not this specific method.", "Correct. Pleoptics dazzles the periphery to restore foveal fixation.", "Physiological diplopia is a phenomenon, not a treatment."]}'),
  ('5222298c-37','{"options": ["Pleoptics", "Eccentric fixation", "Vision therapy", "Physiological diplopia"], "correct": 1, "decode": "Fixation at a non-foveal point in the amblyopic eye, marking deep amblyopia, is eccentric fixation. Pleoptics is its treatment.", "ow": ["Pleoptics is the treatment, not the finding.", "Correct. Eccentric fixation is non-foveal fixation in deep amblyopia.", "Vision therapy is a program, not the finding.", "Physiological diplopia is a normal phenomenon, not this."]}'),
  ('89341acf-3p','{"options": ["Physiological diplopia", "Vision therapy", "Pleoptics", "Eccentric fixation"], "correct": 0, "decode": "Normal doubling of non-fixated objects, present when fusion is intact and absent in suppression, is physiological diplopia. It is a normal finding, not a therapy.", "ow": ["Correct. Physiological diplopia is normal doubling of non-fixated objects.", "Vision therapy is a program, not this phenomenon.", "Pleoptics is a treatment, not this phenomenon.", "Eccentric fixation is a fixation defect, not this phenomenon."]}'),
  ('8f7a6889-3v','{"options": ["Eccentric fixation", "Pleoptics", "Vision therapy", "Bielschowsky head tilt test"], "correct": 3, "decode": "Step 3 of the Parks 3-step, where head tilt loads the cyclovertical muscles, is the Bielschowsky head tilt test. The other terms are not tilt tests.", "ow": ["Eccentric fixation is a fixation defect, not a tilt test.", "Pleoptics is a treatment, not a tilt test.", "Vision therapy is a program, not a tilt test.", "Correct. The head-tilt step is the Bielschowsky test."]}'),
  ('e4535b18-3k','{"options": ["Vision therapy", "Eccentric fixation", "Synoptophore / Amblyoscope", "Pleoptics"], "correct": 2, "decode": "The instrument measuring objective and subjective angles of deviation and training all three BV grades is the synoptophore (amblyoscope). The other terms are not instruments.", "ow": ["Vision therapy is a program, not an instrument.", "Eccentric fixation is a finding, not an instrument.", "Correct. The synoptophore/amblyoscope measures deviation and trains fusion.", "Pleoptics is a technique, not this instrument."]}'),
  ('f1b2347e-35','{"options": ["Eccentric fixation", "Pleoptics", "CAM vision stimulator", "Vision therapy"], "correct": 2, "decode": "Rotating high-contrast gratings that stimulate the amblyopic eye monocularly for about 7 minutes is the CAM stimulator. The other terms are not this device.", "ow": ["Eccentric fixation is a finding, not a device.", "Pleoptics is a different light-dazzle technique.", "Correct. The CAM stimulator uses rotating gratings, about 7 minutes.", "Vision therapy is the broad program, not this device."]}'),
  ('9275cba9-3p','{"options": ["Pleoptics", "Vision therapy", "Eccentric fixation", "Dichoptic training"], "correct": 3, "decode": "Presenting different images to each eye to force cortical integration (modern active therapy) is dichoptic training. The older/other terms are not this method.", "ow": ["Pleoptics is an older monocular technique, not dichoptic.", "Vision therapy is the broad umbrella, not this specific method.", "Eccentric fixation is a finding, not a therapy.", "Correct. Dichoptic training feeds each eye a different image."]}'),
  ('ca51572f-24','{"options": ["Myopia", "Hyperopia", "Presbyopia", "Astigmatism"], "correct": 1, "decode": "In OEP analysis, HYPEROPIA buffers the accommodative pattern (extra plus need shifts the findings). Myopia, presbyopia, and astigmatism are not the accommodative buffer.", "ow": ["Myopia does not buffer the accommodative pattern in OEP.", "Correct. Hyperopia buffers the OEP accommodative pattern.", "Presbyopia is an amplitude loss, not the buffer.", "Astigmatism is not the accommodative buffer."]}'),
  ('1f6a0a73-1r','{"options": ["Exophoria", "Hyperopia", "Esophoria", "Myopia"], "correct": 0, "decode": "In OEP analysis, EXOPHORIA buffers the convergence pattern. Esophoria, hyperopia, and myopia are not the convergence buffer.", "ow": ["Correct. Exophoria buffers the OEP convergence pattern.", "Hyperopia buffers accommodation, not convergence.", "Esophoria is the opposite posture, not the buffer.", "Myopia is not the convergence buffer."]}'),
  ('e19aa83b-2d','{"options": ["Farther and bigger", "Closer and smaller", "Closer and bigger", "Farther and smaller"], "correct": 0, "decode": "A CONVEX lens relaxes accommodation, so the target appears FARTHER and BIGGER (relax response). This is the opposite of the base-out prism response.", "ow": ["Correct. Convex (plus) relaxes accommodation: target farther and bigger.", "That is the convergence-stimulating (base-out) response.", "Bigger yes, but plus makes it appear farther, not closer.", "Plus makes it appear bigger, not smaller."]}'),
  ('017103d5-2e','{"options": ["Closer and bigger", "Farther and smaller", "Closer and smaller", "Farther and bigger"], "correct": 2, "decode": "BASE-OUT prism stimulates convergence, so by SILO the target appears CLOSER and SMALLER (Stimulate In, image smaller). This is the opposite of the plus-lens response.", "ow": ["Base-out makes it appear smaller, not bigger.", "Base-out makes it appear closer, not farther.", "Correct. Base-out stimulates convergence: closer and smaller (SILO).", "That is the plus-lens (relax) response."]}'),
  ('1c154f70-1p','{"options": ["The test #7 findings", "The habitual correction", "Plano lenses", "Full cycloplegic correction"], "correct": 1, "decode": "OEP test #3 is done at 20 feet with the HABITUAL correction in place. Test #7 findings and plano/cycloplegic are used in other steps.", "ow": ["The #7 findings are used at test #8, not #3.", "Correct. Test #3 uses the habitual correction.", "Plano lenses are not the #3 setup.", "Cycloplegia is not used for #3."]}'),
  ('908b909f-1u','{"options": ["To gather information about the patient''s ocular and systemic condition", "To measure the patient''s pupillary distance for lens fitting", "To determine the best spectacle frame size and shape for them", "To determine the thickness of the finished spectacle lenses"], "correct": 0, "decode": "The primary purpose of the case history is to gather information about the patient''s ocular and systemic condition. PD, frame, and lens thickness are dispensing measurements, not the history''s purpose.", "ow": ["Correct. Case history gathers ocular and systemic information.", "PD is a dispensing measurement, not the history''s purpose.", "Frame choice is a dispensing step, not the history.", "Lens thickness is a fabrication detail, not the history."]}'),
  ('58c9b273-1i','{"options": ["Keratometry", "Retinoscopy", "Autorefraction", "Snellen visual acuity"], "correct": 3, "decode": "A SUBJECTIVE acuity test relies on the patient''s response, which is the Snellen chart. Keratometry, retinoscopy, and autorefraction are objective.", "ow": ["Keratometry is an objective corneal measure.", "Retinoscopy is an objective refraction method.", "Autorefraction is an objective, instrument-based measure.", "Correct. Snellen acuity relies on the patient''s responses (subjective)."]}'),
  ('8e7f990b-1v','{"options": ["12 meters", "3 meters", "6 meters", "1 meter"], "correct": 2, "decode": "Standard Snellen distance acuity is measured at 6 meters (20 feet). The other distances are non-standard.", "ow": ["Not the standard Snellen distance.", "A near/intermediate distance, not standard far.", "Correct. Snellen distance acuity is measured at 6 meters.", "That is a near working distance."]}'),
  ('e15a793d-1e','{"options": ["Cover test", "Keratometry", "Tonometry", "Visual acuity"], "correct": 3, "decode": "The test of ability to see fine DETAIL is visual acuity. Cover test checks alignment, keratometry the cornea, tonometry pressure.", "ow": ["The cover test checks alignment, not detail.", "Keratometry measures the cornea, not detail vision.", "Tonometry measures pressure, not detail.", "Correct. Visual acuity measures the ability to resolve fine detail."]}'),
  ('09568f24-1y','{"options": ["Trial frame", "Tonometer", "Ophthalmoscope", "Retinoscope"], "correct": 3, "decode": "The instrument for OBJECTIVE refractive error is the retinoscope. Trial frame holds lenses (subjective), tonometer measures pressure, ophthalmoscope views the fundus.", "ow": ["A trial frame holds lenses for subjective refraction.", "A tonometer measures pressure, not refraction.", "An ophthalmoscope views the fundus, not refraction.", "Correct. The retinoscope objectively measures refractive error."]}'),
  ('736600bb-1n','{"options": ["The patient is highly myopic", "The cornea is opaque", "The eye has no refractive error", "The far point is behind the retinoscope"], "correct": 3, "decode": "A ''with motion'' reflex means the far point is BEHIND the retinoscope, so plus is needed. It does not indicate high myopia, opacity, or emmetropia by itself.", "ow": ["High myopia gives against motion, not with.", "An opaque cornea dulls the reflex, not the motion direction.", "Motion direction indicates a far-point location, not zero error.", "Correct. With motion means the far point is behind the retinoscope."]}'),
  ('ebe4edcd-1l','{"options": ["Amsler grid", "Schirmer test", "Ishihara test", "Cover test"], "correct": 3, "decode": "Binocular ALIGNMENT problems are detected by the cover test. Amsler tests the macula, Schirmer tears, Ishihara color.", "ow": ["The Amsler grid tests the macula, not alignment.", "The Schirmer test measures tears, not alignment.", "The Ishihara test checks color, not alignment.", "Correct. The cover test detects binocular alignment problems."]}'),
  ('8cc5a12b-16','{"options": ["Intraocular pressure", "Ocular alignment/phoria", "Corneal curvature", "Color vision"], "correct": 1, "decode": "The Maddox rod assesses ocular alignment (phoria) by dissociating the eyes. It does not measure pressure, curvature, or color.", "ow": ["Pressure needs a tonometer, not a Maddox rod.", "Correct. The Maddox rod assesses alignment/phoria.", "Curvature needs a keratometer, not a Maddox rod.", "Color needs Ishihara, not a Maddox rod."]}'),
  ('bdedebb9-1c','{"options": ["Schirmer test", "Ishihara test", "Titmus test", "Amsler grid"], "correct": 2, "decode": "Stereopsis is assessed with the Titmus (fly) test using polarized targets. Schirmer, Ishihara, and Amsler test other functions.", "ow": ["The Schirmer test measures tears, not stereopsis.", "The Ishihara test checks color, not stereopsis.", "Correct. The Titmus test assesses stereopsis.", "The Amsler grid tests the macula, not stereopsis."]}'),
  ('51fffb98-19','{"options": ["Accommodation", "Color vision", "Binocular vision", "Visual acuity"], "correct": 1, "decode": "The Ishihara test assesses COLOR vision (red-green). It is not for accommodation, binocularity, or acuity.", "ow": ["Accommodation is measured differently.", "Correct. The Ishihara test assesses color vision.", "Binocular vision uses Worth 4-dot, not Ishihara.", "Acuity uses a Snellen chart, not Ishihara."]}'),
  ('3409feed-1p','{"options": ["Cover test", "Worth 4-dot", "Schirmer test", "Amsler grid"], "correct": 3, "decode": "Central visual FUNCTION (macula) is assessed with the Amsler grid. Cover test is alignment, Worth 4-dot is fusion, Schirmer is tears.", "ow": ["The cover test checks alignment, not central function.", "Worth 4-dot checks fusion, not central function.", "The Schirmer test measures tears, not central function.", "Correct. The Amsler grid assesses central (macular) function."]}'),
  ('38b57f6e-1b','{"options": ["Intraocular pressure", "Binocular sensory fusion", "Corneal curvature", "Tear production"], "correct": 1, "decode": "The Worth 4-dot test evaluates binocular sensory FUSION (and suppression). It is not for pressure, curvature, or tears.", "ow": ["Pressure needs a tonometer, not Worth 4-dot.", "Correct. Worth 4-dot evaluates binocular sensory fusion.", "Curvature needs a keratometer, not Worth 4-dot.", "Tears need a Schirmer test, not Worth 4-dot."]}'),
  ('eb14109e-1k','{"options": ["Lensometer", "Keratometer", "Retinoscope", "Tonometer"], "correct": 3, "decode": "Intraocular pressure is measured with a tonometer. Lensometer reads lens power, keratometer the cornea, retinoscope the refraction.", "ow": ["A lensometer reads lens power, not pressure.", "A keratometer measures the cornea, not pressure.", "A retinoscope measures refraction, not pressure.", "Correct. A tonometer measures intraocular pressure."]}'),
  ('a7f5a3bf-1a','{"options": ["5-10 mmHg", "25-40 mmHg", "10-21 mmHg", "2-5 mmHg"], "correct": 2, "decode": "Normal IOP is about 10 to 21 mmHg. Values much lower or higher fall outside normal.", "ow": ["Too low for normal IOP.", "That is elevated, not normal.", "Correct. Normal IOP is about 10 to 21 mmHg.", "Far too low for normal IOP."]}'),
  ('cc766c70-1t','{"options": ["Lensometer", "Trial frame", "Slit lamp biomicroscope", "Retinoscope"], "correct": 2, "decode": "A magnified, illuminated view of the eye comes from the slit lamp biomicroscope. Lensometer, trial frame, and retinoscope do other jobs.", "ow": ["A lensometer reads lens power, not the eye.", "A trial frame holds lenses, not a view.", "Correct. The slit lamp biomicroscope gives a magnified illuminated view.", "A retinoscope measures refraction, not a magnified view."]}'),
  ('56db81d1-1l','{"options": ["Presbyopia", "Corneal epithelial defects", "Cataract", "Retinal detachment"], "correct": 1, "decode": "Fluorescein stains and reveals CORNEAL EPITHELIAL DEFECTS (abrasions, ulcers). It does not detect presbyopia, cataract, or detachment.", "ow": ["Presbyopia is a focusing loss, not a stainable defect.", "Correct. Fluorescein detects corneal epithelial defects.", "Cataract is a lens opacity, not a surface stain.", "Detachment is intraocular, not a surface stain."]}'),
  ('53143f95-10','{"options": ["Maddox rod", "Amsler test", "Schirmer test", "Ishihara test"], "correct": 2, "decode": "Tear PRODUCTION is measured by the Schirmer test (paper strip). Maddox rod, Amsler, and Ishihara test alignment, macula, and color.", "ow": ["The Maddox rod checks alignment, not tears.", "The Amsler grid tests the macula, not tears.", "Correct. The Schirmer test measures tear production.", "The Ishihara test checks color, not tears."]}'),
  ('9b84d00a-1m','{"options": ["Immediately perform tonometry to measure the eye pressure", "Dilate the pupil right away using mydriatic eyedrops", "Prescribe corrective lenses before any testing is done", "Explain the procedure and obtain appropriate patient cooperation"], "correct": 3, "decode": "Before most tests you first EXPLAIN the procedure and gain the patient''s cooperation. Jumping straight to tonometry, dilation, or prescribing skips that essential step.", "ow": ["Tonometry comes after explaining and preparing the patient.", "Dilation is not the universal first step.", "Prescribing comes after testing, not before.", "Correct. Explain the procedure and obtain cooperation first."]}'),
  ('f9386b99-32','{"options": ["Gonioscopy", "Fluorescein staining", "Fogging and refinement", "Schirmer testing"], "correct": 2, "decode": "Best SPHERE in subjective refraction is found by fogging and refinement (MPMVA). Gonioscopy, fluorescein, and Schirmer are unrelated tests.", "ow": ["Gonioscopy views the angle, not refraction.", "Fluorescein stains the cornea, not refraction.", "Correct. Fogging and refinement finds the best sphere.", "The Schirmer test measures tears, not refraction."]}'),
  ('75e021e1-1m','{"options": ["Cylinder axis and power", "Tear production", "Pupil size", "Intraocular pressure"], "correct": 0, "decode": "The JCC refines the CYLINDER axis and power. It is not for tears, pupil size, or pressure.", "ow": ["Correct. The JCC refines cylinder axis and power.", "Tears are measured by Schirmer, not JCC.", "Pupil size is not a JCC function.", "Pressure needs a tonometer, not JCC."]}'),
  ('9cd8a666-22','{"options": ["Close both eyes", "Report which option appears clearer", "Look at the examiner", "Guess without comparing choices"], "correct": 1, "decode": "In subjective refraction the patient should report which choice looks CLEARER (comparing options). Closing eyes, looking away, or guessing defeats the comparison.", "ow": ["Both eyes closed cannot compare lenses.", "Correct. The patient reports which option is clearer.", "Looking at the examiner is not the task.", "Guessing without comparing gives unreliable answers."]}'),
  ('2717a58e-1c','{"options": ["To induce accommodation", "To increase IOP", "To relax accommodation", "To measure corneal curvature"], "correct": 2, "decode": "Fogging adds plus to RELAX accommodation, preventing over-minus. It does not induce accommodation, raise IOP, or measure the cornea.", "ow": ["Fogging relaxes, not induces, accommodation.", "Fogging has nothing to do with IOP.", "Correct. Fogging relaxes accommodation.", "Fogging does not measure corneal curvature."]}'),
  ('72348cc4-13','{"options": ["Improve visual acuity reduced by refractive error", "Determine the patient''s tear production rate", "Measure the amplitude of accommodation directly", "Measure the intraocular pressure directly"], "correct": 0, "decode": "A pinhole IMPROVES acuity reduced by refractive error, by cutting blur circles. It does not measure tears, accommodation, or pressure.", "ow": ["Correct. A pinhole improves refractive blur.", "Tears need a Schirmer test, not a pinhole.", "A pinhole does not directly measure accommodation.", "A pinhole does not measure IOP."]}'),
  ('c0f1efa3-20','{"options": ["Corneal perforation", "Complete retinal detachment", "Optic nerve atrophy", "Uncorrected refractive error"], "correct": 3, "decode": "If acuity improves a lot with a pinhole, the cause is uncorrected refractive error (optical blur). Perforation, detachment, and optic atrophy would not improve with a pinhole.", "ow": ["A corneal perforation is an emergency, not pinhole-responsive.", "Detachment does not improve with a pinhole.", "Optic atrophy does not improve with a pinhole.", "Correct. Pinhole improvement means uncorrected refractive error."]}'),
  ('9695630d-1e','{"options": ["Measure the central corneal thickness precisely", "Determine the diameter of the patient''s pupil", "Measure the intraocular pressure within each eye", "Equalize accommodation between the eyes during refraction"], "correct": 3, "decode": "Binocular balancing EQUALIZES accommodation between the two eyes during refraction. It does not measure corneal thickness, pupil size, or pressure.", "ow": ["Thickness needs a pachymeter, not balancing.", "Pupil size is unrelated to balancing.", "Pressure needs a tonometer, not balancing.", "Correct. Balancing equalizes accommodation between the eyes."]}'),
  ('31d94889-x','{"options": ["Retinal sensitivity", "Corneal curvature", "Tear volume", "Lens power, axis, and prism"], "correct": 3, "decode": "A lensometer measures a spectacle lens''s power, axis, and prism. It does not measure retinal sensitivity, corneal curvature, or tears.", "ow": ["Retinal sensitivity is measured by perimetry, not a lensometer.", "Corneal curvature needs a keratometer.", "Tear volume needs a Schirmer test.", "Correct. A lensometer reads lens power, axis, and prism."]}'),
  ('d6282664-19','{"options": ["Detecting glaucoma", "Determining IOP", "Measuring corneal thickness", "Proper optical centration of lenses"], "correct": 3, "decode": "Pupillary distance matters for proper OPTICAL CENTRATION of lenses (aligning optical centers with the pupils). It is not for glaucoma, IOP, or thickness.", "ow": ["PD does not detect glaucoma.", "PD is unrelated to IOP.", "PD is unrelated to corneal thickness.", "Correct. PD ensures proper optical centration of lenses."]}'),
  ('64ff0b38-2t','{"options": ["Hyperopia", "Emmetropia", "Myopia", "Presbyopia"], "correct": 2, "decode": "Blurred DISTANCE vision that improves on squinting is myopia (squinting makes a pinhole). Hyperopia and presbyopia affect near; emmetropia is normal.", "ow": ["Hyperopia blurs near more than distance in the young.", "Emmetropia needs no correction and would not blur.", "Correct. Distance blur improved by squinting is myopia.", "Presbyopia is a near-focus problem, not distance blur."]}'),
  ('7d189bfe-3e','{"options": ["Amblyopia", "Presbyopia", "Myopia", "Keratoconus"], "correct": 1, "decode": "A 45-year-old with poor NEAR print but good distance has presbyopia (age-related accommodation loss). Amblyopia, myopia, and keratoconus do not fit this age-and-near pattern.", "ow": ["Amblyopia is a developmental acuity loss, not age-related near blur.", "Correct. Age 45 with near difficulty is presbyopia.", "Myopia blurs distance, not near.", "Keratoconus distorts vision generally, not just near at 45."]}'),
  ('d2ddd79d-3j','{"options": ["Astigmatism", "Color deficiency", "Presbyopia", "Emmetropia"], "correct": 0, "decode": "Lines blurred differently in different ORIENTATIONS suggest astigmatism (meridian-dependent blur). Color deficiency, presbyopia, and emmetropia do not give orientation-dependent blur.", "ow": ["Correct. Orientation-dependent blur suggests astigmatism.", "Color deficiency affects hue, not line orientation.", "Presbyopia blurs near uniformly, not by orientation.", "Emmetropia needs no correction."]}'),
  ('b8d656a1-18','{"options": ["Lower eyelid", "Upper eyelid", "Central visual field", "Extreme peripheral field"], "correct": 2, "decode": "A CENTRAL scotoma is a defect in the central visual field. It is not on the eyelids or in the far periphery.", "ow": ["The lids are not part of the visual field.", "The lids are not part of the visual field.", "Correct. A central scotoma lies in the central field.", "''Central'' places it centrally, not peripherally."]}'),
  ('c43bd371-1i','{"options": ["Visual field", "Pupil size", "Color vision", "Cylinder power and axis"], "correct": 3, "decode": "The Jackson cross-cylinder refines CYLINDER power and axis. It is not for field, pupil, or color.", "ow": ["The field is tested by perimetry, not JCC.", "Pupil size is not a JCC function.", "Color is tested by Ishihara, not JCC.", "Correct. The JCC refines cylinder power and axis."]}'),
  ('a696c7a1-w','{"options": ["Relax accommodation", "Test color vision", "Measure IOP", "Stimulate accommodation"], "correct": 0, "decode": "The fogging technique RELAXES accommodation (adds plus). It does not test color, measure IOP, or stimulate accommodation.", "ow": ["Correct. Fogging relaxes accommodation.", "Fogging is not a color test.", "Fogging is unrelated to IOP.", "Fogging relaxes, not stimulates, accommodation."]}'),
  ('7920b22a-1f','{"options": ["Neutral-density filter", "Cobalt-blue filter", "Green filter", "Red filter"], "correct": 1, "decode": "Fluorescein glows best under the cobalt-blue filter. Neutral-density, green, and red filters do not excite it.", "ow": ["A neutral-density filter only dims light.", "Correct. Cobalt blue enhances fluorescein.", "Green (red-free) is for vessels, not fluorescein.", "A red filter does not excite fluorescein."]}'),
  ('cc4bf8d6-1f','{"options": ["Increase the contrast of fluorescein", "Measure IOP", "Measure corneal curvature", "Measure lens power"], "correct": 0, "decode": "A yellow barrier filter INCREASES fluorescein contrast (blocks blue, passes the green glow). It does not measure pressure, curvature, or lens power.", "ow": ["Correct. The yellow barrier filter boosts fluorescein contrast.", "It does not measure IOP.", "It does not measure corneal curvature.", "It does not measure lens power."]}'),
  ('b6b10624-s','{"options": ["Tonic pupil", "Argyll Robertson pupil", "Marcus Gunn pupil", "Adie pupil"], "correct": 2, "decode": "An RAPD is the Marcus Gunn pupil. Tonic (Adie), Argyll-Robertson, and Adie are different pupil syndromes.", "ow": ["A tonic pupil is Adie''s, not an RAPD.", "Argyll-Robertson shows light-near dissociation, not an RAPD.", "Correct. The RAPD is the Marcus Gunn pupil.", "Adie is a tonic dilated pupil, not an RAPD."]}'),
  ('9f00705b-21','{"options": ["ETDRS", "Amsler", "Ishihara", "Tumbling E"], "correct": 3, "decode": "A chart for children who cannot read letters is the Tumbling E (they point which way it opens). ETDRS uses letters; Amsler and Ishihara test macula and color.", "ow": ["ETDRS uses letters, so not for pre-literate children.", "The Amsler grid tests the macula, not acuity.", "Ishihara tests color, not acuity.", "Correct. The Tumbling E chart suits children who cannot read letters."]}'),
  ('15482727-1l','{"options": ["Size of the E", "Direction of the E", "Number of Es", "Color of the E"], "correct": 1, "decode": "On the Tumbling E chart the patient reports the DIRECTION the E points. Size, number, and color are not the task.", "ow": ["Size is set by the chart line, not reported.", "Correct. The patient reports the direction the E faces.", "There is one E to orient, not counted.", "Color is not part of the test."]}'),
  ('dbaee735-1b','{"options": ["Lens power", "Corneal thickness", "Contact lens diameter", "Pupil size"], "correct": 1, "decode": "A pachymeter measures corneal THICKNESS (''pachy'' = thick). It does not measure lens power, contact lens diameter, or pupil size.", "ow": ["Lens power needs a lensometer, not a pachymeter.", "Correct. A pachymeter measures corneal thickness.", "Lens diameter needs a gauge, not a pachymeter.", "Pupil size needs a pupillometer."]}'),
  ('c4eba6cf-12','{"options": ["Retinal detachment", "Refractive error", "Color blindness", "Corneal epithelial defects"], "correct": 3, "decode": "Fluorescein detects CORNEAL EPITHELIAL DEFECTS by pooling in breaks. It does not detect detachment, refractive error, or color blindness.", "ow": ["Detachment is intraocular, not a surface stain.", "Refractive error is optical, not stainable.", "Color blindness is tested with plates, not dye.", "Correct. Fluorescein detects corneal epithelial defects."]}'),
  ('92a7a99b-21','{"options": ["Aphakia", "Presbyopia", "Myopia", "Hyperopia"], "correct": 2, "decode": "Myopia is corrected with a MINUS (diverging) spherical lens. Hyperopia and aphakia need plus; presbyopia needs a near add.", "ow": ["Aphakia needs strong plus, not minus.", "Presbyopia needs a plus add, not minus.", "Correct. Myopia is corrected with a minus spherical lens.", "Hyperopia needs plus, not minus."]}'),
  ('661fa7ae-1j','{"options": ["Measures IOP", "Measures corneal curvature", "Decreases contrast", "Enhances fluorescein visibility"], "correct": 3, "decode": "A yellow barrier filter ENHANCES fluorescein visibility (blocks blue, passes green glow). It does not measure pressure or curvature.", "ow": ["It does not measure IOP.", "It does not measure corneal curvature.", "It increases, not decreases, contrast.", "Correct. The yellow barrier filter enhances fluorescein visibility."]}'),
  ('02f8f659-1y','{"options": ["Cover test", "Tonometry", "Keratometry", "Case history"], "correct": 3, "decode": "The patient''s account of present complaints is gathered through the case history. Cover test, tonometry, and keratometry are objective measurements.", "ow": ["The cover test checks alignment, not the history.", "Tonometry measures pressure, not the history.", "Keratometry measures the cornea, not the history.", "Correct. Case history captures the present visual complaints."]}'),
  ('84936f17-2f','{"options": ["Myopia", "Presbyopia", "Hyperopia", "Astigmatism"], "correct": 3, "decode": "Unequal refractive power in different meridians is astigmatism. Myopia, hyperopia, and presbyopia are single-power or age-related conditions.", "ow": ["Myopia is a uniform-power error.", "Presbyopia is age-related near-focus loss.", "Hyperopia is a uniform-power error.", "Correct. Unequal power across meridians is astigmatism."]}'),
  ('ef0fbd42-14','{"options": ["Estimate the spherical equivalent refractive error", "Determine the back vertex power of a lens", "Evaluate tear film and lens-cornea interaction", "Measure central corneal thickness in microns"], "correct": 2, "decode": "A fluorescein strip evaluates the tear film and how a lens sits against the cornea. It does not measure refraction, vertex power, or thickness.", "ow": ["Refractive estimates come from other tests, not the dye.", "Back vertex power needs a lensometer.", "Correct. The fluorescein strip evaluates tear film and lens-cornea interaction.", "Thickness needs a pachymeter, not the dye."]}'),
  ('8fce2b71-19','{"options": ["Stereoacuity", "Fine color discrimination", "Near point of convergence", "Visual field"], "correct": 1, "decode": "The Farnsworth-Munsell 100 Hue test grades FINE COLOR discrimination (arranging hue caps). It is not a stereo, convergence, or field test.", "ow": ["Stereoacuity uses stereo tests, not hue caps.", "Correct. The 100 Hue test grades fine color discrimination.", "NPC is a convergence measure, not color.", "The visual field is mapped by perimetry, not hue caps."]}'),
  ('d13c8070-1g','{"options": ["Corneal curvature", "Accommodation", "Visual fields", "Color vision"], "correct": 2, "decode": "Confrontation testing is a basic screen of the VISUAL FIELDS (comparing patient to examiner). It is not for curvature, accommodation, or color.", "ow": ["Curvature needs a keratometer, not confrontation.", "Accommodation is measured differently.", "Correct. Confrontation screens the visual fields.", "Color needs Ishihara, not confrontation."]}'),
  ('1bfe399f-18','{"options": ["Lens power", "Visual field", "Corneal thickness", "Visual acuity"], "correct": 1, "decode": "A perimeter measures the VISUAL FIELD. It is not for lens power, corneal thickness, or acuity.", "ow": ["Lens power needs a lensometer.", "Correct. A perimeter measures the visual field.", "Thickness needs a pachymeter.", "Acuity needs a chart, not a perimeter."]}'),
  ('2077ab38-16','{"options": ["Eyelids only", "Lens only", "Tear film only", "Peripheral visual field"], "correct": 3, "decode": "Perimetry maps the whole field, so it detects PERIPHERAL field defects (glaucoma, neuro disease). It is not a lid, lens, or tear-film test.", "ow": ["The lids are not part of field testing.", "The lens is not what perimetry maps.", "The tear film is not what perimetry maps.", "Correct. Perimetry detects peripheral field defects."]}'),
  ('d9fd5169-1q','{"options": ["Alter the eye''s refractive error during viewing", "Change the curvature of the corneal surface", "View ocular structures in greater detail", "Raise the intraocular pressure temporarily"], "correct": 2, "decode": "The slit lamp''s magnification lets the examiner VIEW ocular structures in greater detail. It does not alter refraction, reshape the cornea, or raise pressure.", "ow": ["Magnification does not change refraction.", "It does not reshape the cornea.", "Correct. Magnification reveals ocular detail.", "It does not raise IOP."]}'),
  ('045d8216-1j','{"options": ["Only the extraocular muscles and orbit", "Only the peripheral retina and optic disc", "The cornea, anterior chamber, and lens", "Only the lacrimal gland and drainage system"], "correct": 2, "decode": "The slit lamp examines the anterior segment together: the cornea, anterior chamber, and lens. The retina/disc need an ophthalmoscope; muscles, orbit, and lacrimal system are outside its view.", "ow": ["Muscles and orbit are outside the slit lamp''s view.", "The retina and disc need an ophthalmoscope.", "Correct. The slit lamp examines the cornea, anterior chamber, and lens.", "The lacrimal system is not the slit lamp''s target."]}'),
  ('c8afc8e7-u','{"options": ["Retinoscope", "Focimeter", "Biomicroscope", "Keratometer"], "correct": 2, "decode": "The slit lamp is also called a biomicroscope. Retinoscope, focimeter, and keratometer are different instruments.", "ow": ["A retinoscope measures refraction, not this.", "A focimeter reads lens power, not this.", "Correct. The slit lamp is a biomicroscope.", "A keratometer measures the cornea, not this."]}'),
  ('ab4c1d8f-28','{"options": ["Due to refractive error or optical factors", "Due to an inherited color-vision deficiency", "Due to advanced open-angle glaucoma damage", "Due to a rhegmatogenous retinal detachment"], "correct": 0, "decode": "The pinhole tells whether reduced acuity is DUE TO REFRACTIVE or optical factors (it clears optical blur). Color deficiency, glaucoma, and detachment do not improve with a pinhole.", "ow": ["Correct. The pinhole isolates refractive/optical causes.", "Color deficiency does not improve with a pinhole.", "Glaucoma damage does not improve with a pinhole.", "Detachment does not improve with a pinhole."]}'),
  ('b8d1917d-14','{"options": ["Polarization", "Chromatic aberration", "Spherical aberration", "Diffraction"], "correct": 1, "decode": "The duochrome test is based on CHROMATIC ABERRATION (red and green focus at different depths). Spherical aberration, diffraction, and polarization are not its basis.", "ow": ["Polarization is used in stereo tests, not duochrome.", "Correct. Duochrome relies on chromatic aberration.", "Spherical aberration is a different lens flaw.", "Diffraction is not the duochrome basis."]}'),
  ('bbf09095-1e','{"options": ["Black and white backgrounds", "Blue and yellow backgrounds", "Red and green backgrounds", "Red and blue backgrounds"], "correct": 2, "decode": "The duochrome shows RED and GREEN backgrounds and asks which is clearer. The other color pairs are not used.", "ow": ["Black and white are not the duochrome colors.", "Blue and yellow are not the duochrome colors.", "Correct. The duochrome uses red and green backgrounds.", "Red and blue are not the duochrome colors."]}'),
  ('519561ba-1x','{"options": ["The eyes can no longer accommodate on the target", "The patient can maintain binocular single vision", "The pupil constricts to a near light stimulus", "The retina first responds to a bright stimulus"], "correct": 1, "decode": "The NPC measures the closest point the patient can keep BINOCULAR SINGLE VISION before an eye breaks out. It is not about accommodation, pupils, or retinal response.", "ow": ["Accommodation is the NPA, not the NPC.", "Correct. NPC is the closest point of single binocular vision.", "Pupil constriction is a separate near-reflex component.", "Retinal response is not what NPC measures."]}'),
  ('6186c564-t','{"options": ["The patient''s refractive power", "The patient''s IOP", "The patient''s main reason for seeking care", "The examiner''s diagnosis"], "correct": 2, "decode": "The chief complaint is the patient''s own MAIN reason for seeking care. It is not the refraction, the pressure, or the examiner''s diagnosis.", "ow": ["Refractive power is a finding, not the complaint.", "IOP is a measurement, not the complaint.", "Correct. The chief complaint is the patient''s main reason for the visit.", "The diagnosis is the examiner''s conclusion, not the complaint."]}'),
  ('c943e929-2n','{"options": ["Amsler grid", "Schirmer", "Ishihara", "Maddox rod"], "correct": 0, "decode": "Central field and MACULA are assessed with the Amsler grid. Schirmer tests tears, Ishihara color, Maddox rod alignment.", "ow": ["Correct. The Amsler grid assesses central field and macula.", "The Schirmer test measures tears.", "Ishihara tests color.", "The Maddox rod checks alignment."]}'),
  ('09d1837f-1w','{"options": ["Case history, visual acuity, pupils, binocular/other screening tests, then ocular health screening", "Contact lens fitting and dispensing first, then surgery, and finally visual acuity", "Diagnostic surgery, then visual acuity measurement, followed by a brief case history", "Tonometry and minor surgery first, with the patient''s case history taken at the very end"], "correct": 0, "decode": "A logical prelim exam runs history first, then acuity, pupils, screening tests, and health screening (least to most invasive). Sequences starting with surgery or fitting are nonsense.", "ow": ["Correct. History, acuity, pupils, screening, then health screening.", "Fitting and surgery do not precede acuity.", "Surgery does not open a preliminary exam.", "History belongs first, not last."]}'),
  ('0cb79752-1c','{"options": ["Corneal curvature", "Visual acuity", "Binocular sensory fusion", "IOP"], "correct": 2, "decode": "The Worth 4 Dot assesses binocular sensory FUSION (and suppression). It is not for curvature, acuity, or pressure.", "ow": ["Curvature needs a keratometer.", "Acuity uses a chart, not Worth 4-dot.", "Correct. Worth 4-dot assesses binocular sensory fusion.", "Pressure needs a tonometer."]}'),
  ('c502f9cd-15','{"options": ["3", "6", "4", "2"], "correct": 2, "decode": "The Worth 4 Dot uses four lights (two green, one red, one white). Not two, three, or six.", "ow": ["Three is not the Worth-dot count.", "Six is not the Worth-dot count.", "Correct. The Worth 4 Dot uses four lights.", "Two is not the Worth-dot count."]}'),
  ('5ec3527c-s','{"options": ["Visual acuity only", "Color perception", "Contrast sensitivity only", "Depth perception"], "correct": 3, "decode": "A stereopsis test measures DEPTH perception (from binocular disparity). Not acuity, color, or contrast alone.", "ow": ["Acuity is a separate measure.", "Color is tested by Ishihara, not stereo.", "Contrast is a different function.", "Correct. Stereopsis measures depth perception."]}'),
  ('f786ce19-19','{"options": ["Red-green color deficiency", "Macular degeneration", "Binocular imbalance", "Glaucoma"], "correct": 0, "decode": "The Ishihara test detects RED-GREEN color deficiency. It is not for macula, binocularity, or glaucoma.", "ow": ["Correct. Ishihara detects red-green color deficiency.", "Macular disease uses the Amsler grid, not Ishihara.", "Binocular problems use Worth 4-dot, not Ishihara.", "Glaucoma is not screened by color plates."]}'),
  ('eb2913df-v','{"options": ["Contrast charts", "Visual acuity charts", "Stereo tests", "Pseudoisochromatic plates"], "correct": 3, "decode": "Ishihara plates are pseudoisochromatic plates (confusing color dots hiding a figure). They are not contrast, acuity, or stereo tests.", "ow": ["Not contrast charts.", "Not acuity charts.", "Not stereo tests.", "Correct. Ishihara plates are pseudoisochromatic plates."]}'),
  ('5199ef4b-21','{"options": ["The base-apex direction of an ophthalmic prism", "The exact location of the physiological blind spot", "Certain numbers or patterns on Ishihara plates", "Large high-contrast letters on a Snellen chart"], "correct": 2, "decode": "Red-green deficiency makes the hidden numbers or patterns on Ishihara plates hard to read. Prism direction, the blind spot, and Snellen letters are unaffected by color loss.", "ow": ["Prism direction is not a color task.", "The blind spot is a field landmark, not a color task.", "Correct. Color deficiency obscures Ishihara numbers or patterns.", "Black high-contrast letters do not depend on color."]}'),
  ('aa34996e-1g','{"options": ["Measure spectacle lens power", "Measure axial length", "Examine the anterior segment", "Measure blood pressure"], "correct": 2, "decode": "The principal use of the slit lamp biomicroscope is to EXAMINE THE ANTERIOR SEGMENT. It does not read lens power, axial length, or blood pressure.", "ow": ["Lens power needs a lensometer.", "Axial length needs biometry.", "Correct. The slit lamp examines the anterior segment.", "Blood pressure is unrelated to the slit lamp."]}'),
  ('2372c58b-1b','{"options": ["Binocular vision", "Tear production", "Visual acuity", "Color vision"], "correct": 1, "decode": "The Schirmer test evaluates TEAR PRODUCTION (paper strip wetting). Not binocularity, acuity, or color.", "ow": ["Binocular vision uses other tests.", "Correct. The Schirmer test evaluates tear production.", "Acuity uses a chart, not Schirmer.", "Color uses Ishihara, not Schirmer."]}'),
  ('c3368379-16','{"options": ["Corneal staining and tear film", "Accommodation", "Visual field only", "Color discrimination"], "correct": 0, "decode": "A fluorescein test evaluates CORNEAL STAINING and the tear film. It is not for accommodation, field, or color.", "ow": ["Correct. Fluorescein evaluates corneal staining and tear film.", "Accommodation is measured differently.", "The field is mapped by perimetry, not dye.", "Color is tested with plates, not dye."]}'),
  ('e067638a-10','{"options": ["Tear film stability", "Retinal function", "Color vision", "Visual acuity"], "correct": 0, "decode": "Tear breakup time (TBUT) evaluates tear film STABILITY (how long before dry spots). Not retinal function, color, or acuity.", "ow": ["Correct. TBUT evaluates tear film stability.", "Retinal function is unrelated to TBUT.", "Color is not what TBUT measures.", "Acuity is not what TBUT measures."]}'),
  ('3e07c534-1z','{"options": ["Media of the eye", "Lacrimal gland only", "Extraocular muscles only", "Eyelids only"], "correct": 0, "decode": "The red reflex test screens the MEDIA of the eye (cornea, lens, vitreous). An abnormal reflex means an opacity. It is not a lid, muscle, or gland test.", "ow": ["Correct. The red reflex screens the ocular media.", "The lacrimal gland is not what the reflex screens.", "The muscles are not what the reflex screens.", "The lids are not what the reflex screens."]}'),
  ('1959c060-1a','{"options": ["Accommodation", "Color vision", "Corneal curvature", "Pupillary light responses"], "correct": 3, "decode": "The swinging flashlight test assesses PUPILLARY LIGHT responses (looking for an RAPD). Not accommodation, color, or curvature.", "ow": ["Accommodation is measured differently.", "Color is tested with plates, not this test.", "Curvature needs a keratometer.", "Correct. The swinging flashlight test assesses pupillary light responses."]}'),
  ('b5528f25-19','{"options": ["Relative accommodative defect", "Corneal defect", "Binocular defect", "Relative afferent pupillary defect"], "correct": 3, "decode": "An afferent pupillary defect is the relative afferent pupillary defect (RAPD). Not accommodative, corneal, or binocular.", "ow": ["It is an afferent, not accommodative, defect.", "It is a pupil (afferent) sign, not a corneal defect.", "It is not a binocular defect.", "Correct. The afferent pupillary defect is the RAPD."]}'),
  ('f2524a01-18','{"options": ["Fluorescein only", "Infrared light only", "Air puff", "Ultrasound"], "correct": 2, "decode": "A non-contact tonometer measures IOP with an AIR PUFF (no touch). Not fluorescein, infrared, or ultrasound as the mechanism.", "ow": ["Fluorescein is used with contact (Goldmann) tonometry, not non-contact.", "Infrared is not the non-contact mechanism.", "Correct. The non-contact tonometer uses an air puff.", "Ultrasound is not the non-contact IOP method."]}'),
  ('95aa77c8-1e','{"options": ["Pupillary light reflex test", "The red-green duochrome balance test", "The Amsler central field grid test", "The Ishihara pseudoisochromatic plate test"], "correct": 0, "decode": "The pupil''s response to light is checked with the pupillary light reflex test. Duochrome, Amsler, and Ishihara test refraction, macula, and color.", "ow": ["Correct. The pupillary light reflex test checks light response.", "Duochrome is a refraction check, not a pupil test.", "The Amsler grid tests the macula, not the pupil.", "Ishihara tests color, not the pupil."]}'),
  ('4ea92b4b-28','{"options": ["Near response", "Direct response", "Consensual response", "Vestibular response"], "correct": 1, "decode": "Constriction of the SAME lit pupil is the direct response. The other eye''s constriction is consensual.", "ow": ["The near response is to a near target, not this.", "Correct. Same eye lit and constricting is the direct response.", "That is the consensual (opposite eye) response.", "The vestibular response is unrelated."]}'),
  ('3b4fb056-2c','{"options": ["Blink response", "Consensual response", "Accommodation response", "Direct response"], "correct": 1, "decode": "Constriction of the OPPOSITE pupil when one eye is lit is the consensual response. The lit eye''s own constriction is the direct response.", "ow": ["A blink is not a pupil light response.", "Correct. Opposite pupil constricting is the consensual response.", "Accommodation is a near response, not this.", "That is the direct (same eye) response."]}'),
  ('14de4a74-1t','{"options": ["Axial myopia in a young adult patient", "Relative afferent pupillary defect", "Regular corneal astigmatism at 90 degrees", "Age-related presbyopic focusing loss"], "correct": 1, "decode": "The swinging flashlight test best detects a relative afferent pupillary defect. Myopia, astigmatism, and presbyopia are refractive, not pupil, findings.", "ow": ["Myopia is refractive, not a pupil sign.", "Correct. The swinging flashlight test detects an RAPD.", "Astigmatism is refractive, not a pupil sign.", "Presbyopia is a focusing loss, not a pupil sign."]}'),
  ('4b917e07-28','{"options": ["Automated projection lensometer", "Ultrasound corneal pachymeter", "Ruler or measuring gauge", "Contact lens radiuscope unit"], "correct": 2, "decode": "The palpebral aperture (lid opening) is measured with a simple ruler or gauge. A lensometer, pachymeter, and radiuscope measure other things.", "ow": ["A lensometer reads lens power, not lid opening.", "A pachymeter measures corneal thickness, not lid opening.", "Correct. A ruler or gauge measures the palpebral aperture.", "A radiuscope measures contact lens curves, not lid opening."]}'),
  ('f5996114-1p','{"options": ["Snellen chart", "Maddox rod", "Ishihara test", "Amsler grid"], "correct": 0, "decode": "Distance visual acuity is measured with the Snellen chart. Maddox rod, Ishihara, and Amsler test alignment, color, and macula.", "ow": ["Correct. The Snellen chart measures distance acuity.", "The Maddox rod checks alignment, not acuity.", "Ishihara tests color, not acuity.", "The Amsler grid tests the macula, not acuity."]}'),
  ('026e8353-12','{"options": ["Cannot identify letters", "Has severe visual impairment", "Sees at 6 m what a normal observer sees at 6 m", "Sees at 6 m what a normal observer sees at 12 m"], "correct": 2, "decode": "6/6 means the patient sees at 6 m what a normal eye sees at 6 m, which is normal acuity. It is not impairment or 6/12.", "ow": ["6/6 patients can identify letters.", "6/6 is normal, not impaired.", "Correct. 6/6 means seeing at 6 m what a normal eye sees at 6 m.", "That would be 6/12, worse than normal."]}'),
  ('393c67e8-1p','{"options": ["Lensometer", "Keratometer", "Pachymeter", "Radiuscope"], "correct": 2, "decode": "Central corneal thickness is measured with a pachymeter (''pachy'' = thick). Not a lensometer, keratometer, or radiuscope.", "ow": ["A lensometer reads lens power.", "A keratometer measures curvature, not thickness.", "Correct. A pachymeter measures corneal thickness.", "A radiuscope measures contact lens curves."]}'),
  ('89531afc-1j','{"options": ["Pupillometer", "Lensometer", "Radiuscope", "Keratometer"], "correct": 0, "decode": "Pupil size is measured with a pupillometer. Not a lensometer, radiuscope, or keratometer.", "ow": ["Correct. A pupillometer measures pupil size.", "A lensometer reads lens power.", "A radiuscope measures contact lens curves.", "A keratometer measures the cornea."]}'),
  ('6ea8419a-13','{"options": ["Increased axial length", "Retinal detachment", "Loss of accommodative ability with age", "Excessive corneal curvature"], "correct": 2, "decode": "Presbyopia is the age-related LOSS of accommodation (lens stiffening). Not axial length, detachment, or corneal steepening.", "ow": ["Axial length change is myopia, not presbyopia.", "Detachment is a retinal emergency, not presbyopia.", "Correct. Presbyopia is age-related loss of accommodation.", "Corneal steepening is not presbyopia."]}'),
  ('fb0a727b-1t','{"options": ["Retinoscope", "Lensometer", "Keratometer", "Tonometer"], "correct": 1, "decode": "The optical power of an ophthalmic lens is measured with a lensometer. Not a retinoscope, keratometer, or tonometer.", "ow": ["A retinoscope measures the eye''s refraction, not a lens.", "Correct. A lensometer measures ophthalmic lens power.", "A keratometer measures the cornea.", "A tonometer measures pressure."]}'),
  ('eddca184-y','{"options": ["Examine the optic nerve directly", "Measure IOP", "Measure corneal thickness", "Determine refractive error objectively"], "correct": 3, "decode": "A retinoscope OBJECTIVELY determines refractive error. It is not for viewing the nerve, IOP, or corneal thickness.", "ow": ["The optic nerve is viewed with an ophthalmoscope.", "Pressure needs a tonometer.", "Thickness needs a pachymeter.", "Correct. A retinoscope objectively determines refractive error."]}'),
  ('d3e15802-1k','{"options": ["Ishihara test", "Cover test", "Schirmer test", "Snellen test"], "correct": 2, "decode": "Tear production with a paper strip is the Schirmer test. Ishihara, cover, and Snellen tests measure color, alignment, and acuity.", "ow": ["Ishihara tests color, not tears.", "The cover test checks alignment, not tears.", "Correct. The Schirmer test uses a paper strip for tear production.", "The Snellen test measures acuity, not tears."]}'),
  ('17e14377-m','{"options": ["Filter paper strips", "Fluorescent dye only", "Prism lenses", "Contact lenses"], "correct": 0, "decode": "The Schirmer test uses filter paper strips hooked over the lower lid to measure tear wetting. Not dye, prisms, or contact lenses.", "ow": ["Correct. The Schirmer test uses filter paper strips.", "Dye is used for staining, not the Schirmer measurement.", "Prisms are for alignment, not the Schirmer test.", "Contact lenses are unrelated to the Schirmer test."]}'),
  ('aa1d2a96-1e','{"options": ["Bright crimson red", "Bright yellow-green", "Deep sapphire blue", "A dull colorless gray"], "correct": 1, "decode": "Under cobalt-blue light, fluorescein fluoresces bright yellow-green. Not red, blue, or gray.", "ow": ["Fluorescein glows green, not red.", "Correct. Fluorescein appears bright yellow-green under blue light.", "The excitation is blue, but the glow is green.", "Fluorescein glows, it does not look gray."]}'),
  ('4743b6c3-1z','{"options": ["Retinoscope", "Slit lamp biomicroscope", "Lensometer", "Trial frame"], "correct": 1, "decode": "Magnified anterior-segment examination uses the slit lamp biomicroscope. Retinoscope, lensometer, and trial frame do other jobs.", "ow": ["A retinoscope measures refraction, not a magnified view.", "Correct. The slit lamp biomicroscope magnifies the anterior segment.", "A lensometer reads lens power.", "A trial frame holds lenses."]}'),
  ('ef1f8623-10','{"options": ["Minus spherical lens", "Minus cylinder only", "Plus spherical lens", "Prism only"], "correct": 2, "decode": "Hyperopia is corrected with a PLUS (converging) spherical lens. Minus is for myopia; cylinder is for astigmatism; prism is for alignment.", "ow": ["Minus corrects myopia, the opposite.", "Cylinder corrects astigmatism, not simple hyperopia.", "Correct. Plus spherical lenses correct hyperopia.", "Prism corrects alignment, not focus."]}'),
  ('fb472397-13','{"options": ["Spherical lens only", "Plano lens", "Cylindrical or toric lens", "Prism only"], "correct": 2, "decode": "Astigmatism needs a CYLINDRICAL or toric lens (meridian-specific power). A sphere, plano, or prism cannot correct it.", "ow": ["A sphere alone cannot fix meridional differences.", "A plano lens has no power to correct astigmatism.", "Correct. Cylindrical or toric lenses correct astigmatism.", "Prism corrects alignment, not astigmatism."]}'),
  ('f357dcf6-1l','{"options": ["Total irreversible blindness in that eye", "Complete destruction of the neural retina", "Refractive or optical cause of reduced acuity", "Advanced optic nerve atrophy and pallor"], "correct": 2, "decode": "Significant improvement with a pinhole means a refractive/optical cause (the pinhole cuts blur circles). Blindness, retinal destruction, and optic atrophy would not improve.", "ow": ["Total blindness does not improve with a pinhole.", "A destroyed retina does not improve with a pinhole.", "Correct. Pinhole improvement means a refractive or optical cause.", "Optic atrophy does not improve with a pinhole."]}'),
  ('3c3fc6f5-1k','{"options": ["Cover test", "Schirmer test", "Ishihara test", "Snellen test"], "correct": 2, "decode": "Color vision is tested with the Ishihara plates. Cover, Schirmer, and Snellen test alignment, tears, and acuity.", "ow": ["The cover test checks alignment, not color.", "The Schirmer test measures tears, not color.", "Correct. The Ishihara test evaluates color vision.", "The Snellen test measures acuity, not color."]}'),
  ('f002f7a5-16','{"options": ["Accommodation", "Corneal curvature", "IOP", "Visual fields"], "correct": 3, "decode": "Confrontation testing evaluates the VISUAL FIELDS. Not accommodation, curvature, or pressure.", "ow": ["Accommodation is measured differently.", "Curvature needs a keratometer.", "Pressure needs a tonometer.", "Correct. Confrontation evaluates the visual fields."]}'),
  ('fd531347-2b','{"options": ["With one eye closed only", "Without light", "Clearly", "Peripherally"], "correct": 2, "decode": "The near point of accommodation is the closest point an object is seen CLEARLY (limit of focusing). Not defined by one eye, darkness, or periphery.", "ow": ["It is a binocular or monocular focusing limit, but clarity is the criterion.", "Focusing needs light; clarity is the point.", "Correct. NPA is the closest point of clear focus.", "Peripheral vision is not the NPA criterion."]}'),
  ('409e141c-14','{"options": ["Amount of convergence", "Maximum pupil size", "Maximum accommodative ability", "Width of the visual field"], "correct": 2, "decode": "Amplitude of accommodation is the MAXIMUM accommodative ability (in diopters). Not convergence, pupil size, or field width.", "ow": ["Convergence is a vergence measure, not accommodation.", "Pupil size is unrelated to amplitude.", "Correct. Amplitude is the maximum accommodative ability.", "Field width is a perimetry measure, not amplitude."]}'),
  ('07f32ea6-1a','{"options": ["Color vision", "Amplitude of accommodation", "IOP", "Corneal curvature"], "correct": 1, "decode": "The push-up method measures amplitude of accommodation (bring target in until blur). Not color, IOP, or curvature.", "ow": ["Color is tested with plates, not push-up.", "Correct. The push-up method measures amplitude of accommodation.", "IOP needs a tonometer.", "Curvature needs a keratometer."]}'),
  ('ee28e002-1j','{"options": ["Detect colors", "Measure corneal thickness", "Change accommodation rapidly", "Detect peripheral objects"], "correct": 2, "decode": "The accommodative facility test measures the ability to CHANGE accommodation rapidly (flippers). Not color, thickness, or peripheral detection.", "ow": ["Color is a separate test.", "Thickness needs a pachymeter.", "Correct. Facility measures rapid accommodation change.", "Peripheral detection is a field measure."]}'),
  ('5231956b-16','{"options": ["Accommodative facility", "Visual field", "IOP", "Corneal diameter"], "correct": 0, "decode": "Flipper lenses assess accommodative FACILITY (speed of focus change). Not field, IOP, or corneal diameter.", "ow": ["Correct. Flippers assess accommodative facility.", "The field is mapped by perimetry.", "IOP needs a tonometer.", "Corneal diameter needs a gauge."]}'),
  ('98d09b19-20','{"options": ["Distance visual acuity on a letter chart", "Systemic arterial blood pressure only", "Retinal and choroidal circulation only", "Optical sections of ocular structures"], "correct": 3, "decode": "A narrow slit beam gives a thin OPTICAL SECTION, revealing depth layers of clear structures. Not for acuity, blood pressure, or retinal circulation.", "ow": ["Acuity uses a chart, not a slit beam.", "Blood pressure is unrelated to the slit lamp.", "Retinal circulation needs a fundus view, not a narrow anterior beam.", "Correct. A narrow beam gives optical sections of ocular structures."]}'),
  ('b0578506-22','{"options": ["Optical section", "Diffuse illumination only", "Sclerotic scatter only", "Retroillumination only"], "correct": 0, "decode": "Corneal layers are viewed with the OPTICAL SECTION technique (thin slit cross-section). Diffuse, sclerotic scatter, and retroillumination serve other purposes.", "ow": ["Correct. The optical section shows corneal layers.", "Diffuse light gives a broad overview, not layers.", "Sclerotic scatter lights up corneal defects, not layers directly.", "Retroillumination backlights opacities, not layers."]}'),
  ('b016bd0e-1m','{"options": ["Pupil diameter under dim illumination only", "Lens or corneal opacities against a bright background", "The vertical height of the palpebral fissure", "Small changes in the patient''s refractive error"], "correct": 1, "decode": "Retroillumination backlights the eye to show lens or corneal OPACITIES against a bright background. Not for pupil size, lid height, or refraction.", "ow": ["Pupil size is measured differently.", "Correct. Retroillumination reveals opacities against a bright background.", "Lid height is measured with a ruler, not retroillumination.", "Refraction is not assessed by retroillumination."]}'),
  ('8f39bb3d-1l','{"options": ["Refractive errors", "Corneal abnormalities", "Retinal detachment only", "Optic nerve disease only"], "correct": 1, "decode": "Sclerotic scatter pipes light through the cornea to reveal CORNEAL abnormalities that glow. Not refraction, retina, or optic nerve.", "ow": ["Refraction is not assessed by sclerotic scatter.", "Correct. Sclerotic scatter reveals corneal abnormalities.", "It targets the cornea, not the retina.", "It targets the cornea, not the optic nerve."]}'),
  ('db7a1cad-1m','{"options": ["Corneal staining and tear film", "Overall ocular axial length", "Back vertex power of the lens", "Posterior segment retinal thickness"], "correct": 0, "decode": "Fluorescein on the slit lamp evaluates corneal STAINING and the tear film. Not axial length, lens power, or retinal thickness.", "ow": ["Correct. Fluorescein evaluates corneal staining and tear film.", "Axial length needs biometry.", "Lens power needs a lensometer.", "Retinal thickness needs OCT, not fluorescein."]}'),
  ('b4593639-1e','{"options": ["Cataract", "Corneal ulcer", "Tropia", "Color deficiency"], "correct": 2, "decode": "The cover-uncover test detects a TROPIA (manifest deviation) by watching the covered eye move as it is uncovered. Not cataract, ulcer, or color.", "ow": ["Cataract is a lens opacity, not a cover-test finding.", "A corneal ulcer is a surface disease, not a cover-test finding.", "Correct. Cover-uncover detects a tropia.", "Color is tested with plates, not the cover test."]}'),
  ('0da3ed16-1h','{"options": ["Visual acuity", "Pupil size", "Total ocular deviation", "Corneal power"], "correct": 2, "decode": "The alternate cover test measures the TOTAL ocular deviation (phoria plus tropia). Not acuity, pupil size, or corneal power.", "ow": ["Acuity uses a chart, not the alternate cover.", "Pupil size is unrelated.", "Correct. The alternate cover test measures total deviation.", "Corneal power needs a keratometer."]}'),
  ('1744a623-t','{"options": ["Visual field", "Color vision", "Ocular alignment", "Tear production"], "correct": 2, "decode": "The Hirschberg test evaluates ocular ALIGNMENT from the corneal light reflex. Not field, color, or tears.", "ow": ["The field is mapped by perimetry.", "Color is tested with plates.", "Correct. Hirschberg evaluates ocular alignment.", "Tears need a Schirmer test."]}'),
  ('9a77fa90-k','{"options": ["Peripheral vision", "Depth perception", "Central acuity", "Color perception"], "correct": 1, "decode": "Stereopsis is DEPTH perception (from binocular disparity). Not peripheral, central acuity, or color.", "ow": ["Peripheral vision is a field function, not stereopsis.", "Correct. Stereopsis is depth perception.", "Central acuity is sharpness, not depth.", "Color perception is separate."]}'),
  ('d932b75d-1s','{"options": ["Distance vision only", "Color vision", "Peripheral vision only", "Convergence"], "correct": 3, "decode": "A receded (farther) near point of convergence indicates a CONVERGENCE difficulty. Not distance, color, or peripheral vision.", "ow": ["Distance vision is not what NPC measures.", "Color is unrelated to NPC.", "Peripheral vision is unrelated to NPC.", "Correct. A receded NPC indicates a convergence problem."]}'),
  ('7084c0ac-16','{"options": ["IOP", "Corneal thickness", "Ocular alignment", "Color vision"], "correct": 2, "decode": "The cover test assesses ocular ALIGNMENT (phorias and tropias). Not IOP, thickness, or color.", "ow": ["IOP needs a tonometer.", "Thickness needs a pachymeter.", "Correct. The cover test assesses ocular alignment.", "Color is tested with plates."]}'),
  ('f9edb375-1c','{"options": ["Accommodation amplitude", "Visual acuity", "Color deficiency", "Total deviation or phoria"], "correct": 3, "decode": "The alternate cover test measures TOTAL deviation or phoria (fully dissociated). Not accommodation, acuity, or color.", "ow": ["Accommodation amplitude is a separate measure.", "Acuity uses a chart.", "Color is tested with plates.", "Correct. The alternate cover test measures total deviation or phoria."]}'),
  ('ef3ba803-1c','{"options": ["Visual acuity", "Color blindness", "Corneal curvature", "Phoria"], "correct": 3, "decode": "The Maddox rod evaluates PHORIA by dissociating the eyes (a red streak vs a white light). Not acuity, color, or curvature.", "ow": ["Acuity uses a chart, not the Maddox rod.", "Color is tested with plates, not the Maddox rod.", "Curvature needs a keratometer.", "Correct. The Maddox rod evaluates phoria."]}'),
  ('35c2e6cb-1f','{"options": ["Triangle", "Circle", "Line", "Square"], "correct": 2, "decode": "The Maddox rod''s cylinders turn a point light into a LINE (streak). Not a triangle, circle, or square.", "ow": ["It makes a line, not a triangle.", "It makes a line, not a circle.", "Correct. The Maddox rod turns a point into a line.", "It makes a line, not a square."]}'),
  ('dc90e2c2-1b','{"options": ["Iris", "Cornea", "Optic nerve only", "Macula"], "correct": 3, "decode": "The Amsler grid assesses the MACULA (central 10 degrees). Not the iris, cornea, or optic nerve primarily.", "ow": ["The iris is not what the grid tests.", "The cornea is not what the grid tests.", "The optic nerve is not the grid''s primary target.", "Correct. The Amsler grid assesses the macula."]}'),
  ('1bd5c114-17','{"options": ["Improved color vision", "Increased IOP", "Improved accommodation", "Metamorphopsia"], "correct": 3, "decode": "On the Amsler grid a macular problem shows as METAMORPHOPSIA (wavy lines). Not improved color, higher pressure, or better focusing.", "ow": ["Vision distorts, it does not improve color.", "IOP is unrelated to the grid.", "Accommodation is unrelated to the grid.", "Correct. Amsler distortion is metamorphopsia."]}'),
  ('96294c26-1h','{"options": ["Detect differences in luminance", "Identify colors only", "Measure IOP", "Measure pupil size"], "correct": 0, "decode": "Contrast sensitivity measures the ability to detect DIFFERENCES IN LUMINANCE (faint light-dark). Not color, IOP, or pupil size.", "ow": ["Correct. Contrast sensitivity detects luminance differences.", "It is not a color-only test.", "IOP needs a tonometer.", "Pupil size is unrelated."]}'),
  ('00640e9c-19','{"options": ["The cornea is absent", "The patient has no retina", "The pupil is completely closed", "Visual acuity is relatively normal"], "correct": 3, "decode": "Contrast sensitivity can be reduced even when SNELLEN ACUITY IS NORMAL (early cataract, optic neuropathy). The other options describe impossible eyes.", "ow": ["An absent cornea is not a realistic scenario here.", "No retina is not a realistic scenario.", "A closed pupil is not a realistic scenario.", "Correct. Contrast loss can occur with relatively normal acuity."]}'),
  ('0767b7e2-2c','{"options": ["Extraocular muscles", "Tear glands", "Macula and central vision", "Eyelids"], "correct": 2, "decode": "The Amsler grid targets the MACULA and central vision. Not muscles, tear glands, or lids.", "ow": ["Muscles are tested by motility, not the grid.", "Tear glands are tested by Schirmer, not the grid.", "Correct. The Amsler grid tests the macula and central vision.", "Lids are not what the grid tests."]}'),
  ('f9474a65-14','{"options": ["Observing fluorescein", "Measuring IOP", "Measuring lens power", "Measuring axial length"], "correct": 0, "decode": "A Burton lamp (UV-blue with magnifier) is used for OBSERVING FLUORESCEIN. Not for pressure, lens power, or axial length.", "ow": ["Correct. The Burton lamp is used to observe fluorescein.", "IOP needs a tonometer.", "Lens power needs a lensometer.", "Axial length needs biometry."]}'),
  ('ee45785e-15','{"options": ["Tonometry", "Head stabilization", "Corneal illumination", "Magnification"], "correct": 1, "decode": "The forehead rest STABILIZES the head against the slit lamp. Not tonometry, illumination, or magnification.", "ow": ["Tonometry is a pressure measurement, not the rest''s job.", "Correct. The forehead rest provides head stabilization.", "Illumination comes from the lamp, not the rest.", "Magnification comes from the microscope, not the rest."]}'),
  ('b2ad0ccb-1c','{"options": ["Measure lens power", "Change the patient''s refractive error", "Move and position the instrument", "Change corneal curvature"], "correct": 2, "decode": "The joystick MOVES and positions the slit lamp. Not lens power, refraction, or corneal shape.", "ow": ["Lens power needs a lensometer.", "The joystick does not change refraction.", "Correct. The joystick moves and positions the instrument.", "It does not change corneal curvature."]}'),
  ('ccd34c23-1x','{"options": ["Cobalt-blue filter", "Infrared filter", "Neutral-density filter", "Red filter"], "correct": 0, "decode": "Fluorescein is observed with the COBALT-BLUE filter. Not infrared, neutral-density, or red.", "ow": ["Correct. The cobalt-blue filter shows fluorescein.", "Infrared is not used to excite fluorescein.", "Neutral-density only dims light.", "A red filter does not excite fluorescein."]}'),
  ('e7606de3-1k','{"options": ["Weight only", "Height and width", "Color only", "Temperature only"], "correct": 1, "decode": "The slit beam is adjustable in HEIGHT and WIDTH (its geometry). Not weight, color-only, or temperature.", "ow": ["Weight is not a beam parameter.", "Correct. The slit beam adjusts in height and width.", "Color filters exist, but the beam size is height and width.", "Temperature is not a beam parameter."]}'),
  ('a14b691e-1n','{"options": ["Precise measurement of ocular axial length", "Measurement of spectacle lens back power", "General examination of the anterior segment", "Isolated assessment of pupil light reaction"], "correct": 2, "decode": "A broad beam floods the anterior segment for a GENERAL examination. Not axial length, lens power, or isolated pupil testing.", "ow": ["Axial length needs biometry.", "Lens power needs a lensometer.", "Correct. A broad beam gives a general anterior-segment exam.", "Pupil light reaction is a separate test."]}'),
  ('8a04e088-18','{"options": ["Normal ocular alignment", "Media opacity", "Normal accommodation", "Normal color vision"], "correct": 1, "decode": "An abnormal or absent red reflex suggests a MEDIA OPACITY (cataract, corneal opacity). The ''normal'' options do not dull the reflex.", "ow": ["Normal alignment does not dull the reflex.", "Correct. An absent red reflex suggests a media opacity.", "Normal accommodation does not dull the reflex.", "Normal color vision does not dull the reflex."]}'),
  ('8fae36fe-16','{"options": ["Retinoscope", "Pupillometer", "Tonometer", "Keratometer"], "correct": 1, "decode": "Pupillary distance is measured with a pupillometer (or PD ruler). Not a retinoscope, tonometer, or keratometer.", "ow": ["A retinoscope measures refraction, not PD.", "Correct. A pupillometer measures pupillary distance.", "A tonometer measures pressure, not PD.", "A keratometer measures the cornea, not PD."]}'),
  ('611b8fa3-1j','{"options": ["Ishihara plates", "Amsler grid only", "Maddox rod", "Near vision chart"], "correct": 3, "decode": "Near acuity is tested with a NEAR VISION chart at reading distance. Ishihara, Amsler, and Maddox test color, macula, and alignment.", "ow": ["Ishihara tests color, not near acuity.", "The Amsler grid tests the macula, not acuity.", "The Maddox rod checks alignment, not acuity.", "Correct. Near acuity uses a near vision chart."]}'),
  ('65b3e6d5-2f','{"options": ["Ishihara pseudoisochromatic color plates at the near point only", "Counting fingers, hand motion, or light perception as appropriate", "A red-green duochrome balancing test at six meters only", "Central and peripheral corneal keratometry readings only"], "correct": 1, "decode": "Below the largest chart letter, step down to counting fingers, hand motion, then light perception. Ishihara, duochrome, and keratometry are not acuity fallbacks.", "ow": ["Color plates are not an acuity fallback.", "Correct. Use CF, HM, LP as appropriate for very low vision.", "Duochrome is a refraction check, not an acuity fallback.", "Keratometry measures the cornea, not low-vision acuity."]}'),
  ('d852ac34-1q','{"options": ["The chief complaint, symptom duration, and prior ocular history", "Only the intraocular pressure measured at this visit", "Only the examiner''s provisional working diagnosis and plan", "Only the objective autorefractor refraction printout"], "correct": 0, "decode": "A good case history covers the chief complaint, symptom duration, and prior ocular history together. The single ''only'' options miss most of the history.", "ow": ["Correct. History includes complaint, duration, and prior ocular history.", "IOP alone is a measurement, not the full history.", "The examiner''s diagnosis is a conclusion, not the history.", "An autorefractor printout is a finding, not the history."]}'),
  ('9dbad8cf-2n','{"options": ["Lensometer", "Pupillometer", "Slit lamp biomicroscope", "Radiuscope"], "correct": 2, "decode": "The corneal surface and anterior chamber are examined under magnification with the slit lamp biomicroscope. Not a lensometer, pupillometer, or radiuscope.", "ow": ["A lensometer reads lens power.", "A pupillometer measures pupil size.", "Correct. The slit lamp examines the cornea and anterior chamber magnified.", "A radiuscope measures contact lens curves."]}'),
  ('c0c62645-1i','{"options": ["Objectively measure the eye''s refractive error", "Examine ocular structures under magnification", "Measure the overall axial length of the eye", "Record the patient''s systemic blood pressure"], "correct": 1, "decode": "The primary purpose of the slit lamp biomicroscope is to EXAMINE ocular structures under magnification. Not refraction, axial length, or blood pressure.", "ow": ["Refraction is measured by a retinoscope/autorefractor.", "Correct. The slit lamp examines ocular structures magnified.", "Axial length needs biometry.", "Blood pressure is unrelated."]}'),
  ('d0d9ab81-z','{"options": ["Ultrasound and infrared radiation", "X-rays and magnification", "Magnification and focused illumination", "Tonometry and retinoscopy"], "correct": 2, "decode": "The slit lamp combines MAGNIFICATION and focused ILLUMINATION. Not ultrasound, X-rays, or tonometry/retinoscopy.", "ow": ["Ultrasound and infrared are not the slit lamp''s principle.", "X-rays are not used in a slit lamp.", "Correct. The slit lamp uses magnification plus focused illumination.", "Tonometry and retinoscopy are separate procedures."]}'),
  ('da5cbeb1-1s','{"options": ["Illumination system", "Joystick", "Microscope", "Chin rest"], "correct": 0, "decode": "The ILLUMINATION SYSTEM produces the slit beam. The joystick, microscope, and chin rest do other jobs.", "ow": ["Correct. The illumination system produces the slit beam.", "The joystick positions the instrument.", "The microscope magnifies, it does not make the beam.", "The chin rest stabilizes the head."]}'),
  ('340cdd14-12','{"options": ["Measurement of IOP only", "Measurement of corneal curvature", "Magnified viewing of the eye", "Illumination only"], "correct": 2, "decode": "The microscope of the slit lamp provides MAGNIFIED viewing of the eye. Not IOP, curvature, or illumination.", "ow": ["IOP needs a tonometer, not the microscope.", "Curvature needs a keratometer.", "Correct. The microscope gives magnified viewing.", "Illumination comes from the lamp, not the microscope."]}'),
  ('d984fe8e-13','{"options": ["Stabilize the patient''s head", "Measure corneal thickness", "Measure visual acuity", "Adjust illumination"], "correct": 0, "decode": "The chin rest STABILIZES the patient''s head. Not thickness, acuity, or illumination.", "ow": ["Correct. The chin rest stabilizes the head.", "Thickness needs a pachymeter.", "Acuity uses a chart.", "Illumination comes from the lamp."]}'),
  ('384f6c58-1p','{"options": ["Perform minor ocular surgery before any other diagnostic testing is done", "Immediately prescribe and dispense contact lenses to the patient", "Measure only the intraocular pressure during the first visit encounter", "Establish baseline information about the patient''s visual and ocular status"], "correct": 3, "decode": "Preliminary testing exists to ESTABLISH BASELINE information about the patient''s visual and ocular status. Not surgery, immediate lenses, or IOP alone.", "ow": ["Surgery is not a preliminary-test purpose.", "Immediate dispensing is not the purpose.", "IOP alone is one test, not the whole baseline.", "Correct. Prelim testing establishes a baseline picture."]}'),
  ('c8112f2a-1q','{"options": ["Snellen test", "Maddox rod", "Amsler test", "Schirmer test"], "correct": 0, "decode": "Acuity is usually assessed first with the Snellen test. Maddox rod, Amsler, and Schirmer test alignment, macula, and tears.", "ow": ["Correct. The Snellen test is the first acuity check.", "The Maddox rod checks alignment, not acuity.", "The Amsler grid tests the macula, not acuity.", "The Schirmer test measures tears, not acuity."]}'),
  ('1a77f2b0-11','{"options": ["6/6 or 20/20", "Prism diopters", "mmHg", "Diopters"], "correct": 0, "decode": "Visual acuity is recorded as a fraction like 6/6 or 20/20. Not in prism diopters, mmHg, or diopters.", "ow": ["Correct. Acuity is recorded as 6/6 or 20/20.", "Prism diopters measure deviation, not acuity.", "mmHg measures pressure, not acuity.", "Diopters measure lens power, not acuity."]}'),
  ('45ce67a0-15','{"options": ["Applanation tonometry", "Central corneal keratometry", "Unaided visual acuity test", "Ultrasound pachymetry"], "correct": 2, "decode": "Unaided (no correction) acuity is measured with the unaided visual acuity test. Tonometry, keratometry, and pachymetry measure other things.", "ow": ["Tonometry measures pressure, not acuity.", "Keratometry measures the cornea, not acuity.", "Correct. The unaided acuity test measures vision without correction.", "Pachymetry measures thickness, not acuity."]}'),
  ('cdc12969-2j','{"options": ["Changing pupil color", "Correcting refractive error", "Increasing IOP", "Increasing illumination"], "correct": 1, "decode": "The pinhole shows whether acuity would improve by CORRECTING REFRACTIVE ERROR (it removes optical blur). Not pupil color, IOP, or illumination.", "ow": ["Pupil color is irrelevant to the pinhole.", "Correct. The pinhole isolates improvement from correcting refractive error.", "IOP is unrelated to the pinhole.", "The pinhole reduces light; it does not work by adding illumination."]}'),
  ('589f6022-16','{"options": ["Objective refractive error", "Tear production", "IOP", "Color vision"], "correct": 0, "decode": "Retinoscopy determines OBJECTIVE refractive error (no patient response needed). Not tears, IOP, or color.", "ow": ["Correct. Retinoscopy determines objective refractive error.", "Tears need a Schirmer test.", "IOP needs a tonometer.", "Color needs Ishihara."]}'),
  ('d206e65f-18','{"options": ["Tear meniscus only", "Corneal thickness", "Retinal reflex", "Pupil diameter only"], "correct": 2, "decode": "During retinoscopy the examiner watches the RETINAL REFLEX move in the pupil. Not the tear meniscus, corneal thickness, or pupil diameter alone.", "ow": ["The tear meniscus is a dry-eye sign, not the retinoscopy target.", "Corneal thickness needs a pachymeter.", "Correct. The examiner observes the retinal reflex.", "Pupil diameter alone is not the retinoscopy observation."]}'),
  ('6e9bc658-13','{"options": ["Lensometer", "Direct ophthalmoscope", "Keratometer", "Pupillometer"], "correct": 1, "decode": "The red reflex is evaluated with a direct ophthalmoscope held at arm''s length. Not a lensometer, keratometer, or pupillometer.", "ow": ["A lensometer reads lens power, not the reflex.", "Correct. The direct ophthalmoscope reveals the red reflex.", "A keratometer measures the cornea, not the reflex.", "A pupillometer measures pupil size, not the reflex."]}'),
  ('effdb5ce-24','{"options": ["Keratometer", "Tonometer", "Corneal measuring gauge", "Lensometer"], "correct": 2, "decode": "The horizontal visible iris diameter (HVID) is measured with a corneal measuring gauge (a millimeter reticule). Not a keratometer, tonometer, or lensometer.", "ow": ["A keratometer measures curvature, not diameter.", "A tonometer measures pressure.", "Correct. A corneal measuring gauge measures HVID.", "A lensometer reads lens power."]}'),
  ('5beec780-1b','{"options": ["Visual acuity", "Color vision", "Ocular alignment", "Contrast sensitivity"], "correct": 2, "decode": "The Hirschberg test assesses ocular ALIGNMENT from the corneal reflex. Not acuity, color, or contrast.", "ow": ["Acuity uses a chart, not Hirschberg.", "Color is tested with plates.", "Correct. Hirschberg assesses ocular alignment.", "Contrast sensitivity is a separate test."]}'),
  ('3ff5d92a-11','{"options": ["Media opacity", "Phoria", "Color deficiency", "Accommodation problems"], "correct": 0, "decode": "The red reflex test helps identify a MEDIA OPACITY (cataract, corneal opacity). Not phoria, color deficiency, or accommodation.", "ow": ["Correct. The red reflex test identifies media opacity.", "Phoria is assessed by cover/Maddox tests.", "Color deficiency uses Ishihara.", "Accommodation is measured differently."]}'),
  ('fb9a80c5-1t','{"options": ["Color vision using pseudoisochromatic plates", "Lens centration and corneal staining", "Systemic blood pressure and pulse rate", "Overall spectacle frame and temple size"], "correct": 1, "decode": "A slit lamp with fluorescein assesses lens centration and corneal STAINING. Not color, blood pressure, or frame size.", "ow": ["Color uses pseudoisochromatic plates, not fluorescein.", "Correct. Slit lamp plus fluorescein assesses centration and corneal staining.", "Blood pressure is unrelated.", "Frame size is a dispensing measurement."]}'),
  ('8a09a98f-1m','{"options": ["Radiuscope", "Lensometer", "Slit lamp", "Retinoscope"], "correct": 2, "decode": "Tear film STABILITY is assessed on the slit lamp (watching fluorescein breakup). Not a radiuscope, lensometer, or retinoscope.", "ow": ["A radiuscope measures contact lens curves.", "A lensometer reads lens power.", "Correct. The slit lamp assesses tear film stability.", "A retinoscope measures refraction."]}'),
  ('9878208b-19','{"options": ["Trial frame", "Fluorescein and slit lamp", "Keratometer alone", "Lensometer"], "correct": 1, "decode": "Tear breakup time is evaluated with fluorescein on the slit lamp (time to first dry spot). Not a trial frame, keratometer alone, or lensometer.", "ow": ["A trial frame holds lenses, not tears.", "Correct. TBUT uses fluorescein and the slit lamp.", "A keratometer alone cannot time film breakup.", "A lensometer reads lens power."]}'),
  ('7c2b5db9-u','{"options": ["Corneal thickness", "Binocular sensory status", "IOP", "Visual acuity only"], "correct": 1, "decode": "The Worth 4 Dot evaluates binocular sensory STATUS (fusion vs suppression). Not thickness, IOP, or acuity.", "ow": ["Thickness needs a pachymeter.", "Correct. Worth 4-dot evaluates binocular sensory status.", "IOP needs a tonometer.", "Acuity uses a chart."]}'),
  ('e9afcefc-w','{"options": ["Orange and violet fields", "Red and green fields", "Blue and yellow fields", "Black and white fields"], "correct": 1, "decode": "The duochrome uses RED and GREEN fields (chromatic aberration). Not orange/violet, blue/yellow, or black/white.", "ow": ["Orange and violet are not the duochrome colors.", "Correct. The duochrome uses red and green fields.", "Blue and yellow are not the duochrome colors.", "Black and white are not the duochrome colors."]}'),
  ('57a00ae0-19','{"options": ["Corneal curvature", "Macular function", "Ocular alignment", "IOP"], "correct": 1, "decode": "The Amsler grid evaluates MACULAR function (central distortion). Not curvature, alignment, or IOP.", "ow": ["Curvature needs a keratometer.", "Correct. The Amsler grid evaluates macular function.", "Alignment is assessed by cover tests.", "IOP needs a tonometer."]}'),
  ('98066f85-1l','{"options": ["Diplopia", "Scotoma", "Metamorphopsia", "Photophobia"], "correct": 2, "decode": "Distortion of straight lines on the Amsler grid is metamorphopsia (''morph'' = shape). Not diplopia, scotoma, or photophobia.", "ow": ["Diplopia is double vision, not distortion.", "A scotoma is a missing patch, not distortion.", "Correct. Wavy-line distortion is metamorphopsia.", "Photophobia is light sensitivity, not distortion."]}'),
  ('1ca2affc-v','{"options": ["Detect brightness only", "Detect eye pressure", "Resolve fine spatial detail", "Measure accommodation"], "correct": 2, "decode": "Visual acuity is the ability to RESOLVE FINE SPATIAL DETAIL. Not brightness, pressure, or accommodation.", "ow": ["Brightness detection is not acuity.", "Pressure is measured by tonometry.", "Correct. Acuity is resolving fine spatial detail.", "Accommodation is a separate function."]}'),
  ('694c568d-2c','{"options": ["Pupillometer", "Lensometer", "Keratometer", "Slit lamp"], "correct": 3, "decode": "Detailed examination of the cornea and anterior segment is best with the slit lamp. Not a pupillometer, lensometer, or keratometer.", "ow": ["A pupillometer measures pupil size only.", "A lensometer reads lens power.", "A keratometer measures curvature, not a detailed view.", "Correct. The slit lamp is best for the cornea and anterior segment."]}'),
  ('8582a679-2k','{"options": ["Huygens", "Einstein", "Planck", "Newton"], "correct": 0, "decode": "Huygens'' WAVE theory correctly predicted light SLOWS in a denser medium.", "ow": ["Correct. Huygens'' wave model rightly had light slowing in dense media.", "Einstein explained the photoelectric effect, not this prediction.", "Planck founded quantum theory, not the dense-medium speed prediction.", "Newton''s corpuscular theory wrongly predicted light speeds up in dense media."]}'),
  ('3787ce77-1i','{"options": ["Huygens, Newton, Einstein, Bohr", "Maxwell, Planck, Newton, Huygens", "Newton, Huygens, Maxwell, Planck", "Planck, Einstein, Newton, Maxwell"], "correct": 2, "decode": "Light theories in order (NHMP): Newton (corpuscular) → Huygens (wave) → Maxwell (electromagnetic) → Planck (quantum).", "ow": ["Bohr is out of place; the sequence ends with Planck''s quantum theory.", "This ordering scrambles the historical sequence.", "Correct. Newton, Huygens, Maxwell, Planck.", "This ordering scrambles the historical sequence."]}'),
  ('eaf956fc-z','{"options": ["n₁/n₂ = sin R/sin i", "n₁ sin i = n₂ sin R", "n₁ cos i = n₂ cos R", "i = R"], "correct": 1, "decode": "Snell''s law: n₁ sin i = n₂ sin R.", "ow": ["This inverts the index-angle pairing.", "Correct. n₁ sin i = n₂ sin R.", "Snell''s law uses sines, not cosines.", "i = R only when the indices are equal, not in general."]}'),
  ('892c5949-1i','{"options": ["v = n/c", "v = c/n", "v = c + n", "v = c × n"], "correct": 1, "decode": "v = c/n: a higher index means slower light.", "ow": ["v = n/c inverts the relationship.", "Correct. v = c/n.", "v = c + n is dimensionally meaningless.", "v = c × n would make light faster in dense media, which is wrong."]}'),
  ('4d54bed3-1q','{"options": ["Zero", "Positive", "Negative", "Undefined"], "correct": 2, "decode": "Diverging light carries NEGATIVE vergence; converging is positive.", "ow": ["Zero vergence is parallel light, not diverging.", "Positive vergence is converging light.", "Correct. Diverging light has negative vergence.", "Vergence is defined for a point source, so it is not undefined."]}'),
  ('fe03eff4-1c','{"options": ["Increases", "Stays the same", "Doubles", "Decreases"], "correct": 3, "decode": "Higher index → LOWER critical angle (diamond ~24.44°).", "ow": ["The critical angle falls, not rises, with index.", "It changes with index, so it does not stay the same.", "It does not simply double.", "Correct. Higher index gives a lower critical angle."]}'),
  ('42c37c4b-1o','{"options": ["Is less than the critical angle", "Equals the refractive index", "Exceeds the critical angle", "Equals zero"], "correct": 2, "decode": "TIR occurs when incidence EXCEEDS the critical angle (dense to rare).", "ow": ["Below the critical angle light still refracts out.", "Incidence is an angle, not compared to the index.", "Correct. Incidence beyond the critical angle gives total internal reflection.", "At zero incidence light passes straight through."]}'),
  ('ba7fedcb-1y','{"options": ["n = 1.5; D = 500/r", "n = 1.376; D = 337.5/r", "n = 1.336; D = 1000/r", "n = 1.3375; D = 337.5/r"], "correct": 3, "decode": "Keratometry uses the keratometric index 1.3375 in D = 337.5/r.", "ow": ["n = 1.5 and 500/r are not the keratometric convention.", "1.376 is the true corneal index, not the keratometric one.", "1.336 with 1000/r is not the keratometry formula.", "Correct. D = 337.5/r with n = 1.3375."]}'),
  ('0facd5d9-23','{"options": ["One-half", "Two-thirds", "All of it", "One-third"], "correct": 1, "decode": "The cornea (~43 D) supplies about TWO-THIRDS of the eye''s total power.", "ow": ["Half understates the corneal contribution.", "Correct. The cornea supplies about two-thirds.", "The cornea is not all of the eye''s power; the lens adds ~19 D.", "One-third understates the corneal share."]}'),
  ('bfd04793-2c','{"options": ["60 D vs 58.64 D", "43 D vs 60 D", "58.64 D vs 60 D", "58.64 D vs 58.64 D"], "correct": 2, "decode": "Gullstrand''s exact eye = 58.64 D; the reduced (Emsley) eye = 60 D.", "ow": ["60 vs 58.64 reverses the two values.", "43 D is the cornea alone, not a whole-eye total.", "Correct. 58.64 D (exact) vs 60 D (reduced).", "The two eyes differ, so identical values are wrong."]}'),
  ('503b1a70-19','{"options": ["They are unrelated", "Higher index → lower Abbe → more chromatic aberration", "Higher index → higher Abbe → less chromatic aberration", "Both increase together"], "correct": 1, "decode": "Higher index → LOWER Abbe → MORE chromatic aberration.", "ow": ["Index and Abbe are related, not unrelated.", "Correct. Higher index means lower Abbe and more chromatic aberration.", "Higher index lowers Abbe, so this is reversed.", "They move oppositely, not together."]}'),
  ('829f9cee-1e','{"options": ["Infrared", "UV-C only", "UV-A", "UV-B"], "correct": 3, "decode": "UV-B causes photokeratitis (''welder''s flash''); UV-A links to cataract.", "ow": ["Infrared causes thermal, not photochemical keratitis.", "UV-C is largely absorbed by the atmosphere and is not the classic cause.", "UV-A penetrates deeper and links to cataract, not photokeratitis.", "Correct. UV-B causes photokeratitis."]}'),
  ('5a0392a6-1q','{"options": ["Permanent", "Limited to the lens", "Reversible", "Always milder"], "correct": 0, "decode": "Thermal radiation injury is PERMANENT; photochemical injury is often reversible.", "ow": ["Correct. Thermal damage is permanent.", "Thermal injury is not limited to the lens.", "Thermal damage is permanent, not reversible.", "Thermal injury is often more severe, not milder."]}'),
  ('029e6b62-13','{"options": ["S − C", "−C", "S + C", "S only"], "correct": 2, "decode": "Flat transposition: new sphere = S + C.", "ow": ["S − C is not the transposed sphere.", "−C is the new cylinder, not the sphere.", "Correct. New sphere = S + C.", "S alone ignores adding the cylinder."]}'),
  ('69518075-1h','{"options": ["1.336", "1.376", "1.406", "1.523"], "correct": 1, "decode": "The cornea''s refractive index (Gullstrand) is 1.376.", "ow": ["1.336 is aqueous and vitreous.", "Correct. The cornea is 1.376.", "1.406 is the lens nucleus.", "1.523 is spectacle crown glass, not cornea."]}'),
  ('a036f355-1n','{"options": ["1.000", "1.336", "1.376", "1.406"], "correct": 1, "decode": "Aqueous and vitreous share n = 1.336.", "ow": ["1.000 is air.", "Correct. Aqueous and vitreous are both 1.336.", "1.376 is the cornea.", "1.406 is the lens nucleus."]}'),
  ('24f53eca-1j','{"options": ["It has no measurable curvature", "Index drops across a convex surface", "It is concave toward the front", "It is completely avascular"], "correct": 1, "decode": "At the posterior cornea the index DROPS across a forward-convex surface, so it diverges (minus).", "ow": ["It does have curvature; that is not the reason.", "Correct. Index falls at a convex surface, giving minus power.", "It is convex toward the front, not concave.", "Being avascular does not set its optical sign."]}'),
  ('9ed49d81-1h','{"options": ["10 D", "19 D", "43 D", "58 D"], "correct": 1, "decode": "The unaccommodated lens contributes about 19 D.", "ow": ["10 D understates the lens power.", "Correct. The lens adds ~19 D unaccommodated.", "43 D is the cornea.", "58 D is roughly the whole eye."]}'),
  ('2816dff9-1z','{"options": ["7.08 mm", "13.5 mm", "17 mm", "24 mm"], "correct": 0, "decode": "The primary nodal point sits ~7.08 mm behind the cornea (not the 13.5 mm center of rotation).", "ow": ["Correct. The primary nodal point is ~7.08 mm behind the cornea.", "13.5 mm is the center of rotation.", "17 mm is roughly the reduced-eye principal-plane-to-retina distance, not the nodal point.", "24 mm is the axial length."]}'),
  ('85157336-19','{"options": ["18 mm", "21 mm", "24 mm", "30 mm"], "correct": 2, "decode": "The emmetropic axial length is about 24 mm.", "ow": ["18 mm is microphthalmic-short.", "21 mm is short.", "Correct. Axial length is ~24 mm.", "30 mm is high-myopia long."]}'),
  ('8e7f4b3c-1o','{"options": ["D = f × 100", "D = 1/f", "D = f/100", "D = 100/f"], "correct": 3, "decode": "Vergence in diopters: D = 100/f when f is in centimeters.", "ow": ["D = f × 100 inverts the relationship.", "D = 1/f applies when f is in meters, not centimeters.", "D = f/100 inverts it.", "Correct. D = 100/f (cm)."]}'),
  ('17a303a0-1w','{"options": ["Chromatic aberration", "Astigmatism", "Spherical aberration only", "No aberration"], "correct": 0, "decode": "High-index materials have low Abbe, so more CHROMATIC aberration.", "ow": ["Correct. High index yields more chromatic aberration.", "Astigmatism is a design/toric issue, not an index effect.", "It is chromatic, not only spherical, aberration that rises.", "There is aberration, so ''no aberration'' is wrong."]}'),
  ('be76d499-14','{"options": ["200–400 nm", "400–700 nm", "700–1000 nm", "100–200 nm"], "correct": 1, "decode": "Visible light spans about 400–700 nm.", "ow": ["200–400 nm is ultraviolet.", "Correct. Visible light is ~400–700 nm.", "700–1000 nm is infrared.", "100–200 nm is far UV."]}'),
  ('8bd716a5-k','{"options": ["Infrared", "All UV below 400 nm", "Only UV-C", "Only visible light"], "correct": 1, "decode": "''UV 400'' blocks all UV below 400 nm.", "ow": ["Infrared is not the target of UV 400.", "Correct. UV 400 blocks all UV below 400 nm.", "It blocks all UV, not only UV-C.", "It does not block visible light."]}'),
  ('5ba0e06b-1o','{"options": ["6.8 mm", "7.7 mm", "10 mm", "13.5 mm"], "correct": 1, "decode": "The anterior corneal radius (Gullstrand) is about 7.7 mm.", "ow": ["6.8 mm is the posterior cornea.", "Correct. The anterior cornea is ~7.7 mm.", "10 mm is too flat for the cornea.", "13.5 mm is the center of rotation."]}'),
  ('beeeab40-16','{"options": ["Real, inverted, same size", "Real, upright, magnified", "Virtual, upright, same size", "Virtual, upright, minified"], "correct": 2, "decode": "A plane mirror gives a VIRTUAL, UPRIGHT, SAME-SIZE image.", "ow": ["A plane mirror image is virtual and upright, not real/inverted.", "It is same size, not magnified.", "Correct. Virtual, upright, same size.", "It is same size, not minified."]}'),
  ('d75582b6-1y','{"options": ["Real, magnified", "Virtual, magnified", "Virtual, upright, minified", "Real, inverted"], "correct": 2, "decode": "A convex mirror always gives a VIRTUAL, UPRIGHT, MINIFIED image.", "ow": ["It is not real/magnified.", "It is minified, not magnified.", "Correct. Convex mirrors always give virtual, upright, minified images.", "It is virtual, not real/inverted."]}'),
  ('20d596cf-13','{"options": ["Positive", "Zero", "Negative", "Infinite"], "correct": 0, "decode": "A concave mirror converges, so its focal length is POSITIVE.", "ow": ["Correct. Concave mirror f is positive.", "It is not zero.", "Negative f is a convex mirror.", "It is finite, not infinite."]}'),
  ('5949cc39-1p','{"options": ["A virtual image", "No image", "A real image", "An inverted image"], "correct": 0, "decode": "A negative image distance q means a VIRTUAL image.", "ow": ["Correct. Negative q means a virtual image.", "There is an image, just a virtual one.", "Positive q is a real image.", "Sign of q indicates real/virtual, not orientation."]}'),
  ('8e370ddd-1d','{"options": ["Inverted", "Upright", "Minified", "Virtual"], "correct": 0, "decode": "Negative magnification m means an INVERTED image.", "ow": ["Correct. Negative m means inverted.", "Positive m is upright.", "Magnitude gives size; sign gives orientation.", "Sign of m gives orientation, not real/virtual."]}'),
  ('baf47f8c-1p','{"options": ["Virtual, magnified", "Real, inverted, magnified", "Virtual, upright, minified", "Real, upright"], "correct": 2, "decode": "A concave (minus) lens always gives a VIRTUAL, UPRIGHT, MINIFIED image.", "ow": ["It is minified, not magnified.", "A minus lens never gives a real magnified image of a real object.", "Correct. Minus lens: always virtual, upright, minified.", "It is virtual, not real."]}'),
  ('3106989a-1q','{"options": ["No image at all", "A virtual, magnified image", "A real, minified image", "A real, inverted image"], "correct": 1, "decode": "A plus lens with the object INSIDE F gives a VIRTUAL, MAGNIFIED image (a simple magnifier).", "ow": ["An image does form, just a virtual one.", "Correct. Object inside F gives a virtual, magnified image.", "It is virtual and magnified, not real/minified.", "It is virtual, not real/inverted."]}'),
  ('ce8e7ffe-1y','{"options": ["base; base", "apex; apex", "apex; base", "base; apex"], "correct": 3, "decode": "Light bends toward the BASE; the image displaces toward the APEX (opposite directions).", "ow": ["Both toward base is wrong; the image goes apexward.", "Both toward apex is wrong; light bends baseward.", "This reverses the two directions.", "Correct. Light to base, image to apex."]}'),
  ('574187ce-1f','{"options": ["Base in", "Base up", "Base down", "Base out"], "correct": 3, "decode": "Esotropia (eye turned in) is corrected with BASE-OUT prism.", "ow": ["Base-in is for exotropia.", "Base-up is for a hypodeviation.", "Base-down is for a hyperdeviation.", "Correct. Esotropia takes base-out prism."]}'),
  ('dd7dd74f-1v','{"options": ["2.5Δ", "1.75Δ", "0.5Δ", "1.0Δ"], "correct": 1, "decode": "One degree of deviation ≈ 1.75Δ.", "ow": ["2.5Δ overstates the conversion.", "Correct. 1° ≈ 1.75Δ.", "0.5Δ is far too small.", "1.0Δ understates it."]}'),
  ('124e8013-1s','{"options": ["Displaces it laterally only", "Reverses its direction", "Converges it to a focus", "Adds plus power to it"], "correct": 0, "decode": "A flat glass slab only DISPLACES the ray laterally; the exit ray is parallel with no power.", "ow": ["Correct. A plane slab shifts the ray laterally with no dioptric power.", "It does not reverse the ray''s direction.", "A flat slab has no focusing power.", "It adds no power."]}'),
  ('52b2f25c-z','{"options": ["The index difference only", "Both radius and index change", "Neither radius nor index", "The radius of curvature only"], "correct": 1, "decode": "Surface power needs BOTH radius and an index change: D = (n₂ − n₁)/r.", "ow": ["Index difference alone is insufficient without curvature.", "Correct. Power depends on both radius and index change.", "It depends on both, not neither.", "Radius alone gives no power if the indices match."]}'),
  ('4b0caad2-28','{"options": ["Actual depth × n", "Actual depth unchanged", "Actual depth ÷ n", "Actual depth + n"], "correct": 2, "decode": "Apparent depth = actual depth ÷ n (the shallowing effect).", "ow": ["Multiplying by n would make it look deeper, which is wrong.", "The apparent depth changes; it is not unchanged.", "Correct. Apparent depth = actual depth ÷ n.", "Adding n is dimensionally meaningless."]}'),
  ('76186ab8-1m','{"options": ["Scissors movement", "WITH movement", "No movement", "AGAINST movement"], "correct": 3, "decode": "A PLUS lens shows AGAINST movement on the movement test.", "ow": ["Scissors movement is an irregular/astigmatic finding, not a plus lens.", "''With'' movement is a minus lens.", "A powered lens does move; ''no movement'' is plano.", "Correct. Plus lenses show against movement."]}'),
  ('efb2696a-1p','{"options": ["f = R/2", "f = R²", "f = R", "f = 2R"], "correct": 0, "decode": "For a mirror, f = R/2.", "ow": ["Correct. Mirror f = R/2.", "f = R² is dimensionally wrong.", "f = R is for a lens surface convention, not a mirror focus.", "f = 2R inverts the relationship."]}'),
  ('c1a0079b-2h','{"options": ["Real, upright, same size", "Virtual, upright, magnified", "Real, inverted, minified", "Virtual, minified"], "correct": 2, "decode": "A concave mirror with the object BEYOND C gives a REAL, INVERTED, MINIFIED image (between F and C).", "ow": ["It is real and inverted, not upright same-size.", "It is real, not virtual.", "Correct. Object beyond C gives a real, inverted, minified image.", "It is real, not virtual."]}'),
  ('17374188-s','{"options": ["Reflection changes wavelength", "Reflected light bends toward the normal", "The angle of incidence equals the angle of reflection", "The angle of incidence is twice the angle of reflection"], "correct": 2, "decode": "Law of reflection: angle of incidence EQUALS angle of reflection.", "ow": ["Reflection does not change wavelength.", "Reflection bounces light; it does not refract toward the normal.", "Correct. Angle of incidence equals angle of reflection.", "The angles are equal, not doubled."]}'),
  ('2de4ccdc-30','{"options": ["It is a thicker lens overall", "It blocks ultraviolet light", "It changes corneal curvature", "It removes the vertex distance"], "correct": 3, "decode": "A contact lens sits at the corneal plane, REMOVING the vertex-distance effect, so high myopia needs less power.", "ow": ["A CL is thinner, not thicker; that is not the reason.", "Blocking UV is unrelated to the power change.", "It does not reshape corneal curvature.", "Correct. It eliminates the vertex distance."]}'),
  ('595d8378-2k','{"options": ["Concave mirror", "Plane mirror", "Convex mirror", "Plano lens"], "correct": 0, "decode": "A dentist''s mouth mirror magnifying a tooth inside its focal length is a CONCAVE mirror.", "ow": ["Correct. A concave mirror inside F gives a magnified virtual image.", "A plane mirror does not magnify.", "A convex mirror minifies.", "A plano lens has no magnifying power."]}'),
  ('f02dc87f-13','{"options": ["Base in", "Base down", "Base out", "Base up"], "correct": 0, "decode": "Exotropia (eye turned out) is corrected with BASE-IN prism.", "ow": ["Correct. Exotropia takes base-in prism.", "Base-down is for a hyperdeviation.", "Base-out is for esotropia.", "Base-up is for a hypodeviation."]}'),
  ('aa42f1d0-2a','{"options": ["Upright and minified", "Real, inverted, same size, at C", "Virtual and magnified", "At infinity"], "correct": 1, "decode": "An object at C (2F) of a concave mirror gives a REAL, INVERTED, SAME-SIZE image at C.", "ow": ["It is inverted and same-size, not upright/minified.", "Correct. Object at C gives a real, inverted, same-size image at C.", "It is real, not virtual/magnified.", "The image is at C, not infinity."]}'),
  ('aa93676d-10','{"options": ["1/p + 1/q = 1/f", "p × q = f", "p + q = f", "1/p − 1/q = 1/f"], "correct": 0, "decode": "The mirror/thin-lens equation is 1/p + 1/q = 1/f.", "ow": ["Correct. 1/p + 1/q = 1/f.", "p × q = f is not the lens equation.", "p + q = f is not the lens equation.", "1/p − 1/q = 1/f uses the wrong sign."]}'),
  ('e2e707ea-1h','{"options": ["Maximum refracting power", "Zero power at any curvature", "Power set by radius alone", "Negative refracting power"], "correct": 1, "decode": "With no index difference (n₁ = n₂), a surface has ZERO power at any curvature.", "ow": ["No index difference gives zero, not maximum, power.", "Correct. Zero power regardless of curvature.", "Power is not set by radius alone when Δn is zero.", "It is zero, not negative."]}'),
  ('c33a4d34-26','{"options": ["Polycarbonate", "CR-39", "Trivex", "Crown glass"], "correct": 0, "decode": "POLYCARBONATE has the lowest Abbe (~30), so the most chromatic aberration.", "ow": ["Correct. Polycarbonate has the lowest Abbe (~30).", "CR-39''s Abbe is ~58, much higher.", "Trivex''s Abbe (~43–45) is higher than polycarbonate.", "Crown glass has the highest Abbe (~58.9)."]}'),
  ('e1ddd272-1c','{"options": ["High-index glass", "Polycarbonate", "CR-39", "Crown glass"], "correct": 1, "decode": "POLYCARBONATE is the most impact-resistant lens material.", "ow": ["High-index glass is not the most impact resistant.", "Correct. Polycarbonate is the most impact resistant.", "CR-39 is less impact resistant than polycarbonate.", "Crown glass is brittle, not the most impact resistant."]}'),
  ('65452c47-w','{"options": ["Present only with a mirror coat", "Limited to the UV-C band", "Inherent, no coating needed", "Absent unless it is coated"], "correct": 2, "decode": "Polycarbonate blocks UV below ~385 nm INHERENTLY, no coating needed.", "ow": ["A mirror coat is not required for its UV protection.", "It blocks a broad UV range, not only UV-C.", "Correct. Polycarbonate''s UV protection is inherent.", "It is not absent; the protection is built in."]}'),
  ('76c7530e-1i','{"options": ["The windshield blocks the UV", "The cabin light is too dim", "The lens stays too warm", "They react only to blue light"], "correct": 0, "decode": "Photochromics fail to darken in a car because the WINDSHIELD BLOCKS THE UV they need.", "ow": ["Correct. The windshield blocks UV.", "Cabin light dimness is not the reason.", "Temperature is not the primary reason.", "They respond to UV, not only blue light."]}'),
  ('159f410a-1r','{"options": ["Photochromic", "Clearer", "Lighter", "Darker"], "correct": 3, "decode": "A higher CPF number means MORE filtering, so a DARKER lens.", "ow": ["A higher CPF is not simply photochromic.", "Higher CPF is darker, not clearer.", "Higher CPF is darker, not lighter.", "Correct. Higher CPF number = darker lens."]}'),
  ('30a09fd8-1p','{"options": ["More minus lens", "Lens with better acuity", "Either lens equally", "More plus lens"], "correct": 0, "decode": "Conventional slab-off is ground on the MORE MINUS (or less plus) lens.", "ow": ["Correct. Slab-off goes on the more minus / less plus lens.", "It is chosen by power, not by which eye sees better.", "It goes on a specific lens, not either equally.", "It goes on the more minus, not the more plus, lens."]}'),
  ('db3a5ac5-1g','{"options": ["P = d(mm) × F", "P = d(cm) × F", "P = F / d(cm)", "P = d(cm)² × F"], "correct": 1, "decode": "Prentice''s rule: P = d(cm) × F.", "ow": ["Decentration must be in centimeters, not millimeters.", "Correct. P = d(cm) × F.", "This inverts the relationship.", "Squaring the decentration is not Prentice''s rule."]}'),
  ('c76c7cc3-1h','{"options": ["20", "30", "45", "58.9"], "correct": 3, "decode": "Crown glass has the highest Abbe (~58.9), the best optical quality.", "ow": ["Abbe 20 is a very high-index, poor-quality material.", "Abbe 30 is polycarbonate.", "Abbe 45 is roughly Trivex.", "Correct. Crown glass Abbe ~58.9."]}'),
  ('319d1ffe-1n','{"options": ["High-index glass", "Polycarbonate", "Trivex", "Crown glass"], "correct": 2, "decode": "TRIVEX (SG ~1.11) is the lightest common lens material.", "ow": ["High-index glass is heavy.", "Polycarbonate (~1.20) is heavier than Trivex.", "Correct. Trivex is the lightest.", "Crown glass is heavy."]}'),
  ('52ae4759-1w','{"options": ["The same index", "No index difference", "Higher index than the major lens", "Lower index than the major"], "correct": 2, "decode": "A fused bifocal uses a HIGHER-index ''button'' segment set into the lower-index major lens.", "ow": ["Same index would add no extra power.", "No index difference gives no added power.", "Correct. The fused segment is a higher-index button.", "A lower-index segment would not add plus power."]}'),
  ('b6acdc06-2l','{"options": ["90°", "Both meridians", "180°", "45°"], "correct": 2, "decode": "''+6.00 × 90'' means the +6.00 power acts in the 180° meridian (perpendicular to the axis).", "ow": ["The power is perpendicular to 90, not in the 90 meridian.", "It acts in one meridian, not both.", "Correct. The power acts in the 180° meridian.", "45° is not the perpendicular of 90."]}'),
  ('c2c0cf9f-20','{"options": ["Yellow/amber", "Dark red CPF 550", "Polarized gray", "Clear UV 400 only"], "correct": 0, "decode": "Yellow/amber filters (CPF 511/527) boost contrast and cut glare for RP.", "ow": ["Correct. Yellow/amber CPF 511/527 suits RP.", "Dark red CPF 550 is for achromatopsia.", "Polarized gray does not give the contrast boost RP needs.", "A clear UV-400 lens adds no contrast enhancement."]}'),
  ('e60cd25d-1n','{"options": ["Minus cylinder", "Bitoric", "Plus cylinder", "No cylinder"], "correct": 0, "decode": "The FBTT (front-toric bifocal) is made in MINUS cylinder (cylinder on the back surface).", "ow": ["Correct. FBTT uses minus cylinder.", "Bitoric has toric on both surfaces, not FBTT.", "Plus cylinder is used for back-toric (UBTT) forms.", "It does carry cylinder, in minus form."]}'),
  ('3ac8ba56-14','{"options": ["20", "30", "45", "58"], "correct": 3, "decode": "CR-39 has an Abbe of about 58, much higher (better) than polycarbonate''s 30.", "ow": ["Abbe 20 is a very-high-index material.", "Abbe 30 is polycarbonate.", "Abbe 45 is Trivex.", "Correct. CR-39 Abbe ~58."]}'),
  ('690f4d48-2n','{"options": ["Greater than 0.5Δ", "Any amount", "Greater than 5Δ", "Greater than ~1.5Δ"], "correct": 3, "decode": "Vertical prism differentials above ~1.5Δ usually need slab-off; smaller ones just drop the OC.", "ow": ["0.5Δ is small enough to manage by dropping the OC.", "Not any amount; small differentials do not need slab-off.", "5Δ is well above threshold but overstates where slab-off begins.", "Correct. Slab-off is indicated above ~1.5Δ."]}'),
  ('0fdc7ef2-29','{"options": ["Polycarbonate", "CR-39", "High-index glass", "1.74 high-index plastic"], "correct": 1, "decode": "For minimal color fringing in sustained near work, choose high-Abbe CR-39.", "ow": ["Polycarbonate''s low Abbe (30) fringes most.", "Correct. CR-39''s high Abbe minimizes chromatic aberration.", "High-index glass has a lower Abbe than CR-39.", "1.74 high-index plastic has a low Abbe."]}'),
  ('eb9aff50-1f','{"options": ["Cylinder on front; sphere on back", "Base curve on the back surface; plus-cyl form", "Fused higher-index segment", "No base curve"], "correct": 1, "decode": "A UBTT (one-piece back-toric) bifocal has the BASE CURVE on the BACK surface, in plus-cyl form.", "ow": ["Cylinder on front / sphere on back is not UBTT.", "Correct. UBTT has the base curve on the back, plus-cyl form.", "A fused higher-index segment describes a fused bifocal, not UBTT.", "It does have a base curve, on the back."]}'),
  ('628f4363-1g','{"options": ["Clear lenses", "Yellow CPF 511", "Polarized only", "Dark red"], "correct": 3, "decode": "Achromats are extremely light-sensitive, so a DARK RED filter (CPF 550) is used.", "ow": ["Clear lenses give no relief from the glare.", "Yellow CPF 511 is for RP, not achromatopsia.", "Polarized alone does not cut the cone-overload glare enough.", "Correct. Achromatopsia takes a dark red filter."]}'),
  ('8d046684-29','{"options": ["0.5%", "1%", "4%", "20%"], "correct": 2, "decode": "Formula (Fresnel, per surface): R = [(n2 − n1)/(n2 + n1)]². Steps: R = [(1.5 − 1)/(1.5 + 1)]² = (0.5/2.5)² = 0.2² = 0.04 = 4% per surface. Two surfaces → ~8% total; the question asks per pattern ~4% per surface.", "ow": ["0.5% is far too low for an n≈1.5 surface.", "1% understates the per-surface loss.", "Correct. (0.5/2.5)² = 0.04 = 4% per surface.", "20% is far too high for n≈1.5."]}'),
  ('89579af7-y','{"options": ["Progressive lenses", "Kryptok, FT-28, FT-35", "Slab-off lenses", "Ultex and Executive"], "correct": 1, "decode": "Fused bifocals include KRYPTOK, FT-28, and FT-35.", "ow": ["Progressives are not fused bifocals.", "Correct. Kryptok, FT-28, FT-35 are fused bifocals.", "Slab-off is a prism technique, not a fused bifocal.", "Ultex and Executive are one-piece, not fused."]}'),
  ('cb069e72-18','{"options": ["It is the most impact resistant", "It is used for safety eyewear", "It blocks UV without a coating", "It has the highest Abbe value"], "correct": 3, "decode": "FALSE: polycarbonate has the LOWEST Abbe (30), not the highest.", "ow": ["True: polycarbonate is the most impact resistant.", "True: polycarbonate is used for safety eyewear.", "True: polycarbonate blocks UV without a coating.", "Correct (the false statement). Polycarbonate''s Abbe is the lowest, not the highest."]}'),
  ('ee658204-10','{"options": ["30", "43–45", "58", "20"], "correct": 1, "decode": "Trivex has an Abbe of about 43–45, between polycarbonate (30) and CR-39 (58).", "ow": ["30 is polycarbonate''s Abbe.", "Correct. Trivex Abbe ~43–45.", "58 is CR-39.", "20 is a very-high-index material."]}'),
  ('0ef7b7d0-2j','{"options": ["Bitoric; both surfaces toric", "No cylinder; flat front", "Plus cyl; base curve on front", "Minus cyl; base curve on back"], "correct": 2, "decode": "SVTT (single-vision toric) uses PLUS cylinder with the BASE CURVE on the FRONT.", "ow": ["Bitoric with both surfaces toric is not SVTT.", "SVTT does carry cylinder.", "Correct. SVTT is plus-cyl with the base curve on the front.", "Minus-cyl with back base curve describes UBTT/FBTT-type forms, not SVTT."]}'),
  ('b27b2efc-26','{"options": ["±1.00 D", "±2.00 D", "±4.00 D", "±8.00 D"], "correct": 2, "decode": "Vertex-distance correction becomes necessary above about ±4.00 D.", "ow": ["Below ±1.00 D the effect is negligible.", "±2.00 D is still below the clinically meaningful threshold.", "Correct. Vertex correction matters above ±4.00 D.", "±8.00 D is above threshold but overstates where it begins."]}'),
  ('e41377b2-27','{"options": ["−6.50 D", "−6.00 D", "−7.00 D", "−5.00 D"], "correct": 1, "decode": "Formula: D_CL = D_spec / (1 − d·D_spec), d in meters. Steps: d = 14 mm = 0.014 m; D_CL = −6.50 / (1 − 0.014×(−6.50)) = −6.50 / (1 + 0.091) = −6.50 / 1.091 = −5.96 ≈ −6.00 D. A high minus needs less minus at the corneal plane.", "ow": ["−6.50 D unchanged ignores the vertex effect (>±4 D).", "Correct. −6.50 / 1.091 ≈ −6.00 D.", "−7.00 D adds minus, the wrong direction.", "−5.00 D overshoots the reduction."]}'),
  ('2edfe813-1u','{"options": ["The silicone polymer matrix", "Surface pores", "Tear exchange only", "Their water content"], "correct": 0, "decode": "Silicone hydrogels transmit oxygen through the SILICONE polymer matrix, not water.", "ow": ["Correct. O₂ passes through the silicone matrix.", "Not through surface pores.", "Not by tear exchange alone.", "High Dk does not require high water content in SiHy."]}'),
  ('d35e1b8c-10','{"options": ["They are highly gas permeable", "They were the first soft lenses", "They are non-gas-permeable", "They are silicone hydrogels"], "correct": 2, "decode": "PMMA is hard and NON-gas-permeable.", "ow": ["PMMA transmits no oxygen.", "PMMA was the first hard lens, not soft.", "Correct. PMMA is non-gas-permeable.", "PMMA is not a silicone hydrogel."]}'),
  ('e24f7c20-17','{"options": ["Excess movement and mechanical trauma", "No effect", "Too little movement → hypoxia and edema", "Improved tear exchange"], "correct": 2, "decode": "A STEEP lens moves too little, restricting tear exchange → HYPOXIA and edema.", "ow": ["Excess movement/mechanical trauma is a flat, not steep, fit.", "A steep fit does have an effect.", "Correct. Steep = too little movement, hypoxia and edema.", "A steep fit worsens, not improves, tear exchange."]}'),
  ('af9fc6d0-1z','{"options": ["Candida", "Pseudomonas aeruginosa", "Staphylococcus aureus", "Acanthamoeba"], "correct": 1, "decode": "PSEUDOMONAS aeruginosa is the most common organism in CL-related microbial keratitis.", "ow": ["Candida is a fungal, less common cause.", "Correct. Pseudomonas is the most common bacterial cause.", "Staph aureus is less common than Pseudomonas in CL keratitis.", "Acanthamoeba is linked to water exposure but is less common."]}'),
  ('7582ce62-1a','{"options": ["Polycarbonate spectacle lenses", "Tap water exposure in lens wear", "Daily disposable lens use", "Wearing reading glasses"], "correct": 1, "decode": "Acanthamoeba keratitis is linked to TAP WATER exposure in lens wear.", "ow": ["Polycarbonate spectacles are unrelated.", "Correct. Acanthamoeba is associated with tap-water/swimming exposure.", "Daily disposables actually reduce this risk.", "Reading glasses are unrelated."]}'),
  ('fd0e2ead-1z','{"options": ["Irreversible", "Reversible with better lenses", "Caused by over-cleaning", "A type of infection"], "correct": 0, "decode": "Polymegethism (variable endothelial cell size from chronic hypoxia) is IRREVERSIBLE.", "ow": ["Correct. Polymegethism is a permanent endothelial change.", "It does not reverse with better lenses.", "It is a hypoxic change, not from over-cleaning.", "It is not an infection."]}'),
  ('28b68778-1w','{"options": ["Near", "Intermediate", "Distance", "Astigmatism only"], "correct": 2, "decode": "In monovision, the DOMINANT eye is corrected for DISTANCE.", "ow": ["Near goes to the non-dominant eye.", "Intermediate is not the standard dominant-eye assignment.", "Correct. Dominant eye = distance.", "It is not corrected for astigmatism only."]}'),
  ('8b21bc46-w','{"options": ["Blocking UV", "Adding a tint", "Permanently flattening the cornea", "Temporary corneal reshaping overnight"], "correct": 3, "decode": "Ortho-K TEMPORARILY reshapes the cornea overnight and helps control myopia.", "ow": ["It does not work by blocking UV.", "It does not add a tint.", "The reshaping is temporary, not permanent.", "Correct. Ortho-K temporarily reshapes the cornea overnight."]}'),
  ('5d2c26e6-1w','{"options": ["−6.00 D", "−10.00 D", "No limit", "−2.00 D"], "correct": 0, "decode": "Ortho-K is effective up to about −6.00 D of myopia.", "ow": ["Correct. The upper limit is about −6.00 D.", "−10.00 D exceeds ortho-K''s effective range.", "There is a practical limit, so ''no limit'' is wrong.", "−2.00 D understates the achievable range."]}'),
  ('3a7dcc63-23','{"options": ["It dissolves the lens matrix", "It has no effect on lenses", "It binds the lens and is toxic", "It discolors the lens material"], "correct": 2, "decode": "BAK is epithelial-toxic and BINDS soft lens material, so it is contraindicated with soft CLs.", "ow": ["It does not dissolve the matrix; the issue is binding and toxicity.", "It does have an effect: toxic binding.", "Correct. BAK binds the lens and is toxic.", "The problem is toxicity, not discoloration."]}'),
  ('1319e696-1r','{"options": ["Ultraviolet light exposure", "Bacterial infection of the lid", "Lens deposits and friction", "Corneal hypoxia alone"], "correct": 2, "decode": "GPC is an immune/mechanical reaction to lens DEPOSITS and FRICTION on the upper tarsus.", "ow": ["UV light does not cause GPC.", "GPC is not a bacterial lid infection.", "Correct. GPC comes from deposits and friction.", "Hypoxia alone does not cause GPC."]}'),
  ('d4142146-28','{"options": ["HVID + 2 mm", "Exactly HVID", "HVID − 2 mm", "Double HVID"], "correct": 0, "decode": "Soft lens diameter ≈ HVID + 2 mm so it vaults onto the sclera.", "ow": ["Correct. SCL diameter ≈ HVID + 2 mm.", "Exactly HVID would not vault the limbus.", "HVID − 2 mm is too small.", "Double HVID is far too large."]}'),
  ('d2fbd92b-1o','{"options": ["5Δ base in", "1–1.5Δ base down", "3–5Δ base up", "No prism"], "correct": 1, "decode": "Toric soft lenses use prism ballast of about 1–1.5Δ BASE-DOWN.", "ow": ["5Δ base-in is not a ballast orientation.", "Correct. Prism ballast is ~1–1.5Δ base-down.", "3–5Δ base-up is wrong in both amount and direction.", "Toric lenses do need stabilization, so ''no prism'' is wrong."]}'),
  ('6ffd3591-1a','{"options": ["George Bier", "Otto Wichterle", "Adolf Fick", "Kevin Touhy"], "correct": 1, "decode": "OTTO WICHTERLE developed the first soft (HEMA) contact lens.", "ow": ["George Bier is not credited with the HEMA soft lens.", "Correct. Wichterle developed the HEMA soft lens.", "Adolf Fick made an early glass scleral lens, not HEMA.", "Kevin Touhy made the first PMMA corneal lens."]}'),
  ('f1d0f41f-2u','{"options": ["Dry eye", "Microbial keratitis", "A normal finding", "Giant papillary conjunctivitis"], "correct": 1, "decode": "A white infiltrate with staining and pain in a CL wearer is MICROBIAL KERATITIS until proven otherwise.", "ow": ["Dry eye does not give a white infiltrate.", "Correct. Infiltrate + staining + pain = microbial keratitis.", "This is not a normal finding.", "GPC gives upper-lid papillae, not a corneal infiltrate."]}'),
  ('3f80dbc3-1l','{"options": ["Patient non-compliance with cleaning", "Higher oxygen transmission", "Lower cost", "Better optics"], "correct": 0, "decode": "Daily disposables were introduced mainly to fix poor cleaning COMPLIANCE/hygiene.", "ow": ["Correct. They address non-compliance with cleaning.", "Higher oxygen was not the primary driver.", "Lower cost was not the driver.", "Better optics was not the driver."]}'),
  ('4e3db8f2-2t','{"options": ["The full cylinder", "Sphere only", "The spherical equivalent", "Double the cylinder"], "correct": 2, "decode": "For a small cylinder, set power by the SPHERICAL EQUIVALENT (sph + ½ cyl).", "ow": ["The full cylinder is not used with a spherical soft lens.", "Sphere only ignores the small cylinder''s contribution.", "Correct. Use the spherical equivalent for low cyl.", "Doubling the cylinder is not the rule."]}'),
  ('4103d437-1i','{"options": ["Only keratometry", "No fitting at all", "Daily disposal", "A diagnostic trial fitting"], "correct": 3, "decode": "RGP lenses require a DIAGNOSTIC TRIAL fitting; soft lenses can be fit empirically.", "ow": ["RGP fitting needs more than keratometry alone.", "RGPs do require fitting.", "RGPs are not daily-disposal lenses.", "Correct. RGP success depends on trial-lens fitting."]}'),
  ('d9e06308-20','{"options": ["Optimal fit", "Normal daily wear", "Dehydration", "Excessive edema"], "correct": 3, "decode": "7–14% corneal edema in conventional extended-wear hydrogel is EXCESSIVE (hypoxic).", "ow": ["This level is not an optimal fit.", "It is above the normal daily-wear range (~2–7%).", "It reflects swelling, not dehydration.", "Correct. 7–14% edema is excessive."]}'),
  ('82505bc8-1j','{"options": ["Excess movement, decentered", "Too little lens movement", "Perfect central positioning", "It steepens the cornea"], "correct": 0, "decode": "A FLAT-fitting RGP shows EXCESS movement and decentration.", "ow": ["Correct. Flat fit = excess movement, decentered.", "Too little movement is a steep fit.", "A flat fit does not center well.", "A flat lens does not steepen the cornea."]}'),
  ('6530f9be-1e','{"options": ["Thomas Young", "Leonardo da Vinci", "Kevin Touhy", "Otto Wichterle"], "correct": 2, "decode": "KEVIN TOUHY is credited with the first PMMA corneal contact lens (1947).", "ow": ["Thomas Young is not the CL inventor.", "Leonardo da Vinci conceptualized but did not make the PMMA lens.", "Correct. Touhy made the first PMMA corneal lens.", "Wichterle developed soft HEMA lenses later."]}'),
  ('b6f05e61-1v','{"options": ["Newton, Huygens, Maxwell, Planck", "Huygens, Newton, Planck, Maxwell", "Newton, Planck, Maxwell, Huygens", "Maxwell, Newton, Huygens, Planck"], "correct": 0, "decode": "Light theories in order (NHMP): Newton, Huygens, Maxwell, Planck.", "ow": ["Correct. Newton, Huygens, Maxwell, Planck.", "This ordering scrambles the sequence.", "This ordering scrambles the sequence.", "This ordering scrambles the sequence."]}'),
  ('7b6a49e8-1t','{"options": ["v = c + n", "v = c × n", "v = n/c", "v = c/n"], "correct": 3, "decode": "v = c/n: a higher index means slower light, which bends the ray at an interface.", "ow": ["v = c + n is dimensionally meaningless.", "v = c × n would speed light up in dense media.", "v = n/c inverts the relationship.", "Correct. v = c/n."]}'),
  ('63aad50d-1r','{"options": ["Visible blue", "UV-B", "Infrared", "UV-A"], "correct": 1, "decode": "UV-B causes photokeratitis (welder''s flash), a reversible photochemical injury.", "ow": ["Visible blue is not the photokeratitis band.", "Correct. UV-B causes photokeratitis.", "Infrared causes permanent thermal damage.", "UV-A penetrates deeper and links to cataract."]}'),
  ('f33eec3c-1q','{"options": ["Permanent", "Limited to the conjunctiva", "Reversible and milder", "Caused only by UV-C"], "correct": 0, "decode": "Thermal (infrared) damage is PERMANENT; photochemical injury is reversible.", "ow": ["Correct. Thermal damage is permanent.", "It is not limited to the conjunctiva.", "Thermal damage is permanent, not reversible/milder.", "It is caused by infrared, not UV-C."]}'),
  ('7c8aacf4-1i','{"options": ["20 D", "43 D", "58.64 D", "72 D"], "correct": 2, "decode": "Gullstrand''s schematic eye totals about 58.64 D (cornea ~43 D).", "ow": ["20 D is far too low.", "43 D is the cornea alone.", "Correct. The eye totals ~58.64 D.", "72 D is too high."]}'),
  ('6d8e4ba2-1d','{"options": ["Real, erect, same size", "Virtual, inverted, magnified", "Virtual, erect, minified", "Real, inverted, minified"], "correct": 2, "decode": "A concave (minus) lens image is always VIRTUAL, ERECT, MINIFIED.", "ow": ["A minus lens gives no real image of a real object.", "It is erect and minified, not inverted/magnified.", "Correct. Concave lens: always virtual, erect, minified.", "It is virtual, not real."]}'),
  ('3770c566-2d','{"options": ["A higher Abbe and less chromatic aberration", "A lower Abbe and more chromatic aberration", "No change in Abbe value", "A higher Abbe and more chromatic aberration"], "correct": 1, "decode": "Higher index → LOWER Abbe → MORE chromatic aberration (the thinning trade-off).", "ow": ["Higher index lowers Abbe, so ''higher Abbe/less CA'' is reversed.", "Correct. Higher index means lower Abbe and more chromatic aberration.", "Abbe does change with index.", "Higher index does raise CA, but Abbe falls, not rises."]}'),
  ('d154729a-1n','{"options": ["337.5 with n = 1.336", "1.000", "1.3375 with a constant of 1000", "337.5 with n = 1.3375"], "correct": 3, "decode": "Keratometry converts radius to power via D = 337.5/r using n = 1.3375.", "ow": ["The keratometric index is 1.3375, not 1.336.", "1.000 is air, not the keratometric index.", "The constant used is 337.5, not 1000.", "Correct. 337.5/r with n = 1.3375."]}'),
  ('a4d4b8b3-15','{"options": ["The sum of sphere and cylinder", "Half the original power", "The original sign reversed", "The same sign as the original"], "correct": 2, "decode": "Flat transposition: new cylinder = −C (original sign reversed).", "ow": ["S + C is the new sphere, not the cylinder.", "It is not half the power.", "Correct. New cylinder = the original sign reversed (−C).", "The sign flips, not stays the same."]}'),
  ('06dae06b-2h','{"options": ["Trivex", "CR-39", "Polycarbonate", "Crown glass"], "correct": 2, "decode": "POLYCARBONATE has the lowest Abbe (30), so the most chromatic aberration.", "ow": ["Trivex Abbe (~43–45) is higher than polycarbonate.", "CR-39 Abbe (~58) is much higher.", "Correct. Polycarbonate''s Abbe (30) is the lowest.", "Crown glass Abbe (58.9) is the highest."]}'),
  ('67f19ed1-1u','{"options": ["Crown glass", "Polycarbonate", "CR-39", "Trivex"], "correct": 3, "decode": "TRIVEX (SG 1.11) is the lightest, matching polycarbonate''s impact resistance.", "ow": ["Crown glass is heavy.", "Polycarbonate (1.20) is heavier than Trivex.", "CR-39 is heavier than Trivex.", "Correct. Trivex is the lightest (SG 1.11)."]}'),
  ('cd8a015d-1g','{"options": ["CR-39", "High-index plastic", "Polycarbonate", "Crown glass"], "correct": 2, "decode": "POLYCARBONATE is the most impact-resistant material and blocks UV below 385 nm uncoated.", "ow": ["CR-39 is less impact resistant.", "High-index plastic is less impact resistant.", "Correct. Polycarbonate is the most impact resistant.", "Crown glass is brittle."]}'),
  ('51001b7a-11','{"options": ["Thermal expansion of the matrix", "A polarizing film", "Silver halide crystals reacting to UV", "A liquid crystal layer"], "correct": 2, "decode": "Photochromics darken because SILVER HALIDE crystals react to UV.", "ow": ["Thermal expansion does not drive the darkening.", "A polarizing film does not darken with UV.", "Correct. Silver halide crystals react to UV.", "A liquid-crystal layer is not the photochromic mechanism."]}'),
  ('13e01028-1i','{"options": ["350 nm", "385 nm", "400 nm", "500 nm"], "correct": 2, "decode": "''UV 400'' blocks all UV below 400 nm (the gold standard).", "ow": ["350 nm leaves some UV unblocked.", "385 nm is untreated polycarbonate''s cutoff, below the UV-400 standard.", "Correct. UV 400 blocks all UV below 400 nm.", "500 nm would block visible light too."]}'),
  ('229b3917-z','{"options": ["Excess edge thickness", "Vertical prism imbalance", "Peripheral spherical aberration", "Chromatic aberration at near"], "correct": 1, "decode": "A slab-off corrects VERTICAL PRISM IMBALANCE at near in anisometropia.", "ow": ["Edge thickness is a cosmetic issue, not what slab-off corrects.", "Correct. Slab-off corrects vertical prism imbalance.", "It does not address peripheral spherical aberration.", "It does not address chromatic aberration."]}'),
  ('d9c1032b-22','{"options": ["UBTT", "Plano-cylindrical", "FBTT", "SVTT"], "correct": 2, "decode": "Fused bifocals (Kryptok, FT-28) are made in FBTT (front base toric, minus-cyl) form.", "ow": ["UBTT is the one-piece back-toric form.", "''Plano-cylindrical'' is not a bifocal cylinder form.", "Correct. Fused bifocals are FBTT.", "SVTT is a single-vision toric form."]}'),
  ('903e0dcf-1p','{"options": ["Dark red CPF 550", "A clear UV 400 lens", "A grey polarized lens", "Yellow-amber CPF 511 or 527"], "correct": 3, "decode": "For RP, the recommended absorptive filter is YELLOW-AMBER (CPF 511 or 527).", "ow": ["Dark red CPF 550 is for achromatopsia.", "A clear UV-400 lens adds no contrast enhancement.", "Grey polarized does not give the contrast boost RP needs.", "Correct. RP takes amber CPF 511/527."]}'),
  ('f22a88be-1e','{"options": ["Otto Wichterle", "Kevin Touhy", "Adolf Fick", "William Feinbloom"], "correct": 1, "decode": "KEVIN TOUHY is credited with the first corneal PMMA contact lens (1947).", "ow": ["Wichterle developed the HEMA soft lens later.", "Correct. Touhy made the first PMMA corneal lens.", "Adolf Fick made an early glass scleral lens, not PMMA.", "William Feinbloom worked with early plastics/scleral lenses, not the PMMA corneal lens."]}'),
  ('02efaf11-18','{"options": ["1947", "1961", "1971", "1987"], "correct": 2, "decode": "Soft (HEMA) contact lenses received FDA approval in 1971.", "ow": ["1947 is the first PMMA corneal lens.", "1961 is Wichterle''s HEMA development, not FDA approval.", "Correct. Soft CLs were FDA-approved in 1971.", "1987 is the first disposable lens."]}'),
  ('61b4654e-1y','{"options": ["Through surface pores", "Around the lens edge", "Through the silicone polymer itself", "Through the water content"], "correct": 2, "decode": "Silicone hydrogels move oxygen through the SILICONE polymer itself, not the water.", "ow": ["Not through surface pores.", "Not around the lens edge.", "Correct. O₂ passes through the silicone polymer.", "In conventional hydrogels O₂ rides through water, but SiHy uses the polymer."]}'),
  ('92205626-1r','{"options": ["1–1.5Δ base-down", "4–5Δ base-in", "3Δ base-up", "0.25Δ base-down"], "correct": 0, "decode": "Toric soft lenses are stabilized with about 1–1.5Δ BASE-DOWN prism ballast.", "ow": ["Correct. Prism ballast is ~1–1.5Δ base-down.", "4–5Δ base-in is not a ballast orientation.", "3Δ base-up is the wrong direction.", "0.25Δ is too little to stabilize."]}'),
  ('782ad8b9-1r','{"options": ["Candida albicans", "Staphylococcus aureus", "Acanthamoeba", "Pseudomonas aeruginosa"], "correct": 3, "decode": "PSEUDOMONAS aeruginosa is the most common (and aggressive) CL microbial keratitis organism.", "ow": ["Candida is a fungal, less common cause.", "Staph aureus is less common than Pseudomonas here.", "Acanthamoeba is water-linked but less common.", "Correct. Pseudomonas is the most common cause."]}'),
  ('8ca4e588-x','{"options": ["Too little movement", "Marked lens decentration", "Excessive lens movement", "Inferior dropping of the lens"], "correct": 0, "decode": "A STEEP RGP grips the cornea, producing TOO LITTLE movement and hypoxia.", "ow": ["Correct. A steep fit gives too little movement.", "Marked decentration is a flat fit.", "Excessive movement is a flat fit.", "Inferior dropping is a flat/heavy fit."]}'),
  ('7019439f-1k','{"options": ["Intermediate", "Near", "Whichever eye is more ametropic", "Distance"], "correct": 3, "decode": "In monovision, the DOMINANT eye is corrected for DISTANCE.", "ow": ["Intermediate is not the standard dominant-eye assignment.", "Near goes to the non-dominant eye.", "It is set by dominance, not by which eye is more ametropic.", "Correct. Dominant eye = distance."]}'),
  ('ffaf824a-1q','{"options": ["−6.00 D", "−15.00 D", "−2.00 D", "−10.00 D"], "correct": 0, "decode": "Ortho-K is effective up to about −6.00 D of myopia.", "ow": ["Correct. The myopia limit is about −6.00 D.", "−15.00 D is far beyond ortho-K''s range.", "−2.00 D is the astigmatism limit, not the myopia ceiling.", "−10.00 D exceeds ortho-K''s effective range."]}'),
  ('ff92048d-1w','{"options": ["±4.00 D", "±2.00 D", "±8.00 D", "±1.00 D"], "correct": 0, "decode": "Vertex-distance correction becomes necessary beyond about ±4.00 D.", "ow": ["Correct. Vertex correction matters beyond ±4.00 D.", "±2.00 D is below the meaningful threshold.", "±8.00 D overstates where correction begins.", "±1.00 D is negligible."]}'),
  ('20704fc9-1e','{"options": ["HVID plus 2 mm", "HVID minus 2 mm", "Equal to the HVID", "Twice the pupil diameter"], "correct": 0, "decode": "Soft lens diameter is chosen as HVID + ~2 mm so it vaults the limbus.", "ow": ["Correct. SCL diameter ≈ HVID + 2 mm.", "HVID − 2 mm is too small to vault the limbus.", "Equal to HVID would not cover the limbus.", "Twice the pupil diameter is not the sizing rule."]}'),
  ('5386f0d9-1e','{"options": ["Reversible epithelial edema", "Normal aging of the tear film", "Temporary stromal thinning", "Irreversible endothelial change"], "correct": 3, "decode": "Polymegethism signifies IRREVERSIBLE endothelial change from chronic hypoxia.", "ow": ["It is not reversible epithelial edema.", "It is not normal tear-film aging.", "It is not temporary stromal thinning.", "Correct. Polymegethism is an irreversible endothelial change."]}'),
  ('966ffeb5-1i','{"options": ["7–14%", "0%", "2–7%", "15–20%"], "correct": 2, "decode": "Daily-wear hydrogel edema is normally 2–7%.", "ow": ["7–14% is conventional extended wear (excessive).", "0% edema is unrealistic for daily wear.", "Correct. Daily-wear hydrogel edema is 2–7%.", "15–20% is pathological."]}'),
  ('f7e7b130-1m','{"options": ["Scleral lenses", "Soft contact lenses", "RGP lenses", "Orthokeratology lenses"], "correct": 1, "decode": "SOFT contact lenses can be fit EMPIRICALLY from K and refraction, without a trial lens.", "ow": ["Scleral lenses require trial fitting.", "Correct. Soft lenses can be fit empirically.", "RGPs need trial fitting (fluorescein pattern).", "Ortho-K lenses require careful trial fitting."]}'),
  ('c4e7ca5b-2q','{"options": ["Speed up", "Stop entirely", "Slow down", "Change color"], "correct": 0, "decode": "Newton''s corpuscular theory wrongly predicted light would SPEED UP in a denser medium.", "ow": ["Correct. Newton predicted speeding up; measurement showed the opposite.", "It did not predict light would stop.", "Slowing down is what actually happens (Huygens), not Newton''s prediction.", "It did not predict a color change."]}'),
  ('9420f66d-18','{"options": ["Stays constant", "Falls", "Rises then falls", "Rises"], "correct": 1, "decode": "As index rises, the critical angle FALLS (diamond 24.44°).", "ow": ["It does change with index, not stay constant.", "Correct. Higher index lowers the critical angle.", "It falls monotonically, not rises-then-falls.", "It falls, not rises."]}'),
  ('cc378010-1s','{"options": ["UV-A", "UV-C", "Visible green", "UV-B"], "correct": 0, "decode": "UV-A penetrates deeper to the lens and links to CATARACT.", "ow": ["Correct. UV-A penetrates deeper and links to cataract.", "UV-C is largely blocked by the atmosphere.", "Visible green is not the cataract band.", "UV-B is absorbed by the cornea (photokeratitis), not the cataract link."]}'),
  ('bbfa0515-2e','{"options": ["Matches the tear film exactly", "Is easier to calculate with", "Corrects for the tear prism", "Absorbs the posterior surface"], "correct": 3, "decode": "The keratometric index 1.3375 folds in (ABSORBS) the minus posterior corneal surface.", "ow": ["It is not meant to match the tear film exactly.", "Ease of calculation is not the real reason.", "It does not correct for a tear prism.", "Correct. 1.3375 absorbs the posterior surface so one anterior reading gives total power."]}'),
  ('9bafe0d9-1o','{"options": ["Undefined", "Positive", "Zero", "Negative"], "correct": 3, "decode": "Diverging light from a point source carries NEGATIVE vergence.", "ow": ["Vergence is defined here, not undefined.", "Positive vergence is converging light.", "Zero vergence is parallel light.", "Correct. Diverging light has negative vergence."]}'),
  ('ac208765-2c','{"options": ["Optical center", "Nearest edge", "Base as well", "Apex"], "correct": 3, "decode": "Light bends toward the BASE while the image moves toward the APEX (opposite).", "ow": ["The optical center is not where the image shifts.", "The nearest edge is not the rule.", "The image goes apexward, not baseward.", "Correct. The image moves toward the apex."]}'),
  ('ab23f5aa-11','{"options": ["Base up", "Base down", "Base out", "Base in"], "correct": 2, "decode": "The correcting prism for esotropia is BASE-OUT (exotropia takes base-in).", "ow": ["Base-up is for a hypodeviation.", "Base-down is for a hyperdeviation.", "Correct. Esotropia takes base-out.", "Base-in is for exotropia."]}'),
  ('f2a153a3-17','{"options": ["With movement", "Rotational movement", "Against movement", "No movement"], "correct": 2, "decode": "On the movement test, a PLUS lens shows AGAINST movement.", "ow": ["''With'' movement is a minus lens.", "Rotational (scissors) movement is astigmatic, not a plus lens.", "Correct. Plus lenses show against movement.", "A powered plus lens does move."]}'),
  ('11a35b86-12','{"options": ["Virtual and minified", "Real and magnified", "Real and inverted", "Virtual and magnified"], "correct": 0, "decode": "A convex mirror always gives a VIRTUAL, MINIFIED (upright) image.", "ow": ["Correct. Convex mirror: virtual and minified.", "It is not real/magnified.", "It is virtual, not real/inverted.", "It is minified, not magnified."]}'),
  ('887cffff-10','{"options": ["Shallower than it is", "At its true depth", "Deeper than it is", "Laterally displaced only"], "correct": 0, "decode": "An object in water appears SHALLOWER (apparent depth = actual ÷ n).", "ow": ["Correct. It appears shallower than it is.", "It does not appear at true depth.", "It appears shallower, not deeper.", "It shifts in apparent depth, not only laterally."]}'),
  ('26f0f289-1u','{"options": ["Unchanged in tint", "Lighter", "More reflective", "Darker"], "correct": 3, "decode": "A higher CPF number filters MORE, so the lens is DARKER (CPF 450 lightest, 550 darkest).", "ow": ["A higher CPF does change the tint (darker).", "Higher CPF is darker, not lighter.", "The change is darkness, not reflectivity.", "Correct. Higher CPF number = darker lens."]}'),
  ('2bd881a1-1r','{"options": ["The dominant eye''s lens", "Either lens equally", "The more plus lens", "The more minus lens"], "correct": 3, "decode": "Conventional slab-off is applied to the MORE MINUS (or less plus) lens.", "ow": ["It is chosen by power, not by dominance.", "It goes on a specific lens, not either equally.", "It goes on the more minus, not the more plus, lens.", "Correct. Slab-off goes on the more minus lens."]}'),
  ('955fc02b-1d','{"options": ["On the front, and spherical", "On the back, and spherical", "On the front, and toric", "On the back, and toric"], "correct": 0, "decode": "In an FBTT lens the base curve is on the FRONT and SPHERICAL (back is toric, minus-cyl).", "ow": ["Correct. FBTT: base curve front and spherical.", "The BC is on the front, not the back, in FBTT.", "The front is spherical, not toric, in FBTT.", "The toric surface is the back, not the front, and the BC is front."]}'),
  ('d4bdd83d-1s','{"options": ["The back", "The front, spherical", "Neither; both are toric", "The front, calculated"], "correct": 0, "decode": "In a UBTT lens the base curve is the BACK surface (−BC).", "ow": ["Correct. UBTT: the base curve is the back.", "The front is not the spherical base curve in UBTT.", "The BC is a single surface (back), not both toric.", "The front is derived, not the base curve, in UBTT."]}'),
  ('f3335cea-19','{"options": ["CR-39", "They are identical", "Neither has an Abbe value", "Polycarbonate"], "correct": 0, "decode": "CR-39 (Abbe 58) has a much HIGHER Abbe than polycarbonate (30).", "ow": ["Correct. CR-39''s Abbe (58) is higher.", "They are not identical.", "Both have Abbe values.", "Polycarbonate''s Abbe (30) is lower."]}'),
  ('17385a5b-p','{"options": ["Highly gas permeable", "A silicone hydrogel", "Moderately gas permeable", "Non-gas permeable"], "correct": 3, "decode": "PMMA is NON-gas permeable, which is why RGP materials replaced it.", "ow": ["PMMA transmits no oxygen.", "PMMA is not a silicone hydrogel.", "PMMA is not moderately permeable; it is essentially impermeable.", "Correct. PMMA is non-gas permeable."]}'),
  ('ee647b3c-14','{"options": ["Extended wear only", "Both soft and RGP wearers", "Soft lens wearers only", "RGP wearers only"], "correct": 1, "decode": "GPC arises from deposits and friction, so it affects BOTH soft and RGP wearers.", "ow": ["It is not limited to extended wear.", "Correct. GPC affects both soft and RGP wearers.", "It is not soft-only.", "It is not RGP-only."]}'),
  ('3a86ba3b-1m','{"options": ["Superior comfort", "Better optics", "Poor cleaning compliance", "Lower cost"], "correct": 2, "decode": "Daily disposables were introduced chiefly for HYGIENE (poor cleaning compliance).", "ow": ["Comfort was not the primary driver.", "Better optics was not the driver.", "Correct. They address poor cleaning compliance.", "Lower cost was not the driver."]}'),
  ('1ed75aaf-1w','{"options": ["Converted to plus", "Less minus than −8.00 D", "More minus than −8.00 D", "The same, −8.00 D"], "correct": 1, "decode": "A high minus needs LESS minus at the corneal plane (vertex effect).", "ow": ["A myope''s CL stays minus, not converted to plus.", "Correct. Less minus than −8.00 D as a contact lens.", "More minus overcorrects at the cornea.", "The same power ignores the vertex effect above ±4 D."]}'),
  ('a6c37377-24','{"options": ["Excess movement and rubbing", "Inducing corneal hypoxia", "Causing no harm at all", "Restricting tear exchange"], "correct": 0, "decode": "A FLAT-fitting lens harms mainly by EXCESS movement and mechanical rubbing.", "ow": ["Correct. Flat fit = excess movement and rubbing.", "Hypoxia is the steep-fit harm, not flat.", "A flat fit does cause harm.", "Restricted tear exchange is the steep-fit harm."]}'),
  ('d428c949-55','{"options": ["1.2Δ base out", "0.9Δ base up", "1.5Δ base in", "0.9Δ base in"], "correct": 0, "decode": "Formula (Prentice): P = d(cm) × F, using the power in the meridian of the decentration. Horizontal decentration → 180° meridian. Axis 90 puts the cyl power in the 180° meridian, so horizontal power = −3.00 + (−1.00) = −4.00 D. Steps: 3 mm = 0.3 cm; P = 0.3 × 4.00 = 1.2Δ. Minus lens displaced temporally → base out.", "ow": ["Correct. Horizontal power = −4.00 D (sphere + cyl, axis 90); 0.3 cm × 4.00 = 1.2Δ, base out.", "0.9Δ base-up applies vertical decentration, but the displacement here is horizontal.", "1.5Δ base-in uses the wrong magnitude and direction.", "0.9Δ comes from using only the −3.00 sphere; it forgets that the −1.00 cyl (axis 90) also acts in the horizontal meridian, making it −4.00 D."]}'),
  ('52cf9b87-2s','{"options": ["Light refracts normally and bends away from the normal", "Light is completely absorbed", "Total internal reflection occurs", "Light refracts and bends toward the normal"], "correct": 2, "decode": "Formula: sin θc = n_rare / n_dense. Steps: sin θc = 1.000 / 1.523 = 0.6566 → θc = 41.04°. The incidence (50°) exceeds θc (41.04°), and beyond the critical angle a dense-to-rare ray is fully reflected → TOTAL INTERNAL REFLECTION.", "ow": ["Light is not transmitted/refracted once incidence passes the critical angle.", "It is reflected, not absorbed.", "Correct. 50° > θc (41.04°), so TIR occurs.", "It reflects internally rather than bending toward the normal."]}'),
  ('94295717-67','{"options": ["+6.00D", "+6.16D", "+6.48D", "+6.80D"], "correct": 2, "decode": "Concave-side-down reads BACK VERTEX POWER. Formula: BVP = F1/(1 − (t/n)·F1) + F2. Steps: t/n = 0.006/1.5 = 0.004; F1/(1 − 0.004×10) = 10/0.96 = 10.42; BVP = 10.42 + (−4) = +6.42 D ≈ +6.48. BVP exceeds the +6.00 nominal (F1 + F2) because of the thickness term.", "ow": ["+6.00 D is the nominal thin-lens power (F1 + F2), ignoring the thickness term.", "+6.16 D understates the thickness/vertex correction.", "Correct. BVP = 10/(1 − 0.004×10) − 4 = 10.42 − 4 ≈ +6.4–6.5 D (nearest option +6.48).", "+6.80 D overstates it; the thickness term adds only ~0.42 D, not 0.80."]}'),
  ('4279ebef-4r','{"options": ["Virtual, upright, magnified", "Real, inverted, minified", "Real, inverted, magnified", "Virtual, upright, minified"], "correct": 0, "decode": "Formulas: f = R/2 and 1/p + 1/q = 1/f, m = −q/p. Steps: f = 40/2 = 20 mm; object p = 15 mm is inside f. 1/q = 1/20 − 1/15 = (3 − 4)/60 = −1/60 → q = −60 mm (negative = virtual). m = −(−60)/15 = +4 (positive = upright, ×4). So the image is VIRTUAL, UPRIGHT, MAGNIFIED.", "ow": ["Correct. q = −60 mm (virtual), m = +4 (upright, magnified).", "m is positive (+4), so upright, not inverted; and q is negative (virtual), not real.", "q is negative, so the image is virtual, not real.", "m = +4, so magnified, not minified."]}'),
  ('8554be70-2s','{"options": ["8△ Base Out right eye", "4△ Base Out each eye", "4△ Base In each eye", "8△ Base In right eye"], "correct": 3, "decode": "Right exotropia (eye turned out) is corrected with BASE-IN prism, full amount on the affected eye = 8Δ BI OD.", "ow": ["Base-out corrects esotropia, not exotropia.", "Splitting base-out is wrong in direction.", "Splitting the prism is acceptable, but the board form places the full amount on the affected eye.", "Correct. 8Δ base-in on the right eye."]}'),
  ('c00bb664-39','{"options": ["27 cm below the surface", "53 cm below the surface", "30 cm below the surface", "40 cm below the surface"], "correct": 2, "decode": "Formula (shallowing): apparent depth = actual depth × (n_observer / n_medium). Steps: = 40 × (1.00 / 1.33) = 40 / 1.33 = 30.08 ≈ 30 cm. Objects in a denser medium look closer to the observer.", "ow": ["27 cm uses the wrong ratio (would need n ≈ 1.48).", "53 cm multiplies by n instead of dividing, giving deeper (wrong direction).", "Correct. 40 / 1.33 ≈ 30 cm.", "40 cm ignores refraction; the coin appears shallower than its true depth."]}'),
  ('5a726df8-4r','{"options": ["High-index glass", "Trivex", "CR-39", "Polycarbonate"], "correct": 2, "decode": "For sustained near/monitor work, prioritize optical quality: CR-39 (Abbe 58) minimizes color fringing.", "ow": ["High-index glass has a lower Abbe and is heavier.", "Trivex (Abbe 43–45) is a costlier compromise with no real gain here.", "Correct. CR-39''s high Abbe minimizes chromatic aberration in near gaze.", "Polycarbonate (Abbe 30) fringes most in sustained near work."]}'),
  ('0a1461e7-5s','{"options": ["2.8Δ differential; drop the distance OC", "2.8Δ differential; slab-off on OS", "0.8Δ differential; dissimilar segments", "3.6Δ differential; slab-off on OD"], "correct": 1, "decode": "At 8 mm: OD 0.8Δ BU, OS 3.6Δ BU → 2.8Δ differential; since >1.5Δ, slab-off on the MOST PLUS lens (OS).", "ow": ["2.8Δ is right, but >1.5Δ needs slab-off, not just dropping the OC.", "Correct. 2.8Δ differential; slab-off on the more plus OS.", "0.8Δ is only the OD prism, not the differential.", "3.6Δ is only the OS prism; slab-off goes on OS, not OD."]}'),
  ('2934ef0c-30','{"options": ["0.58%", "3.87%", "4.45%", "7.75%"], "correct": 3, "decode": "Formula (Fresnel, per surface): R = [(n2 − n1)/(n2 + n1)]². Steps: R = [(1.498 − 1)/(1.498 + 1)]² = (0.498/2.498)² = 0.1994² = 0.0387 = 3.87% per surface; two uncoated surfaces → 3.87% × 2 = 7.75% total.", "ow": ["0.58% is a single AR-coated back-surface loss.", "3.87% is per-surface only, not both surfaces.", "4.45% is a partially-coated value.", "Correct. 3.87% × 2 = ~7.75% for both surfaces."]}'),
  ('154f339a-7w','{"options": ["Corneal abrasion from flat-fitting lens", "GPC from protein deposits", "Corneal neovascularization from chronic hypoxia", "Microbial keratitis"], "correct": 3, "decode": "A white infiltrate with staining and pain in a CL wearer is MICROBIAL KERATITIS, a sight-threatening emergency.", "ow": ["An abrasion does not give a white infiltrate.", "GPC gives upper-lid papillae, not a corneal infiltrate.", "Neovascularization is initially asymptomatic, without a white infiltrate.", "Correct. This is microbial keratitis until proven otherwise."]}'),
  ('889917ca-3i','{"options": ["−6.50D", "−6.25D", "−6.00D", "−5.75D"], "correct": 2, "decode": "Formula: D_CL = D_spec / (1 − d·D_spec), d in meters. Steps: d = 14 mm = 0.014 m; D_CL = −6.50 / (1 − 0.014×(−6.50)) = −6.50 / (1 + 0.091) = −6.50 / 1.091 = −5.96 ≈ −6.00 D. Vertex matters here because |Rx| > 4 D.", "ow": ["−6.50 D unchanged ignores the vertex effect.", "−6.25 D undercorrects the reduction.", "Correct. −6.50 / 1.091 ≈ −6.00 D.", "−5.75 D overshoots the reduction."]}'),
  ('91d5fa63-46','{"options": ["0.00D", "1.00D", "2.00D", "3.00D"], "correct": 1, "decode": "Formula: residual astigmatism = total astigmatism − corneal astigmatism. Steps: total (from Rx cyl) = 3.00 D; corneal (K difference) = 45.00 − 43.00 = 2.00 D; residual = 3.00 − 2.00 = 1.00 D. An RGP corrects the corneal 2.00 D but leaves the 1.00 D lenticular residual.", "ow": ["0.00 D would require total to equal corneal astigmatism (purely corneal).", "Correct. 3.00 − 2.00 = 1.00 D residual.", "2.00 D is the corneal component, not the residual.", "3.00 D is the total astigmatism, not the residual."]}'),
  ('0fe22738-1w','{"options": ["An upright image", "A minified image", "A virtual image", "A real image"], "correct": 3, "decode": "A POSITIVE image distance q means a REAL image.", "ow": ["Orientation is given by m, not the sign of q.", "Size is not indicated by the sign of q.", "Negative q is a virtual image.", "Correct. Positive q means a real image."]}'),
  ('ccd61696-1h','{"options": ["Virtual", "Minified", "Inverted", "Upright"], "correct": 2, "decode": "A NEGATIVE magnification m means an INVERTED image.", "ow": ["Real/virtual is indicated by q, not the sign of m.", "Size is given by the magnitude of m.", "Correct. Negative m means inverted.", "Positive m is upright."]}'),
  ('bc84a29b-12','{"options": ["Zero", "Negative, since it diverges", "Positive, since it converges", "Equal to its radius"], "correct": 1, "decode": "A convex mirror diverges, so its focal length is NEGATIVE (image always virtual, upright, minified).", "ow": ["It is not zero.", "Correct. Convex mirror f is negative.", "Positive f is a concave (converging) mirror.", "f is R/2, not equal to R."]}'),
  ('f2864ad4-1i','{"options": ["2.00Δ", "1.00Δ", "1.75Δ", "0.57Δ"], "correct": 2, "decode": "One degree of deviation ≈ 1.75Δ (and 1Δ ≈ 0.57°).", "ow": ["2.00Δ overstates the conversion.", "1.00Δ understates it.", "Correct. 1° ≈ 1.75Δ.", "0.57Δ is the reciprocal (1Δ ≈ 0.57°), not the forward conversion."]}'),
  ('db84178d-2o','{"options": ["The reflected ray bends toward the normal", "The ray speeds up on reflection", "The image is always real", "Incident ray, normal and reflected ray are coplanar"], "correct": 3, "decode": "Law of reflection: i = r, AND the incident ray, normal, and reflected ray are COPLANAR.", "ow": ["The reflected ray does not bend toward the normal.", "Reflection keeps the same medium, so speed is unchanged.", "Reflected images can be real or virtual, not always real.", "Correct. All three rays are coplanar."]}'),
  ('0aba1ac0-24','{"options": ["It removes the air-to-cornea index step", "It absorbs part of the incident light", "It flattens the corneal curvature", "It sits closer to the nodal point"], "correct": 0, "decode": "A contact lens abolishes the AIR-CORNEA index step that supplies most of the cornea''s power.", "ow": ["Correct. The CL removes the air-to-cornea index step.", "It does not work by absorbing light.", "It does not flatten the corneal curvature.", "Proximity to the nodal point is not the mechanism."]}'),
  ('1c35192b-11','{"options": ["1.000", "1.336", "1.376", "1.406"], "correct": 2, "decode": "The cornea''s true refractive index is 1.376.", "ow": ["1.000 is air.", "1.336 is aqueous/vitreous.", "Correct. The cornea is 1.376.", "1.406 is the lens nucleus."]}'),
  ('e6de5e68-17','{"options": ["1.336", "1.376", "1.386", "1.406"], "correct": 3, "decode": "The lens NUCLEUS index is 1.406 (cortex 1.386).", "ow": ["1.336 is aqueous/vitreous.", "1.376 is the cornea.", "1.386 is the lens cortex.", "Correct. The lens nucleus is 1.406."]}'),
  ('994bbc60-1d','{"options": ["5.33 mm", "6.8 mm", "7.7 mm", "10.0 mm"], "correct": 2, "decode": "The anterior corneal radius of curvature is about 7.7 mm.", "ow": ["5.33 mm is the fully accommodated anterior lens radius.", "6.8 mm is the posterior cornea.", "Correct. The anterior cornea is ~7.7 mm.", "10.0 mm is the unaccommodated anterior lens radius."]}'),
  ('57270d53-1z','{"options": ["2.00 mm", "5.33 mm", "6.8 mm", "7.7 mm"], "correct": 1, "decode": "On full accommodation the anterior lens radius steepens from 10.0 mm to 5.33 mm.", "ow": ["2.00 mm is far too steep.", "Correct. It steepens to 5.33 mm.", "6.8 mm is the posterior cornea.", "7.7 mm is the anterior cornea."]}'),
  ('eb5eedbe-2k','{"options": ["10 D", "19 D", "43 D", "58.64 D"], "correct": 1, "decode": "In Gullstrand''s eye the unaccommodated lens contributes 19 D.", "ow": ["10 D understates the lens power.", "Correct. The lens adds 19 D unaccommodated.", "43 D is the cornea.", "58.64 D is the whole eye."]}'),
  ('fa4035ea-1r','{"options": ["43 D", "58.64 D", "60 D", "62 D"], "correct": 2, "decode": "Emsley''s reduced eye assigns a total power of 60 D.", "ow": ["43 D is the cornea alone.", "58.64 D is Gullstrand''s exact eye.", "Correct. The reduced eye is 60 D.", "62 D is not a standard value."]}'),
  ('bfdcf560-27','{"options": ["7.08 mm", "7.33 mm", "13.5 mm", "24 mm"], "correct": 2, "decode": "The center of rotation lies about 13.5 mm behind the corneal apex.", "ow": ["7.08 mm is the primary nodal point.", "7.33 mm is the secondary nodal point.", "Correct. The center of rotation is ~13.5 mm.", "24 mm is the axial length."]}'),
  ('d139d662-1k','{"options": ["13.5 mm and 14.0 mm", "7.08 mm and 7.33 mm", "24.0 mm and 24.4 mm", "1.35 mm and 1.60 mm"], "correct": 1, "decode": "The nodal points lie at 7.08 mm (N) and 7.33 mm (N'') behind the corneal apex.", "ow": ["13.5/14.0 mm is near the center of rotation, not the nodal points.", "Correct. N 7.08 mm, N'' 7.33 mm.", "24 mm is near the axial length.", "1.35/1.60 mm is far too shallow."]}'),
  ('3a2bf077-27','{"options": ["Prentice''s Rule", "Diopter", "TIR", "Snell''s Law"], "correct": 3, "decode": "SNELL''S LAW (n₁ sin i = n₂ sin R) governs bending at every optical interface.", "ow": ["Prentice''s rule is about prism from decentration.", "The diopter is a unit, not the refraction law.", "TIR is a specific reflection condition, not the general law.", "Correct. Snell''s Law governs refraction."]}'),
  ('f90c44f6-2c','{"options": ["Diopter", "TIR", "Snell''s Law", "Prentice''s Rule"], "correct": 1, "decode": "TIR (total internal reflection): dense→rare beyond the critical angle, fully reflected.", "ow": ["The diopter is a unit, not this phenomenon.", "Correct. TIR is full reflection beyond the critical angle.", "Snell''s law is the general refraction law.", "Prentice''s rule is about prism from decentration."]}'),
  ('23ed25f9-1r','{"options": ["Diopter", "Snell''s Law", "TIR", "Prentice''s Rule"], "correct": 0, "decode": "The DIOPTER is the unit of vergence and lens power = 1/f (meters).", "ow": ["Correct. The diopter is 1/f (meters).", "Snell''s law is the refraction law, not a unit.", "TIR is a reflection phenomenon.", "Prentice''s rule is a prism formula."]}'),
  ('89c9831b-29','{"options": ["Prentice''s Rule", "TIR", "Diopter", "Snell''s Law"], "correct": 0, "decode": "PRENTICE''S RULE: prismatic effect P = d × F (d in cm, F in D).", "ow": ["Correct. Prentice''s rule: P = d × F.", "TIR is a reflection phenomenon.", "The diopter is a unit.", "Snell''s law is the refraction law."]}'),
  ('bd927955-2q','{"options": ["Abbe value", "TIR", "Diopter", "Snell''s Law"], "correct": 0, "decode": "The ABBE VALUE measures chromatic aberration; higher = less dispersion = better optics.", "ow": ["Correct. Abbe value measures chromatic dispersion.", "TIR is a reflection phenomenon.", "The diopter is a power unit.", "Snell''s law is the refraction law."]}'),
  ('6d5a2bd7-e','{"options": ["1.20", "1.498", "1.532", "1.586"], "correct": 1, "decode": "CR-39''s refractive index is 1.498.", "ow": ["1.20 is polycarbonate''s specific gravity, not an index.", "Correct. CR-39 n = 1.498.", "1.532 is Trivex.", "1.586 is polycarbonate."]}'),
  ('0cffc60d-m','{"options": ["1.20", "1.498", "1.532", "1.586"], "correct": 3, "decode": "Polycarbonate''s refractive index is 1.586.", "ow": ["1.20 is polycarbonate''s specific gravity.", "1.498 is CR-39.", "1.532 is Trivex.", "Correct. Polycarbonate n = 1.586."]}'),
  ('5460e15b-n','{"options": ["1.20", "1.498", "1.532", "1.586"], "correct": 0, "decode": "Polycarbonate''s specific gravity is 1.20 (lightest manufactured lens).", "ow": ["Correct. Polycarbonate SG = 1.20.", "1.498 is CR-39''s index, not an SG.", "1.532 is Trivex''s index.", "1.586 is polycarbonate''s index."]}'),
  ('10bb9b9e-f','{"options": ["1.20", "1.498", "1.532", "1.586"], "correct": 2, "decode": "Trivex''s refractive index is 1.532.", "ow": ["1.20 is polycarbonate''s specific gravity.", "1.498 is CR-39.", "Correct. Trivex n = 1.532.", "1.586 is polycarbonate."]}'),
  ('5916602e-i','{"options": ["1.498", "1.20", "1.586", "43–45"], "correct": 3, "decode": "Trivex''s Abbe value is 43–45.", "ow": ["1.498 is CR-39''s index, not an Abbe value.", "1.20 is polycarbonate''s SG.", "1.586 is polycarbonate''s index.", "Correct. Trivex Abbe = 43–45."]}'),
  ('0c498f29-n','{"options": ["1.20", "1.498", "1.586", "58.9"], "correct": 3, "decode": "Crown glass''s Abbe value is 58.9 (best CA control in glass).", "ow": ["1.20 is polycarbonate''s SG.", "1.498 is CR-39''s index.", "1.586 is polycarbonate''s index.", "Correct. Crown glass Abbe = 58.9."]}'),
  ('d2fbcb95-h','{"options": ["1.20", "1.498", "1.586", "58"], "correct": 3, "decode": "CR-39''s Abbe value is 58 (best CA control in plastic).", "ow": ["1.20 is polycarbonate''s SG.", "1.498 is CR-39''s index, not its Abbe.", "1.586 is polycarbonate''s index.", "Correct. CR-39 Abbe = 58."]}'),
  ('5d895377-28','{"options": ["Photochromic", "Specific gravity", "CPF filter", "Wratten filter"], "correct": 0, "decode": "A PHOTOCHROMIC lens darkens on UV exposure via a silver halide reaction.", "ow": ["Correct. Photochromic = UV-triggered silver halide darkening.", "Specific gravity is a weight property, not a lens type.", "A CPF filter is a fixed low-vision filter, not photochromic.", "A Wratten filter is a gelatin trial filter, not photochromic."]}'),
  ('ea07477a-1o','{"options": ["Specific gravity", "CPF filter", "Photochromic", "Wratten filter"], "correct": 1, "decode": "A CPF filter is a longpass filter for low-vision patients.", "ow": ["Specific gravity is a weight property, not a filter.", "Correct. CPF = Corning longpass low-vision filter.", "Photochromic lenses darken with UV; they are not the CPF longpass filter.", "A Wratten filter is a gelatin trial filter, not the CPF."]}'),
  ('0adaf7bd-21','{"options": ["CPF filter", "Specific gravity", "Wratten filter", "Photochromic"], "correct": 2, "decode": "A WRATTEN filter is a gelatin/glass trial filter for low-vision assessment.", "ow": ["A CPF filter is a dispensed longpass filter, not the trial filter.", "Specific gravity is a weight property.", "Correct. Wratten = gelatin/glass trial filter.", "Photochromic lenses darken with UV; not the trial filter."]}'),
  ('bfd71d19-x','{"options": ["1999–2002", "1987", "1971", "7.4"], "correct": 2, "decode": "The first soft CL FDA approval was in 1971.", "ow": ["1999–2002 is the first silicone hydrogel.", "1987 is the first disposable lens.", "Correct. First soft CL approval = 1971.", "7.4 is the tear-film pH, not a year."]}'),
  ('33f0912d-q','{"options": ["7.4", "1999–2002", "1971", "1987"], "correct": 3, "decode": "The first disposable CL appeared in 1987 (hygiene improvement).", "ow": ["7.4 is tear-film pH, not a year.", "1999–2002 is the first silicone hydrogel.", "1971 is the first soft CL approval.", "Correct. First disposable CL = 1987."]}'),
  ('91496398-u','{"options": ["1971", "1999–2002", "7.4", "1987"], "correct": 1, "decode": "The first silicone hydrogel arrived around 1999–2002 (the O₂ breakthrough).", "ow": ["1971 is the first soft CL approval.", "Correct. First silicone hydrogel = 1999–2002.", "7.4 is tear-film pH, not a year.", "1987 is the first disposable lens."]}'),
  ('540f8783-j','{"options": ["13.5–15 mm", "8–10 mm", "Flatter than K by ~0.8–1.0 mm", "11.7 mm average"], "correct": 0, "decode": "Soft lens diameter is 13.5–15 mm (covers the limbus).", "ow": ["Correct. SCL diameter = 13.5–15 mm.", "8–10 mm is the RGP diameter.", "''Flatter than K by 0.8–1.0 mm'' describes the base curve, not diameter.", "11.7 mm is the HVID, not the lens diameter."]}'),
  ('491c98a0-j','{"options": ["11.7 mm average", "Flatter than K by ~0.8–1.0 mm", "13.5–15 mm", "8–10 mm"], "correct": 3, "decode": "RGP diameter is 8–10 mm (corneal only).", "ow": ["11.7 mm is the HVID.", "''Flatter than K'' describes a base curve, not diameter.", "13.5–15 mm is the soft lens diameter.", "Correct. RGP diameter = 8–10 mm."]}'),
  ('e20f51a7-l','{"options": ["Steeper than K by 0.8–1.0 mm", "Flatter than K by 0.8–1.0 mm", "Equal to the flattest K", "Flatter than K by 3.0 mm"], "correct": 1, "decode": "A soft lens base curve is typically FLATTER than K by ~0.8–1.0 mm.", "ow": ["It is flatter, not steeper, than K.", "Correct. SCL BC is flatter than K by ~0.8–1.0 mm.", "It is not equal to the flattest K.", "Flatter by 3.0 mm is far too flat."]}'),
  ('e7d96392-j','{"options": ["1971", "7.4", "1999–2002", "1987"], "correct": 1, "decode": "Tear-film pH is 7.4 (the CL solution target).", "ow": ["1971 is the first soft CL approval, not a pH.", "Correct. Tear-film pH = 7.4.", "1999–2002 is the silicone hydrogel era, not a pH.", "1987 is the first disposable, not a pH."]}'),
  ('872e986d-r','{"options": ["1987", "6.5–8.0", "1999–2002", "1971"], "correct": 1, "decode": "The CL solution pH range is 6.5–8.0 (outside = burn risk).", "ow": ["1987 is the first disposable year, not a pH range.", "Correct. CL solution pH = 6.5–8.0.", "1999–2002 is the silicone hydrogel era, not a pH range.", "1971 is the first soft CL approval, not a pH range."]}'),
  ('b38588b1-b','{"options": ["13.5–15 mm", "8–10 mm", "11.7 mm average", "Flatter than K by ~0.8–1.0 mm"], "correct": 2, "decode": "HVID (horizontal visible iris diameter) averages 11.7 mm; SCL diameter = HVID + ~2 mm.", "ow": ["13.5–15 mm is the soft lens diameter, not the HVID.", "8–10 mm is the RGP diameter.", "Correct. HVID ≈ 11.7 mm.", "''Flatter than K'' describes a base curve, not the HVID."]}'),
  ('4a795b6b-b','{"options": ["8–10 mm", "Flatter than K by ~0.8–1.0 mm", "10.6 mm average", "13.5–15 mm"], "correct": 2, "decode": "VVID (vertical visible iris diameter) averages 10.6 mm.", "ow": ["8–10 mm is the RGP diameter.", "''Flatter than K'' describes a base curve.", "Correct. VVID ≈ 10.6 mm.", "13.5–15 mm is the soft lens diameter."]}'),
  ('a3b14cd0-17','{"options": ["−2.00 D", "D_CL = Sph + ½ Cyl", "> ±4.00 D", "−6.00 D"], "correct": 2, "decode": "Vertex-distance correction is needed above about ±4.00 D.", "ow": ["−2.00 D is the ortho-K astigmatism limit, not the vertex threshold.", "''D_CL = Sph + ½ Cyl'' is the spherical-equivalent rule.", "Correct. Vertex correction matters above ±4.00 D.", "−6.00 D is the ortho-K myopia limit, not the vertex threshold."]}'),
  ('f06c8257-w','{"options": ["−2.00 D", "> ±4.00 D", "−6.00 D", "D_CL = Sph + ½ Cyl"], "correct": 3, "decode": "The spherical equivalent rule: D_CL = Sph + ½ Cyl (for cyl < 1.00 D).", "ow": ["−2.00 D is the ortho-K astigmatism limit.", "> ±4.00 D is the vertex-distance threshold.", "−6.00 D is the ortho-K myopia limit.", "Correct. Spherical equivalent = Sph + ½ Cyl."]}'),
  ('69ba471d-p','{"options": ["Flatter than K by ~0.8–1.0 mm", "8–10 mm", "13.5–15 mm", "Flattest K + 0.3–0.9 mm"], "correct": 3, "decode": "SCL BOZR is selected as flattest K + 0.3–0.9 mm (starting point).", "ow": ["''Flatter than K by 0.8–1.0 mm'' is a rough BC rule, not this specific BOZR selection.", "8–10 mm is the RGP diameter.", "13.5–15 mm is the soft lens diameter.", "Correct. SCL BOZR = flattest K + 0.3–0.9 mm."]}'),
  ('dd834ea5-t','{"options": ["ΔTD 0.5 mm = ΔBOZR 0.3 mm", "Flatter than K by ~0.8–1.0 mm", "13.5–15 mm", "8–10 mm"], "correct": 0, "decode": "Soft lens TD/BOZR rule: ΔTD 0.5 mm = ΔBOZR 0.3 mm (compensate when changing diameter).", "ow": ["Correct. ΔTD 0.5 mm ↔ ΔBOZR 0.3 mm.", "''Flatter than K'' describes the base curve, not this rule.", "13.5–15 mm is the soft lens diameter.", "8–10 mm is the RGP diameter."]}'),
  ('feb41058-p','{"options": ["−6.00 D", "> ±4.00 D", "−2.00 D", "D_CL = Sph + ½ Cyl"], "correct": 0, "decode": "Ortho-K max myopia is about −6.00 D (beyond this, insufficient flattening).", "ow": ["Correct. Ortho-K myopia limit = −6.00 D.", "> ±4.00 D is the vertex threshold.", "−2.00 D is the ortho-K astigmatism limit.", "''D_CL = Sph + ½ Cyl'' is the spherical-equivalent rule."]}'),
  ('cc877a04-u','{"options": ["D_CL = Sph + ½ Cyl", "> ±4.00 D", "−6.00 D", "−2.00 D"], "correct": 3, "decode": "Ortho-K max astigmatism is about −2.00 D (irregular astigmatism develops above this).", "ow": ["''D_CL = Sph + ½ Cyl'' is the spherical-equivalent rule.", "> ±4.00 D is the vertex threshold.", "−6.00 D is the ortho-K myopia limit.", "Correct. Ortho-K astigmatism limit = −2.00 D."]}'),
  ('172357a4-29','{"options": ["Dk/t", "Base curve", "PMMA", "HEMA"], "correct": 0, "decode": "Dk/t (Dk ÷ lens thickness) is oxygen TRANSMISSIBILITY: the actual O₂ delivered to the cornea.", "ow": ["Correct. Dk/t is oxygen transmissibility.", "Base curve is the back-surface radius, not transmissibility.", "PMMA is a material, not a transmissibility measure.", "HEMA is a monomer, not transmissibility."]}'),
  ('e8c3f2d5-22','{"options": ["Dk/t", "Base curve", "PMMA", "HEMA"], "correct": 1, "decode": "The BASE CURVE (back-surface radius) must approximate the corneal curvature for a proper fit.", "ow": ["Dk/t is oxygen transmissibility, not the fitting curve.", "Correct. The base curve must approximate corneal curvature.", "PMMA is a material, not a curve.", "HEMA is a monomer, not a curve."]}'),
  ('3ae779b0-29','{"options": ["PMMA", "Dk/t", "Base curve", "HEMA"], "correct": 3, "decode": "HEMA is the monomer Wichterle developed, the basis of all hydrogel soft lenses.", "ow": ["PMMA is the rigid, non-permeable material.", "Dk/t is oxygen transmissibility.", "Base curve is the back-surface radius.", "Correct. HEMA is the hydrogel soft-lens monomer."]}'),
  ('5ce56434-29','{"options": ["Base curve", "HEMA", "Dk/t", "PMMA"], "correct": 3, "decode": "PMMA is the first plastic CL material, non-gas-permeable (Touhy, 1947).", "ow": ["Base curve is the back-surface radius.", "HEMA is the soft hydrogel monomer.", "Dk/t is oxygen transmissibility.", "Correct. PMMA is the first, non-permeable plastic lens."]}'),
  ('84b5cb95-20','{"options": ["HEMA", "Dk/t", "Base curve", "RGP"], "correct": 3, "decode": "RGP (rigid gas permeable) is the hard lens that transmits oxygen through the polymer.", "ow": ["HEMA is the soft hydrogel monomer.", "Dk/t is oxygen transmissibility.", "Base curve is the back-surface radius.", "Correct. RGP is the oxygen-permeable hard lens."]}'),
  ('71739407-2z','{"options": ["Base curve", "HEMA", "Dk/t", "Ortho-K"], "correct": 3, "decode": "Ortho-K is overnight RGP wear that temporarily reshapes the cornea to correct myopia.", "ow": ["Base curve is the back-surface radius.", "HEMA is the soft hydrogel monomer.", "Dk/t is oxygen transmissibility.", "Correct. Ortho-K reshapes the cornea overnight."]}'),
  ('9aa6a319-2y','{"options": ["Component ametropia", "Correlative ametropia", "Pathological ametropia", "Acquired ametropia"], "correct": 1, "decode": "CORRELATIVE (simple) ametropia is normal variation, largely hereditary, generally under 6.00 D.", "ow": ["Component ametropia is the pathological, potentially >6 D form.", "Correct. Correlative ametropia is normal variation, <6 D.", "Pathological ametropia is the component form, not correlative.", "Acquired ametropia arises from disease, not normal variation."]}'),
  ('bfa65d5c-2q','{"options": ["Physiological ametropia", "Component ametropia", "Correlative ametropia", "Simple ametropia"], "correct": 1, "decode": "COMPONENT ametropia is the pathological form: an abnormal component, able to exceed 6.00 D and progress.", "ow": ["''Physiological'' ametropia is the normal-variation (correlative) form.", "Correct. Component ametropia is pathological and can exceed 6 D.", "Correlative ametropia is the normal-variation form.", "Simple ametropia is another name for correlative, not component."]}'),
  ('b8e73171-1q','{"options": ["0.5 mm", "1 mm", "5 mm", "10 mm"], "correct": 2, "decode": "Axial length grows about 5 mm from birth to age 3 (the fastest phase).", "ow": ["0.5 mm badly understates early growth.", "1 mm is roughly the annual growth from ages 3–13, not birth-to-3.", "Correct. About 5 mm in the first three years.", "10 mm overstates the early growth."]}'),
  ('10debb31-1p','{"options": ["0.1 mm per year", "3 mm per year", "5 mm per year", "1 mm per year"], "correct": 3, "decode": "From ages 3 to 13 axial length grows about 1 mm per year.", "ow": ["0.1 mm per year understates it.", "3 mm per year overstates it.", "5 mm per year is roughly the total birth-to-3 growth, not annual.", "Correct. About 1 mm per year from 3 to 13."]}'),
  ('c700b1cc-2b','{"options": ["Overall symmetrical", "Meridional symmetrical", "Asymmetrical", "Compound symmetrical"], "correct": 1, "decode": "MERIDIONAL symmetrical aniseikonia enlarges one image in a single meridian only.", "ow": ["Overall symmetrical enlarges all dimensions equally.", "Correct. Meridional affects one meridian only.", "Asymmetrical distorts unevenly, not in one clean meridian.", "Compound combines meridional and overall."]}'),
  ('0fd11f71-2a','{"options": ["Meridional symmetrical", "Overall symmetrical", "Cylindrical", "Compound symmetrical"], "correct": 1, "decode": "OVERALL symmetrical aniseikonia enlarges one image equally in ALL dimensions.", "ow": ["Meridional affects one meridian only.", "Correct. Overall symmetrical scales the whole image.", "''Cylindrical'' is not the standard aniseikonia category.", "Compound is a combination, not the all-dimensions form."]}'),
  ('2185cd30-1d','{"options": ["Cornea", "Eyelid", "Conjunctiva", "Sclera"], "correct": 0, "decode": "A standard contact lens sits directly on the CORNEA (and tear film).", "ow": ["Correct. A contact lens rests on the cornea.", "The eyelid is not the optical seat of the lens.", "The conjunctiva is not where a corneal lens sits.", "Scleral lenses vault the cornea but are the exception, not the default."]}'),
  ('0aa6acc0-14','{"options": ["Correct refractive error", "Change axial length", "Produce tears", "Increase intraocular pressure"], "correct": 0, "decode": "A contact lens''s main purpose is to CORRECT REFRACTIVE ERROR.", "ow": ["Correct. It corrects refractive error.", "It does not change axial length.", "It does not produce tears.", "It does not raise intraocular pressure."]}'),
  ('f36b837a-1v','{"options": ["Spherical and cylindrical", "Convex and concave", "Plus and minus", "Soft and rigid"], "correct": 3, "decode": "By material, contact lenses are classified as SOFT and RIGID.", "ow": ["Spherical/cylindrical describes design geometry, not material.", "Convex/concave describes optical form, not material.", "Plus/minus describes power, not material.", "Correct. Soft and rigid is the material classification."]}'),
  ('76e54bd4-e','{"options": ["Regular Glass Plastic", "Refractive Gas Polymer", "Rigid Glass Power", "Rigid Gas-Permeable"], "correct": 3, "decode": "RGP stands for RIGID GAS-PERMEABLE.", "ow": ["''Regular Glass Plastic'' is not a real term.", "''Refractive Gas Polymer'' is invented.", "''Rigid Glass Power'' is invented.", "Correct. RGP = Rigid Gas-Permeable."]}'),
  ('4de604b7-21','{"options": ["Carbon dioxide", "Hydrogen", "Oxygen", "Nitrogen"], "correct": 2, "decode": "The avascular cornea needs OXYGEN, which the lens must transmit.", "ow": ["CO₂ is a waste product to release, not supply.", "Hydrogen is not consumed by the cornea.", "Correct. Oxygen is the critical gas.", "Nitrogen is not the metabolically needed gas."]}'),
  ('0b41b6e7-3f','{"options": ["More minus", "Always zero", "Less minus", "More plus"], "correct": 2, "decode": "A minus spectacle Rx converts to a LESS MINUS contact lens power at the corneal plane (vertex effect).", "ow": ["It does not become more minus.", "It does not go to zero for a myope.", "Correct. Less minus at the corneal plane.", "It stays minus, not more plus."]}'),
  ('993b0f04-1r','{"options": ["Vitreous film", "Post-lens tear film", "Precorneal tear film only", "Retinal film"], "correct": 1, "decode": "The tear layer BEHIND the lens (between lens and cornea) is the POST-LENS tear film.", "ow": ["''Vitreous film'' is not a tear structure.", "Correct. Behind the lens is the post-lens tear film.", "The precorneal film sits in front of a bare cornea, not behind a lens.", "''Retinal film'' is not a tear structure."]}'),
  ('f7e43e06-1m','{"options": ["Lens opacity", "Optical correction", "Pupil dilation", "Retinal detachment"], "correct": 1, "decode": "The tear lens under an RGP contributes OPTICAL CORRECTION, masking irregular astigmatism.", "ow": ["It does not cause lens opacity.", "Correct. The tear lens adds optical correction.", "It does not dilate the pupil.", "It does not cause retinal detachment."]}'),
  ('b1239b25-24','{"options": ["Stop blinking", "Reduce oxygen supply", "Exchange tears beneath the lens", "Increase corneal thickness"], "correct": 2, "decode": "Lens movement on blinking EXCHANGES tears beneath the lens (a pump for O₂ and debris).", "ow": ["It does not stop blinking.", "It increases, not reduces, oxygen supply.", "Correct. Movement exchanges tears beneath the lens.", "It does not increase corneal thickness."]}'),
  ('ef7ae432-1a','{"options": ["Reduced tear exchange", "Improved oxygenation", "Increased blinking efficiency", "Increased visual field"], "correct": 0, "decode": "Excessive tightness (steep, immobile) REDUCES tear exchange, causing hypoxia.", "ow": ["Correct. Tightness reduces tear exchange.", "Tightness worsens, not improves, oxygenation.", "It does not improve blinking efficiency.", "It does not increase the visual field."]}'),
  ('1c502af1-1h','{"options": ["Too tight", "Too opaque", "Too loose", "Perfectly fitted"], "correct": 2, "decode": "Excessive movement indicates a LOOSE/FLAT fit; a tight lens barely moves.", "ow": ["A tight lens barely moves, the opposite of excess movement.", "Opacity is a material issue, not a movement/fit sign.", "Correct. Excess movement means the lens is too loose (flat).", "A perfect fit moves modestly, not excessively."]}'),
  ('d2b10ccb-27','{"options": ["Comfort", "Improved vision", "Eye pain and redness", "Normal blinking"], "correct": 2, "decode": "Remove a contact lens immediately for significant EYE PAIN and REDNESS (possible infection/hypoxia).", "ow": ["Comfort is not a reason to remove.", "Improved vision is not a reason to remove.", "Correct. Pain and redness warrant immediate removal.", "Normal blinking is not a reason to remove."]}'),
  ('8132f9c6-1v','{"options": ["Presbyopia", "Hyperopia", "Microbial keratitis", "Retinal pigmentation"], "correct": 2, "decode": "A common complication of improper wear is MICROBIAL KERATITIS.", "ow": ["Presbyopia is an age change, not a lens complication.", "Hyperopia is a refractive state, not a lens complication.", "Correct. Microbial keratitis is a wear complication.", "Retinal pigmentation is unrelated to lens wear."]}'),
  ('b69ec32e-1f','{"options": ["Corneal infection", "Better visual acuity", "Increased tear production", "Improved oxygenation"], "correct": 0, "decode": "Sleeping in lenses raises the risk of CORNEAL INFECTION (less O₂, stagnant tears).", "ow": ["Correct. Overnight wear raises corneal infection risk.", "It does not improve acuity.", "It does not increase tear production.", "It reduces, not improves, oxygenation."]}'),
  ('1fa4e510-1i','{"options": ["Refractive errors", "Myopia progression only", "Infection and contamination", "Accommodation"], "correct": 2, "decode": "Lens hygiene primarily prevents INFECTION and CONTAMINATION.", "ow": ["Hygiene does not cause or fix refractive errors.", "It is not specifically about myopia progression.", "Correct. Hygiene prevents infection and contamination.", "It does not affect accommodation."]}'),
  ('89f148c0-v','{"options": ["Diluted with tap water before every use", "Shared among several contact lens wearers", "Reused indefinitely to save on solution", "Used according to the manufacturer''s instructions"], "correct": 3, "decode": "Contact lens solution must be used according to the MANUFACTURER''S INSTRUCTIONS (fresh each time).", "ow": ["Never dilute with tap water.", "Never share solution between wearers.", "Never reuse solution indefinitely.", "Correct. Use it as the manufacturer directs."]}'),
  ('42d9e639-1d','{"options": ["Recommended multipurpose solution", "Sterile saline when appropriate", "Approved contact lens solution", "Tap water"], "correct": 3, "decode": "Lenses should NEVER be rinsed with TAP WATER (Acanthamoeba risk).", "ow": ["Recommended multipurpose solution is acceptable.", "Sterile saline is acceptable when appropriate.", "Approved lens solution is acceptable.", "Correct. Tap water must never touch lenses."]}'),
  ('5d59920b-1g','{"options": ["Increased bone density", "Tooth decay", "Hypoxia and mechanical trauma", "Hair growth"], "correct": 2, "decode": "The corneal epithelium is vulnerable to HYPOXIA and MECHANICAL TRAUMA from lenses.", "ow": ["Bone density is unrelated to the cornea.", "Tooth decay is unrelated.", "Correct. The epithelium is vulnerable to hypoxia and trauma.", "Hair growth is unrelated."]}'),
  ('116cccc2-1r','{"options": ["Hypoxia", "Excessive vitamin intake", "Increased accommodation", "Pupil constriction"], "correct": 0, "decode": "Lens-related corneal edema results from HYPOXIA (oxygen deprivation).", "ow": ["Correct. Hypoxia causes the corneal edema.", "Excess vitamin intake does not cause it.", "Increased accommodation does not cause it.", "Pupil constriction does not cause it."]}'),
  ('b4882a47-1c','{"options": ["Less oxygen transmission", "Greater lens thickness", "No tear exchange", "Greater oxygen transmission"], "correct": 3, "decode": "A high-Dk material allows GREATER oxygen transmission.", "ow": ["High Dk means more, not less, oxygen.", "Dk is not about lens thickness.", "It does not stop tear exchange.", "Correct. High Dk allows greater oxygen transmission."]}'),
  ('e40e10c9-r','{"options": ["Base curve", "Oxygen permeability", "Diameter", "Water volume only"], "correct": 1, "decode": "Dk is the material''s OXYGEN PERMEABILITY (D = diffusion, k = solubility).", "ow": ["Base curve is a geometry parameter, not Dk.", "Correct. Dk is oxygen permeability.", "Diameter is a geometry parameter, not Dk.", "Water content is separate from Dk."]}'),
  ('54622c60-e','{"options": ["Lens diameter", "Lens power", "Oxygen transmissibility", "Tear volume"], "correct": 2, "decode": "Dk/t is OXYGEN TRANSMISSIBILITY (permeability divided by thickness).", "ow": ["Diameter is unrelated to Dk/t.", "Power is unrelated to Dk/t.", "Correct. Dk/t is oxygen transmissibility.", "Tear volume is unrelated to Dk/t."]}'),
  ('d7d7b3fa-1h','{"options": ["Spectacle frames", "Trial prisms", "Soft contact lenses", "Ophthalmoscopes"], "correct": 2, "decode": "Water content matters most for SOFT (hydrogel) contact lenses.", "ow": ["Spectacle frames have no water content parameter.", "Trial prisms have no water content.", "Correct. Water content applies to soft lenses.", "Ophthalmoscopes have no water content."]}'),
  ('dd35476f-1b','{"options": ["Always be more durable", "Always provide the highest oxygen transmission", "Lose water through evaporation and become uncomfortable", "Never dehydrate"], "correct": 2, "decode": "A very high water content lens may DEHYDRATE on the eye, drawing tears and causing discomfort.", "ow": ["It is not always more durable; often less.", "It does not always give the highest oxygen (thickness matters).", "Correct. High water can evaporate and cause discomfort.", "It can dehydrate, so ''never'' is wrong."]}'),
  ('5836732c-1r','{"options": ["Pinhole", "Occluder", "RGP lens", "Plano spectacle lens"], "correct": 2, "decode": "Irregular corneal astigmatism is best corrected with an RGP LENS (its tear lens masks the irregularity).", "ow": ["A pinhole is a diagnostic tool, not a corrective lens.", "An occluder blocks vision; it does not correct.", "Correct. An RGP masks irregular astigmatism.", "A plano spectacle adds no correction."]}'),
  ('5806aa21-16','{"options": ["Eye patches only", "Only spherical spectacles", "No optical correction", "Specialized contact lenses"], "correct": 3, "decode": "Keratoconus is managed optically with SPECIALIZED (RGP/scleral) contact lenses.", "ow": ["Eye patches do not correct the irregularity.", "Spherical spectacles cannot fix irregular astigmatism.", "Some optical correction does help, so ''none'' is wrong.", "Correct. Specialty contact lenses manage keratoconus."]}'),
  ('3646e030-1r','{"options": ["Using tap water for cleaning", "Sleeping with trial lenses", "Comprehensive ocular examination", "Immediate lens insertion"], "correct": 2, "decode": "Before prescribing lenses, do a COMPREHENSIVE OCULAR EXAMINATION first.", "ow": ["Never use tap water for cleaning.", "Do not sleep in trial lenses as a first step.", "Correct. A comprehensive ocular exam comes first.", "Immediate insertion skips assessment."]}'),
  ('cf4c7c3c-1j','{"options": ["Maximum lens movement regardless of patient comfort", "Zero blinking so the lens never shifts on the eye", "Good vision, comfort, ocular health, and appropriate lens fit", "Permanent corneal flattening to reduce the prescription"], "correct": 2, "decode": "The goal of fitting is GOOD VISION, COMFORT, OCULAR HEALTH, and appropriate fit.", "ow": ["Maximizing movement regardless of comfort is not the goal.", "Zero blinking is not a goal.", "Correct. Balance vision, comfort, health, and fit.", "Permanent corneal flattening is not the goal."]}'),
  ('c6ab3ef2-1k','{"options": ["Sound", "Magnetism only", "Light", "Electricity only"], "correct": 2, "decode": "Optics is the branch of physics concerned with LIGHT.", "ow": ["Sound is acoustics, not optics.", "Magnetism is a separate branch.", "Correct. Optics is the study of light.", "Electricity is a separate branch."]}'),
  ('35ad9ecd-11','{"options": ["Convex", "Magnifying", "Concave", "Plus"], "correct": 2, "decode": "A CONCAVE (minus) lens has negative power.", "ow": ["Convex lenses have positive power.", "Magnifying (plus) lenses have positive power.", "Correct. Concave lenses have negative power.", "Plus lenses have positive power."]}'),
  ('7bc43774-2r','{"options": ["Accommodation", "Dispersion", "Reflection", "Absorption"], "correct": 1, "decode": "DISPERSION separates white light into its component colors (each wavelength bends differently).", "ow": ["Accommodation is focusing, not color separation.", "Correct. Dispersion splits white light into colors.", "Reflection bounces light; it does not split it.", "Absorption removes light; it does not disperse it."]}'),
  ('2197a74c-1l','{"options": ["Toward the normal", "Back toward the source", "Along the surface", "Away from the normal"], "correct": 0, "decode": "Going from air into denser glass, light bends TOWARD the normal.", "ow": ["Correct. Into a denser medium, light bends toward the normal.", "Light continues forward, not back toward the source.", "It does not travel along the surface (that is the critical-angle case).", "It bends away from the normal only entering a less dense medium."]}'),
  ('04fabf36-29','{"options": ["Polarization", "Dispersion", "Diffusion", "Reflection"], "correct": 1, "decode": "DISPERSION is white light separating into its component colors.", "ow": ["Polarization filters orientation; it does not split colors.", "Correct. Dispersion separates white light into colors.", "Diffusion scatters light; it does not disperse into colors.", "Reflection bounces light; it does not split it."]}'),
  ('7d350600-1a','{"options": ["Routine calibration of a manual lensometer", "Rigid contact lens fluorescein patterns", "The natural color of the patient''s pupil", "The overall length of a spectacle temple"], "correct": 1, "decode": "Fluorescein is used to evaluate RIGID contact lens FLUORESCEIN PATTERNS (the tear layer under the lens).", "ow": ["Lensometer calibration does not use fluorescein.", "Correct. Fluorescein shows the rigid-lens fit pattern.", "Pupil color is not assessed with fluorescein.", "Temple length is unrelated to fluorescein."]}'),
  ('45b4498c-2c','{"options": ["Temperature", "Density", "Weight", "Optical power"], "correct": 3, "decode": "Bringing parallel rays to a focus is the job of OPTICAL POWER.", "ow": ["Temperature does not determine focusing ability.", "Density does not determine focusing ability.", "Weight does not determine focusing ability.", "Correct. Optical power brings parallel rays to a focus."]}'),
  ('77232f20-1u','{"options": ["Temporal side", "Center", "Nasal side", "Edge"], "correct": 1, "decode": "A plus lens is thickest at the CENTER, thinning toward the edge.", "ow": ["The temporal side is not the thickest part of a plus lens.", "Correct. A plus lens is thickest in the center.", "The nasal side is not the thickest part.", "The edge is thickest in a minus lens, not plus."]}'),
  ('cc81dfc1-2c','{"options": ["Lens thickness", "Corneal astigmatism", "Pupil diameter", "Axial length"], "correct": 1, "decode": "The difference between the two principal corneal powers is the CORNEAL ASTIGMATISM.", "ow": ["Lens thickness is unrelated to the meridian difference.", "Correct. The difference between corneal meridians is the astigmatism.", "Pupil diameter is unrelated.", "Axial length is unrelated."]}'),
  ('aa483d1f-17','{"options": ["Intraocular pressure", "Contact lens surface", "Corneal thickness", "Axial length"], "correct": 1, "decode": "A magnifier or loupe inspects the CONTACT LENS SURFACE for deposits or damage.", "ow": ["It does not measure intraocular pressure.", "Correct. A loupe inspects the lens surface.", "It does not measure corneal thickness.", "It does not measure axial length."]}'),
  ('2529af99-v','{"options": ["Corneal thickness", "Decentration in centimeters", "Lens curvature in meters", "Cylinder axis"], "correct": 1, "decode": "In Prentice''s rule (P = c × F), c is DECENTRATION in CENTIMETERS.", "ow": ["It is not corneal thickness.", "Correct. c is decentration in centimeters.", "It is not lens curvature in meters.", "It is not the cylinder axis."]}'),
  ('4c715515-19','{"options": ["Absorbs all light", "Polarizes all light", "Refracts light", "Reflects light"], "correct": 3, "decode": "A mirror primarily REFLECTS light.", "ow": ["It does not absorb all light.", "It does not polarize all light.", "It reflects rather than refracts light.", "Correct. A mirror reflects light."]}'),
  ('dddadccc-1n','{"options": ["Equal to the angle of reflection", "Less than the angle of reflection", "Twice the angle of reflection", "Greater than the angle of reflection"], "correct": 0, "decode": "Law of reflection: angle of incidence EQUALS angle of reflection.", "ow": ["Correct. Incidence equals reflection.", "It is equal, not less.", "It is equal, not twice.", "It is equal, not greater."]}'),
  ('25ee6a89-11','{"options": ["Always magnified", "Smaller than the object", "The same size as the object", "Larger than the object"], "correct": 2, "decode": "A plane mirror forms a SAME-SIZE (upright, virtual) image.", "ow": ["It does not magnify.", "It is same size, not smaller.", "Correct. The image is the same size as the object.", "It is same size, not larger."]}'),
  ('95748d60-16','{"options": ["Lens power", "Corneal curvature", "IOP", "Retinal thickness"], "correct": 1, "decode": "A keratometer measures CORNEAL CURVATURE (front surface).", "ow": ["It does not measure lens power.", "Correct. It measures corneal curvature.", "It does not measure intraocular pressure.", "It does not measure retinal thickness."]}'),
  ('a5cfefbe-x','{"options": ["Tonometer", "Perimeter", "Ophthalmometer", "Pachymeter"], "correct": 2, "decode": "A keratometer is also called an OPHTHALMOMETER.", "ow": ["A tonometer measures pressure.", "A perimeter maps fields.", "Correct. The keratometer is also the ophthalmometer.", "A pachymeter measures thickness."]}'),
  ('adfa90ba-1r','{"options": ["Systemic blood pressure and pulse rate", "The back vertex power of the lens", "Lens centration, movement, and corneal staining", "Corneal thickness by ultrasound pachymetry"], "correct": 2, "decode": "On-eye slit-lamp exam shows LENS CENTRATION, MOVEMENT, and corneal STAINING together.", "ow": ["It does not read blood pressure or pulse.", "It does not read back vertex power.", "Correct. Centration, movement, and staining are assessed together.", "It does not measure thickness by ultrasound pachymetry."]}'),
  ('4b715ad5-2a','{"options": ["Lensometer", "Slit lamp", "Retinoscope", "Keratometer alone"], "correct": 1, "decode": "A SLIT LAMP with fluorescein evaluates a rigid contact lens fit.", "ow": ["A lensometer reads lens power, not fit pattern.", "Correct. The slit lamp with fluorescein shows the fit.", "A retinoscope determines refraction, not fit.", "A keratometer alone cannot show the fluorescein pattern."]}'),
  ('058a326a-2a','{"options": ["Systemic arterial blood pressure and pulse", "General dental and periodontal health status", "The patient''s overall hearing ability and balance", "Corneal shape and ocular response to contact lens wear"], "correct": 3, "decode": "Keratometry + slit lamp together inform CORNEAL SHAPE and OCULAR RESPONSE to lens wear.", "ow": ["They do not measure blood pressure or pulse.", "They do not assess dental health.", "They do not assess hearing or balance.", "Correct. Corneal shape and ocular response to lens wear."]}'),
  ('019e3aa1-1q','{"options": ["The keratometer measures retinal thickness while the slit lamp reads spectacle power", "Keratometer primarily measures corneal curvature, while slit lamp examines ocular structures", "Both the keratometer and the slit lamp are used only to measure intraocular pressure", "The slit lamp measures only spectacle lens power and never examines the eye itself"], "correct": 1, "decode": "Correctly: the KERATOMETER measures corneal curvature, the SLIT LAMP examines ocular structures.", "ow": ["This swaps the two instruments'' functions.", "Correct. Keratometer = curvature; slit lamp = structures.", "Neither is limited to measuring IOP.", "The slit lamp examines the eye; it does not read spectacle power."]}'),
  ('a38463bd-v','{"options": ["Progressive corneal thinning and protrusion", "Painless swelling of the optic nerve head", "Spontaneous displacement of the crystalline lens", "Sudden intraretinal and preretinal hemorrhage"], "correct": 0, "decode": "Keratoconus is progressive corneal THINNING and cone-shaped PROTRUSION.", "ow": ["Correct. Keratoconus is thinning and conical protrusion.", "Optic-nerve-head swelling is papilledema, not keratoconus.", "Lens displacement is ectopia lentis, not keratoconus.", "Retinal hemorrhage is unrelated to keratoconus."]}'),
  ('1f50560c-18','{"options": ["Irregular astigmatism", "Retinal detachment", "Hyperopia only", "Complete color blindness"], "correct": 0, "decode": "A classic keratoconus feature is IRREGULAR ASTIGMATISM.", "ow": ["Correct. Keratoconus causes irregular astigmatism.", "Retinal detachment is not a hallmark of keratoconus.", "It is not pure hyperopia.", "Complete color blindness is unrelated."]}'),
  ('43432efb-28','{"options": ["Red reflex", "Lens power", "Pupil reaction", "Fluorescein"], "correct": 3, "decode": "A cobalt-blue filter on the slit lamp is used to view FLUORESCEIN.", "ow": ["It is not primarily for the red reflex.", "It does not measure lens power.", "It is not for pupil reaction.", "Correct. Cobalt blue makes fluorescein fluoresce."]}'),
  ('b080d42d-28','{"options": ["Pachymeter", "Keratometer", "Lensometer", "Slit lamp"], "correct": 2, "decode": "A LENSOMETER measures the optical power of a contact lens in air.", "ow": ["A pachymeter measures thickness.", "A keratometer measures corneal curvature.", "Correct. A lensometer reads lens power in air.", "A slit lamp examines structures, not power."]}'),
  ('5da40697-10','{"options": ["Focimeter", "Keratometer", "Pachometer", "Ophthalmometer"], "correct": 0, "decode": "A manual lensometer is also called a FOCIMETER.", "ow": ["Correct. The lensometer is also the focimeter.", "A keratometer measures corneal curvature.", "A pachometer measures thickness.", "An ophthalmometer is the keratometer."]}'),
  ('b3206f91-2v','{"options": ["Lensometer", "Tonometer", "Radiuscope", "Retinoscope"], "correct": 2, "decode": "A RADIUSCOPE measures the base curve of a rigid gas-permeable lens.", "ow": ["A lensometer reads lens power, not base curve.", "A tonometer measures pressure.", "Correct. A radiuscope reads the RGP base curve.", "A retinoscope determines refraction."]}'),
  ('079b3176-13','{"options": ["Tear volume", "Corneal diameter", "Pupil diameter", "Lens thickness"], "correct": 3, "decode": "A contact lens thickness gauge measures LENS THICKNESS.", "ow": ["It does not measure tear volume.", "It does not measure corneal diameter.", "It does not measure pupil diameter.", "Correct. It measures lens thickness."]}'),
  ('52365ad5-1u','{"options": ["Lens gauge", "Ophthalmoscope", "Retinoscope", "Tonometer"], "correct": 0, "decode": "A LENS GAUGE (measuring magnifier) reads contact lens diameter.", "ow": ["Correct. A lens gauge measures lens diameter.", "An ophthalmoscope views the fundus, not lens size.", "A retinoscope determines refraction.", "A tonometer measures pressure."]}'),
  ('ac62f35b-11','{"options": ["Perimeter", "Pachymeter", "Ophthalmometer", "Aberrometer"], "correct": 2, "decode": "The keratometer is also known as an OPHTHALMOMETER.", "ow": ["A perimeter maps fields.", "A pachymeter measures thickness.", "Correct. The keratometer is the ophthalmometer.", "An aberrometer measures wavefront aberrations."]}'),
  ('b4f00700-1o','{"options": ["Tonometer", "Keratometer", "Pupillometer", "Lensometer"], "correct": 1, "decode": "A KERATOMETER measures corneal astigmatism from the two principal meridians.", "ow": ["A tonometer measures pressure.", "Correct. A keratometer measures corneal astigmatism.", "A pupillometer measures pupil size.", "A lensometer reads lens power."]}'),
  ('1db383c6-2e','{"options": ["Slit lamp", "Retinoscope", "Lensometer", "Trial lens set"], "correct": 0, "decode": "A SLIT LAMP gives magnified examination of the lens and ocular surface.", "ow": ["Correct. The slit lamp magnifies the lens and ocular surface.", "A retinoscope does not magnify the eye.", "A lensometer reads lens power.", "A trial lens set does not magnify the eye."]}'),
  ('407622ec-p','{"options": ["Only diminished images for every object position", "Real or virtual images depending on object position", "No image of any kind under any condition", "Only upright virtual images regardless of distance"], "correct": 1, "decode": "A concave mirror can form REAL or VIRTUAL images depending on object position.", "ow": ["It is not limited to diminished images.", "Correct. It forms real or virtual images by object position.", "It does form images.", "It is not limited to upright virtual images."]}'),
  ('09c308a2-1n','{"options": ["The real object position only", "The final image position only", "Pole and center of curvature", "The secondary focal point only"], "correct": 2, "decode": "The principal axis of a spherical mirror passes through the POLE and CENTER OF CURVATURE.", "ow": ["It is not defined by the object position.", "It is not defined by the image position.", "Correct. It passes through the pole and center of curvature.", "It is not defined only by the focal point."]}'),
  ('e56430f6-1y','{"options": ["Refraction", "Polarization", "Diffraction", "Reflection"], "correct": 0, "decode": "Light bending as it crosses between media is REFRACTION.", "ow": ["Correct. Refraction is bending between media.", "Polarization filters orientation, not bending.", "Diffraction is spreading at edges.", "Reflection bounces light back."]}'),
  ('e019fba1-12','{"options": ["Hooke''s law", "Boyle''s law", "Newton''s law", "Snell''s law"], "correct": 3, "decode": "Refraction is governed by SNELL''S LAW.", "ow": ["Hooke''s law is about springs.", "Boyle''s law is about gases.", "Newton''s laws are mechanics.", "Correct. Snell''s law governs refraction."]}'),
  ('d4213e68-1e','{"options": ["The total back vertex optical power of the lens", "The overall horizontal diameter of the lens", "Height or depth from the chord to the lens surface", "The geometric center thickness of the lens only"], "correct": 2, "decode": "Sagittal depth is the HEIGHT from the CHORD to the deepest point of the lens surface (its vault).", "ow": ["It is not the back vertex power.", "It is not the horizontal diameter.", "Correct. It is the height from chord to surface.", "It is not the center thickness."]}'),
  ('c21e8245-1r','{"options": ["Ophthalmoscope", "Retinoscope", "Tonometer", "Vernier caliper"], "correct": 3, "decode": "A VERNIER CALIPER measures the diameter and dimensions of a contact lens.", "ow": ["An ophthalmoscope views the fundus, not lens size.", "A retinoscope determines refraction.", "A tonometer measures pressure.", "Correct. A vernier caliper measures lens dimensions."]}'),
  ('617138a2-1c','{"options": ["IOP", "Corneal thickness", "Lens diameter", "Pupil reaction"], "correct": 2, "decode": "A contact lens diameter gauge measures LENS DIAMETER.", "ow": ["It does not measure intraocular pressure.", "It does not measure corneal thickness.", "Correct. It measures lens diameter.", "It does not measure pupil reaction."]}'),
  ('5a8add79-2z','{"options": ["Lens gauge", "Ophthalmoscope", "Radiuscope", "Lensometer"], "correct": 1, "decode": "An OPHTHALMOSCOPE examines the posterior segment (retina, disc), not lens fit.", "ow": ["A lens gauge measures lens diameter.", "Correct. An ophthalmoscope examines the posterior segment.", "A radiuscope measures base curve.", "A lensometer reads lens power."]}'),
  ('ba791709-1l','{"options": ["Measure lens diameter", "Determine refractive error", "Measure corneal thickness", "Inspect lens deposits"], "correct": 1, "decode": "In CL practice a RETINOSCOPE is used to determine REFRACTIVE ERROR.", "ow": ["It does not measure lens diameter.", "Correct. A retinoscope determines refractive error.", "It does not measure corneal thickness.", "It does not inspect lens deposits."]}'),
  ('cd651ab9-n','{"options": ["One plane and one concave surface", "Two plane surfaces", "Two concave surfaces", "One plane and one convex surface"], "correct": 3, "decode": "A plano-convex lens has ONE PLANE and ONE CONVEX surface.", "ow": ["It is convex, not concave, on the curved side.", "It has one curved surface, not two plane.", "It has no concave surface.", "Correct. One plane and one convex surface."]}'),
  ('92df7177-21','{"options": ["Deviating strongly toward the prism base", "Deviating strongly toward the prism apex", "Without significant angular deviation", "With the greatest possible angular deviation"], "correct": 2, "decode": "A ray through the OPTICAL CENTER passes WITHOUT significant angular deviation.", "ow": ["A center ray is not deviated toward the base.", "A center ray is not deviated toward the apex.", "Correct. It passes without significant deviation.", "The center gives the least, not greatest, deviation."]}'),
  ('dcac910a-1h','{"options": ["Parallel incident rays converge", "All rays are reflected", "Diverging rays originate", "Light becomes polarized"], "correct": 0, "decode": "The principal focus of a plus lens is where PARALLEL incident rays CONVERGE.", "ow": ["Correct. Parallel rays converge at the focus.", "It is a refracting, not reflecting, focus.", "Diverging rays do not originate at a plus-lens focus.", "Light is not polarized there."]}'),
  ('3d754ded-1p','{"options": ["6 meters", "12 meters", "3 meters", "1 meter"], "correct": 0, "decode": "The standard Snellen testing distance is 6 meters (~20 feet).", "ow": ["Correct. Snellen is tested at 6 meters.", "12 meters is not the standard lane.", "3 meters is not the standard full distance.", "1 meter is a near distance, not the standard."]}'),
  ('6a9f3b70-t','{"options": ["The back vertex power of a lens only", "The overall diameter of a lens only", "Radius of curvature of a lens surface", "The central thickness of the cornea"], "correct": 2, "decode": "A radiuscope determines the RADIUS OF CURVATURE of a lens surface.", "ow": ["It does not read back vertex power.", "It does not read diameter.", "Correct. It determines the radius of curvature.", "It does not measure corneal thickness."]}'),
  ('12c560bf-2f','{"options": ["Tonometer", "Keratometer", "Radiuscope", "Lensometer"], "correct": 0, "decode": "A TONOMETER measures intraocular pressure, relevant to ocular health in CL practice.", "ow": ["Correct. A tonometer measures IOP.", "A keratometer measures curvature.", "A radiuscope measures base curve.", "A lensometer reads lens power."]}'),
  ('fb96b456-1g','{"options": ["To measure base curve", "To measure contact lens diameter", "To determine lens power", "To evaluate ocular health"], "correct": 3, "decode": "A tonometer matters in CL practice to EVALUATE OCULAR HEALTH.", "ow": ["It does not measure base curve.", "It does not measure lens diameter.", "It does not determine lens power.", "Correct. It helps evaluate ocular health."]}'),
  ('214456ef-x','{"options": ["Converging mirror", "Plane mirror", "Diverging mirror", "Cylindrical mirror"], "correct": 0, "decode": "A concave mirror is a CONVERGING mirror.", "ow": ["Correct. Concave = converging.", "A plane mirror neither converges nor diverges.", "Diverging is a convex mirror.", "It is not a cylindrical mirror."]}'),
  ('41a060dd-k','{"options": ["Converging mirror", "Diverging mirror", "Magnifying mirror", "Plane mirror"], "correct": 1, "decode": "A convex mirror is a DIVERGING mirror.", "ow": ["Converging is a concave mirror.", "Correct. Convex = diverging.", "It minifies rather than magnifies.", "A plane mirror neither converges nor diverges."]}'),
  ('a007595c-27','{"options": ["Center of curvature", "Focal point", "Pole", "Vertex"], "correct": 0, "decode": "The center of the sphere a mirror is cut from is the CENTER OF CURVATURE.", "ow": ["Correct. It is the center of curvature.", "The focal point is halfway to the center, not the center.", "The pole is on the mirror surface.", "The vertex is on the mirror surface."]}'),
  ('985e396c-20','{"options": ["Optical distance", "Vertex distance", "Focal length", "Radius of curvature"], "correct": 3, "decode": "Pole to center of curvature is the RADIUS OF CURVATURE.", "ow": ["''Optical distance'' is not this defined distance.", "Vertex distance is spectacle-to-eye, not this.", "Focal length is half of this distance.", "Correct. Pole to center = radius of curvature."]}'),
  ('bec0aadf-1g','{"options": ["Twice the radius of curvature", "Half the radius of curvature", "Four times the radius", "Equal to radius of curvature"], "correct": 1, "decode": "For a spherical mirror, focal length is HALF the radius of curvature (f = R/2).", "ow": ["It is half, not twice, the radius.", "Correct. f = R/2.", "It is half, not four times, the radius.", "It is half, not equal to, the radius."]}'),
  ('050e3435-19','{"options": ["Virtual and magnified", "Real and inverted", "Real and magnified", "Virtual, upright, and diminished"], "correct": 3, "decode": "A convex mirror always forms a VIRTUAL, UPRIGHT, DIMINISHED image.", "ow": ["It does not magnify.", "It is virtual, not real/inverted.", "It is virtual, not real/magnified.", "Correct. Virtual, upright, and diminished."]}'),
  ('e23e2998-1g','{"options": ["+1.00 D", "+5.00 D", "+0.50 D", "+2.00 D"], "correct": 3, "decode": "Power = 1/f, so 1/0.50 m = +2.00 D.", "ow": ["+1.00 D would be a 1.0 m focus.", "+5.00 D would be a 0.20 m focus.", "+0.50 D would be a 2.0 m focus.", "Correct. 1/0.50 = +2.00 D."]}'),
  ('73cd637e-1f','{"options": ["-2.00 D", "+4.00 D", "-4.00 D", "+2.00 D"], "correct": 2, "decode": "Power = 1/f, so 1/(−0.25 m) = −4.00 D (diverging).", "ow": ["−2.00 D would be a −0.50 m focus.", "The sign is negative for a minus lens.", "Correct. 1/(−0.25) = −4.00 D.", "The sign is negative, not positive."]}'),
  ('730f2f3d-1l','{"options": ["P = F/h", "P = hF/10", "P = 10h/F", "P = F/10h"], "correct": 1, "decode": "Prentice''s rule (mm form): P = hF/10 (h in mm, F in D).", "ow": ["P = F/h is not Prentice''s rule.", "Correct. P = hF/10.", "P = 10h/F inverts the terms.", "P = F/10h inverts the terms."]}'),
  ('190f08ed-x','{"options": ["Optical center", "Base", "Apex", "Center"], "correct": 1, "decode": "A prism deviates light toward its BASE.", "ow": ["The optical center is a lens concept, not the prism deviation direction.", "Correct. Light bends toward the base.", "The image, not the light, shifts toward the apex.", "The ''center'' is not the deviation direction."]}'),
  ('6c491d85-1y','{"options": ["Flatter cornea", "Thinner cornea", "Steeper cornea", "More curved lens"], "correct": 2, "decode": "A SMALLER keratometry image means a stronger curve, so a STEEPER cornea.", "ow": ["A larger image means a flatter cornea.", "Image size reflects curvature, not thickness.", "Correct. Smaller image = steeper cornea.", "It reflects corneal, not lens, curvature."]}'),
  ('8ca34aa6-19','{"options": ["Prism diopters of horizontal deviation only", "Diopters and/or millimeters of radius", "Centimeters of ocular axial length only", "Angular degrees of meridional rotation only"], "correct": 1, "decode": "A keratometer reports corneal curvature in DIOPTERS and/or MILLIMETERS of radius.", "ow": ["It does not report prism diopters.", "Correct. Diopters and/or mm of radius.", "It does not report axial length in centimeters.", "It does not report angular degrees."]}'),
  ('0dd4317a-1d','{"options": ["Retinal implants", "Contact lenses", "Spectacle temples", "Hearing aids"], "correct": 1, "decode": "Keratometry is especially useful before fitting CONTACT LENSES (guides base curve).", "ow": ["Retinal implants are not fit by keratometry.", "Correct. Keratometry guides contact lens fitting.", "Spectacle temple length is unrelated.", "Hearing aids are unrelated."]}'),
  ('edf93224-1k','{"options": ["Prism diopters", "Millimeters", "Centimeters only", "Degrees only"], "correct": 1, "decode": "Corneal radius of curvature is expressed in MILLIMETERS.", "ow": ["It is not expressed in prism diopters.", "Correct. It is expressed in millimeters.", "It is reported in mm, not centimeters.", "It is not expressed in degrees."]}'),
  ('347237a9-1m','{"options": ["Applanation intraocular pressure readings alone", "Corneal radius and assumed refractive index", "Overall ocular axial length by ultrasound alone", "Entrance pupil diameter under bright light alone"], "correct": 1, "decode": "A keratometer estimates corneal power from CORNEAL RADIUS and an ASSUMED refractive index.", "ow": ["It does not use IOP readings.", "Correct. It uses radius plus an assumed index.", "It does not use axial length by ultrasound.", "It does not use pupil diameter."]}'),
  ('fd8f15fb-2b','{"options": ["1.5000", "2.0000", "1.000", "1.3375"], "correct": 3, "decode": "The standard keratometric index is about 1.3375.", "ow": ["1.5000 is roughly a spectacle-glass index, not the keratometric one.", "2.0000 is far too high.", "1.000 is air.", "Correct. The keratometric index is ~1.3375."]}'),
  ('c3ae9de2-32','{"options": ["Keratometer", "Ophthalmoscope", "Tonometer", "Vernier caliper"], "correct": 3, "decode": "A VERNIER CALIPER measures a contact lens''s diameter and dimensions in the lab.", "ow": ["A keratometer measures corneal curvature.", "An ophthalmoscope views the fundus.", "A tonometer measures pressure.", "Correct. A vernier caliper measures lens dimensions."]}'),
  ('644cebc9-1x','{"options": ["Slit lamp with fluorescein", "Lensometer with ophthalmoscope only", "Perimeter with trial frame only", "Tonometer with retinoscope only"], "correct": 0, "decode": "Contact lens fit is best evaluated with a SLIT LAMP + FLUORESCEIN.", "ow": ["Correct. Slit lamp with fluorescein evaluates fit.", "This pair omits the essential slit lamp/dye.", "This pair omits the essential slit lamp/dye.", "This pair omits the essential slit lamp/dye."]}'),
  ('59d3a0a1-2p','{"options": ["Retinoscope only", "Slit lamp biomicroscope", "Lensometer only", "Trial frame only"], "correct": 1, "decode": "The SLIT LAMP BIOMICROSCOPE is essential for detailed CL wearer evaluation.", "ow": ["A retinoscope alone is not enough.", "Correct. The slit lamp biomicroscope is essential.", "A lensometer alone is not enough.", "A trial frame alone is not enough."]}'),
  ('62102685-1c','{"options": ["1-10 mm", "100-200 nm", "1-10 nm", "380-750 nm"], "correct": 3, "decode": "Visible light spans about 380–750 nm.", "ow": ["1–10 mm is far too large (radio/micro scale).", "100–200 nm is far ultraviolet.", "1–10 nm is X-ray scale.", "Correct. Visible light is ~380–750 nm."]}'),
  ('8b2d2202-24','{"options": ["+0.50 m", "-0.25 m", "-0.50 m", "+2.00 m"], "correct": 2, "decode": "Focal length = 1/P, so 1/(−2.00) = −0.50 m.", "ow": ["+0.50 m has the wrong sign for a minus lens.", "−0.25 m would be a −4 D lens.", "Correct. f = 1/(−2.00) = −0.50 m.", "+2.00 m is neither the right magnitude nor sign."]}'),
  ('6a125143-1i','{"options": ["4 prism diopters", "0.5 prism diopters", "2 prism diopters", "1 prism diopter"], "correct": 2, "decode": "Prentice: prism = decentration(cm) × power = 0.5 × 4 = 2Δ.", "ow": ["4Δ ignores the mm-to-cm conversion.", "0.5Δ uses the wrong figures.", "Correct. 0.5 cm × +4 D = 2Δ.", "1Δ understates it."]}'),
  ('3168a098-1m','{"options": ["Apex", "Base", "Principal axis", "Optical center"], "correct": 0, "decode": "The apparent image through a prism is displaced toward the APEX.", "ow": ["Correct. The image displaces toward the apex.", "Light bends toward the base, but the image goes apexward.", "It is not displaced toward the principal axis.", "It is not displaced toward the optical center."]}'),
  ('b4f8f139-1e','{"options": ["Thickness only", "Temperature only", "Speed of light in the medium", "Weight of the medium"], "correct": 2, "decode": "Refractive index reflects the SPEED OF LIGHT in the medium (n = c/v).", "ow": ["Index is not defined by thickness alone.", "Index is not defined by temperature alone.", "Correct. Index relates to the speed of light in the medium.", "Index is not defined by the medium''s weight."]}'),
  ('5549812f-1d','{"options": ["0", "0.5", "2.00", "1.00"], "correct": 3, "decode": "The refractive index of a vacuum is 1.00 (the reference).", "ow": ["It is not 0.", "It is not 0.5.", "It is not 2.00.", "Correct. Vacuum index = 1.00."]}'),
  ('4af7d39d-1f','{"options": ["From a less dense medium into a much denser optical medium", "From a denser to a less dense medium and exceeds the critical angle", "At exactly normal (perpendicular) incidence to the surface", "Only through a perfect vacuum where no medium is present"], "correct": 1, "decode": "TIR occurs going from a DENSER to a LESS-DENSE medium and EXCEEDING the critical angle.", "ow": ["Going into a denser medium light refracts inward, not TIR.", "Correct. Denser-to-rarer beyond the critical angle gives TIR.", "At normal incidence light passes straight through.", "TIR needs a medium boundary, not a perfect vacuum."]}'),
  ('52a063b7-27','{"options": ["Parallel to the normal", "Back toward the source", "At 90 degrees to the boundary", "Along the boundary"], "correct": 3, "decode": "At the CRITICAL ANGLE the refracted ray travels ALONG the boundary (refraction 90° to the normal).", "ow": ["It does not travel parallel to the normal.", "It does not go back toward the source at the critical angle.", "At the critical angle the ray is at 90° to the normal, i.e. along the surface, not ''90° to the boundary''.", "Correct. The refracted ray runs along the boundary."]}')
)
UPDATE question_reviews r
SET payload = r.payload || d.patch::jsonb
FROM d
WHERE r.question_id = d.qid;
